def filtrar_kwargs(kwargs):
    """
    Remove argumentos incompatíveis
    do ttkbootstrap.
    """

    for chave in [
        "style",
        "bootstyle",
        "padding",
        "relief",
        "borderwidth",
        "focusthickness"
    ]:
        kwargs.pop(chave, None)

    return kwargs

