import unicodedata as _unicodedata_botao

# =====================================================
# 🎨 PALETA DE CORES SEMÂNTICAS DOS BOTÕES
# =====================================================
# Cada categoria mantém o MESMO efeito 3D (borda/sombra) que já existia,
# só troca o tom. Cores suaves, profissionais (nada de "carnaval").
_PALETA_CORES_BOTAO = {
    # [TEMA MODERNO] Botoes chapados: "sombra" = mesma cor do botao (sem borda 3D)
    "verde":    {"normal": "#1B8F4D", "hover": "#22A85B", "click": "#157A41", "sombra": "#1B8F4D", "texto": "white"},
    "vermelho": {"normal": "#DC2626", "hover": "#EF4444", "click": "#B91C1C", "sombra": "#DC2626", "texto": "white"},
    "amarelo":  {"normal": "#F59E0B", "hover": "#FBB13C", "click": "#D97706", "sombra": "#F59E0B", "texto": "#3B2300"},
    "azul":     {"normal": "#2563EB", "hover": "#3B82F6", "click": "#1D4ED8", "sombra": "#2563EB", "texto": "white"},
    "cinza":    {"normal": "#E5E7EB", "hover": "#D1D5DB", "click": "#9CA3AF", "sombra": "#E5E7EB", "texto": "#374151"},
    # [APARENCIA] categorias extras: comecam IGUAIS a cor que esses botoes ja tinham (visual nao muda)
    # ate o usuario escolher outra cor em CONFIG > Aparencia.
    "ajustar":  {"normal": "#F59E0B", "hover": "#FBB13C", "click": "#D97706", "sombra": "#F59E0B", "texto": "#3B2300"},
    "copiar":   {"normal": "#1B8F4D", "hover": "#22A85B", "click": "#157A41", "sombra": "#1B8F4D", "texto": "white"},
    "gerar":    {"normal": "#1B8F4D", "hover": "#22A85B", "click": "#157A41", "sombra": "#1B8F4D", "texto": "white"},
    "encerrar": {"normal": "#1B8F4D", "hover": "#22A85B", "click": "#157A41", "sombra": "#1B8F4D", "texto": "white"},
    "senhas":   {"normal": "#1B8F4D", "hover": "#22A85B", "click": "#157A41", "sombra": "#1B8F4D", "texto": "white"},
}

# Palavras-chave (sem acento, minúsculas) que definem a categoria de cor
# a partir do TEXTO do próprio botão. A ordem importa: checa da mais
# "perigosa" (vermelho) para a mais neutra (verde é o padrão final).
_PALAVRAS_COR_BOTAO = (
    ("vermelho", ("excluir", "exclu", "remover", "remov", "deletar", "delet",
                  "apagar", "cancelar", "cancel", "descartar", "descarte",
                  "estornar", "estorno", "esvaziar")),
    ("amarelo",  ("editar", "edit", "alterar", "altera", "atualizar",
                  "atualiza")),
    ("ajustar",  ("ajustar", "ajuste")),   # [APARENCIA] antes fazia parte do amarelo (mesma cor por padrao)
    ("cinza",    ("fechar", "voltar", "sair", "limpar", "limpa")),
    ("azul",     ("buscar", "busca", "filtrar", "filtro", "relatorio",
                  "imprimir", "historico", "consultar", "exportar")),
    # [APARENCIA] novas categorias: so pegam botoes que antes caiam no verde (por padrao ficam iguais)
    ("copiar",   ("copiar", "copia")),
    ("gerar",    ("gerar", "gerador")),
    ("encerrar", ("encerrar", "encerra")),
    ("senhas",   ("senha",)),
)


def _normalizar_texto_botao(texto):
    texto = str(texto or "")
    texto = _unicodedata_botao.normalize("NFKD", texto)
    texto = "".join(c for c in texto if not _unicodedata_botao.combining(c))
    return texto.lower()


def _detectar_cor_botao(texto):
    """Decide a categoria de cor do botão pelo próprio texto (case/acento
    insensitive). Se nada bater, cai no verde (cor padrão de sempre)."""
    t = _normalizar_texto_botao(texto)
    for categoria, palavras in _PALAVRAS_COR_BOTAO:
        if any(palavra in t for palavra in palavras):
            return categoria
    return "verde"


