class BotaoArredondadoDefinitivo(_BaseBotao):

    def __init__(self, master, *args, **kwargs):

        # Permite forçar manualmente uma categoria de cor (opcional; se não
        # vier, é detectada automaticamente pelo texto do botão). Precisa
        # ser retirado ANTES do filtrar_kwargs, que não conhece essa chave.
        cor_forcada = kwargs.pop("cor_botao", None)

        filtrar_kwargs(kwargs)

        largura_antiga = kwargs.get("width")
        if isinstance(largura_antiga, (int, float)) and largura_antiga <= 80:
            kwargs["width"] = max(112, int(largura_antiga) * 8)
        else:
            kwargs.setdefault("width", 145)

        # Mesma lógica do width: se vier um "height" no estilo antigo do
        # ttk.Button (ex.: height=2, que é em "linhas de texto", não pixels),
        # convertemos para um valor razoável em pixels. Isso evita o erro
        # "got multiple values for keyword argument 'height'" quando algum
        # botão antigo do sistema é chamado com height=N.
        altura_antiga = kwargs.get("height")
        if isinstance(altura_antiga, (int, float)) and altura_antiga <= 10:
            kwargs["height"] = max(40, int(altura_antiga) * 20)
        else:
            kwargs.setdefault("height", 40)

        categoria = cor_forcada if cor_forcada in _PALETA_CORES_BOTAO else _detectar_cor_botao(kwargs.get("text"))
        cores = _PALETA_CORES_BOTAO[categoria]
        self.categoria_botao = categoria   # [APARENCIA] permite recolorir ao vivo pela categoria exata

        self.cor_normal = cores["normal"]
        self.cor_hover = cores["hover"]
        self.cor_click = cores["click"]
        self.cor_sombra_3d = cores["sombra"]
        self.cor_texto_botao = cores["texto"]

        super().__init__(

            master,
            *args,

            fg_color=self.cor_normal,

            hover_color=self.cor_hover,

            text_color=self.cor_texto_botao,

            corner_radius=8,

            border_width=0,

            border_color=self.cor_sombra_3d,

            font=("Segoe UI Semibold", max(10, round(16 * globals().get("_ESCALA_FONTE", 1.0)))),

            cursor="hand2",

            **kwargs
        )

        # Clique
        self.bind(
            "<ButtonPress-1>",
            lambda e: self.configure(
                fg_color=self.cor_click,
                border_color=self.cor_click
            )
        )

        # Soltou
        self.bind(
            "<ButtonRelease-1>",
            lambda e: self.configure(
                fg_color=self.cor_normal,
                border_color=self.cor_sombra_3d
            )
        )

        # Mouse saiu
        self.bind(
            "<Leave>",
            lambda e: self.configure(
                fg_color=self.cor_normal,
                border_color=self.cor_sombra_3d
            )
        )

    def configure(self, *args, **kwargs):

        filtrar_kwargs(kwargs)

        return super().configure(*args, **kwargs)


