class ScrollbarModerna(ctk.CTkScrollbar):
    _kwargs_ttk_ignorados = {
        "style",
        "bootstyle",
        "relief",
        "borderwidth",
        "elementborderwidth",
        "takefocus",
        "cursor",
        "class_",
    }

    def __init__(self, master, *args, **kwargs):
        orientacao = kwargs.pop("orient", kwargs.pop("orientation", "vertical"))
        comando = kwargs.pop("command", None)

        for chave in self._kwargs_ttk_ignorados:
            kwargs.pop(chave, None)

        if orientacao not in ("vertical", "horizontal"):
            orientacao = "vertical"

        opcoes = {
            "orientation": orientacao,
            "command": comando,
            "fg_color": "#F4F6F8",
            "button_color": "#C5CDD3",
            "button_hover_color": "#1B8F4D",
            "corner_radius": 8,
            "border_spacing": 3,
        }

        if orientacao == "horizontal":
            opcoes["height"] = 12
        else:
            opcoes["width"] = 12

        opcoes.update(kwargs)
        super().__init__(master, *args, **opcoes)

    def configure(self, *args, **kwargs):
        args = list(args)
        if args and isinstance(args[0], dict):
            args[0] = {
                chave: valor
                for chave, valor in args[0].items()
                if chave not in self._kwargs_ttk_ignorados
            }
        for chave in self._kwargs_ttk_ignorados:
            kwargs.pop(chave, None)
        if "orient" in kwargs:
            kwargs["orientation"] = kwargs.pop("orient")
        return super().configure(*args, **kwargs)

    config = configure


