ARQ_CLIENTES = "clientes_enderecos.json"

def carregar_clientes():
    if os.path.exists(ARQ_CLIENTES):
        with open(ARQ_CLIENTES, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}

def salvar_cliente(nome, endereco, telefone=""):
    # Cadastro ANTIGO (JSON, 1 endereço por nome, sobrescreve). Só continua gravando
    # enquanto GRAVAR_JSON_LEGADO estiver True; o cadastro de verdade agora é o clientes.db.
    if not GRAVAR_JSON_LEGADO:
        return
    clientes = carregar_clientes()

    clientes[nome.upper()] = {
        "endereco": endereco,
        "telefone": telefone
    }

    with open(ARQ_CLIENTES, "w", encoding="utf-8") as f:
        json.dump(clientes, f, indent=4, ensure_ascii=False)

