# =====================================================
# 👥 CLIENTES — LIGAÇÃO COM O MÓDULO clientes_db.py (base clientes.db)
# =====================================================
# Cliente = TELEFONE (não mais o nome): dois clientes com o mesmo nome e
# telefones diferentes são dois cadastros e nada é sobrescrito.
#
#   * No campo Cliente (aba Pedidos) e nos filtros de cliente (Contas a Receber,
#     Pendências, Consumo por Cliente, Histórico) aparece uma lista de sugestões
#     com NOME + TELEFONE + ENDEREÇO enquanto se digita. Escolha com clique ou
#     com ↑/↓ + Enter. A seta ▼ (ou ↓ no campo vazio) mostra os clientes recentes.
#   * Pedidos: Enter (ou Tab) com a lista aberta escolhe o item destacado, que
#     por padrão é o PRIMEIRO da lista (nome completo digitado = o primeiro).
#     Esc fecha a lista e mantém o que foi digitado (cliente novo).
#   * Cliente novo é gravado na base ao FINALIZAR o pedido (cdb_registrar_pedido).
#   * Se clientes_db.py ou clientes.db não existirem, o sis.py segue como antes.
import re as _re_cdb
import traceback as _traceback_cdb
from tkinter import font as _tkfont_cdb

try:
    import clientes_db as _cdb
except Exception as _erro_import_cdb:
    _cdb = None
    try:
        print(f"[clientes_db] módulo indisponível, seguindo com o cadastro antigo: {_erro_import_cdb}")
    except Exception:
        pass

# Continua gravando o clientes_enderecos.json antigo em paralelo (rede de
# segurança, e caso outro programa ainda leia esse arquivo). Pode virar False
# quando nada mais depender dele.
GRAVAR_JSON_LEGADO = True

_cdb_selecoes = {}   # caminho do campo -> {"texto", "cid", "nomes", "quando"}


def _cdb_base_existe():
    try:
        return _cdb is not None and os.path.exists(_cdb.caminho_padrao(PASTA_BASE))
    except Exception:
        return False


def _cdb_executar(func, padrao=None):
    """Abre uma conexão curta em clientes.db, roda func(con) e fecha.
    NUNCA levanta erro: em qualquer falha devolve 'padrao'."""
    if _cdb is None:
        return padrao
    con = None
    try:
        caminho = _cdb.caminho_padrao(PASTA_BASE)
        if not os.path.exists(caminho):
            return padrao
        con = _cdb.abrir(caminho)
        if not _cdb._base_pronta(con):
            return padrao
        return func(con)
    except Exception as erro:
        try:
            print(f"[clientes_db] consulta ignorada: {erro}")
        except Exception:
            pass
        return padrao
    finally:
        try:
            if con is not None:
                con.close()
        except Exception:
            pass


def cdb_status_texto():
    if _cdb is None:
        return "[clientes_db] módulo não carregado - usando cadastro antigo (JSON)"
    if not _cdb_base_existe():
        return f"[clientes_db] clientes.db NÃO encontrado em {PASTA_BASE} - usando cadastro antigo (JSON)"
    n = _cdb_executar(lambda con: con.execute("SELECT COUNT(*) FROM clientes").fetchone()[0], None)
    return f"[clientes_db] base ativa: {n} clientes em {_cdb.caminho_padrao(PASTA_BASE)}"


def _cdb_item(d, nome, exato=False):
    ends = d.get("enderecos") or []
    return {
        "cid": d["id"],
        "nome": nome,
        "nome_principal": d.get("nome", ""),
        "telefone": d.get("telefone", ""),
        "telefone_fmt": d.get("telefone_fmt", ""),
        "endereco": d.get("endereco", "") or "",
        "n_enderecos": len(ends),
        "lista_enderecos": [
            str((e.get("endereco") if isinstance(e, dict) else e) or "").strip()
            for e in ends
            if str((e.get("endereco") if isinstance(e, dict) else e) or "").strip()
        ],                                    # do mais recente para o mais antigo
        "pedidos": d.get("pedidos", 0),
        "exato": exato,
    }


def _cdb_montar_sugestoes(achados, texto, limite):
    """Do que buscar_clientes() devolve, fica só quem COMEÇA com o que foi
    digitado (busca por telefone mantém tudo). Nome exato vem primeiro."""
    digitos = _re_cdb.sub(r"\D", "", texto)
    por_fone = len(digitos) >= 4 and len(digitos) >= len(_re_cdb.sub(r"\s", "", texto)) - 2
    alvo = _cdb.normalizar_nome(texto)
    if not alvo and not por_fone:
        return []
    saida = []
    for d in achados:
        apelidos = d.get("apelidos") or []     # já vêm do mais usado para o menos usado
        escolhido, exato = None, False
        for a in apelidos:
            if _cdb.normalizar_nome(a["nome"]) == alvo:
                escolhido, exato = a["nome"], True
                break
        if escolhido is None:
            for a in apelidos:
                if _cdb.normalizar_nome(a["nome"]).startswith(alvo):
                    escolhido = a["nome"]
                    break
        if escolhido is None:
            if not por_fone:
                continue
            escolhido = d.get("nome", "")
        saida.append(_cdb_item(d, escolhido, exato))
    saida.sort(key=lambda s: 0 if s["exato"] else 1)     # estável: mantém a ordem por uso
    return saida[:limite]


def cdb_buscar_sugestoes(texto, limite=30):
    texto = (texto or "").strip()
    if len(texto) < 2:
        return []

    def _f(con):
        achados = _cdb.buscar_clientes(con, texto, limite=80)
        return _cdb_montar_sugestoes(achados, texto, limite)
    return _cdb_executar(_f, []) or []


def cdb_clientes_recentes(limite=15):
    def _f(con):
        ids = [r[0] for r in con.execute(
            "SELECT id FROM clientes ORDER BY ultimo_uso DESC, pedidos DESC LIMIT ?", (limite,))]
        saida = []
        for cid in ids:
            d = _cdb.detalhe_cliente(con, cid)
            if d:
                saida.append(_cdb_item(d, d["nome"]))
        return saida
    return _cdb_executar(_f, []) or []


def cdb_registrar_pedido(cliente, endereco, telefone):
    """Chamar UMA vez por pedido NOVO. Telefone vazio/inválido, nome ignorado
    (mesa, teste, só números...) ou qualquer falha: não faz nada e não dá erro."""
    if _cdb is None:
        return None
    try:
        return _cdb.registrar_uso_seguro(PASTA_BASE, cliente, telefone, endereco)
    except Exception:
        return None


def cdb_telefone_por_nome(nome):
    """None = nome não está na base nova. '' = nome é de mais de um cliente
    (ambíguo) -> NÃO chuta. Senão, o telefone do único cliente com esse nome."""
    def _f(con):
        nn = _cdb.normalizar_nome(nome)
        if not nn:
            return None
        linhas = con.execute(
            "SELECT DISTINCT c.id, c.telefone FROM cliente_nomes n "
            "JOIN clientes c ON c.id = n.cliente_id WHERE n.nome_norm = ?", (nn,)).fetchall()
        if not linhas:
            return None
        if len(linhas) > 1:
            return ""
        return linhas[0][1] or ""
    return _cdb_executar(_f, None)


def telefone_cadastrado_por_nome(nome):
    """Telefone do cadastro para esse nome (usado quando o pedido não guardou o
    telefone). Base nova primeiro (homônimos = não chuta); se o nome não estiver
    nela, cai no cadastro antigo (JSON), como era antes."""
    achou = cdb_telefone_por_nome(nome)
    if achou is not None:
        return achou
    try:
        dados = carregar_clientes().get(str(nome).upper(), {})
        if isinstance(dados, dict):
            return str(dados.get("telefone", "") or dados.get("fone", "")).strip()
    except Exception:
        pass
    return ""


# ---------- filtros por cliente (Relatórios / Gestão / Histórico) ----------
def cdb_selecao_filtro(campo):
    """Cliente escolhido na lista para este campo (None se o texto foi editado
    depois da escolha ou nada foi escolhido)."""
    sel = _cdb_selecoes.get(str(campo))
    if not sel:
        return None
    try:
        if campo.get().strip().casefold() != sel["texto"].casefold():
            return None
    except Exception:
        return None
    return sel


def cdb_nomes_filtro(campo):
    """Todas as grafias do cliente escolhido (apelidos + nomes brutos), ou None."""
    sel = cdb_selecao_filtro(campo)
    if not sel:
        return None
    agora = time.time()
    if "nomes" not in sel or agora - sel.get("quando", 0) > 30:
        sel["nomes"] = _cdb_executar(lambda con: _cdb.nomes_do_cliente(con, sel["cid"]), None)
        sel["quando"] = agora
    return sel["nomes"] or None


def _cdb_chave_do_pedido(observacao):
    """Chave (DDD + 8 últimos dígitos) do telefone gravado no pedido ([TEL_PEDIDO:...] ou,
    se não houver, o contato do WhatsApp [WA_JID:...]); '' se o pedido não tem telefone
    válido. Não depende do 9º dígito: 88 9 9950-1947 e 88 9950-1947 dão a MESMA chave."""
    if _cdb is None:
        return ""
    for bruto in (extrair_telefone_observacao(observacao),
                  extrair_jid_observacao(observacao).split("@")[0]):
        if not bruto:
            continue
        try:
            r = _cdb.normalizar_telefone(bruto)
        except Exception:
            r = None
        if r:
            return r[1]
    return ""


def _cdb_contexto_cliente(sel):
    """(chave do telefone do cliente, nomes 'seguros' dele) -- só leitura em clientes.db.
    Nomes seguros = grafias do cliente que NÃO pertencem também a outro cliente (homônimos)."""
    agora = time.time()
    if "ctx" in sel and agora - sel.get("ctx_quando", 0) <= 30:
        return sel["ctx"]

    def _ler(con):
        lin = con.execute("SELECT telefone_chave FROM clientes WHERE id=?", (sel["cid"],)).fetchone()
        if not lin:
            return None
        ambiguos = {r[0] for r in con.execute(
            "SELECT nome_norm FROM cliente_nomes GROUP BY nome_norm "
            "HAVING COUNT(DISTINCT cliente_id) > 1")}
        seguros = {n.strip().lower() for n in _cdb.nomes_do_cliente(con, sel["cid"])
                   if _cdb.normalizar_nome(n) not in ambiguos}
        return (lin[0], seguros)

    ctx = _cdb_executar(_ler, None)
    if ctx:
        # Aprende os nomes que ESTE telefone já usou nos pedidos (ex.: "RENATO" e "RENATO JUJU"):
        # um pedido SEM telefone com esse nome também é dele. Nome que também aparece com OUTRO
        # telefone é ambíguo e fica de fora. Só leitura no sistema.db.
        try:
            chave, nomes = ctx
            usos = {}
            cur = conn.cursor()
            cur.execute("SELECT cliente, observacao FROM pedidos")
            for nome_p, obs_p in cur.fetchall():
                k = _cdb_chave_do_pedido(obs_p)
                if k and nome_p:
                    usos.setdefault(str(nome_p).strip().lower(), set()).add(k)
            cur.close()
            aprendidos = {n for n, ks in usos.items() if ks == {chave}}
            de_outros = {n for n, ks in usos.items() if ks - {chave}}
            ctx = (chave, (nomes | aprendidos) - de_outros)
        except Exception as erro:
            print(f"[clientes_db] nomes aprendidos dos pedidos indisponíveis ({erro})")
    sel["ctx"] = ctx
    sel["ctx_quando"] = agora
    return sel["ctx"]


def cdb_predicado_cliente(campo):
    """Cliente ESCOLHIDO na lista -> função f(cliente, observacao) -> bool que diz se o
    pedido é desse cliente. Regra: se o pedido tem telefone gravado, vale SÓ o telefone
    (ignorando o 9º dígito; o nome digitado no pedido não importa); se não tem telefone
    (pedido antigo), vale o nome. None se nada foi escolhido na lista (texto livre)."""
    sel = cdb_selecao_filtro(campo)
    if not sel:
        return None
    ctx = _cdb_contexto_cliente(sel)
    if not ctx:
        return None
    chave, nomes = ctx

    def _pred(cliente, observacao=""):
        t = _cdb_chave_do_pedido(observacao)
        if t:
            return t == chave
        return str(cliente or "").strip().lower() in nomes
    return _pred


def cdb_ids_pedidos_cliente(campo):
    """IDs dos pedidos do cliente escolhido (leitura simples da tabela pedidos; nada é
    gravado). None se nada foi escolhido na lista ou se a consulta não pôde ser feita."""
    pred = cdb_predicado_cliente(campo)
    if pred is None:
        return None
    try:
        cur = conn.cursor()
        cur.execute("SELECT id, cliente, observacao FROM pedidos")
        ids = [int(i) for i, c, o in cur.fetchall() if pred(c, o)]
        cur.close()
        return ids
    except Exception as erro:
        print(f"[clientes_db] filtro por telefone falhou ({erro}); usando os nomes do cliente")
        return None


def cdb_clausula_cliente(campo, coluna="cliente"):
    """(sql, params) para filtrar por cliente. Cliente escolhido na lista: os pedidos feitos
    com o TELEFONE dele (ignorando o 9º dígito; pedido sem telefone entra pelo nome).
    Texto livre: LIKE '%texto%' (igual ao de antes)."""
    texto = campo.get().strip()
    if not texto:
        return "", []
    ids = cdb_ids_pedidos_cliente(campo)
    if ids is not None:
        if not ids:
            return "1=0", []
        col_id = (coluna.rsplit(".", 1)[0] + ".id") if "." in coluna else "id"
        return f"{col_id} IN ({','.join(str(i) for i in ids)})", []
    nomes = cdb_nomes_filtro(campo)
    if nomes:
        marcas = ",".join("?" * len(nomes))
        return f"{coluna} COLLATE NOCASE IN ({marcas})", list(nomes)
    return f"{coluna} LIKE ?", [f"%{texto}%"]


# ---------- o campo com sugestões ----------
_TECLAS_SEM_BUSCA = {
    "Left", "Right", "Up", "Down", "Return", "KP_Enter", "Escape", "Tab", "ISO_Left_Tab",
    "Shift_L", "Shift_R", "Control_L", "Control_R", "Alt_L", "Alt_R", "Caps_Lock", "Num_Lock",
    "Home", "End", "Prior", "Next", "Insert", "Menu", "Win_L", "Win_R", "Super_L", "Super_R",
}


def ativar_busca_cliente(campo, ao_escolher=None, proximo_widget=None, ao_enter=None,
                         tab_escolhe=False, ignorar_texto=None, max_linhas=10):
    """Liga ao 'campo' (ttk.Combobox ou Entry) a lista de sugestões de clientes.

    ao_escolher(s)  : chamada depois que um cliente é escolhido (clique ou Enter);
                      'campo' já está com o nome. s = dict (cid, nome, telefone_fmt, endereco...).
    proximo_widget  : recebe o foco depois do Enter (fluxo Enter -> próximo campo).
    ao_enter()      : chamada no Enter quando NADA foi escolhido (ex.: rodar a busca).
    tab_escolhe     : Tab com a lista aberta também escolhe o destacado (aba Pedidos).
    ignorar_texto(t): True = não sugerir para esse texto (ex.: código de funcionário).

    Sem clientes_db, só liga o Enter (ao_enter / proximo_widget): tudo como antes.
    """
    def _ir_proximo():
        try:
            campo.selection_clear()
        except Exception:
            pass
        try:
            campo.icursor(tk.END)
        except Exception:
            pass
        if proximo_widget is not None:
            proximo_widget.focus_set()
            try:
                proximo_widget.selection_clear()
            except Exception:
                pass

    if _cdb is None:
        def _enter_simples(event):
            if ao_enter is not None:
                try:
                    ao_enter()
                except Exception:
                    _traceback_cdb.print_exc()
            _ir_proximo()
            return "break"
        campo.bind("<Return>", _enter_simples)
        return None

    janela = campo.winfo_toplevel()
    fonte = _tkfont_cdb.Font(family="Consolas", size=10)
    popup = tk.Toplevel(janela)
    popup.withdraw()
    popup.overrideredirect(True)
    try:
        popup.attributes("-topmost", True)
    except tk.TclError:
        pass
    lista = tk.Listbox(popup, activestyle="none", relief="flat", highlightthickness=1,
                       highlightbackground="#999999", selectbackground="#cfe8ff",
                       selectforeground="black", font=fonte, bd=0, exportselection=False)
    lista.pack(fill="both", expand=True)
    est = {"itens": [], "job": None}

    def _linha(s):
        end = s["endereco"] or "(sem endereço)"
        if len(end) > 46:
            end = end[:45] + "…"
        extra = f"  (+{s['n_enderecos'] - 1} end.)" if s["n_enderecos"] > 1 else ""
        return f"{s['nome'][:22]:<22}  {s['telefone_fmt']:<15}  {end}{extra}"

    def _fechar(event=None):
        est["itens"] = []
        try:
            if popup.winfo_exists():
                popup.withdraw()
        except tk.TclError:
            pass

    def _visivel():
        try:
            return bool(est["itens"]) and bool(popup.winfo_ismapped())
        except tk.TclError:
            return False

    def _destacar(i):
        if not est["itens"]:
            return
        i = max(0, min(len(est["itens"]) - 1, i))
        lista.selection_clear(0, tk.END)
        lista.selection_set(i)
        lista.activate(i)
        lista.see(i)

    def _indice_atual():
        sel = lista.curselection()
        return sel[0] if sel else 0

    def _mostrar(itens):
        if not itens:
            _fechar()
            return
        est["itens"] = itens
        linhas = [_linha(s) for s in itens]
        lista.delete(0, tk.END)
        for texto_linha in linhas:
            lista.insert(tk.END, texto_linha)
        larg = max(40, min(max(len(t) for t in linhas), 100))
        lista.configure(width=larg, height=min(len(linhas), max_linhas))
        _destacar(0)                       # o primeiro da lista já nasce destacado
        popup.update_idletasks()
        x = campo.winfo_rootx()
        y = campo.winfo_rooty() + campo.winfo_height()
        w, h = popup.winfo_reqwidth(), popup.winfo_reqheight()
        sw, sh = campo.winfo_screenwidth(), campo.winfo_screenheight()
        if x + w > sw:
            x = max(0, sw - w)
        if y + h > sh:                     # sem espaço embaixo: abre por cima do campo
            y = max(0, campo.winfo_rooty() - h)
        popup.geometry(f"+{x}+{y}")
        popup.deiconify()
        popup.lift()

    def _cancelar_busca_pendente():
        if est["job"] is not None:
            try:
                janela.after_cancel(est["job"])
            except Exception:
                pass
            est["job"] = None

    def _buscar_agora():
        _cancelar_busca_pendente()
        texto = campo.get().strip()
        if len(texto) < 2:
            return []
        if ignorar_texto is not None:
            try:
                if ignorar_texto(texto):
                    return []
            except Exception:
                pass
        return cdb_buscar_sugestoes(texto, 30)

    def _escolher(i):
        itens = est["itens"]
        if not (0 <= i < len(itens)):
            return
        s = itens[i]
        _fechar()
        campo.delete(0, tk.END)
        campo.insert(0, s["nome"])
        campo.icursor(tk.END)
        _cdb_selecoes[str(campo)] = {"texto": s["nome"], "cid": s["cid"]}
        if ao_escolher is not None:
            try:
                ao_escolher(s)
            except Exception:
                _traceback_cdb.print_exc()

    def _sincronizar_pendente():
        """Digitou e já deu Enter/Tab antes da lista aparecer: busca na hora."""
        if est["job"] is not None:
            _mostrar(_buscar_agora())

    # ---- eventos ----
    def _ao_digitar(event):
        ks = event.keysym
        if ks in _TECLAS_SEM_BUSCA or (ks.startswith("F") and ks[1:].isdigit()):
            return
        try:
            if (event.state & 0x4) and ks.lower() in ("a", "c"):   # Ctrl+A / Ctrl+C
                return
        except Exception:
            pass
        _cancelar_busca_pendente()
        est["job"] = janela.after(130, _busca_agendada)

    def _busca_agendada():
        est["job"] = None
        try:
            if janela.focus_get() is not campo:
                return
        except Exception:
            pass
        _mostrar(_buscar_agora())

    def _ao_enter(event):
        _sincronizar_pendente()
        if _visivel():
            _escolher(_indice_atual())
        elif ao_enter is not None:
            try:
                ao_enter()
            except Exception:
                _traceback_cdb.print_exc()
        _ir_proximo()
        return "break"

    def _ao_tab(event):
        if tab_escolhe:
            _sincronizar_pendente()
            if _visivel():
                _escolher(_indice_atual())
        return None                        # o Tab segue o caminho normal

    def _abrir_lista():
        itens = _buscar_agora()
        if not itens:
            itens = cdb_clientes_recentes(15)
        _mostrar(itens)

    def _ao_descer(event):
        if _visivel():
            _destacar(_indice_atual() + 1)
        else:
            _abrir_lista()
        return "break"

    def _ao_subir(event):
        if _visivel():
            _destacar(_indice_atual() - 1)
        return "break"

    def _ao_escape(event):
        if _visivel():
            _fechar()
            return "break"
        return None

    def _ao_clique_campo(event):
        try:
            elemento = str(campo.identify(event.x, event.y)).lower()
        except Exception:
            elemento = ""
        try:
            na_borda_direita = event.x >= campo.winfo_width() - 18
        except Exception:
            na_borda_direita = False
        if "arrow" in elemento or na_borda_direita:   # clicou na setinha ▼ do combobox
            campo.focus_set()
            if _visivel():
                _fechar()
            else:
                _abrir_lista()
            return "break"
        return None

    def _ao_clicar_lista(event):
        i = lista.nearest(event.y)
        if 0 <= i < lista.size():
            _escolher(i)
        return "break"

    def _clique_fora(event):
        if _visivel() and str(event.widget) not in (str(campo), str(lista)):
            _fechar()

    def _janela_mexeu(event):
        if event.widget is janela:
            _fechar()

    lista.bind("<ButtonPress-1>", _ao_clicar_lista)
    campo.bind("<KeyRelease>", _ao_digitar, add="+")
    campo.bind("<Return>", _ao_enter)
    campo.bind("<KP_Enter>", _ao_enter)
    campo.bind("<Down>", _ao_descer)
    campo.bind("<Up>", _ao_subir)
    campo.bind("<Escape>", _ao_escape)
    campo.bind("<Tab>", _ao_tab, add="+")
    campo.bind("<ButtonPress-1>", _ao_clique_campo, add="+")
    campo.bind("<FocusOut>", lambda e: janela.after(150, _fechar), add="+")
    janela.bind("<Button-1>", _clique_fora, add="+")
    janela.bind("<Configure>", _janela_mexeu, add="+")

    def _ao_destruir(event):
        if event.widget is campo:
            try:
                popup.destroy()
            except Exception:
                pass
    campo.bind("<Destroy>", _ao_destruir, add="+")
    return _fechar


MARCADOR_TELEFONE_PEDIDO = "[TEL_PEDIDO:"
MARCADOR_JID_WHATSAPP = "[WA_JID:"

def extrair_telefone_observacao(observacao):
    texto = observacao or ""
    ini = texto.rfind(MARCADOR_TELEFONE_PEDIDO)
    if ini == -1:
        return ""
    fim = texto.find("]", ini)
    if fim == -1:
        return ""
    return texto[ini + len(MARCADOR_TELEFONE_PEDIDO):fim].strip()

def extrair_jid_observacao(observacao):
    texto = observacao or ""
    ini = texto.rfind(MARCADOR_JID_WHATSAPP)
    if ini == -1:
        return ""
    fim = texto.find("]", ini)
    if fim == -1:
        return ""
    return texto[ini + len(MARCADOR_JID_WHATSAPP):fim].strip()

def limpar_observacao_telefone(observacao):
    texto = observacao or ""
    for marcador in (MARCADOR_TELEFONE_PEDIDO, MARCADOR_JID_WHATSAPP):
        while True:
            ini = texto.rfind(marcador)
            if ini == -1:
                break
            fim = texto.find("]", ini)
            if fim == -1:
                break
            texto = (texto[:ini] + texto[fim + 1:]).rstrip()
    return texto.rstrip()

def anexar_telefone_observacao(observacao, telefone):
    texto = limpar_observacao_telefone(observacao)
    tel = str(telefone or "").strip()
    if not tel:
        return texto
    return f"{texto}\n{MARCADOR_TELEFONE_PEDIDO}{tel}]".strip()

def anexar_contato_whatsapp_observacao(observacao, telefone="", jid=""):
    texto = anexar_telefone_observacao(observacao, telefone)
    jid_limpo = str(jid or "").strip()
    if not jid_limpo:
        return texto
    return f"{texto}\n{MARCADOR_JID_WHATSAPP}{jid_limpo}]".strip()

def preservar_telefone_observacao(pedido_id, observacao):
    try:
        cursor.execute("SELECT observacao FROM pedidos WHERE id = ?", (pedido_id,))
        atual = cursor.fetchone()
        telefone = extrair_telefone_observacao(atual[0] if atual else "")
        jid = extrair_jid_observacao(atual[0] if atual else "")
    except Exception:
        telefone = ""
        jid = ""
    return anexar_contato_whatsapp_observacao(observacao, telefone, jid)

def texto_pedido(dados, *chaves, padrao=""):
    for chave in chaves:
        valor = dados.get(chave) if isinstance(dados, dict) else None
        if valor is not None and str(valor).strip():
            return str(valor).strip()
    return padrao

def montar_endereco_pedido(dados):
    endereco = texto_pedido(dados, "endereco", "endereco_completo")
    numero = texto_pedido(dados, "numero")
    bairro = texto_pedido(dados, "bairro")
    complemento = texto_pedido(dados, "complemento")
    referencia = texto_pedido(dados, "referencia")

    partes = [endereco]
    if numero and numero not in endereco:
        partes.append(f"N: {numero}")
    if bairro and bairro.lower() not in endereco.lower():
        partes.append(f"Bairro: {bairro}")
    if complemento and complemento.lower() not in endereco.lower():
        partes.append(complemento)
    if referencia and referencia.lower() not in endereco.lower():
        partes.append(f"Ref: {referencia}")
    return " - ".join([p for p in partes if p]).strip()

def normalizar_pagamento_pedido(valor):
    forma = str(valor or "").strip().lower()
    if "pix" in forma:
        return "Pix"
    if "cart" in forma:
        return "Cartão"
    if "dinheiro" in forma:
        return "Dinheiro"
    if "descarte" in forma:
        return "Descarte"
    return "Pendente"

def montar_observacao_pedido(dados):
    obs = texto_pedido(dados, "observacao", "obs")
    extras = []
    origem = texto_pedido(dados, "origem")
    forma = texto_pedido(dados, "forma_pagamento", "pagamento")
    troco = texto_pedido(dados, "troco")
    tipo_entrega = texto_pedido(dados, "tipo_entrega")
    referencia = texto_pedido(dados, "referencia")
    bairro = texto_pedido(dados, "bairro")

    if origem:
        extras.append(f"ORIGEM: {origem}")
    if forma:
        extras.append(f"PAGTO: {forma}")
    if troco:
        extras.append(f"TROCO: {troco}")
    if tipo_entrega:
        extras.append(f"TIPO: {tipo_entrega}")
    if bairro:
        extras.append(f"BAIRRO: {bairro}")
    if referencia:
        extras.append(f"REF: {referencia}")

    # Remove marcadores do obs para nao duplicar, mas preserva os valores
    obs_limpo = limpar_observacao_telefone(obs)
    jid_existente = extrair_jid_observacao(obs)
    tel_existente = extrair_telefone_observacao(obs)

    # Fallback: pega jid/tel dos campos diretos do JSON (pedidos do site)
    jid_json = texto_pedido(dados, "jid")
    tel_json = texto_pedido(dados, "telefone", "fone", "whatsapp")

    jid_final = jid_existente or jid_json
    tel_final = tel_existente or tel_json

    texto = obs_limpo.strip()
    if extras:
        bloco = " | ".join(extras)
        texto = f"{texto}\n{bloco}".strip()

    # Reanexar marcadores para que o botao ENT sempre encontre o JID
    texto = anexar_contato_whatsapp_observacao(texto, tel_final, jid_final)
    return texto

def normalizar_item_pedido_json(item):
    if not isinstance(item, dict):
        item = {"nome_id": str(item or ""), "qtd": 1}
    nome_id = texto_pedido(item, "nome_id", "codigo")
    codigo = texto_pedido(item, "codigo")
    if not codigo and nome_id:
        codigo = nome_id.split(" - ")[0].strip()
    try:
        qtd = int(item.get("qtd", item.get("quantidade", 1)))
    except Exception:
        qtd = 1
    if qtd <= 0:
        qtd = 1
    return {
        **item,
        "nome_id": nome_id or codigo,
        "codigo": codigo,
        "qtd": qtd,
        "quantidade": qtd,
    }

def normalizar_pedido_entrada(dados):
    dados = dict(dados or {})
    itens = dados.get("itens", [])
    if isinstance(itens, str):
        try:
            itens = json.loads(itens)
        except Exception:
            itens = []
    if not isinstance(itens, list):
        itens = []

    cliente = texto_pedido(dados, "nome_cliente", "cliente", "nome", padrao="CLIENTE APP")
    telefone = texto_pedido(dados, "telefone", "fone", "whatsapp")
    endereco = montar_endereco_pedido(dados)
    pagamento = normalizar_pagamento_pedido(
        texto_pedido(dados, "forma_pagamento", "pagamento", padrao="Pendente")
    )
    observacao = montar_observacao_pedido(dados)

    dados["cliente"] = cliente
    dados["telefone"] = telefone
    dados["fone"] = telefone
    dados["endereco"] = endereco
    dados["pagamento"] = pagamento
    dados["obs"] = observacao
    dados["observacao"] = observacao
    dados["itens"] = [normalizar_item_pedido_json(item) for item in itens]
    return dados

def trazer_janela_para_frente(janela):
    try:
        janela.transient(root)
    except Exception:
        pass
    try:
        janela.lift()
        janela.attributes("-topmost", True)
        janela.after(600, lambda: janela.attributes("-topmost", False))
        janela.focus_force()
    except Exception:
        pass

def backup_automatico():

    try:

        conn.commit()

        try:
            conn.execute("PRAGMA wal_checkpoint(FULL)")
        except:
            pass

        # pasta do sistema (EXE ou PY)
        if getattr(sys, 'frozen', False):
            pasta_base = os.path.dirname(sys.executable)
        else:
            pasta_base = os.path.dirname(os.path.abspath(__file__))
        
        bat = os.path.join(
            pasta_base,
            "html",
            "fechar_cardapio.bat"
        )

        # histórico local
        pasta_historico = os.path.join(
            pasta_base,
            "backup"
        )

        os.makedirs(
            pasta_historico,
            exist_ok=True
        )

        # pasta html enviada ao github
        pasta_git = os.path.join(
            pasta_base,
            "html",
            "backup"
        )

        os.makedirs(
            pasta_git,
            exist_ok=True
        )

        # nome histórico
        nome = datetime.now().strftime(
            "backup_%d-%m-%Y_%H-%M.db"
        )

        destino_historico = os.path.join(
            pasta_historico,
            nome
        )

        # backup histórico
        bk = sqlite3.connect(
            destino_historico
        )

        conn.backup(bk)

        bk.close()


        # arquivo único github
        ultimo = os.path.join(
            pasta_git,
            "ultimo_backup.db"
        )

        if os.path.exists(ultimo):
            os.remove(ultimo)

        bk2 = sqlite3.connect(
            ultimo
        )

        conn.backup(bk2)

        bk2.close()



        if os.path.exists(bat):
            subprocess.Popen(bat)


        registrar_log("BACKUP_EXECUTADO", "BACKUP", nome, {"historico": destino_historico, "ultimo_backup": ultimo})

        print("Backup criado")

    except Exception as e:

        print(
            "Erro backup:",
            e
        )

def tocar_alerta():
    try:
        winsound.MessageBeep()
    except:
        pass

# ---------------------------------------------------------------
# SOM DE CAIXA (pagamento confirmado)
# Procura o caixa.wav em varios lugares para funcionar tanto rodando o .py
# quanto no .exe (onefile: pasta temporaria _MEIPASS; onedir/solto: pasta do exe).
# Toca em segundo plano (SND_ASYNC): nunca trava a tela. Se o arquivo nao for
# encontrado, cai no beep padrao do Windows, como era antes.
# ---------------------------------------------------------------
_SOM_CAIXA_CAMINHO = None
_SOM_CAIXA_PASTAS_PROCURADAS = []

def _localizar_som_caixa():
    global _SOM_CAIXA_CAMINHO
    if _SOM_CAIXA_CAMINHO and os.path.isfile(_SOM_CAIXA_CAMINHO):
        return _SOM_CAIXA_CAMINHO
    pastas = []
    try:
        pastas.append(sys._MEIPASS)          # exe --onefile (arquivos embutidos)
    except Exception:
        pass
    try:
        if getattr(sys, "frozen", False):
            pastas.append(os.path.dirname(sys.executable))   # ao lado do exe
    except Exception:
        pass
    try:
        pastas.append(os.path.dirname(os.path.abspath(__file__)))
    except Exception:
        pass
    pastas.append(os.path.abspath("."))
    _SOM_CAIXA_PASTAS_PROCURADAS[:] = pastas
    for pasta in pastas:
        caminho = os.path.join(pasta, "caixa.wav")
        if os.path.isfile(caminho):
            _SOM_CAIXA_CAMINHO = caminho
            return caminho
    return None

def tocar_som_caixa():
    """Toca o som de caixa registradora. Nunca levanta erro nem bloqueia.
    Escreve no console o que aconteceu ([SOM] ...) para facilitar o diagnostico."""
    try:
        caminho = _localizar_som_caixa()
        if not caminho:
            print(f"[SOM] caixa.wav NAO encontrado. Pastas procuradas: {_SOM_CAIXA_PASTAS_PROCURADAS}")
            winsound.MessageBeep(winsound.MB_ICONASTERISK)
            return
        # winsound so toca WAV PCM; confere antes para nao falhar em silencio.
        try:
            import wave
            with wave.open(caminho, "rb") as _w:
                _info = f"{_w.getnchannels()} canal(is), {_w.getsampwidth() * 8} bits, {_w.getframerate()} Hz"
        except Exception as erro_wav:
            print(f"[SOM] {caminho} nao e um WAV PCM valido ({erro_wav}). Converta para WAV PCM 16 bits.")
            winsound.MessageBeep(winsound.MB_ICONASTERISK)
            return
        print(f"[SOM] Tocando {caminho} ({_info})")
        winsound.PlaySound(
            caminho,
            winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT
        )
    except Exception as erro:
        print(f"[SOM] Erro ao tocar o som de caixa: {erro}")

# ---------------------------------------------------------------
# SOM DA BAIXA EM DINHEIRO VINDA DO APP DE ENTREGA
# Avisa o operador que o entregador recebeu dinheiro na rua (valor total,
# parcial ou maior que o da nota) para ele lembrar de prestar contas com o
# motoboy. Procura o arquivo nas mesmas pastas do caixa.wav. Se nao achar (ou
# se nao for um WAV PCM valido), cai no caixa.wav e, em ultimo caso, no beep
# padrao do Windows. Toca em segundo plano (SND_ASYNC): nunca trava a tela.
# ---------------------------------------------------------------
_SOM_ENTREGA_DINHEIRO_ARQUIVO = "entrega_caixa_abre_sino1.wav"
_SOM_ENTREGA_DINHEIRO_CAMINHO = None

def _localizar_som_entrega_dinheiro():
    global _SOM_ENTREGA_DINHEIRO_CAMINHO
    if _SOM_ENTREGA_DINHEIRO_CAMINHO and os.path.isfile(_SOM_ENTREGA_DINHEIRO_CAMINHO):
        return _SOM_ENTREGA_DINHEIRO_CAMINHO
    pastas = []
    try:
        pastas.append(sys._MEIPASS)          # exe --onefile / pasta _internal
    except Exception:
        pass
    try:
        if getattr(sys, "frozen", False):
            pastas.append(os.path.dirname(sys.executable))   # ao lado do exe
    except Exception:
        pass
    try:
        pastas.append(os.path.dirname(os.path.abspath(__file__)))
    except Exception:
        pass
    pastas.append(os.path.abspath("."))
    for pasta in pastas:
        caminho = os.path.join(pasta, _SOM_ENTREGA_DINHEIRO_ARQUIVO)
        if os.path.isfile(caminho):
            _SOM_ENTREGA_DINHEIRO_CAMINHO = caminho
            return caminho
    return None

def tocar_som_entrega_dinheiro():
    """Toca o som exclusivo da baixa em dinheiro do app de entrega.
    Nunca levanta erro nem bloqueia. Em caso de falha, usa o som de caixa."""
    try:
        caminho = _localizar_som_entrega_dinheiro()
        if not caminho:
            print(f"[SOM] {_SOM_ENTREGA_DINHEIRO_ARQUIVO} NAO encontrado; usando o caixa.wav.")
            tocar_som_caixa()
            return
        try:
            import wave
            with wave.open(caminho, "rb") as _w:
                _info = f"{_w.getnchannels()} canal(is), {_w.getsampwidth() * 8} bits, {_w.getframerate()} Hz"
        except Exception as erro_wav:
            print(f"[SOM] {caminho} nao e um WAV PCM valido ({erro_wav}); usando o caixa.wav.")
            tocar_som_caixa()
            return
        print(f"[SOM] Tocando {caminho} ({_info})")
        winsound.PlaySound(
            caminho,
            winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT
        )
    except Exception as erro:
        print(f"[SOM] Erro ao tocar o som de entrega em dinheiro: {erro}")
        try:
            tocar_som_caixa()
        except Exception:
            pass

# ---------------------------------------------------------------
# AVISO VISUAL DA BAIXA EM DINHEIRO VINDA DO APP DE ENTREGA
# Junto com o som: mostra um cartao pequeno no canto inferior direito da tela
# (logo acima do relogio do Windows) com pedido, cliente e valor, e destaca a
# linha do pedido na lista de vendas.
#  - O cartao pisca por 5 segundos e some sozinho.
#  - Clicar fora dele fecha (o clique continua funcionando normal no sistema).
#  - Clicar nele FIXA o cartao: ele fica ate clicar fora (ou trocar de janela),
#    dando tempo de conferir. Mesmo padrao da janela de detalhes do pedido.
#  - A linha do pedido fica destacada enquanto o cartao existir.
# Nunca levanta erro nem trava a baixa: qualquer falha aqui so e impressa.
# ---------------------------------------------------------------
_CARTAO_DINHEIRO_DURACAO_MS = 5000
_CARTAO_DINHEIRO_PISCA_MS = 450
_CARTAO_DINHEIRO_CARENCIA_S = 1.0    # clique fora logo ao aparecer nao fecha (da tempo de ler)
_CARTAO_DINHEIRO_MAX = 5             # no maximo 5 cartoes empilhados
_TAG_DESTAQUE_DINHEIRO = "destaque_dinheiro"
_cartoes_dinheiro = []               # cartoes abertos (o mais antigo primeiro)
_destaques_dinheiro = {}             # pedido_id (str) -> {"cartoes": n, "base": tags originais}
_cartao_dinheiro_bind = {"ok": False}

def _dinheiro_br(valor):
    try:
        texto = f"{float(valor):,.2f}"
        return "R$ " + texto.replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return "R$ 0,00"

def _area_util_tela():
    """(esq, topo, dir, base) da area util do monitor da janela principal, SEM a
    barra de tarefas do Windows. Se falhar, usa a tela menos 48 px embaixo."""
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.WinDLL("user32", use_last_error=True)

        class _MONITORINFO(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                        ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]

        user32.GetAncestor.argtypes = [ctypes.c_void_p, ctypes.c_uint]
        user32.GetAncestor.restype = ctypes.c_void_p
        user32.MonitorFromWindow.argtypes = [ctypes.c_void_p, ctypes.c_uint]
        user32.MonitorFromWindow.restype = ctypes.c_void_p
        user32.GetMonitorInfoW.argtypes = [ctypes.c_void_p, ctypes.POINTER(_MONITORINFO)]
        user32.GetMonitorInfoW.restype = ctypes.c_int
        hwnd = user32.GetAncestor(root.winfo_id(), 2)      # GA_ROOT
        monitor = user32.MonitorFromWindow(hwnd, 2)        # MONITOR_DEFAULTTONEAREST
        info = _MONITORINFO()
        info.cbSize = ctypes.sizeof(_MONITORINFO)
        if monitor and user32.GetMonitorInfoW(monitor, ctypes.byref(info)):
            r = info.rcWork
            return (r.left, r.top, r.right, r.bottom)
    except Exception:
        pass
    try:
        return (0, 0, root.winfo_screenwidth(), root.winfo_screenheight() - 48)
    except Exception:
        return (0, 0, 1366, 720)

def _arvores_historico_destaque():
    arvores = []
    for nome in ("lista_caixa_atual", "lista_caixa_fechado"):
        arvore = globals().get(nome)
        if arvore is not None:
            arvores.append(arvore)
    return arvores

def _tags_linha_historico(pedido_id, tag_visual):
    """Usada por carregar_historico ao (re)inserir cada linha: se o pedido esta com
    o aviso de dinheiro ativo, a linha continua destacada mesmo apos recarregar."""
    try:
        entrada = _destaques_dinheiro.get(str(pedido_id))
        if entrada:
            entrada["base"] = (tag_visual,)
            return (_TAG_DESTAQUE_DINHEIRO,)
    except Exception:
        pass
    return (tag_visual,)

def _aplicar_destaque_linha(pedido_id):
    chave = str(pedido_id)
    entrada = _destaques_dinheiro.get(chave)
    if entrada is None:
        entrada = {"cartoes": 0, "base": None}
        _destaques_dinheiro[chave] = entrada
    entrada["cartoes"] += 1
    for arvore in _arvores_historico_destaque():
        try:
            arvore.tag_configure(_TAG_DESTAQUE_DINHEIRO, background="#FFD54F",
                                 foreground="#000000", font=("Segoe UI", 9, "bold"))
            if arvore.exists(chave):
                atuais = tuple(arvore.item(chave, "tags") or ())
                if _TAG_DESTAQUE_DINHEIRO not in atuais:
                    entrada["base"] = atuais or entrada["base"]
                    arvore.item(chave, tags=(_TAG_DESTAQUE_DINHEIRO,))
        except Exception:
            pass

def _remover_destaque_linha(pedido_id):
    chave = str(pedido_id)
    entrada = _destaques_dinheiro.get(chave)
    if not entrada:
        return
    entrada["cartoes"] -= 1
    if entrada["cartoes"] > 0:
        return
    _destaques_dinheiro.pop(chave, None)
    base = tuple(entrada.get("base") or ("pendente",))
    for arvore in _arvores_historico_destaque():
        try:
            if arvore.exists(chave) and _TAG_DESTAQUE_DINHEIRO in tuple(arvore.item(chave, "tags") or ()):
                arvore.item(chave, tags=base)
        except Exception:
            pass

def _reposicionar_cartoes_dinheiro():
    """Empilha os cartoes no canto inferior direito, acima da barra de tarefas
    (o mais novo fica embaixo, perto do relogio)."""
    try:
        esq, topo, direita, base = _area_util_tela()
        margem = 12
        y = _posicionar_paineis_entrega(direita, base, margem)   # paineis fixos ficam por baixo
        for est in reversed(_cartoes_dinheiro):
            card = est["card"]
            card.update_idletasks()
            w = card.winfo_reqwidth()
            h = card.winfo_reqheight()
            y -= h
            card.geometry(f"+{direita - w - margem}+{y}")
            y -= 6
    except Exception as erro:
        print(f"[AVISO] Falha ao posicionar o cartao de dinheiro: {erro}")

def _clique_global_cartao_dinheiro(event):
    """Clique em qualquer lugar do sistema: dentro de um cartao FIXA ele; fora de
    todos fecha os cartoes. O clique nunca e consumido (segue normal no sistema)."""
    try:
        try:
            if _clique_global_paineis_entrega(event):
                return          # clique dentro do painel do entregador: nada a fechar
        except Exception:
            pass
        if not _cartoes_dinheiro:
            return
        try:
            topo = event.widget.winfo_toplevel()
        except Exception:
            topo = None
        dentro = False
        for est in list(_cartoes_dinheiro):
            if topo is not None and topo is est["card"]:
                dentro = True
                est["fixar"]()
        if dentro:
            return
        agora = time.time()
        for est in list(_cartoes_dinheiro):
            if agora - est["criado"] >= _CARTAO_DINHEIRO_CARENCIA_S:
                est["fechar"]()
    except Exception:
        pass

def _garantir_bind_cartao_dinheiro():
    if _cartao_dinheiro_bind["ok"]:
        return
    root.bind_all("<Button-1>", _clique_global_cartao_dinheiro, add="+")
    _cartao_dinheiro_bind["ok"] = True

def _abrir_cartao_dinheiro(pedido_id, cliente, valor, quita, restante_apos, excedente):
    forte, clara = ("#1B5E20", "#43A047") if quita else ("#0D47A1", "#1E88E5")
    card = tk.Toplevel(root)
    card.withdraw()
    card.overrideredirect(True)
    card.attributes("-topmost", True)
    card.configure(bg=forte, highlightthickness=2, highlightbackground=forte, highlightcolor=forte)

    nome = (cliente or "Cliente").strip()
    if len(nome) > 26:
        nome = nome[:25] + "\u2026"
    tol = globals().get("VALOR_TOLERANCIA", 0.009)
    nota = "PAGO TOTAL" if quita else f"PARCIAL \u00b7 restam {_dinheiro_br(restante_apos)}"
    if excedente and excedente > tol:
        nota += f" \u00b7 estornar {_dinheiro_br(excedente)}"

    lbl_topo = tk.Label(card, text=f"\U0001F4B5 #{pedido_id} \u00b7 {nome}", bg=forte, fg="#FFFFFF",
                        font=("Segoe UI", 9, "bold"), anchor="w", cursor="hand2")
    lbl_valor = tk.Label(card, text=_dinheiro_br(valor), bg=forte, fg="#FFFFFF",
                         font=("Segoe UI", 16, "bold"), anchor="w", cursor="hand2")
    lbl_nota = tk.Label(card, text=nota, bg=forte, fg="#FFFFFF",
                        font=("Segoe UI", 8), anchor="w", cursor="hand2")
    lbl_topo.pack(fill="x", padx=10, pady=(6, 0))
    lbl_valor.pack(fill="x", padx=10)
    lbl_nota.pack(fill="x", padx=10, pady=(0, 6))
    widgets = (card, lbl_topo, lbl_valor, lbl_nota)

    est = {"card": card, "pedido": pedido_id, "fixo": False, "fechado": False,
           "ligado": True, "criado": time.time(), "timer_pisca": None, "timer_fim": None}

    def _pintar(cor):
        for w in widgets:
            try:
                w.configure(bg=cor)
            except Exception:
                pass
        try:
            card.configure(highlightbackground=cor, highlightcolor=cor)
        except Exception:
            pass

    def _cancelar_timers():
        for chave in ("timer_pisca", "timer_fim"):
            if est[chave]:
                try:
                    card.after_cancel(est[chave])
                except Exception:
                    pass
                est[chave] = None

    def _pisca():
        est["timer_pisca"] = None
        if est["fechado"] or est["fixo"]:
            return
        est["ligado"] = not est["ligado"]
        _pintar(forte if est["ligado"] else clara)
        est["timer_pisca"] = card.after(_CARTAO_DINHEIRO_PISCA_MS, _pisca)

    def _fechar():
        if est["fechado"]:
            return
        est["fechado"] = True
        _cancelar_timers()
        try:
            _cartoes_dinheiro.remove(est)
        except ValueError:
            pass
        try:
            card.destroy()
        except Exception:
            pass
        _remover_destaque_linha(pedido_id)
        _reposicionar_cartoes_dinheiro()

    def _fim():
        est["timer_fim"] = None
        if not est["fixo"]:
            _fechar()

    def _perdeu_foco(event):
        if event.widget is card:
            _fechar()

    def _tomar_foco():
        try:
            if not est["fechado"]:
                card.focus_force()
        except Exception:
            pass

    def _fixar():
        if est["fechado"] or est["fixo"]:
            return
        est["fixo"] = True
        _cancelar_timers()
        _pintar(forte)
        try:
            card.configure(highlightbackground="#FFFFFF", highlightcolor="#FFFFFF")
            card.bind("<FocusOut>", _perdeu_foco)
            card.after(50, _tomar_foco)
        except Exception:
            pass

    est["fechar"] = _fechar
    est["fixar"] = _fixar

    _cartoes_dinheiro.append(est)
    while len(_cartoes_dinheiro) > _CARTAO_DINHEIRO_MAX:
        _cartoes_dinheiro[0]["fechar"]()
    _garantir_bind_cartao_dinheiro()
    _aplicar_destaque_linha(pedido_id)
    _reposicionar_cartoes_dinheiro()
    card.deiconify()
    card.lift()
    est["timer_pisca"] = card.after(_CARTAO_DINHEIRO_PISCA_MS, _pisca)
    est["timer_fim"] = card.after(_CARTAO_DINHEIRO_DURACAO_MS, _fim)

# ---------------------------------------------------------------
# PAINEL "A RECEBER DO ENTREGADOR"
# Janelinha FIXA (uma por entregador) que acumula, em memoria, o dinheiro que
# o entregador recebeu na rua e precisa repassar ao operador.
#  - Compacta: nome + total a receber + botao RECEBER.
#  - Clicar nela expande os detalhes (uma linha por pedido); clicar fora
#    volta ao modo compacto. Clicar NUNCA fecha: so some ao confirmar RECEBER.
#  - E movel: arraste pelo cabecalho para tirar da frente de algo em uso.
#  - Cor da linha pelo valor recebido x valor devido do pedido:
#       verde claro = exato | verde escuro = recebeu a mais (estornar)
#       azul = recebeu a menos (falta cobrar do cliente)
#  - So memoria: se o sistema fechar, a lista e perdida (entregas sao rapidas).
# Nunca levanta erro nem trava a baixa: qualquer falha aqui so e impressa.
# ---------------------------------------------------------------
_PAINEL_ENTREGA_MAX_LINHAS = 8        # linhas mostradas (o total sempre soma todas)
_PAINEL_ENTREGA_CONFIRMA_MS = 8000    # a confirmacao do RECEBER expira sozinha
_PAINEL_ENTREGA_LARGURA_DETALHES = 330
_PAINEL_FUNDO = "#263238"
_PAINEL_COR_EXATO = ("#A5D6A7", "#0B2A0E")    # (fundo, texto) verde claro
_PAINEL_COR_ACIMA = ("#1B5E20", "#FFFFFF")    # verde escuro
_PAINEL_COR_ABAIXO = ("#1565C0", "#FFFFFF")   # azul
_paineis_entrega = {}                 # chave do entregador -> estado do painel

def _chave_painel_entrega(entregador_id, entregador_nome):
    ident = str(entregador_id or "").strip()
    if not ident:
        ident = str(entregador_nome or "").strip().lower().replace(" ", "_")
    return ident or "__sem_identificacao__"

def _classificar_linha_entrega(recebido, devido):
    """Devolve (tipo, (fundo, texto), diferenca) comparando o que o entregador
    recebeu com o que o pedido devia naquele momento."""
    tol = globals().get("VALOR_TOLERANCIA", 0.009)
    if recebido > devido + tol:
        return "acima", _PAINEL_COR_ACIMA, round(recebido - devido, 2)
    if recebido < devido - tol:
        return "abaixo", _PAINEL_COR_ABAIXO, round(devido - recebido, 2)
    return "exato", _PAINEL_COR_EXATO, 0.0

def _texto_detalhe_linha_entrega(item):
    tipo, _cores, dif = _classificar_linha_entrega(item["recebido"], item["devido"])
    tol = globals().get("VALOR_TOLERANCIA", 0.009)
    rotulo = "Pedido"
    if item["total"] - item["devido"] > tol:
        rotulo = "Restante do pedido"     # ja tinha pagamento parcial antes
    base = f"{rotulo} {_dinheiro_br(item['devido'])}"
    if tipo == "acima":
        return f"{base} \u00b7 estornar {_dinheiro_br(dif)} ao cliente"
    if tipo == "abaixo":
        return f"{base} \u00b7 falta cobrar {_dinheiro_br(dif)} do cliente"
    return f"{base} \u00b7 valor exato"

def _limites_virtuais_tela():
    try:
        vx, vy = root.winfo_vrootx(), root.winfo_vrooty()
        vw, vh = root.winfo_vrootwidth(), root.winfo_vrootheight()
        if vw > 0 and vh > 0:
            return vx, vy, vx + vw, vy + vh
    except Exception:
        pass
    return 0, 0, root.winfo_screenwidth(), root.winfo_screenheight()

def _manter_painel_visivel(est):
    """Painel movido pelo operador: mantem a posicao dele, apenas garantindo que
    nao fique para fora da tela (ex.: ao expandir perto da borda)."""
    try:
        win = est["win"]
        win.update_idletasks()
        esq, topo, dir_, base = _limites_virtuais_tela()
        w, h = win.winfo_reqwidth(), win.winfo_reqheight()
        x = max(esq, min(est["x"], dir_ - w))
        y = max(topo, min(est["y"], base - h))
        est["x"], est["y"] = x, y
        win.geometry(f"+{x}+{y}")
    except Exception as erro:
        print(f"[AVISO] Falha ao ajustar o painel do entregador: {erro}")

def _posicionar_paineis_entrega(direita, base, margem):
    """Empilha os paineis que o operador NAO moveu no canto inferior direito.
    Devolve o y do topo da pilha (os cartoes piscantes ficam acima dela)."""
    y = base - margem
    for est in list(_paineis_entrega.values()):
        if est["movido"]:
            continue
        win = est["win"]
        win.update_idletasks()
        w, h = win.winfo_reqwidth(), win.winfo_reqheight()
        y -= h
        win.geometry(f"+{direita - w - margem}+{y}")
        y -= 6
    return y

def _montar_detalhes_painel_entrega(est):
    cont = est["detalhes"]
    for filho in cont.winfo_children():
        try:
            filho.destroy()
        except Exception:
            pass
    tk.Frame(cont, width=_PAINEL_ENTREGA_LARGURA_DETALHES, height=1, bg=_PAINEL_FUNDO).pack()
    itens = est["itens"]
    ocultos = max(0, len(itens) - _PAINEL_ENTREGA_MAX_LINHAS)
    if ocultos:
        lbl = tk.Label(cont, text=f"\u2026 e mais {ocultos} pedido(s) anterior(es) (j\u00e1 somados no total)",
                       bg=_PAINEL_FUNDO, fg="#B0BEC5", font=("Segoe UI", 8), anchor="w")
        lbl.pack(fill="x", padx=4)
        _ligar_arraste_painel_entrega(est, lbl, alterna=False)
    for item in itens[-_PAINEL_ENTREGA_MAX_LINHAS:]:
        _tipo, (fundo, texto), _dif = _classificar_linha_entrega(item["recebido"], item["devido"])
        nome = (item["cliente"] or "Cliente").strip()
        if len(nome) > 22:
            nome = nome[:21] + "\u2026"
        linha = tk.Frame(cont, bg=fundo)
        linha.pack(fill="x", padx=2, pady=2)
        topo = tk.Frame(linha, bg=fundo)
        topo.pack(fill="x", padx=6, pady=(3, 0))
        l1 = tk.Label(topo, text=f"#{item['pedido']} \u00b7 {nome}", bg=fundo, fg=texto,
                      font=("Segoe UI", 9, "bold"), anchor="w")
        l2 = tk.Label(topo, text=_dinheiro_br(item["recebido"]), bg=fundo, fg=texto,
                      font=("Segoe UI", 11, "bold"), anchor="e")
        l2.pack(side="right")
        l1.pack(side="left")
        l3 = tk.Label(linha, text=_texto_detalhe_linha_entrega(item), bg=fundo, fg=texto,
                      font=("Segoe UI", 8), anchor="w")
        l3.pack(fill="x", padx=6, pady=(0, 3))
        for w in (linha, topo, l1, l2, l3):
            _ligar_arraste_painel_entrega(est, w, alterna=False)
    tol = globals().get("VALOR_TOLERANCIA", 0.009)
    tot_estornar = round(sum(max(0.0, i["recebido"] - i["devido"]) for i in itens), 2)
    tot_cobrar = round(sum(max(0.0, i["devido"] - i["recebido"]) for i in itens), 2)
    if tot_estornar > tol:
        lbl = tk.Label(cont, text=f"Estornar aos clientes: {_dinheiro_br(tot_estornar)}",
                       bg=_PAINEL_FUNDO, fg="#81C784", font=("Segoe UI", 9, "bold"), anchor="w")
        lbl.pack(fill="x", padx=6, pady=(2, 0))
        _ligar_arraste_painel_entrega(est, lbl, alterna=False)
    if tot_cobrar > tol:
        lbl = tk.Label(cont, text=f"Falta cobrar dos clientes: {_dinheiro_br(tot_cobrar)}",
                       bg=_PAINEL_FUNDO, fg="#90CAF9", font=("Segoe UI", 9, "bold"), anchor="w")
        lbl.pack(fill="x", padx=6, pady=(2, 0))
        _ligar_arraste_painel_entrega(est, lbl, alterna=False)

def _atualizar_geometria_painel_entrega(est):
    try:
        est["win"].update_idletasks()
        if est["movido"]:
            _manter_painel_visivel(est)
        else:
            _reposicionar_cartoes_dinheiro()      # reposiciona paineis e cartoes
    except Exception as erro:
        print(f"[AVISO] Falha ao reposicionar o painel do entregador: {erro}")

def _sincronizar_painel_com_servidor(entregador_id, a_recolher):
    """Chamada pela aba ENTREGAS a cada status: o cartao mostra EXATAMENTE o mesmo
    "A recolher" da tabela de entregadores. Se o servidor diz que nao ha nada a recolher
    (acerto feito em outro lugar) o cartao fecha sozinho, apos 20 s para evitar corrida."""
    est = _paineis_entrega.get(str(entregador_id or "").strip())
    if not est:
        return
    tol = globals().get("VALOR_TOLERANCIA", 0.009)
    valor = round(float(a_recolher or 0), 2)
    if valor <= tol:
        desde = est.setdefault("zero_desde", time.time())
        if time.time() - desde >= 20:
            _fechar_painel_entrega(est)
        return
    est.pop("zero_desde", None)
    if est.get("total_servidor") != valor:
        est["total_servidor"] = valor
        _atualizar_painel_entrega(est)

def _atualizar_painel_entrega(est):
    itens = est["itens"]
    total = round(sum(i["recebido"] for i in itens), 2)
    if est.get("total_servidor") is not None:
        total = est["total_servidor"]          # o servidor manda: igual ao "A recolher" da aba
    est["lbl_total"].configure(text=_dinheiro_br(total))
    est["lbl_nome"].configure(text=f"\U0001F3CD {est['titulo']} \u00b7 {len(itens)} pedido(s)")
    if est["expandido"]:
        _montar_detalhes_painel_entrega(est)
    _atualizar_geometria_painel_entrega(est)

def _expandir_painel_entrega(est):
    if est["expandido"]:
        return
    est["expandido"] = True
    est["detalhes"].pack(fill="x", padx=4, pady=(0, 4))
    _montar_detalhes_painel_entrega(est)
    _atualizar_geometria_painel_entrega(est)

def _recolher_painel_entrega(est):
    _cancelar_confirmacao_painel_entrega(est)
    if not est["expandido"]:
        return
    est["expandido"] = False
    try:
        est["detalhes"].pack_forget()
    except Exception:
        pass
    _atualizar_geometria_painel_entrega(est)

def _alternar_painel_entrega(est):
    if est["expandido"]:
        _recolher_painel_entrega(est)
    else:
        _expandir_painel_entrega(est)

def _cancelar_confirmacao_painel_entrega(est):
    if est.get("timer_confirma"):
        try:
            est["win"].after_cancel(est["timer_confirma"])
        except Exception:
            pass
        est["timer_confirma"] = None
    if est.get("confirmando"):
        est["confirmando"] = False
        try:
            est["frame_confirma"].pack_forget()
            est["btn_receber"].pack(side="right", padx=(8, 0))
        except Exception:
            pass
        _atualizar_geometria_painel_entrega(est)

def _pedir_confirmacao_painel_entrega(est):
    if est.get("confirmando"):
        return
    est["confirmando"] = True
    est["confirma_desde"] = time.time()
    est["btn_receber"].pack_forget()
    est["frame_confirma"].pack(side="right", padx=(8, 0))
    est["timer_confirma"] = est["win"].after(
        _PAINEL_ENTREGA_CONFIRMA_MS, lambda: _cancelar_confirmacao_painel_entrega(est))
    _atualizar_geometria_painel_entrega(est)

def _fechar_painel_entrega(est):
    _paineis_entrega.pop(est["chave"], None)
    for chave in ("timer_confirma",):
        if est.get(chave):
            try:
                est["win"].after_cancel(est[chave])
            except Exception:
                pass
    try:
        est["win"].destroy()
    except Exception:
        pass
    _reposicionar_cartoes_dinheiro()

def _fechar_painel_por_chave(entregador_id):
    """Chamada pela aba ENTREGAS: fecha o cartao flutuante do entregador, se existir."""
    est = _paineis_entrega.get(str(entregador_id or "").strip())
    if est:
        _fechar_painel_entrega(est)

def _confirmar_recebimento_painel_entrega(est):
    # Protecao contra clique duplo: ignora confirmacao nos primeiros 0,5 s.
    if time.time() - est.get("confirma_desde", 0) < 0.5:
        return
    itens = list(est["itens"])
    total = round(sum(i["recebido"] for i in itens), 2)
    try:
        registrar_log("ACERTO_ENTREGADOR", "ENTREGAS", est["chave"], {
            "entregador": est["titulo"],
            "total_recebido_do_entregador": total,
            "pedidos": [{"pedido": i["pedido"], "recebido": i["recebido"], "devido": i["devido"]}
                        for i in itens],
        })
    except Exception as erro:
        print(f"[AVISO] Falha ao gravar o log do acerto com o entregador: {erro}")
    print(f"[ENTREGAS] Acerto com {est['titulo']}: {_dinheiro_br(total)} recebido ({len(itens)} pedido(s)).")
    try:
        import entregas_tela
        entregas_tela.repassar_em_segundo_plano(est["chave"])
    except Exception as erro:
        print(f"[AVISO] Falha ao sincronizar o repasse com o servidor: {erro}")
    _fechar_painel_entrega(est)

def _ligar_arraste_painel_entrega(est, widget, alterna):
    """Permite arrastar a janela por este widget. Se `alterna`, um clique SEM
    arrastar expande/recolhe o painel (usado no cabecalho)."""
    win = est["win"]

    def _press(e):
        est["arr"] = {"x0": e.x_root, "y0": e.y_root, "wx": win.winfo_x(), "wy": win.winfo_y(),
                      "moveu": False}

    def _move(e):
        a = est.get("arr")
        if not a:
            return
        dx, dy = e.x_root - a["x0"], e.y_root - a["y0"]
        if not a["moveu"] and abs(dx) < 4 and abs(dy) < 4:
            return
        a["moveu"] = True
        est["movido"] = True
        est["x"], est["y"] = a["wx"] + dx, a["wy"] + dy
        _manter_painel_visivel(est)

    def _solta(e):
        a = est.get("arr")
        est["arr"] = None
        if alterna and a and not a["moveu"]:
            _alternar_painel_entrega(est)

    widget.bind("<ButtonPress-1>", _press, add="+")
    widget.bind("<B1-Motion>", _move, add="+")
    widget.bind("<ButtonRelease-1>", _solta, add="+")

def _criar_painel_entrega(chave, titulo):
    win = tk.Toplevel(root)
    win.withdraw()
    win.overrideredirect(True)
    win.attributes("-topmost", True)
    win.configure(bg=_PAINEL_FUNDO, highlightthickness=2,
                  highlightbackground="#78909C", highlightcolor="#78909C")
    est = {"chave": chave, "titulo": titulo, "win": win, "itens": [], "expandido": False,
           "movido": False, "x": 0, "y": 0, "arr": None, "confirmando": False,
           "confirma_desde": 0.0, "timer_confirma": None}

    cab = tk.Frame(win, bg=_PAINEL_FUNDO, cursor="fleur")
    cab.pack(fill="x", padx=8, pady=6)
    col_esq = tk.Frame(cab, bg=_PAINEL_FUNDO, cursor="fleur")
    col_esq.pack(side="left")
    lbl_nome = tk.Label(col_esq, text="", bg=_PAINEL_FUNDO, fg="#B0BEC5",
                        font=("Segoe UI", 8, "bold"), anchor="w", cursor="fleur")
    lbl_total = tk.Label(col_esq, text="R$ 0,00", bg=_PAINEL_FUNDO, fg="#FFFFFF",
                         font=("Segoe UI", 16, "bold"), anchor="w", cursor="fleur")
    lbl_nome.pack(fill="x")
    lbl_total.pack(fill="x")

    btn_receber = tk.Button(cab, text="Receber", bg="#2E7D32", fg="#FFFFFF",
                            activebackground="#388E3C", activeforeground="#FFFFFF",
                            font=("Segoe UI", 10, "bold"), relief="flat", bd=0,
                            padx=14, pady=6, cursor="hand2",
                            command=lambda: _pedir_confirmacao_painel_entrega(est))
    btn_receber.pack(side="right", padx=(8, 0))

    frame_confirma = tk.Frame(cab, bg=_PAINEL_FUNDO)
    btn_sim = tk.Button(frame_confirma, text="\u2714 Confirmar", bg="#2E7D32", fg="#FFFFFF",
                        activebackground="#388E3C", activeforeground="#FFFFFF",
                        font=("Segoe UI", 9, "bold"), relief="flat", bd=0, padx=8, pady=6,
                        cursor="hand2",
                        command=lambda: _confirmar_recebimento_painel_entrega(est))
    btn_nao = tk.Button(frame_confirma, text="\u2716", bg="#B71C1C", fg="#FFFFFF",
                        activebackground="#C62828", activeforeground="#FFFFFF",
                        font=("Segoe UI", 9, "bold"), relief="flat", bd=0, padx=8, pady=6,
                        cursor="hand2",
                        command=lambda: _cancelar_confirmacao_painel_entrega(est))
    btn_sim.pack(side="left")
    btn_nao.pack(side="left", padx=(4, 0))

    detalhes = tk.Frame(win, bg=_PAINEL_FUNDO)

    est.update({"lbl_nome": lbl_nome, "lbl_total": lbl_total, "btn_receber": btn_receber,
                "frame_confirma": frame_confirma, "detalhes": detalhes})

    for w in (cab, col_esq, lbl_nome, lbl_total):
        _ligar_arraste_painel_entrega(est, w, alterna=True)
    return est

def _registrar_no_painel_entregador(entregador_id, entregador_nome, pedido_id, cliente,
                                    recebido, devido, total_pedido):
    chave = _chave_painel_entrega(entregador_id, entregador_nome)
    titulo = (str(entregador_nome or "").strip() or str(entregador_id or "").strip()
              or "Entregador n\u00e3o identificado")
    est = _paineis_entrega.get(chave)
    novo = est is None
    if novo:
        est = _criar_painel_entrega(chave, titulo)
        _paineis_entrega[chave] = est
    elif str(entregador_nome or "").strip():
        est["titulo"] = str(entregador_nome).strip()
    est["itens"].append({"pedido": pedido_id, "cliente": cliente,
                         "recebido": round(float(recebido or 0), 2),
                         "devido": round(float(devido or 0), 2),
                         "total": round(float(total_pedido or devido or 0), 2)})
    _garantir_bind_cartao_dinheiro()
    _atualizar_painel_entrega(est)
    if novo:
        est["win"].deiconify()
        est["win"].lift()

def _clique_global_paineis_entrega(event):
    """Clique em qualquer lugar do sistema: paineis expandidos (ou em
    confirmacao) que NAO foram clicados voltam ao modo compacto. Devolve True
    se o clique foi dentro de um painel."""
    try:
        topo = event.widget.winfo_toplevel()
    except Exception:
        topo = None
    dentro = None
    for est in list(_paineis_entrega.values()):
        if topo is not None and topo is est["win"]:
            dentro = est
    for est in list(_paineis_entrega.values()):
        if est is dentro:
            continue
        _recolher_painel_entrega(est)
    return dentro is not None

def mostrar_aviso_dinheiro_entrega(pedido_id, valor, quita, restante_apos, excedente,
                                   valor_recebido=None, devido=None, total_pedido=None,
                                   entregador_id="", entregador_nome=""):
    """Cartao + painel do entregador para a baixa em dinheiro do app de entrega.
    `valor` = o que entrou no caixa; `valor_recebido` = o que o entregador tem NA
    MAO para repassar (inclui excedente/troco). Nunca levanta erro nem bloqueia a baixa."""
    try:
        if not _eh_thread_principal():
            enfileirar_acao_ui(lambda: mostrar_aviso_dinheiro_entrega(
                pedido_id, valor, quita, restante_apos, excedente,
                valor_recebido, devido, total_pedido, entregador_id, entregador_nome))
            return
        cliente = ""
        try:
            cursor.execute("SELECT cliente FROM pedidos WHERE id=?", (pedido_id,))
            linha = cursor.fetchone()
            if linha and linha[0]:
                cliente = str(linha[0]).strip()
        except Exception:
            pass
        na_mao = valor_recebido if valor_recebido is not None else valor
        devido_ = devido if devido is not None else valor
        total_ = total_pedido if total_pedido is not None else devido_
        try:
            _abrir_cartao_dinheiro(pedido_id, cliente, na_mao, quita, restante_apos, excedente)
        except Exception as erro_cartao:
            print(f"[AVISO] Falha ao mostrar o cartao de dinheiro da entrega: {erro_cartao}")
        try:
            _registrar_no_painel_entregador(entregador_id, entregador_nome, pedido_id, cliente,
                                            na_mao, devido_, total_)
        except Exception as erro_painel:
            print(f"[AVISO] Falha ao atualizar o painel do entregador: {erro_painel}")
    except Exception as erro:
        print(f"[AVISO] Falha ao mostrar o aviso de dinheiro da entrega: {erro}")

