# ================= CAMINHO BASE DINÂMICO =================
def pasta_real():
    # Se estiver rodando como EXE
    if getattr(sys, 'frozen', False):
        return os.path.dirname(sys.executable)
    # Se estiver rodando como Script .py
    return os.path.dirname(os.path.abspath(__file__))

PASTA_BASE = pasta_real()

# Definição das pastas usando a PASTA_BASE
PASTA_BOT = os.path.join(PASTA_BASE, "BOT-WHATSAPP")
PASTA_JSON = os.path.join(PASTA_BASE, "pedidos_entrada")
PASTA_BACKUP = os.path.join(PASTA_BASE, "backup")
PASTA_NOVO_APP = os.path.join(PASTA_BASE, "novo_app")
