# =====================================================
# A7 - DIAGNOSTICO: logs\sistema_erros.log (RotatingFileHandler)
# Registra com traceback completo, nome da thread e pedido:
#   sys.excepthook, threading.excepthook, root.report_callback_exception
#   e os except de baixar_pagamento_rapido / aplicar_baixa_entrega /
#   registrar_lancamento_caixa. Nunca levanta excecao (diagnostico
#   nao pode derrubar o sistema).
# =====================================================
import logging
import logging.handlers
import traceback
import functools

VALOR_TOLERANCIA = 0.009  # tolerancia para comparar dinheiro (nunca >= / <= em float cru)

PASTA_LOGS_SISTEMA = os.path.join(PASTA_BASE, "logs")
try:
    os.makedirs(PASTA_LOGS_SISTEMA, exist_ok=True)
except Exception:
    pass
CAMINHO_LOG_ERROS = os.path.join(PASTA_LOGS_SISTEMA, "sistema_erros.log")

_logger_erros = logging.getLogger("sistema_erros")
_logger_erros.setLevel(logging.ERROR)
_logger_erros.propagate = False
if not _logger_erros.handlers:
    try:
        _handler_erros = logging.handlers.RotatingFileHandler(
            CAMINHO_LOG_ERROS, maxBytes=2 * 1024 * 1024, backupCount=5, encoding="utf-8"
        )
        _handler_erros.setFormatter(logging.Formatter("%(asctime)s | %(message)s"))
        _logger_erros.addHandler(_handler_erros)
    except Exception as _erro_log:
        print(f"⚠️ Nao foi possivel abrir {CAMINHO_LOG_ERROS}: {_erro_log}")


def registrar_erro_diagnostico(contexto, exc_info=None, pedido=None, extra=None):
    """Grava em logs\\sistema_erros.log: contexto, thread, pedido, tipo e traceback completo.
    exc_info: None (usa a excecao em tratamento), uma excecao ou uma tupla (tipo, valor, tb)."""
    try:
        if exc_info is None or exc_info is True:
            exc_info = sys.exc_info()
        elif isinstance(exc_info, BaseException):
            exc_info = (type(exc_info), exc_info, exc_info.__traceback__)
        tipo = getattr(exc_info[0], "__name__", str(exc_info[0]))
        trace = "".join(traceback.format_exception(*exc_info))
        thread_atual = threading.current_thread()
        msg = (
            f"[{contexto}] thread={thread_atual.name} "
            f"principal={thread_atual is threading.main_thread()} "
            f"pedido={'-' if pedido is None else pedido} "
            f"tipo={tipo} erro={exc_info[1]!r}"
        )
        if extra:
            msg += f" extra={extra!r}"
        _logger_erros.error(msg + "\n" + trace)
    except Exception:
        pass


_excepthook_original = sys.excepthook


def _excepthook_sistema(tp, valor, tb):
    registrar_erro_diagnostico("sys.excepthook", (tp, valor, tb))
    try:
        _excepthook_original(tp, valor, tb)
    except Exception:
        pass


sys.excepthook = _excepthook_sistema

if hasattr(threading, "excepthook"):
    _thread_excepthook_original = threading.excepthook

    def _thread_excepthook_sistema(args):
        try:
            if args.exc_type is not SystemExit:
                nome_thread = getattr(args.thread, "name", "?")
                registrar_erro_diagnostico(
                    f"threading.excepthook[{nome_thread}]",
                    (args.exc_type, args.exc_value, args.exc_traceback),
                )
        except Exception:
            pass
        try:
            _thread_excepthook_original(args)
        except Exception:
            pass

    threading.excepthook = _thread_excepthook_sistema


# =====================================================
# A2 - THREAD-SAFETY DO SQLITE / TK  (abordagem unica e consistente)
#   * Thread PRINCIPAL (Tk): usa a conexao/cursor globais (como sempre).
#   * QUALQUER OUTRA thread (Flask do garcom, monitores, Firebase...):
#     nunca usa conn/cursor globais -> abre conexao curta propria
#     (abrir_conexao_curta), grava, commit e fecha. Assim um rollback da
#     principal nao desfaz o trabalho delas e vice-versa.
#   * Nenhuma thread de fundo toca em widgets/messagebox/carregar_historico/
#     atualizar_saldo: ela chama enfileirar_acao_ui(func); a thread
#     principal executa (root.after(100, _processar_fila_acoes_ui)).
#     carregar_historico/atualizar_saldo/sincronizar_financeiro tambem
#     se auto-protegem (@somente_thread_principal): se chamadas de outra
#     thread, viram uma acao enfileirada.
# =====================================================
def _eh_thread_principal():
    return threading.current_thread() is threading.main_thread()


def abrir_conexao_curta():
    """Conexao SQLite curta e propria (mesmos PRAGMAs da global). Quem abre FECHA."""
    c = sqlite3.connect(CAMINHO_DB, timeout=30)
    try:
        c.execute("PRAGMA busy_timeout=30000")
        c.execute("PRAGMA synchronous=NORMAL")
    except Exception:
        pass
    return c


_fila_acoes_ui = queue.Queue()
_chaves_acoes_ui_pendentes = set()
_lock_acoes_ui = threading.Lock()


def enfileirar_acao_ui(func, chave=None):
    """Agenda func() para rodar na thread principal (Tk). Segura para chamar de
    qualquer thread. 'chave' (opcional) evita acumular acoes repetidas ainda
    nao executadas (ex.: varias chamadas de carregar_historico)."""
    if not callable(func):
        return False
    if chave is not None:
        with _lock_acoes_ui:
            if chave in _chaves_acoes_ui_pendentes:
                return False
            _chaves_acoes_ui_pendentes.add(chave)
    _fila_acoes_ui.put((func, chave))
    return True


def _processar_fila_acoes_ui():
    try:
        for _ in range(50):
            try:
                func, chave = _fila_acoes_ui.get_nowait()
            except queue.Empty:
                break
            if chave is not None:
                with _lock_acoes_ui:
                    _chaves_acoes_ui_pendentes.discard(chave)
            try:
                func()
            except Exception:
                registrar_erro_diagnostico("fila_acoes_ui")
    finally:
        try:
            root.after(100, _processar_fila_acoes_ui)
        except Exception:
            pass


def somente_thread_principal(func):
    """Decorator: se chamada fora da thread principal, NAO executa na hora --
    enfileira para a thread principal e retorna None."""
    @functools.wraps(func)
    def _envelope(*args, **kwargs):
        if _eh_thread_principal():
            return func(*args, **kwargs)
        chave = f"principal:{func.__name__}" if not args and not kwargs else None
        enfileirar_acao_ui(lambda: func(*args, **kwargs), chave=chave)
        return None
    return _envelope


def iniciar_transacao_imediata():
    """BEGIN IMMEDIATE na conexao global (thread principal). Se ja houver uma
    transacao implicita aberta, fecha-a antes (o sqlite3 nao aninha BEGIN)."""
    if conn.in_transaction:
        conn.commit()
    conn.execute("BEGIN IMMEDIATE")


# 🔴 CONEXÃO ÚNICA E GLOBAL
# A1: timeout=30 (espera ate 30s por um lock em vez de falhar em 5s) +
# WAL (leitores nao bloqueiam o escritor) + busy_timeout + synchronous
# NORMAL. Os MESMOS valores sao aplicados na conexao do BancoMesas
# (mesa.py). journal_mode=WAL fica gravado no arquivo do banco.
conn = sqlite3.connect(CAMINHO_DB, timeout=30, check_same_thread=False)
for _pragma_a1 in (
    "PRAGMA journal_mode=WAL",
    "PRAGMA busy_timeout=30000",
    "PRAGMA synchronous=NORMAL",
):
    try:
        _res_pragma = conn.execute(_pragma_a1).fetchone()
        if _pragma_a1.startswith("PRAGMA journal_mode"):
            print("📦 journal_mode:", _res_pragma[0] if _res_pragma else "?")
    except Exception as _erro_pragma:
        print(f"⚠️ Nao foi possivel aplicar '{_pragma_a1}': {_erro_pragma}")
