def registrar_log(acao, modulo, referencia="", detalhes="", usuario="Sistema", commit=True):
    """
    Grava em `auditoria`. Segura para qualquer thread (A2):
      * thread principal: usa o cursor/conn globais. commit=True (padrao) faz
        commit como sempre; commit=False so faz o INSERT (para ficar na MESMA
        transacao do chamador, que da o commit) e, nesse modo, um erro e
        PROPAGADO para o chamador dar rollback.
      * outra thread: conexao curta propria (commit + close); nunca toca no
        cursor global.
    """
    try:
        data_hora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        if isinstance(detalhes, (dict, list, tuple)):
            detalhes = json.dumps(detalhes, ensure_ascii=False, default=str)
        sql_log = """
            INSERT INTO auditoria (data_hora, usuario, acao, modulo, referencia, detalhes)
            VALUES (?, ?, ?, ?, ?, ?)
        """
        parametros_log = (data_hora, usuario, str(acao), str(modulo), str(referencia), str(detalhes))
        if _eh_thread_principal():
            cursor.execute(sql_log, parametros_log)
            if commit:
                conn.commit()
        else:
            conn_log = abrir_conexao_curta()
            try:
                conn_log.execute(sql_log, parametros_log)
                conn_log.commit()
            finally:
                conn_log.close()
    except Exception as e:
        try:
            print("Falha auditoria:", e)
        except Exception:
            pass
        registrar_erro_diagnostico("registrar_log", extra={"acao": acao, "referencia": referencia})
        if not commit:
            raise

def abrir_painel_auditoria(event=None):
    try:
        senha = simpledialog.askstring("Auditoria", "Senha:", show="*", parent=root)
        if senha != SENHA_AUDITORIA:
            if senha is not None:
                messagebox.showwarning("Auditoria", "Senha incorreta.")
            return
        periodo = pedir_periodo("Auditoria", parent=root)
        if not periodo:
            return
        data_ini, data_fim = periodo
        ini_sql = datetime.strptime(data_ini.strip(), "%d/%m/%Y").strftime("%Y-%m-%d 00:00:00")
        fim_sql = datetime.strptime(data_fim.strip(), "%d/%m/%Y").strftime("%Y-%m-%d 23:59:59")
        cursor.execute("""
            SELECT data_hora, usuario, acao, modulo, referencia, detalhes
            FROM auditoria
            WHERE data_hora BETWEEN ? AND ?
            ORDER BY data_hora ASC
        """, (ini_sql, fim_sql))
        linhas = cursor.fetchall()
        texto = "================================================\n"
        texto += "AUDITORIA CUMBUCA\n"
        texto += "=================\n\n"
        texto += f"DATA: {data_ini} a {data_fim}\n\n"
        texto += "HORA\nACAO\nMODULO\nREFERENCIA\nDETALHES\n"
        texto += "------------------------------------------------\n"
        for data_hora, usuario, acao, modulo, referencia, detalhes in linhas:
            try:
                hora = datetime.strptime(data_hora, "%Y-%m-%d %H:%M:%S").strftime("%d/%m/%Y %H:%M:%S")
            except Exception:
                hora = str(data_hora)
            texto += f"HORA: {hora}\n"
            texto += f"ACAO: {acao}\n"
            texto += f"MODULO: {modulo}\n"
            texto += f"REFERENCIA: {referencia}\n"
            texto += f"USUARIO: {usuario}\n"
            texto += f"DETALHES: {detalhes}\n"
            texto += "------------------------------------------------\n"
        if not linhas:
            texto += "Nenhum registro encontrado no periodo.\n"
        texto += "================================================\n"
        caminho = os.path.join(PASTA_BASE, "auditoria.txt")
        with open(caminho, "w", encoding="utf-8") as f:
            f.write(texto)
        os.startfile(caminho)
    except ValueError:
        messagebox.showerror("Auditoria", "Formato de data invalido. Use DD/MM/AAAA.")
    except Exception as e:
        messagebox.showerror("Auditoria", f"Falha ao gerar relatorio: {e}")


