# =====================================================
# REGRA 10 — PADRONIZAÇÃO ÚNICA DA FORMA DE PAGAMENTO
# Toda gravação em `caixa` DEVE passar por esta função.
# =====================================================
def padronizar_forma_pagamento(valor):
    """
    Fonte única de padronização de forma de pagamento.
    Sempre retorna exatamente um de: 'Dinheiro', 'Pix', 'Cartão',
    'Pendente' ou 'Descarte'. Elimina variações como 'PIX', 'pix',
    'CARTAO', 'dinheiro', e o bug do 'MANUAL'.
    """
    forma = str(valor or "").strip().lower()
    if "pix" in forma:
        return "Pix"
    if "cart" in forma:  # cartao, cartão, credito, débito -> Cartão
        return "Cartão"
    if "dinheiro" in forma:
        return "Dinheiro"
    if "descarte" in forma:
        return "Descarte"
    return "Pendente"


# =====================================================
# REGRA 11 — SINCRONIZAÇÃO IMEDIATA DO FINANCEIRO
# Chamar ao final de QUALQUER função que grave uma movimentação em
# `caixa` (entrada, saída, ajuste, estorno, pagamento, contas a
# receber, baixa do entregador, receita/despesa manual) — ANTES de
# a função retornar. Sem timers, sem polling, sem loops.
# =====================================================
@somente_thread_principal
def sincronizar_financeiro():
    for nome_func in (
        "atualizar_saldo",
        "carregar_historico",
        "atualizar_totais_receita",
        "carregar_receitas_caixa",
        "atualizar_contas_receber_tela",
    ):
        fn = globals().get(nome_func)
        if callable(fn):
            try:
                fn()
            except Exception as e:
                print(f"[SINCRONIZAR_FINANCEIRO] erro em {nome_func}: {e}")


def _extrair_pedido_id_descricao(descricao):
    """Extrai o numero de descricoes no formato 'Pedido #123'."""
    try:
        import re
        m = re.search(r"Pedido\s*#\s*(\d+)", str(descricao or ""), re.IGNORECASE)
        return int(m.group(1)) if m else None
    except Exception:
        return None


def _obter_ciclo_aberto_id():
    try:
        if 'ciclo_caixa_aberto' in globals() and ciclo_caixa_aberto.get("id"):
            return ciclo_caixa_aberto.get("id")
    except Exception:
        pass
    try:
        sql_ciclo = "SELECT id FROM ciclos_caixa WHERE status='ABERTO' ORDER BY id DESC LIMIT 1"
        if _eh_thread_principal():
            cursor.execute(sql_ciclo)
            row = cursor.fetchone()
        else:
            # Fora da thread principal NUNCA usa o cursor global (conexao curta propria).
            conn_ciclo = abrir_conexao_curta()
            try:
                row = conn_ciclo.execute(sql_ciclo).fetchone()
            finally:
                conn_ciclo.close()
        return row[0] if row else None
    except Exception:
        return None


def registrar_lancamento_caixa(tipo, descricao, valor, forma, pedido_id=None, ciclo_id=None, estornado_de=None, commit=True, categoria=None):
    """
    Ponto unico de gravacao em `caixa` (Regras 1, 9 e 10).
    Garante rastreio por ciclo_id e, quando for pedido, por pedido_id.

    commit=True (padrao): comportamento de sempre (INSERT + commit +
    sincronizar_financeiro).
    commit=False: faz SO o INSERT -- sem commit e sem
    sincronizar_financeiro -- para ser usado dentro de uma transacao
    maior (ex.: UPDATE pedidos + caixa + log). O CHAMADOR deve dar
    conn.commit() e, depois, sincronizar_financeiro() (ou rollback em
    caso de erro). Retorna o id do lancamento nos dois modos.

    Thread-safety: na thread principal usa o cursor/conn globais (como
    sempre). Em QUALQUER outra thread usa conexao curta propria (commit +
    close); nesse caso commit=False nao e aceito (nao ha transacao do
    chamador para participar) e o lancamento e sempre confirmado; a
    sincronizar_financeiro() ja se enfileira para a thread principal.
    """
    principal = _eh_thread_principal()
    if not principal and not commit:
        raise RuntimeError(
            "registrar_lancamento_caixa(commit=False) so pode ser usado na thread principal"
        )

    forma_padrao = padronizar_forma_pagamento(forma)
    c_id = ciclo_id if ciclo_id is not None else _obter_ciclo_aberto_id()

    if pedido_id is None:
        pedido_id = _extrair_pedido_id_descricao(descricao)

    conn_local = None if principal else abrir_conexao_curta()
    cur = cursor if principal else conn_local.cursor()
    try:
        if pedido_id is not None:
            try:
                pedido_id = int(pedido_id)
            except (TypeError, ValueError):
                pedido_id = None
            if pedido_id is not None:
                # Erro de banco aqui (ex.: "database is locked") NAO pode mais ser
                # engolido: antes, o lancamento ia para o caixa SEM pedido_id.
                try:
                    cur.execute("SELECT 1 FROM pedidos WHERE id=?", (pedido_id,))
                    if not cur.fetchone():
                        pedido_id = None
                except Exception:
                    registrar_erro_diagnostico("registrar_lancamento_caixa.valida_pedido", pedido=pedido_id)
                    raise

        try:
            valor = round(float(valor or 0), 2)
        except Exception:
            valor = 0.0

        agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        try:
            cur.execute("""
                INSERT INTO caixa (data, tipo, descricao, valor, pagamento, ciclo_id, pedido_id, estornado_de)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """, (agora, tipo, descricao, valor, forma_padrao, c_id, pedido_id, estornado_de))
        except Exception:
            registrar_erro_diagnostico(
                "registrar_lancamento_caixa", pedido=pedido_id,
                extra={"tipo": tipo, "valor": valor, "forma": forma_padrao, "ciclo_id": c_id, "commit": commit},
            )
            raise
        novo_id = cur.lastrowid
        if categoria:
            # Categoria do gasto (opcional). Falha aqui NUNCA derruba o lançamento.
            try:
                cur.execute("UPDATE caixa SET categoria=? WHERE id=?", (str(categoria).strip(), novo_id))
            except Exception:
                registrar_erro_diagnostico("registrar_lancamento_caixa.categoria", extra={"id": novo_id})
        if principal:
            if commit:
                conn.commit()
                sincronizar_financeiro()
        else:
            conn_local.commit()
            sincronizar_financeiro()   # enfileirada para a thread principal (decorator)
        return novo_id
    except Exception:
        if conn_local is not None:
            try:
                conn_local.rollback()
            except Exception:
                pass
        raise
    finally:
        if conn_local is not None:
            conn_local.close()


# =====================================================
# DESPESAS NO RELATORIO (aba Relatorios > Despesas)
# O relatorio de Despesas le `despesas` + `despesas_itens`. Toda saida de
# caixa que seja despesa real (compra avulsa, gas, salario, vale) precisa
# aparecer la tambem; senao o relatorio fica menor que as Saidas do Caixa.
# Estas funcoes NAO fazem commit: devem ser chamadas ANTES de
# registrar_lancamento_caixa(commit=True), cujo commit grava as duas
# coisas na mesma transacao (ou das duas nada, em caso de erro + rollback).
# =====================================================
def registrar_despesa_relatorio(fornecedor, item, valor, categoria, categoria_item=None, data_sql=None, id_despesa=None):
    """Grava despesa (mae) + item (filha) para o relatorio de Despesas.
    Se id_despesa for informado, a mae ja existe e so o item e gravado.
    Retorna o id da despesa. Sem commit."""
    valor = round(float(valor or 0), 2)
    data_sql = data_sql or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if id_despesa is None:
        cursor.execute(
            "INSERT INTO despesas (fornecedor, valor_total, data_lancamento, categoria) VALUES (?, ?, ?, ?)",
            (fornecedor, valor, data_sql, categoria)
        )
        id_despesa = cursor.lastrowid
    cursor.execute(
        "INSERT INTO despesas_itens (id_despesa, item, categoria_item, valor, data_lancamento) VALUES (?, ?, ?, ?, ?)",
        (id_despesa, (str(item or "").strip() or "DIVERSOS"), categoria_item or categoria, valor, data_sql)
    )
    return id_despesa


def remover_despesa_relatorio_do_lancamento(lancamento_id):
    """Ao estornar uma SAIDA de despesa avulsa/gas, retira a despesa
    correspondente do relatorio de Despesas (senao ela ficaria la mesmo
    com o dinheiro devolvido ao caixa). Sem commit. Retorna quantas removeu."""
    cursor.execute("SELECT descricao, valor, data FROM caixa WHERE id=?", (lancamento_id,))
    row = cursor.fetchone()
    if not row:
        return 0
    descricao, valor, data_lanc = row
    cursor.execute("""
        SELECT d.id FROM despesas d
        WHERE d.categoria IN ('DESPESA AVULSA', 'COMPRA GÁS')
          AND ABS(d.valor_total - ?) < 0.005
          AND ABS(strftime('%s', d.data_lancamento) - strftime('%s', ?)) <= 120
          AND (
                ? = COALESCE((SELECT di.item FROM despesas_itens di WHERE di.id_despesa = d.id LIMIT 1), '')
                    || ' (' || COALESCE(d.fornecedor, '') || ')'
             OR ? = 'COMPRA GÁS (' || COALESCE(d.fornecedor, '') || ')'
          )
        ORDER BY d.id DESC LIMIT 1
    """, (valor, data_lanc, descricao, descricao))
    achou = cursor.fetchone()
    if not achou:
        return 0
    cursor.execute("DELETE FROM despesas_itens WHERE id_despesa=?", (achou[0],))
    cursor.execute("DELETE FROM despesas WHERE id=?", (achou[0],))
    try:
        registrar_log("DESPESA_RELATORIO_REMOVIDA", "FINANCEIRO", lancamento_id,
                      {"id_despesa": achou[0], "descricao": descricao, "valor": valor}, commit=False)
    except Exception:
        pass
    return 1


def reparar_rastreio_caixa_antigo():
    """
    Preenche pedido_id/ciclo_id de lancamentos antigos do caixa sem rastreio.
    Nao altera valores nem formas de pagamento.
    """
    try:
        import re
        cursor.execute("""
            SELECT id, data, descricao, pedido_id, ciclo_id
            FROM caixa
            WHERE (pedido_id IS NULL OR ciclo_id IS NULL)
              AND descricao LIKE '%Pedido #%'
        """)
        linhas = cursor.fetchall()
        alterados = 0
        for lanc_id, data_lanc, desc, pedido_atual, ciclo_atual in linhas:
            novo_pedido_id = pedido_atual
            if novo_pedido_id is None:
                m = re.search(r"Pedido\s*#\s*(\d+)", str(desc or ""), re.IGNORECASE)
                if m:
                    candidato = int(m.group(1))
                    cursor.execute("SELECT 1 FROM pedidos WHERE id=?", (candidato,))
                    if cursor.fetchone():
                        novo_pedido_id = candidato

            novo_ciclo_id = ciclo_atual
            if novo_ciclo_id is None and data_lanc:
                cursor.execute("""
                    SELECT id FROM ciclos_caixa
                    WHERE abertura <= ?
                      AND (fechamento IS NULL OR fechamento >= ?)
                    ORDER BY id DESC
                    LIMIT 1
                """, (data_lanc, data_lanc))
                row_ciclo = cursor.fetchone()
                if row_ciclo:
                    novo_ciclo_id = row_ciclo[0]

            if novo_pedido_id != pedido_atual or novo_ciclo_id != ciclo_atual:
                cursor.execute(
                    "UPDATE caixa SET pedido_id=?, ciclo_id=? WHERE id=?",
                    (novo_pedido_id, novo_ciclo_id, lanc_id)
                )
                alterados += 1

        if alterados:
            conn.commit()
            print(f"[CAIXA] Rastreio antigo reparado em {alterados} lancamento(s).")
    except Exception as e:
        print(f"[CAIXA] Erro ao reparar rastreio antigo: {e}")


def estornar_lancamento_caixa(lancamento_id, motivo=""):
    """
    Regra 8 — nunca DELETE em `caixa`. Gera lançamento de estorno
    (inverso) referenciando o original; histórico permanece intacto.
    """
    cursor.execute("SELECT tipo, descricao, valor, pagamento, ciclo_id, pedido_id FROM caixa WHERE id=?", (lancamento_id,))
    row = cursor.fetchone()
    if not row:
        return None
    tipo, descricao, valor, forma, ciclo_id, pedido_id = row
    tipo_inverso = "SAIDA" if tipo == "ENTRADA" else "ENTRADA"
    desc_estorno = f"Estorno: {descricao}" + (f" ({motivo})" if motivo else "")
    novo_id = registrar_lancamento_caixa(
        tipo_inverso, desc_estorno, valor, forma,
        pedido_id=pedido_id, ciclo_id=ciclo_id, estornado_de=lancamento_id
    )
    registrar_log("ESTORNO_CAIXA", "FINANCEIRO", lancamento_id, {
        "lancamento_original": lancamento_id, "novo_lancamento": novo_id,
        "valor": valor, "forma": forma, "motivo": motivo
    })
    return novo_id

