# Função global para formatar valores em R$
def formatar_real(valor):
    valor = valor or 0
    a = f"{valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"R$ {a}"

def pedido_elegivel_contas_receber(total, valor_pago, pagamento):
    """
    Mesma regra da lista de Contas a Receber (atualizar_contas_receber_tela):
    o pedido so conta como "em aberto" se nao for CANCELADO/DESCARTE, tiver
    restante > 0 e estiver Pendente/vazio ou parcialmente pago. Usada tambem
    pela baixa automatica do Pix, para nunca baixar pedido que ja foi resolvido
    por outro caminho enquanto a cobranca estava pendente.
    """
    total = float(total or 0)
    pago = float(valor_pago or 0)
    forma = str(pagamento or "").strip().upper()
    if forma in ("CANCELADO", "DESCARTE"):
        return False
    if (total - pago) <= 0.001:
        return False
    return forma in ("", "PENDENTE") or (pago > 0.001 and pago < total - 0.001)


# =====================================================
# 📊 IMPOSTOS - CALCULO, CALENDARIO, TELA E EXPORTACOES
# =====================================================
# Regras (combinadas com o dono do sistema):
#   * Base = PEDIDOS do periodo (mesma base do Relatorio Caixa da aba Pedidos).
#   * Faturamento = Pix + Cartao + Dinheiro ja RECEBIDOS. Pendente nao entra.
#   * A forma de pagamento de cada pedido vem dos lancamentos do `caixa`
#     ligados a ele (pedido_id): assim um pedido pago em duas formas, ou em
#     parcelas, e dividido certo. Pedido antigo sem lancamento usa a forma
#     gravada no proprio pedido.
#   * Funcionario, cancelados/descartados e receitas manuais ficam FORA.
# =====================================================
import calendar as _calendar_imp
import csv as _csv_imp
import unicodedata as _unicodedata_imp
from datetime import date as _date_imp

_MESES_IMP = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",
              "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"]
_FORMAS_REAIS_IMP = ("Pix", "Cartão", "Dinheiro")


def _moeda_imp(valor):
    valor = round(float(valor or 0), 2)
    texto = f"{abs(valor):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"- R$ {texto}" if valor < 0 else f"R$ {texto}"


def _num_csv_imp(valor):
    return f"{float(valor or 0):.2f}".replace(".", ",")


def _data_br_imp(texto):
    try:
        return datetime.strptime(str(texto)[:10], "%Y-%m-%d").strftime("%d/%m/%Y")
    except Exception:
        return str(texto or "")[:10]


def _forma_imp(texto):
    """Classifica o texto de pagamento (tolerante a acento/maiuscula)."""
    t = _unicodedata_imp.normalize("NFKD", str(texto or ""))
    t = "".join(c for c in t if not _unicodedata_imp.combining(c)).strip().lower()
    if not t or t == "pendente":
        return "Pendente"
    if "descarte" in t or "cancel" in t:
        return "Cancelado"
    if "pix" in t:
        return "Pix"
    if "cart" in t or "credito" in t or "debito" in t:
        return "Cartão"
    if "dinheiro" in t:
        return "Dinheiro"
    if "funcion" in t:
        return "Funcionário"
    return "Outros"


def calcular_faturamento_impostos(cur, d_ini, d_fim):
    """Apura o faturamento recebido entre d_ini e d_fim (objetos date).
    Funcao pura: so le o banco pelo cursor recebido."""
    ini = d_ini.strftime("%Y-%m-%d")
    fim = d_fim.strftime("%Y-%m-%d")

    cur.execute("""
        SELECT id, data, COALESCE(cliente,''), COALESCE(pagamento,''),
               COALESCE(total,0), COALESCE(valor_pago,0), COALESCE(observacao,'')
        FROM pedidos
        WHERE date(data) BETWEEN ? AND ?
        ORDER BY date(data), id
    """, (ini, fim))
    pedidos = cur.fetchall()

    # Recebimentos reais de cada pedido, por forma (entradas menos estornos/ajustes)
    cur.execute("""
        SELECT c.pedido_id, c.pagamento, c.tipo, SUM(c.valor), MAX(date(c.data))
        FROM caixa c
        JOIN pedidos p ON p.id = c.pedido_id
        WHERE date(p.data) BETWEEN ? AND ?
        GROUP BY c.pedido_id, c.pagamento, c.tipo
    """, (ini, fim))
    recebimentos = {}
    for pid, pg, tipo, soma, ultima in cur.fetchall():
        reg = recebimentos.setdefault(pid, {"formas": {}, "ultima": ""})
        tipo = str(tipo or "").upper()
        forma = _forma_imp(pg)
        if forma in _FORMAS_REAIS_IMP and tipo in ("ENTRADA", "SAIDA"):
            sinal = 1.0 if tipo == "ENTRADA" else -1.0
            reg["formas"][forma] = reg["formas"].get(forma, 0.0) + sinal * float(soma or 0)
        if tipo == "ENTRADA" and ultima and ultima > reg["ultima"]:
            reg["ultima"] = ultima

    # Meses do periodo (inclusive os vazios, para o quadro ficar continuo)
    meses = {}
    a, m = d_ini.year, d_ini.month
    while (a, m) <= (d_fim.year, d_fim.month):
        meses[f"{a:04d}-{m:02d}"] = {"pix": 0.0, "cartao": 0.0, "dinheiro": 0.0,
                                     "pendente": 0.0, "n": 0}
        m += 1
        if m > 12:
            m, a = 1, a + 1

    tot = {"Pix": 0.0, "Cartão": 0.0, "Dinheiro": 0.0}
    a_receber = funcionario = sem_forma = 0.0
    n_cancelados = n_validos = pagos_depois = 0
    divergentes = []
    linhas = []

    for pid, data, cliente, pagamento, total, valor_pago, obs in pedidos:
        total = float(total or 0)
        valor_pago = float(valor_pago or 0)
        forma_ped = _forma_imp(pagamento)

        if forma_ped == "Cancelado" or "CANCELADO" in str(obs).upper():
            n_cancelados += 1
            continue

        if forma_ped == "Funcionário":
            funcionario += total
            linhas.append((pid, _data_br_imp(data), cliente, "Funcionário",
                           total, 0.0, 0.0, "Funcionário"))
            continue

        reg = recebimentos.get(pid)
        por_forma = {}
        if reg and reg["formas"]:
            por_forma = {k: round(max(0.0, v), 2) for k, v in reg["formas"].items()}
            por_forma = {k: v for k, v in por_forma.items() if v > 0.001}
            recebido_caixa = round(sum(por_forma.values()), 2)
            if abs(recebido_caixa - valor_pago) > 0.01:
                divergentes.append(pid)
        elif forma_ped in _FORMAS_REAIS_IMP:
            # Pedido antigo, sem lancamento no caixa: usa o que o pedido diz.
            por_forma = {forma_ped: round(valor_pago if valor_pago > 0.001 else total, 2)}
        elif valor_pago > 0.001:
            sem_forma += valor_pago

        recebido = round(sum(por_forma.values()), 2)
        pendente = round(max(0.0, total - recebido), 2) if forma_ped == "Pendente" else 0.0

        if forma_ped == "Pendente":
            situacao = "Parcial" if recebido > 0.001 else "Pendente"
        else:
            situacao = "Pago"

        for forma, valor in por_forma.items():
            tot[forma] += valor

        mes = meses.setdefault(str(data)[:7], {"pix": 0.0, "cartao": 0.0, "dinheiro": 0.0,
                                               "pendente": 0.0, "n": 0})
        mes["pix"] += por_forma.get("Pix", 0.0)
        mes["cartao"] += por_forma.get("Cartão", 0.0)
        mes["dinheiro"] += por_forma.get("Dinheiro", 0.0)
        mes["pendente"] += pendente
        mes["n"] += 1

        a_receber += pendente
        n_validos += 1
        if reg and reg["ultima"] and reg["ultima"] > fim and recebido > 0.001:
            pagos_depois += 1

        forma_txt = " + ".join(f for f in _FORMAS_REAIS_IMP if f in por_forma) or forma_ped
        linhas.append((pid, _data_br_imp(data), cliente, forma_txt,
                       total, recebido, pendente, situacao))

    # Conferencia: entradas de pedidos no caixa pela DATA DO RECEBIMENTO
    cur.execute("""
        SELECT c.pagamento, c.tipo, SUM(c.valor)
        FROM caixa c
        JOIN pedidos p ON p.id = c.pedido_id
        WHERE date(c.data) BETWEEN ? AND ?
          AND UPPER(COALESCE(p.pagamento,'')) NOT IN ('DESCARTE', 'CANCELADO')
          AND UPPER(COALESCE(p.observacao,'')) NOT LIKE '%CANCELADO%'
        GROUP BY c.pagamento, c.tipo
    """, (ini, fim))
    caixa_periodo = 0.0
    for pg, tipo, soma in cur.fetchall():
        if _forma_imp(pg) in _FORMAS_REAIS_IMP:
            tipo = str(tipo or "").upper()
            if tipo == "ENTRADA":
                caixa_periodo += float(soma or 0)
            elif tipo == "SAIDA":
                caixa_periodo -= float(soma or 0)

    lista_meses = []
    for chave in sorted(meses):
        v = meses[chave]
        ano_m, mes_m = chave.split("-")
        try:
            nome = f"{_MESES_IMP[int(mes_m) - 1][:3]}/{ano_m}"
        except Exception:
            nome = chave
        lista_meses.append({
            "mes": nome, "pix": round(v["pix"], 2), "cartao": round(v["cartao"], 2),
            "dinheiro": round(v["dinheiro"], 2),
            "total": round(v["pix"] + v["cartao"] + v["dinheiro"], 2),
            "pendente": round(v["pendente"], 2), "n": v["n"],
        })

    return {
        "pix": round(tot["Pix"], 2), "cartao": round(tot["Cartão"], 2),
        "dinheiro": round(tot["Dinheiro"], 2),
        "total": round(sum(tot.values()), 2),
        "a_receber": round(a_receber, 2), "funcionario": round(funcionario, 2),
        "sem_forma": round(sem_forma, 2),
        "n_cancelados": n_cancelados, "n_validos": n_validos,
        "meses": lista_meses, "pedidos": linhas,
        "caixa_periodo": round(caixa_periodo, 2),
        "divergentes": divergentes, "pagos_depois": pagos_depois,
    }


# Categoria da paleta (_PALETA_CORES_BOTAO) usada no botao do campo de data.
# Para mudar a cor de TODOS os campos de data, troque so esta linha
# ("verde", "azul", "cinza", "amarelo" ou "vermelho").
_COR_CAMPO_DATA = "azul"

# Aparencia dos dias do calendario (mesma familia de cores dos botoes do sistema)
_PAL_DIA = {"normal": "#FFFFFF", "hover": "#D5DBDB", "click": "#BDC3C7",
            "sombra": "#E5E8E8", "texto": "#2C3E50"}


def _botao_padrao(master, texto, comando=None, categoria=None, largura=110, altura=34,
                  fonte=14, raio=8, cores=None, **extra):
    """Botao no MESMO visual dos botoes do sistema (BotaoArredondadoDefinitivo):
    cantos arredondados, borda 3D e cores da _PALETA_CORES_BOTAO (escolhidas pelo
    texto, como nos demais botoes). Aceita tamanho pequeno, que a classe original
    nao permite (ela impoe largura/altura minimas)."""
    cat = categoria if categoria in _PALETA_CORES_BOTAO else _detectar_cor_botao(texto)
    pal = dict(cores) if cores else dict(_PALETA_CORES_BOTAO[cat])
    b = _BaseBotao(master, text=texto, command=comando, width=largura, height=altura,
                      corner_radius=raio, border_width=0, fg_color=pal["normal"],
                      hover_color=pal["hover"], border_color=pal["sombra"],
                      text_color=pal["texto"], text_color_disabled="#95A5A6",
                      font=("Segoe UI Semibold", max(9, round(fonte * globals().get("_ESCALA_FONTE", 1.0)))), cursor="hand2", **extra)
    b._pal_padrao = pal

    def _repouso(e=None):
        p = b._pal_padrao
        b.configure(fg_color=p["normal"], border_color=p["sombra"])

    def _clique(e=None):
        p = b._pal_padrao
        b.configure(fg_color=p["click"], border_color=p["click"])

    b.bind("<ButtonPress-1>", _clique)
    b.bind("<ButtonRelease-1>", _repouso)
    b.bind("<Leave>", _repouso)
    return b


class SeletorDataImp(tk.Toplevel):
    """Calendario de cliques, no padrao visual dos botoes do sistema.
    Usado pela aba Impostos e por todos os CampoData."""

    def __init__(self, master, data_inicial, ao_escolher, ancora=None):
        super().__init__(master)
        self._ao_escolher = ao_escolher
        self._sel = data_inicial
        self._ano, self._mes = data_inicial.year, data_inicial.month
        self.title("Escolher data")
        self.resizable(False, False)
        self.configure(bg="#FFFFFF", highlightbackground=_PALETA_CORES_BOTAO["cinza"]["normal"],
                       highlightthickness=1)
        try:
            self.transient(master.winfo_toplevel())
        except Exception:
            pass
        self._corpo = tk.Frame(self, bg="#FFFFFF")
        self._corpo.pack(padx=12, pady=12)
        self._montar()
        self._desenhar()
        self.update_idletasks()
        try:
            if ancora is not None:
                x = ancora.winfo_rootx()
                y = ancora.winfo_rooty() + ancora.winfo_height() + 4
            else:
                x = (self.winfo_screenwidth() - self.winfo_reqwidth()) // 2
                y = (self.winfo_screenheight() - self.winfo_reqheight()) // 3
            x = max(0, min(x, self.winfo_screenwidth() - self.winfo_reqwidth() - 10))
            y = max(0, min(y, self.winfo_screenheight() - self.winfo_reqheight() - 60))
            self.geometry(f"+{x}+{y}")
        except Exception:
            pass
        self.bind("<Escape>", lambda e: self.destroy())
        try:
            self.grab_set()
        except Exception:
            pass
        self.focus_set()

    def _mudar(self, meses):
        total = self._ano * 12 + (self._mes - 1) + meses
        ano, mes = divmod(total, 12)
        if 1900 <= ano <= 2200:
            self._ano, self._mes = ano, mes + 1
            self._desenhar()

    def _escolher(self, dia):
        data = _date_imp(self._ano, self._mes, dia)
        self.destroy()
        self._ao_escolher(data)

    def _montar(self):
        """Cria os widgets UMA vez; _desenhar so atualiza textos e cores."""
        fonte = "Segoe UI"
        topo = tk.Frame(self._corpo, bg="#FFFFFF")
        topo.pack(fill="x", pady=(0, 8))

        def nav(texto, meses):
            return _botao_padrao(topo, texto, lambda: self._mudar(meses), categoria="cinza",
                                 largura=38, altura=30, fonte=14, raio=8)

        nav("«", -12).pack(side="left")
        nav("‹", -1).pack(side="left", padx=(4, 0))
        nav("»", 12).pack(side="right")
        nav("›", 1).pack(side="right", padx=(0, 4))
        self._lbl_mes = tk.Label(topo, text="", bg="#FFFFFF", fg="#2C3E50",
                                 font=("Segoe UI Semibold", 12))
        self._lbl_mes.pack(side="left", expand=True)

        grade = tk.Frame(self._corpo, bg="#FFFFFF")
        grade.pack()
        for col, nome in enumerate(["D", "S", "T", "Q", "Q", "S", "S"]):
            grade.columnconfigure(col, minsize=44)
            tk.Label(grade, text=nome, bg="#FFFFFF", fg="#7F8C8D",
                     font=(fonte, 9, "bold")).grid(row=0, column=col, pady=(0, 2))
        self._dias = []
        for lin in range(1, 7):
            linha = []
            for col in range(7):
                b = _botao_padrao(grade, "", None, categoria="cinza", largura=40, altura=32,
                                  fonte=13, raio=7, cores=_PAL_DIA)
                b.grid(row=lin, column=col, padx=1, pady=1)
                linha.append(b)
            self._dias.append(linha)

        rodape = tk.Frame(self._corpo, bg="#FFFFFF")
        rodape.pack(fill="x", pady=(8, 0))
        _botao_padrao(rodape, "Hoje",
                      lambda: (self.destroy(), self._ao_escolher(_date_imp.today())),
                      largura=84, altura=32, fonte=13).pack(side="left")
        _botao_padrao(rodape, "Fechar", self.destroy,
                      largura=84, altura=32, fonte=13).pack(side="right")

    def _desenhar(self):
        self._lbl_mes.configure(text=f"{_MESES_IMP[self._mes - 1]} {self._ano}")
        hoje = _date_imp.today()
        verde = _PALETA_CORES_BOTAO["verde"]
        semanas = _calendar_imp.Calendar(firstweekday=6).monthdayscalendar(self._ano, self._mes)
        for lin in range(6):
            semana = semanas[lin] if lin < len(semanas) else [0] * 7
            for col, dia in enumerate(semana):
                b = self._dias[lin][col]
                if dia == 0:
                    b.grid_remove()
                    continue
                atual = _date_imp(self._ano, self._mes, dia)
                if atual == self._sel:
                    pal = dict(verde)
                elif atual == hoje:
                    pal = dict(_PAL_DIA, sombra=verde["normal"], hover="#EAFAF1")
                else:
                    pal = dict(_PAL_DIA)
                b._pal_padrao = pal
                b.configure(text=str(dia), command=lambda d=dia: self._escolher(d),
                            fg_color=pal["normal"], hover_color=pal["hover"],
                            border_color=pal["sombra"], text_color=pal["texto"])
                b.grid()


def _periodo_rapido_imp(nome):
    """Devolve (inicio, fim) dos atalhos de periodo."""
    hoje = _date_imp.today()

    def ultimo(ano, mes):
        return _date_imp(ano, mes, _calendar_imp.monthrange(ano, mes)[1])

    if nome == "mes_atual":
        return _date_imp(hoje.year, hoje.month, 1), ultimo(hoje.year, hoje.month)
    if nome == "mes_anterior":
        ano, mes = (hoje.year - 1, 12) if hoje.month == 1 else (hoje.year, hoje.month - 1)
        return _date_imp(ano, mes, 1), ultimo(ano, mes)
    if nome == "trimestre":
        m0 = 3 * ((hoje.month - 1) // 3) + 1
        return _date_imp(hoje.year, m0, 1), ultimo(hoje.year, m0 + 2)
    if nome == "ano_atual":
        return _date_imp(hoje.year, 1, 1), _date_imp(hoje.year, 12, 31)
    if nome == "ano_anterior":
        return _date_imp(hoje.year - 1, 1, 1), _date_imp(hoje.year - 1, 12, 31)
    return hoje, hoje


# =====================================================================
# CAMPO DE DATA COM CALENDARIO (reutiliza SeletorDataImp da aba Impostos)
# =====================================================================
def _parse_data_campo(valor):
    """Converte 'DD/MM/AAAA', 'DD/MM/AA', 'AAAA-MM-DD', date ou datetime em date.
    Vazio/None -> None. Data inexistente ou formato desconhecido -> ValueError."""
    if valor is None:
        return None
    if isinstance(valor, datetime):
        return valor.date()
    if isinstance(valor, _date_imp):
        return valor
    txt = str(valor).strip()
    if not txt:
        return None
    base = txt.split(" ")[0]
    if "/" in base:
        partes = base.split("/")
        if len(partes) == 3 and all(p.isdigit() for p in partes):
            dia, mes, ano = int(partes[0]), int(partes[1]), int(partes[2])
            if len(partes[2]) <= 2:
                ano += 2000
            return _date_imp(ano, mes, dia)
    elif "-" in base:
        partes = base.split("-")
        if len(partes) == 3 and all(p.isdigit() for p in partes):
            return _date_imp(int(partes[0]), int(partes[1]), int(partes[2]))
    raise ValueError(f"Data invalida: {valor!r}")


def _bg_pai_campo(master):
    """Cor de fundo do container (funciona com tk e ttk)."""
    try:
        return master.cget("background")
    except Exception:
        pass
    try:
        from tkinter import ttk as _ttk_cd
        estilo = _ttk_cd.Style(master)
        for nome in (master.winfo_class(), "TFrame"):
            cor = estilo.lookup(nome, "background")
            if cor:
                return cor
    except Exception:
        pass
    return "#F0F0F0"


class CampoData(tk.Frame):
    """Botao '📅  DD/MM/AAAA' que abre o calendario de cliques.

    Compativel com o antigo Entry de data: get() devolve sempre 'DD/MM/AAAA'
    (ou '' se vazio), e delete(0,'end') / insert(0, texto) / focus() / bind()
    / config(state=) continuam funcionando. Aceita grid, pack e place.
    """

    def __init__(self, master, valor=None, pode_vazio=False, ao_mudar=None, width=14, **kw):
        bg = kw.pop("bg", None) or _bg_pai_campo(master)
        super().__init__(master, bg=bg, **kw)
        self.pode_vazio = bool(pode_vazio)
        self._ao_mudar = ao_mudar
        self._habilitado = True
        self._cal = None
        self._data = None
        self._btn = _botao_padrao(self, "", self._abrir, categoria=_COR_CAMPO_DATA,
                                  largura=int(width * 12), altura=34, fonte=14)
        self._btn.pack(side="left")
        self._btn_x = None
        if self.pode_vazio:
            self._btn_x = _botao_padrao(self, "✕", self._limpar_clique, categoria="cinza",
                                        largura=34, altura=34, fonte=14)
            self._btn_x.pack(side="left", padx=(4, 0))
        if valor is None:
            self._data = None if self.pode_vazio else _date_imp.today()
        else:
            self._data = _parse_data_campo(valor)
            if self._data is None and not self.pode_vazio:
                self._data = _date_imp.today()
        self._atualizar_texto()

    # ---------- interface compativel com Entry ----------
    def get(self):
        return "" if self._data is None else self._data.strftime("%d/%m/%Y")

    def get_date(self):
        return self._data

    def set(self, valor, notificar=False):
        nova = _parse_data_campo(valor)
        if nova is None and not self.pode_vazio:
            nova = _date_imp.today()
        self._data = nova
        self._atualizar_texto()
        if notificar:
            self._chamar_ao_mudar()

    def clear(self):
        self._data = None if self.pode_vazio else _date_imp.today()
        self._atualizar_texto()

    def delete(self, first=0, last=None):
        self.clear()

    def insert(self, index, texto):
        try:
            self.set(texto)
        except ValueError:
            pass

    def focus_set(self):
        self._btn.focus_set()

    focus = focus_set

    def bind(self, sequence=None, func=None, add=True):
        return self._btn.bind(sequence, func, add=True)

    def configure(self, cnf=None, **kw):
        if "state" in kw:
            estado = kw.pop("state")
            self._habilitado = estado not in ("disabled", "readonly")
            st = "normal" if self._habilitado else "disabled"
            self._btn.configure(state=st)
            if self._btn_x is not None:
                self._btn_x.configure(state=st)
        return super().configure(cnf, **kw)

    config = configure

    # ---------- internos ----------
    def _atualizar_texto(self):
        if self._data is None:
            self._btn.configure(text="📅  Escolher data")
        else:
            self._btn.configure(text=f"📅  {self._data:%d/%m/%Y}")

    def _chamar_ao_mudar(self):
        if self._ao_mudar:
            self._ao_mudar()

    def _limpar_clique(self):
        if not self._habilitado:
            return
        self.clear()
        self._chamar_ao_mudar()

    def _abrir(self):
        if not self._habilitado:
            return
        try:
            if self._cal is not None and self._cal.winfo_exists():
                return
        except Exception:
            pass
        try:
            anterior = self.grab_current()
        except Exception:
            anterior = None

        def escolhido(d):
            self.set(d)
            self._chamar_ao_mudar()

        cal = SeletorDataImp(self, self._data or _date_imp.today(), escolhido, ancora=self._btn)
        self._cal = cal

        def restaurar_grab(ev=None):
            # Ao fechar o calendario o Tk solta o grab: devolve a janela modal de origem.
            if ev is not None and ev.widget is not cal:
                return
            def _volta():
                try:
                    if anterior is not None and anterior.winfo_exists():
                        anterior.grab_set()
                except Exception:
                    pass
            try:
                self.after_idle(_volta)
            except Exception:
                pass

        cal.bind("<Destroy>", restaurar_grab, add="+")


def _periodo_invalido(ini_txt, fim_txt, parent=None):
    """True (e avisa o usuario) se a data inicial for maior que a final."""
    try:
        d_ini = _parse_data_campo(ini_txt)
        d_fim = _parse_data_campo(fim_txt)
    except ValueError:
        return False  # formato invalido segue nas validacoes antigas de cada tela
    if d_ini and d_fim and d_ini > d_fim:
        par = (str(ini_txt), str(fim_txt))
        if parent is None or getattr(parent, "_ultimo_aviso_periodo", None) != par:
            if parent is not None:
                try:
                    parent._ultimo_aviso_periodo = par
                except Exception:
                    pass
            messagebox.showwarning("Período inválido",
                                   "A data inicial não pode ser maior que a data final.",
                                   parent=parent)
        return True
    if parent is not None:
        try:
            parent._ultimo_aviso_periodo = None
        except Exception:
            pass
    return False


def criar_atalhos_periodo(master, campo_ini, campo_fim, ao_aplicar=None, com_tudo=False):
    """Linha de atalhos (Mes atual, Mes anterior, Trimestre, Ano atual, Ano anterior)."""
    quadro = tk.Frame(master, bg=_bg_pai_campo(master))

    def aplicar(nome):
        ini, fim = _periodo_rapido_imp(nome)
        campo_ini.set(ini)
        campo_fim.set(fim)
        if ao_aplicar:
            ao_aplicar()

    def limpar():
        campo_ini.clear()
        campo_fim.clear()
        if ao_aplicar:
            ao_aplicar()

    atalhos = [("Mês atual", "mes_atual"), ("Mês anterior", "mes_anterior"),
               ("Trimestre", "trimestre"), ("Ano atual", "ano_atual"),
               ("Ano anterior", "ano_anterior")]
    for texto, nome in atalhos:
        _botao_padrao(quadro, texto, lambda n=nome: aplicar(n), categoria="cinza",
                      largura=int(len(texto) * 7 + 18), altura=28, fonte=11, raio=8
                      ).pack(side="left", padx=(0, 4))
    if com_tudo:
        _botao_padrao(quadro, "Tudo (sem filtro)", limpar, categoria="cinza",
                      largura=int(len("Tudo (sem filtro)") * 7 + 18), altura=28, fonte=11,
                      raio=8).pack(side="left", padx=(8, 0))
    return quadro


def _dialogo_datas(titulo, campos, parent=None, atalhos=False):
    """Janela modal com um ou dois CampoData. campos = [(rotulo, valor_inicial), ...].
    Devolve lista de strings 'DD/MM/AAAA' ou None se cancelar."""
    dono = parent or globals().get("root")
    dlg = tk.Toplevel(dono)
    dlg.title(titulo)
    dlg.resizable(False, False)
    dlg.configure(bg="#FFFFFF")
    try:
        dlg.transient(dono.winfo_toplevel())
    except Exception:
        pass
    corpo = tk.Frame(dlg, bg="#FFFFFF")
    corpo.pack(padx=18, pady=(14, 8))
    cs = []
    for i, (rotulo, ini) in enumerate(campos):
        tk.Label(corpo, text=rotulo, bg="#FFFFFF", fg="#1F2D26",
                 font=("Segoe UI", 10)).grid(row=i, column=0, sticky="w", padx=(0, 10), pady=4)
        c = CampoData(corpo, valor=ini, bg="#FFFFFF")
        c.grid(row=i, column=1, sticky="w", pady=4)
        cs.append(c)
    if atalhos and len(cs) == 2:
        criar_atalhos_periodo(corpo, cs[0], cs[1]).grid(
            row=len(cs), column=0, columnspan=2, sticky="w", pady=(6, 0))

    resultado = {"v": None}

    def confirmar(ev=None):
        if len(cs) == 2 and _periodo_invalido(cs[0].get(), cs[1].get(), dlg):
            return
        resultado["v"] = [c.get() for c in cs]
        dlg.destroy()

    rodape = tk.Frame(dlg, bg="#FFFFFF")
    rodape.pack(fill="x", padx=18, pady=(4, 14))
    _botao_padrao(rodape, "Confirmar", confirmar, largura=120, altura=36,
                  fonte=14).pack(side="right")
    _botao_padrao(rodape, "Cancelar", dlg.destroy, largura=120, altura=36,
                  fonte=14).pack(side="right", padx=(0, 8))
    dlg.bind("<Escape>", lambda e: dlg.destroy())
    dlg.bind("<Return>", confirmar)
    dlg.update_idletasks()
    try:
        x = dlg.winfo_screenwidth() // 2 - dlg.winfo_reqwidth() // 2
        y = dlg.winfo_screenheight() // 3
        dlg.geometry(f"+{max(0, x)}+{max(0, y)}")
    except Exception:
        pass
    try:
        dlg.wait_visibility()
        dlg.grab_set()
    except Exception:
        pass
    dlg.focus_set()
    dlg.wait_window()
    return resultado["v"]


def pedir_data(titulo, inicial=None, parent=None):
    """Substitui simpledialog.askstring de data. Devolve 'DD/MM/AAAA' ou None."""
    r = _dialogo_datas(titulo, [("Data", inicial or _date_imp.today())], parent=parent)
    return r[0] if r else None


def pedir_periodo(titulo, parent=None, ini=None, fim=None):
    """Pede data inicial e final. Devolve ('DD/MM/AAAA', 'DD/MM/AAAA') ou None."""
    hoje = _date_imp.today()
    r = _dialogo_datas(titulo, [("Data inicial", ini or hoje), ("Data final", fim or hoje)],
                       parent=parent, atalhos=True)
    return (r[0], r[1]) if r else None


def _construir_aba_impostos(aba):
    """Monta a sub aba Impostos dentro de `aba`. Devolve a funcao `atualizar`."""
    from tkinter import ttk, messagebox, filedialog
    from xml.sax.saxutils import escape as _xml_escape

    g = globals()
    C_FUNDO = g.get("cor_fundo_sistema", "#F4F6F8")
    C_VERDE = g.get("cor_principal", "#1B8F4D")
    C_VERDE_ESC = "#14452B"
    C_CARD = "#FFFFFF"
    C_TEXTO = "#1F2D26"
    C_SUAVE = "#6B7B72"
    C_BORDA = "#D6E2DA"
    C_AVISO = "#B9770E"
    FONTE = "Segoe UI"
    EMPRESA = "SABORES DA CUMBUCA"

    estado = {"ini": None, "fim": None, "res": None}
    estado["ini"], estado["fim"] = _periodo_rapido_imp("mes_atual")

    def card(parent):
        return tk.Frame(parent, bg=C_CARD, highlightbackground=C_BORDA, highlightthickness=1)

    def botao(parent, texto, comando, primario=False):
        bg = C_VERDE if primario else "#E4EFE8"
        fg = "#FFFFFF" if primario else C_VERDE_ESC
        hov = "#22A85B" if primario else "#D3E6DA"
        b = tk.Button(parent, text=texto, command=comando, bg=bg, fg=fg,
                      activebackground=hov, activeforeground=fg, relief="flat", bd=0,
                      cursor="hand2", font=(FONTE, 10, "bold"), padx=14, pady=7)
        b.bind("<Enter>", lambda e: b.configure(bg=hov))
        b.bind("<Leave>", lambda e: b.configure(bg=bg))
        return b

    raiz = tk.Frame(aba, bg=C_FUNDO)
    raiz.pack(fill="both", expand=True, padx=14, pady=10)

    # ---------------- cabecalho ----------------
    cab = tk.Frame(raiz, bg=C_FUNDO)
    cab.pack(fill="x", pady=(0, 8))
    tk.Label(cab, text="Impostos: faturamento recebido", bg=C_FUNDO, fg="#16251B",
             font=(FONTE, 16, "bold")).pack(side="left")
    lbl_periodo = tk.Label(cab, text="", bg=C_FUNDO, fg=C_SUAVE, font=(FONTE, 10))
    lbl_periodo.pack(side="right")

    # ---------------- filtro ----------------
    filtro = card(raiz)
    filtro.pack(fill="x")
    linha1 = tk.Frame(filtro, bg=C_CARD)
    linha1.pack(fill="x", padx=12, pady=(10, 4))
    tk.Label(linha1, text="Período", bg=C_CARD, fg=C_SUAVE, font=(FONTE, 10)).pack(side="left")

    def abrir_calendario(qual, ancora):
        def ao_escolher(d):
            estado[qual] = d
            atualizar()
        SeletorDataImp(raiz, estado[qual], ao_escolher, ancora=ancora)

    btn_ini = botao(linha1, "", lambda: abrir_calendario("ini", btn_ini))
    btn_ini.pack(side="left", padx=(10, 6))
    tk.Label(linha1, text="até", bg=C_CARD, fg=C_SUAVE, font=(FONTE, 10)).pack(side="left")
    btn_fim = botao(linha1, "", lambda: abrir_calendario("fim", btn_fim))
    btn_fim.pack(side="left", padx=6)
    botao(linha1, "Consultar", lambda: atualizar(), primario=True).pack(side="right")

    linha2 = tk.Frame(filtro, bg=C_CARD)
    linha2.pack(fill="x", padx=12, pady=(0, 10))

    def aplicar_atalho(nome):
        estado["ini"], estado["fim"] = _periodo_rapido_imp(nome)
        atualizar()

    for texto, nome in (("Mês atual", "mes_atual"), ("Mês anterior", "mes_anterior"),
                        ("Trimestre", "trimestre"), ("Ano atual", "ano_atual"),
                        ("Ano anterior", "ano_anterior")):
        b = tk.Button(linha2, text=texto, command=lambda n=nome: aplicar_atalho(n),
                      bg=C_CARD, fg=C_VERDE_ESC, relief="solid", bd=1, cursor="hand2",
                      font=(FONTE, 9), padx=10, pady=2, activebackground="#E4EFE8")
        b.pack(side="left", padx=(0, 6))

    # ---------------- cartoes de valores ----------------
    linha_kpi = tk.Frame(raiz, bg=C_FUNDO)
    linha_kpi.pack(fill="x", pady=(10, 0))
    for col, peso in enumerate((3, 3, 3, 4)):
        linha_kpi.columnconfigure(col, weight=peso)

    def kpi(coluna, titulo, cor, destaque=False):
        if destaque:
            c = tk.Frame(linha_kpi, bg=C_VERDE_ESC)
            tk.Label(c, text=titulo, bg=C_VERDE_ESC, fg="#BFE3CC",
                     font=(FONTE, 10)).pack(anchor="w", padx=16, pady=(12, 0))
            v = tk.Label(c, text="R$ 0,00", bg=C_VERDE_ESC, fg="#FFFFFF",
                         font=(FONTE, 24, "bold"))
            v.pack(anchor="w", padx=16, pady=(0, 12))
        else:
            c = card(linha_kpi)
            tk.Frame(c, bg=cor, width=5).pack(side="left", fill="y")
            corpo = tk.Frame(c, bg=C_CARD)
            corpo.pack(side="left", fill="both", expand=True)
            tk.Label(corpo, text=titulo, bg=C_CARD, fg=C_SUAVE,
                     font=(FONTE, 10)).pack(anchor="w", padx=12, pady=(10, 0))
            v = tk.Label(corpo, text="R$ 0,00", bg=C_CARD, fg=C_TEXTO,
                         font=(FONTE, 18, "bold"))
            v.pack(anchor="w", padx=12, pady=(0, 10))
        c.grid(row=0, column=coluna, sticky="nsew", padx=(0 if coluna == 0 else 8, 0))
        return v

    lbl_pix = kpi(0, "Pix", "#1E88A8")
    lbl_cartao = kpi(1, "Cartão", "#7B5EA7")
    lbl_din = kpi(2, "Dinheiro", "#1B8F4D")
    lbl_total = kpi(3, "Faturamento total", None, destaque=True)

    # ---------------- faixa: fora do faturamento ----------------
    faixa = card(raiz)
    faixa.pack(fill="x", pady=(8, 0))

    def item_faixa(titulo, cor_valor):
        f = tk.Frame(faixa, bg=C_CARD)
        f.pack(side="left", padx=16, pady=8)
        tk.Label(f, text=titulo, bg=C_CARD, fg=C_SUAVE, font=(FONTE, 9)).pack(anchor="w")
        v = tk.Label(f, text="-", bg=C_CARD, fg=cor_valor, font=(FONTE, 12, "bold"))
        v.pack(anchor="w")
        return v

    lbl_receber = item_faixa("A receber (pendentes, fora do total)", C_AVISO)
    lbl_func = item_faixa("Consumo de funcionário (fora do total)", C_SUAVE)
    lbl_cancel = item_faixa("Pedidos cancelados (ignorados)", C_SUAVE)

    # ---------------- tabelas ----------------
    try:
        estilo = ttk.Style()
        estilo.configure("Imp.Treeview", rowheight=26, font=(FONTE, 10))
        estilo.configure("Imp.Treeview.Heading", font=(FONTE, 10, "bold"))
    except Exception:
        pass

    nb = ttk.Notebook(raiz)
    nb.pack(fill="both", expand=True, pady=(10, 0))

    def tabela(titulo_aba, colunas):
        quadro = ttk.Frame(nb)
        nb.add(quadro, text=f"  {titulo_aba}  ")
        tree = ttk.Treeview(quadro, columns=[c[0] for c in colunas], show="headings",
                            height=8, style="Imp.Treeview")
        for chave, titulo, largura, ancora in colunas:
            tree.heading(chave, text=titulo)
            tree.column(chave, width=largura, anchor=ancora, stretch=True)
        sb = ttk.Scrollbar(quadro, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        tree.pack(side="left", fill="both", expand=True)
        tree.tag_configure("total", font=(FONTE, 10, "bold"), background="#E4EFE8")
        tree.tag_configure("pendente", foreground=C_AVISO)
        tree.tag_configure("func", foreground=C_SUAVE)
        return tree

    tree_mes = tabela("Mês a mês", [
        ("mes", "Mês", 110, "w"), ("pix", "Pix", 120, "e"), ("cartao", "Cartão", 120, "e"),
        ("dinheiro", "Dinheiro", 120, "e"), ("total", "Total recebido", 130, "e"),
        ("pendente", "A receber", 120, "e"), ("n", "Pedidos", 70, "center")])
    tree_ped = tabela("Pedidos do período", [
        ("id", "Pedido", 70, "center"), ("data", "Data", 90, "center"),
        ("cliente", "Cliente", 220, "w"), ("forma", "Forma", 150, "w"),
        ("total", "Valor do pedido", 120, "e"), ("recebido", "Recebido", 120, "e"),
        ("receber", "A receber", 110, "e"), ("situacao", "Situação", 100, "center")])

    # ---------------- conferencia ----------------
    lbl_conf = tk.Label(raiz, text="", bg=C_FUNDO, fg=C_SUAVE, font=(FONTE, 9),
                        justify="left", anchor="w", wraplength=900)
    lbl_conf.pack(fill="x", pady=(8, 0))
    raiz.bind("<Configure>", lambda e: lbl_conf.configure(wraplength=max(300, e.width - 30)))

    # ---------------- preenchimento ----------------
    def atualizar(silencioso=False):
        btn_ini.configure(text=f"📅  {estado['ini']:%d/%m/%Y}")
        btn_fim.configure(text=f"📅  {estado['fim']:%d/%m/%Y}")
        if estado["ini"] > estado["fim"]:
            estado["res"] = None
            lbl_conf.configure(fg=C_AVISO, text="⚠ A data de início é maior que a data final. "
                                                "Ajuste o período para consultar.")
            if not silencioso:
                messagebox.showwarning("Período inválido",
                                       "A data de início é maior que a data final.")
            return None
        try:
            res = calcular_faturamento_impostos(cursor, estado["ini"], estado["fim"])
        except Exception as erro:
            estado["res"] = None
            try:
                registrar_erro_diagnostico("impostos.calcular")
            except Exception:
                pass
            if not silencioso:
                messagebox.showerror("Erro", f"Não foi possível calcular o faturamento.\n\n{erro}")
            return None
        estado["res"] = res

        lbl_periodo.configure(text=f"{estado['ini']:%d/%m/%Y} a {estado['fim']:%d/%m/%Y}")
        lbl_pix.configure(text=_moeda_imp(res["pix"]))
        lbl_cartao.configure(text=_moeda_imp(res["cartao"]))
        lbl_din.configure(text=_moeda_imp(res["dinheiro"]))
        lbl_total.configure(text=_moeda_imp(res["total"]))
        lbl_receber.configure(text=_moeda_imp(res["a_receber"]))
        lbl_func.configure(text=_moeda_imp(res["funcionario"]))
        lbl_cancel.configure(text=f"{res['n_cancelados']} pedido(s)")

        tree_mes.delete(*tree_mes.get_children())
        for m in res["meses"]:
            tree_mes.insert("", "end", values=(
                m["mes"], _moeda_imp(m["pix"]), _moeda_imp(m["cartao"]),
                _moeda_imp(m["dinheiro"]), _moeda_imp(m["total"]),
                _moeda_imp(m["pendente"]), m["n"]))
        tree_mes.insert("", "end", tags=("total",), values=(
            "TOTAL", _moeda_imp(res["pix"]), _moeda_imp(res["cartao"]),
            _moeda_imp(res["dinheiro"]), _moeda_imp(res["total"]),
            _moeda_imp(res["a_receber"]), res["n_validos"]))

        tree_ped.delete(*tree_ped.get_children())
        for pid, data, cli, forma, total, recebido, receber, situ in res["pedidos"]:
            tag = ("pendente",) if situ in ("Pendente", "Parcial") else (
                ("func",) if situ == "Funcionário" else ())
            tree_ped.insert("", "end", tags=tag, values=(
                pid, data, cli, forma, _moeda_imp(total), _moeda_imp(recebido),
                _moeda_imp(receber) if receber else "-", situ))

        # Conferencia com o caixa + avisos
        dif = round(res["total"] - res["caixa_periodo"], 2)
        linhas = [f"Conferência: os pedidos do período apuram {_moeda_imp(res['total'])}; "
                  f"o caixa recebeu {_moeda_imp(res['caixa_periodo'])} em pedidos nessas datas."]
        if abs(dif) > 0.01:
            linhas.append(f"A diferença de {_moeda_imp(abs(dif))} é normal quando há pedido pago "
                          "em mês diferente do mês em que foi feito (ex.: venda pendente quitada depois).")
        alertas = []
        if res["divergentes"]:
            ids = ", ".join(str(i) for i in res["divergentes"][:8])
            mais = "..." if len(res["divergentes"]) > 8 else ""
            alertas.append(f"⚠ {len(res['divergentes'])} pedido(s) com valor recebido diferente do "
                           f"registrado no próprio pedido (nº {ids}{mais}). Vale conferir.")
        if res["sem_forma"] > 0.001:
            alertas.append(f"⚠ {_moeda_imp(res['sem_forma'])} recebidos sem forma de pagamento "
                           "identificada; esse valor NÃO entrou no total.")
        if res["pagos_depois"]:
            alertas.append(f"⚠ {res['pagos_depois']} pedido(s) deste período foram pagos depois de "
                           f"{estado['fim']:%d/%m/%Y}. Se você já declarou este período, o valor mudou.")
        lbl_conf.configure(fg=C_AVISO if alertas else C_VERDE_ESC,
                           text=("✔ " if not alertas else "") + "\n".join(linhas + alertas))
        return res

    def resultado_atual():
        res = estado["res"]
        if res is None or estado["ini"] > estado["fim"]:
            res = atualizar()
        return res

    def nome_base():
        return f"{estado['ini']:%d-%m-%Y}_a_{estado['fim']:%d-%m-%Y}"

    # ---------------- exportacoes ----------------
    def exportar_csv():
        res = resultado_atual()
        if not res:
            return
        caminho = filedialog.asksaveasfilename(
            defaultextension=".csv", filetypes=[("Planilha CSV (Excel)", "*.csv")],
            initialfile=f"faturamento_{nome_base()}.csv", title="Salvar planilha")
        if not caminho:
            return
        try:
            with open(caminho, "w", newline="", encoding="utf-8-sig") as f:
                w = _csv_imp.writer(f, delimiter=";")
                w.writerow([EMPRESA, "Faturamento recebido"])
                w.writerow(["Período", f"{estado['ini']:%d/%m/%Y}", f"{estado['fim']:%d/%m/%Y}"])
                w.writerow([])
                w.writerow(["RESUMO"])
                for nome, chave in (("Pix", "pix"), ("Cartão", "cartao"), ("Dinheiro", "dinheiro"),
                                    ("Faturamento total", "total"),
                                    ("A receber (fora do total)", "a_receber"),
                                    ("Consumo de funcionário (fora do total)", "funcionario")):
                    w.writerow([nome, _num_csv_imp(res[chave])])
                w.writerow([])
                w.writerow(["MÊS A MÊS"])
                w.writerow(["Mês", "Pix", "Cartão", "Dinheiro", "Total recebido", "A receber", "Pedidos"])
                for m in res["meses"]:
                    w.writerow([m["mes"], _num_csv_imp(m["pix"]), _num_csv_imp(m["cartao"]),
                                _num_csv_imp(m["dinheiro"]), _num_csv_imp(m["total"]),
                                _num_csv_imp(m["pendente"]), m["n"]])
                w.writerow([])
                w.writerow(["PEDIDOS"])
                w.writerow(["Pedido", "Data", "Cliente", "Forma", "Valor do pedido",
                            "Recebido", "A receber", "Situação"])
                for pid, data, cli, forma, total, recebido, receber, situ in res["pedidos"]:
                    w.writerow([pid, data, cli, forma, _num_csv_imp(total),
                                _num_csv_imp(recebido), _num_csv_imp(receber), situ])
            messagebox.showinfo("Pronto", "Planilha salva com sucesso!")
        except Exception as erro:
            messagebox.showerror("Erro", f"Não foi possível salvar a planilha.\n\n{erro}")

    def exportar_xml():
        res = resultado_atual()
        if not res:
            return
        caminho = filedialog.asksaveasfilename(
            defaultextension=".xml", filetypes=[("Arquivo XML", "*.xml")],
            initialfile=f"faturamento_{nome_base()}.xml", title="Salvar XML")
        if not caminho:
            return
        try:
            xml = (
                '<?xml version="1.0" encoding="UTF-8"?>\n'
                "<fiscal>\n"
                f"    <empresa>{_xml_escape(EMPRESA)}</empresa>\n"
                f"    <periodo>{estado['ini']:%d/%m/%Y} ate {estado['fim']:%d/%m/%Y}</periodo>\n"
                f"    <pix>{res['pix']:.2f}</pix>\n"
                f"    <cartao>{res['cartao']:.2f}</cartao>\n"
                f"    <pix_cartao>{res['pix'] + res['cartao']:.2f}</pix_cartao>\n"
                f"    <dinheiro>{res['dinheiro']:.2f}</dinheiro>\n"
                f"    <faturamento_total>{res['total']:.2f}</faturamento_total>\n"
                f"    <a_receber>{res['a_receber']:.2f}</a_receber>\n"
                "</fiscal>\n")
            with open(caminho, "w", encoding="utf-8") as f:
                f.write(xml)
            messagebox.showinfo("Pronto", "XML gerado com sucesso!")
        except Exception as erro:
            messagebox.showerror("Erro", f"Não foi possível gerar o XML.\n\n{erro}")

    def exportar_pdf():
        res = resultado_atual()
        if not res:
            return
        caminho = filedialog.asksaveasfilename(
            defaultextension=".pdf", filetypes=[("Arquivo PDF", "*.pdf")],
            initialfile=f"faturamento_{nome_base()}.pdf", title="Salvar PDF")
        if not caminho:
            return
        try:
            from reportlab.lib import colors
            from reportlab.lib.pagesizes import A4
            from reportlab.lib.styles import getSampleStyleSheet
            from reportlab.lib.units import mm
            from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle

            estilos = getSampleStyleSheet()
            verde = colors.HexColor("#14452B")
            doc = SimpleDocTemplate(caminho, pagesize=A4, leftMargin=15 * mm, rightMargin=15 * mm,
                                    topMargin=15 * mm, bottomMargin=15 * mm,
                                    title="Faturamento recebido")

            def tabela_pdf(dados, larguras, direita_a_partir=1, total_ultima=False):
                t = Table(dados, colWidths=larguras, repeatRows=1)
                cmds = [("BACKGROUND", (0, 0), (-1, 0), verde),
                        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                        ("FONTSIZE", (0, 0), (-1, -1), 8.5),
                        ("ALIGN", (direita_a_partir, 0), (-1, -1), "RIGHT"),
                        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F3F8F5")]),
                        ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#C9D8CF")),
                        ("TOPPADDING", (0, 0), (-1, -1), 3), ("BOTTOMPADDING", (0, 0), (-1, -1), 3)]
                if total_ultima:
                    cmds += [("FONTNAME", (0, -1), (-1, -1), "Helvetica-Bold"),
                             ("BACKGROUND", (0, -1), (-1, -1), colors.HexColor("#E4EFE8"))]
                t.setStyle(TableStyle(cmds))
                return t

            historia = [
                Paragraph(f"{EMPRESA}", estilos["Title"]),
                Paragraph(f"Faturamento recebido de {estado['ini']:%d/%m/%Y} a {estado['fim']:%d/%m/%Y}",
                          estilos["Heading3"]),
                Spacer(1, 6),
                tabela_pdf([["Pix", "Cartão", "Dinheiro", "Faturamento total"],
                            [_moeda_imp(res["pix"]), _moeda_imp(res["cartao"]),
                             _moeda_imp(res["dinheiro"]), _moeda_imp(res["total"])]],
                           [45 * mm] * 4, direita_a_partir=0),
                Spacer(1, 4),
                Paragraph(f"Fora do total: a receber (pendentes) {_moeda_imp(res['a_receber'])}; "
                          f"consumo de funcionário {_moeda_imp(res['funcionario'])}.", estilos["Normal"]),
                Spacer(1, 10),
                Paragraph("Mês a mês", estilos["Heading3"]),
            ]
            dados_mes = [["Mês", "Pix", "Cartão", "Dinheiro", "Total", "A receber", "Pedidos"]]
            for m in res["meses"]:
                dados_mes.append([m["mes"], _moeda_imp(m["pix"]), _moeda_imp(m["cartao"]),
                                  _moeda_imp(m["dinheiro"]), _moeda_imp(m["total"]),
                                  _moeda_imp(m["pendente"]), str(m["n"])])
            dados_mes.append(["TOTAL", _moeda_imp(res["pix"]), _moeda_imp(res["cartao"]),
                              _moeda_imp(res["dinheiro"]), _moeda_imp(res["total"]),
                              _moeda_imp(res["a_receber"]), str(res["n_validos"])])
            historia.append(tabela_pdf(dados_mes, [24 * mm, 27 * mm, 27 * mm, 27 * mm, 28 * mm,
                                                   27 * mm, 16 * mm], total_ultima=True))
            historia += [Spacer(1, 12), Paragraph("Pedidos do período", estilos["Heading3"])]
            dados_ped = [["Pedido", "Data", "Cliente", "Forma", "Valor", "Recebido", "Situação"]]
            for pid, data, cli, forma, total, recebido, receber, situ in res["pedidos"]:
                dados_ped.append([str(pid), data, str(cli)[:24], forma, _moeda_imp(total),
                                  _moeda_imp(recebido), situ])
            t_ped = tabela_pdf(dados_ped, [14 * mm, 20 * mm, 44 * mm, 32 * mm, 24 * mm, 24 * mm, 22 * mm],
                               direita_a_partir=4)
            t_ped.setStyle(TableStyle([("ALIGN", (0, 0), (3, -1), "LEFT"),
                                       ("ALIGN", (6, 0), (6, -1), "LEFT")]))
            historia.append(t_ped)
            doc.build(historia)
            messagebox.showinfo("Pronto", "PDF gerado com sucesso!")
        except ImportError:
            messagebox.showerror("Erro", "A biblioteca reportlab não está instalada neste computador.")
        except Exception as erro:
            messagebox.showerror("Erro", f"Não foi possível gerar o PDF.\n\n{erro}")

    # ---------------- botoes de baixo ----------------
    rodape = tk.Frame(raiz, bg=C_FUNDO)
    rodape.pack(fill="x", pady=(10, 0))
    botao(rodape, "📊 Exportar Excel (CSV)", exportar_csv).pack(side="left", padx=(0, 8))
    botao(rodape, "📄 Gerar PDF", exportar_pdf).pack(side="left", padx=(0, 8))
    botao(rodape, "📦 Gerar XML", exportar_xml).pack(side="left")

    atualizar(silencioso=True)
    return atualizar


def criar_aba_gestao_financeira(notebook):
    import tkinter as tk
    from tkinter import ttk

    # Declarado global para que outras telas (ex.: lançamento de nota como
    # Pendente em lancar_nota_estoque) consigam chamar a atualização da lista
    # de Contas a Pagar imediatamente, sem precisar reiniciar o sistema.
    global atualizar_contas

    frame_principal = ttk.Frame(notebook)
    frame_principal.pack(fill="both", expand=True, padx=0, pady=0)

    # Notebook interno (SUBABAS)
    notebook_fin = ttk.Notebook(frame_principal)
    notebook_fin.pack(fill="both", expand=True)

    # =====================================================
    # 📑 ABA CONTAS / FATURAS
    # =====================================================

    aba_contas = ttk.Frame(notebook_fin)
    notebook_fin.add(aba_contas, text="📑 Contas / Faturas")

    frame_contas = ttk.LabelFrame(aba_contas, text="Cadastro de Contas")
    frame_contas.pack(fill="x", padx=10, pady=10)

    ttk.Label(frame_contas, text="Descrição").grid(row=0, column=0)
    ttk.Label(frame_contas, text="Fornecedor").grid(row=0, column=1)
    ttk.Label(frame_contas, text="Categoria").grid(row=0, column=2)
    ttk.Label(frame_contas, text="Valor").grid(row=0, column=3)
    ttk.Label(frame_contas, text="Vencimento").grid(row=0, column=4)

    e_desc_conta = ttk.Entry(frame_contas, width=25)
    e_fornecedor_conta = ttk.Entry(frame_contas, width=20)
    e_categoria_conta = ttk.Entry(frame_contas, width=15)
    e_valor_conta = ttk.Entry(frame_contas, width=12)
    e_venc_conta = CampoData(frame_contas, pode_vazio=True)

    e_desc_conta.grid(row=1, column=0, padx=5, pady=5)
    e_fornecedor_conta.grid(row=1, column=1, padx=5, pady=5)
    e_categoria_conta.grid(row=1, column=2, padx=5, pady=5)
    e_valor_conta.grid(row=1, column=3, padx=5, pady=5)
    e_venc_conta.grid(row=1, column=4, padx=5, pady=5)

    # Total a pagar: mesmo formato do "TOTAL DO PEDIDO" da aba Pedidos
    # (Segoe UI 16 negrito, valor em padrão brasileiro). Soma as contas ainda não pagas.
    frame_contas.columnconfigure(5, weight=1)
    lbl_total_pagar = ttk.Label(frame_contas, text="TOTAL A PAGAR: R$ 0,00",
                                font=("Segoe UI", 16, "bold"), foreground="#C0392B")
    lbl_total_pagar.grid(row=0, column=5, rowspan=2, sticky="e", padx=15)


    # -----------------------------------------------------
    # FUNÇÕES
    # -----------------------------------------------------

    # --- auxiliares de exibição (não mexem em dados) ---
    def _gc_num(v):
        try:
            if v is None:
                return 0.0
            if isinstance(v, (int, float)):
                return float(v)
            s = str(v).replace("R$", "").replace(" ", "").strip()
            if not s:
                return 0.0
            if "," in s:
                s = s.replace(".", "").replace(",", ".")
            return float(s)
        except Exception:
            return 0.0

    def _gc_brl(v):
        return f"R$ {_gc_num(v):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    # filtro da lista: Pendentes (padrão) / Pagas / Todas
    # master=aba_contas é ESSENCIAL: sem ele o StringVar nasce na root "fantasma" criada pelo
    # ttk.Style (outro interpretador Tk), o Combobox muda a variável da root real e o .get()
    # abaixo sempre devolvia "Pendentes" -> o filtro parecia não funcionar.
    var_mostrar_contas = tk.StringVar(master=aba_contas, value="Todas")
    estado_filtro = {"modo": None}

    def _gc_parse_data(txt):
        # import local: nesta função grande há outro "from datetime import datetime"
        # mais abaixo, o que torna o nome "datetime" local e ainda sem valor aqui.
        from datetime import datetime as _dt_gc
        t = str(txt or "").strip()
        if not t:
            return None
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y"):
            try:
                return _dt_gc.strptime(t, fmt)
            except ValueError:
                pass
        return None

    def _gc_data_hora(txt):
        d = _gc_parse_data(txt)
        if d is None:
            return str(txt or "").strip()
        t = str(txt).strip()
        return d.strftime("%d/%m/%Y %H:%M") if len(t) > 10 else d.strftime("%d/%m/%Y")

    def _gc_nomes_itens(linhas):
        """{id_conta: [nomes dos itens]}. Usa os itens gravados na conta e, para as notas
        antigas, os itens da despesa ligada (observação 'Despesa #N'). Somente leitura."""
        import re as _re_gc
        nomes = {}
        try:
            cursor.execute("SELECT id_conta, produto FROM contas_pagar_itens ORDER BY id")
            for idc, prod in cursor.fetchall():
                nomes.setdefault(idc, []).append(str(prod or "").strip())
        except Exception:
            pass
        faltam = {}
        for idc, obs in linhas:
            if idc in nomes:
                continue
            m = _re_gc.search(r"Despesa #(\d+)", str(obs or ""))
            if m:
                faltam[int(m.group(1))] = idc
        ids = list(faltam)
        for i in range(0, len(ids), 400):
            bloco = ids[i:i + 400]
            try:
                cursor.execute(
                    f"SELECT id_despesa, item FROM despesas_itens WHERE id_despesa IN ({','.join('?' * len(bloco))}) ORDER BY id",
                    bloco)
                for idd, item in cursor.fetchall():
                    nomes.setdefault(faltam[idd], []).append(str(item or "").strip())
            except Exception:
                pass
        return nomes

    def _gc_desc_exibicao(descricao, nomes):
        """'COMPRA ESTOQUE (NF 123)' + itens -> 'NF 123 — PICANHA, COSTELA +1'."""
        import re as _re_gc
        d = str(descricao or "").strip()
        lista = [n for n in (nomes or []) if n]
        if not lista:
            return d
        m = _re_gc.match(r"^COMPRA ESTOQUE \((.*)\)$", d, _re_gc.I)
        base = m.group(1).strip() if m else d
        txt = ", ".join(lista[:3]) + (f" +{len(lista) - 3}" if len(lista) > 3 else "")
        return f"{base} — {txt}"

    def atualizar_contas():
        modo = var_mostrar_contas.get()

        # lembra quais fornecedores estavam abertos (só enquanto o filtro for o mesmo)
        abertos = {}
        if estado_filtro["modo"] == modo:
            def _coletar_abertos(pai):
                for iid in tree_contas.get_children(pai):
                    try:
                        if tree_contas.get_children(iid):
                            abertos[iid] = bool(tree_contas.item(iid, "open"))
                            _coletar_abertos(iid)
                    except Exception:
                        pass
            _coletar_abertos("")
        estado_filtro["modo"] = modo

        for item in tree_contas.get_children():
            tree_contas.delete(item)

        cursor.execute("""
        SELECT id, descricao, fornecedor, categoria, valor, data_vencimento, status,
               data_pagamento, data_emissao, observacao
        FROM contas_pagar
        """)
        registros = cursor.fetchall()
        nomes_itens = _gc_nomes_itens([(r[0], r[9]) for r in registros])

        grupos = {}
        n_ocultas = 0
        for (id_c, desc, forn, cat, valor, venc, status, data_pgto, emissao, _obs) in registros:
            nome = (forn or "").strip() or "(Sem fornecedor)"
            g = grupos.setdefault(nome.casefold(), {"nome": nome, "contas": [], "pend": 0.0, "pago": 0.0,
                                                   "n_pend": 0, "n_pago": 0})
            v = _gc_num(valor)
            esta_paga = str(status or "").upper() == "PAGO"
            if esta_paga:
                g["pago"] += v
                g["n_pago"] += 1
            else:
                g["pend"] += v
                g["n_pend"] += 1

            if not (modo == "Todas" or (modo == "Pendentes" and not esta_paga) or (modo == "Pagas" and esta_paga)):
                n_ocultas += 1
                continue

            # ordem pela data REAL (o campo é texto dd/mm/aaaa): em aberto por vencimento
            # (o mais antigo/atrasado primeiro); pagas pela mais recente.
            if esta_paga:
                d_pg = _gc_parse_data(data_pgto)
                chave = (1, -(d_pg.timestamp() if d_pg else 0), id_c)
            else:
                d_v = _gc_parse_data(venc)
                chave = (0, d_v.toordinal() if d_v else 10 ** 9, id_c)

            d_compra = _gc_parse_data(emissao) or _gc_parse_data(venc)
            g["contas"].append((chave, esta_paga,
                                (id_c, _gc_desc_exibicao(desc, nomes_itens.get(id_c)), nome, cat,
                                 _gc_brl(valor), venc, status,
                                 _gc_data_hora(data_pgto) if esta_paga else "",
                                 "", "",
                                 d_compra.strftime("%d/%m/%Y") if d_compra else "")))

        total_pagar = sum(g["pend"] for g in grupos.values())
        n_exibidas = 0
        n_forn = 0
        for chave_f, g in sorted(grupos.items(),
                                 key=lambda kv: (-(kv[1]["pago"] if modo == "Pagas" else kv[1]["pend"]),
                                                 kv[1]["nome"].casefold())):
            if not g["contas"]:
                continue
            n_forn += 1
            iid_f = "forn::" + chave_f
            padrao_aberto = (modo == "Pendentes") or (modo == "Todas" and g["pend"] > 0.001)
            rot_pagas = "paga" if g["n_pago"] == 1 else "pagas"
            tree_contas.insert("", "end", iid=iid_f, open=abertos.get(iid_f, padrao_aberto),
                               values=("", f"{g['nome'].upper()}   ({g['n_pend']} em aberto · {g['n_pago']} {rot_pagas})",
                                       g["nome"], "", _gc_brl(g["pend"] + g["pago"]), "", "", "",
                                       _gc_brl(g["pend"]), _gc_brl(g["pago"]), ""),
                               tags=("forn",))
            contas_ord = sorted(g["contas"], key=lambda c: c[0])
            if modo == "Todas":
                abertas_l = [c for c in contas_ord if not c[1]]
                pagas_l = [c for c in contas_ord if c[1]]
                blocos = []
                if abertas_l:
                    blocos.append(("ab", f"🔴 EM ABERTO ({len(abertas_l)})", abertas_l, g["pend"], True, "sub_ab"))
                if pagas_l:
                    blocos.append(("pg", f"✅ PAGAS ({len(pagas_l)})", pagas_l, g["pago"], False, "sub_pg"))
                for suf, rot, lista, soma, aberto_padrao, tag_sub in blocos:
                    iid_s = f"{iid_f}::{suf}"
                    tree_contas.insert(iid_f, "end", iid=iid_s, open=abertos.get(iid_s, aberto_padrao),
                                       values=("", rot, g["nome"], "", _gc_brl(soma), "", "", "",
                                               _gc_brl(soma) if suf == "ab" else "",
                                               _gc_brl(soma) if suf == "pg" else "", ""),
                                       tags=(tag_sub,))
                    for _ch, esta_paga, vals in lista:
                        n_exibidas += 1
                        tree_contas.insert(iid_s, "end", iid=f"c{vals[0]}", values=vals,
                                           tags=("paga",) if esta_paga else ("aberta",))
            else:
                for _ch, esta_paga, vals in contas_ord:
                    n_exibidas += 1
                    tree_contas.insert(iid_f, "end", iid=f"c{vals[0]}", values=vals,
                                       tags=("paga",) if esta_paga else ("aberta",))

        lbl_total_pagar.config(text=f"TOTAL A PAGAR: {_gc_brl(total_pagar)}")
        info = f"{n_exibidas} conta(s) em {n_forn} fornecedor(es)"
        if n_ocultas:
            info += f"  ·  {n_ocultas} {'paga(s)' if modo == 'Pendentes' else 'pendente(s)'} oculta(s) — use \"Mostrar\""
        lbl_info_contas.config(text=info)


    def cadastrar_conta():

        desc = e_desc_conta.get()
        forn = e_fornecedor_conta.get()
        cat = e_categoria_conta.get()
        valor = e_valor_conta.get()
        venc = e_venc_conta.get()

        if not desc or not valor:
            messagebox.showwarning("Aviso","Preencha os campos obrigatórios")
            return

        cursor.execute("""
        INSERT INTO contas_pagar
        (descricao, fornecedor, categoria, valor, data_vencimento, status)
        VALUES (?,?,?,?,?,'PENDENTE')
        """,(desc,forn,cat,valor,venc))

        conn.commit()
        registrar_log("CONTA_CADASTRADA", "FINANCEIRO", cursor.lastrowid, {"descricao": desc, "fornecedor": forn, "categoria": cat, "valor": valor, "vencimento": venc})

        atualizar_contas()

        e_desc_conta.delete(0,"end")
        e_fornecedor_conta.delete(0,"end")
        e_categoria_conta.delete(0,"end")
        e_valor_conta.delete(0,"end")
        e_venc_conta.delete(0,"end")


    def excluir_conta():

        item = tree_contas.selection()

        if not item:
            return

        id_conta = tree_contas.item(item,"values")[0]

        if id_conta in ("", None):
            messagebox.showwarning("Aviso", "Selecione uma conta (não a linha do fornecedor).")
            return

        if not messagebox.askyesno("Confirmar", "Excluir esta conta? Os itens da nota vinculados a ela também serão removidos."):
            return

        try:
            # Remove primeiro os itens filhos (contas_pagar_itens) para não
            # deixar registros órfãos no banco quando a conta é excluída
            # (ex.: uma nota lançada como Pendente antes de ser paga).
            cursor.execute("DELETE FROM contas_pagar_itens WHERE id_conta=?", (id_conta,))
            cursor.execute("DELETE FROM contas_pagar WHERE id=?", (id_conta,))
            conn.commit()
            registrar_log("CONTA_EXCLUIDA", "FINANCEIRO", id_conta, {})
        except Exception as e:
            conn.rollback()
            messagebox.showerror("Erro", f"Erro ao excluir conta: {e}")
            return

        atualizar_contas()

    def ver_detalhes_conta(event=None):
        """Duplo clique numa conta: mostra fornecedor, datas (inclusive a de
        pagamento), total e, quando existirem (notas lançadas como Pendente),
        a lista completa dos itens da nota com os valores e o total dos itens.
        Em uma linha de fornecedor o duplo clique só abre/fecha o grupo."""
        selecao = tree_contas.selection()
        if not selecao:
            return

        dados = tree_contas.item(selecao[0], "values")
        id_conta = dados[0] if dados else ""
        if id_conta in ("", None):
            return

        cursor.execute("""
            SELECT descricao, fornecedor, categoria, valor, data_emissao, data_vencimento,
                   status, forma_pagamento, data_pagamento, observacao
            FROM contas_pagar WHERE id=?
        """, (id_conta,))
        registro = cursor.fetchone()
        if not registro:
            return
        (desc_conta, forn_conta, cat_conta, valor_conta, emissao, venc_conta,
         status_conta, forma_pg, data_pg, obs_conta) = registro
        esta_paga = str(status_conta or "").upper() == "PAGO"

        jan_det = tk.Toplevel(root)
        jan_det.title(f"Detalhes da Conta #{id_conta}")
        jan_det.geometry("680x520")
        jan_det.grab_set()

        ttk.Label(jan_det, text=desc_conta or "", font=("Arial", 12, "bold")).pack(pady=(10, 2))

        f_info = ttk.Frame(jan_det)
        f_info.pack(fill="x", padx=15, pady=5)

        ttk.Label(f_info, text=f"Fornecedor: {forn_conta or '(Sem fornecedor)'}").grid(row=0, column=0, sticky="w", pady=2)
        ttk.Label(f_info, text=f"Categoria: {cat_conta or ''}").grid(row=1, column=0, sticky="w", pady=2)
        ttk.Label(f_info, text=f"Compra: {_gc_data_hora(emissao) or '-'}").grid(row=0, column=1, sticky="w", padx=20, pady=2)
        ttk.Label(f_info, text=f"Vencimento: {venc_conta or ''}").grid(row=1, column=1, sticky="w", padx=20, pady=2)
        ttk.Label(f_info, text=f"Status: {status_conta or ''}",
                  font=("Arial", 10, "bold"),
                  foreground="#2E7D32" if esta_paga else "#B03A2E").grid(row=2, column=0, sticky="w", pady=2)
        if esta_paga:
            txt_pg = f"Pago em: {_gc_data_hora(data_pg) or '-'}"
            if forma_pg:
                txt_pg += f"  ({forma_pg})"
        else:
            txt_pg = "Pago em: ainda não pago"
        ttk.Label(f_info, text=txt_pg).grid(row=2, column=1, sticky="w", padx=20, pady=2)
        ttk.Label(f_info, text=f"Total da conta: {_gc_brl(valor_conta)}",
                  font=("Arial", 11, "bold"), foreground="#B03A2E").grid(row=3, column=0, columnspan=2, sticky="w", pady=(4, 2))

        # Botão fixo no rodapé (empacotado antes para nunca ser empurrado para fora)
        ttk.Button(jan_det, text="Fechar", command=jan_det.destroy).pack(side="bottom", pady=10)

        # --- ITENS DA NOTA (se houver, ex.: notas lançadas como Pendente) ---
        cursor.execute("""
            SELECT produto, categoria_item, quantidade, valor_unitario, subtotal
            FROM contas_pagar_itens WHERE id_conta=?
        """, (id_conta,))
        itens = cursor.fetchall()

        if not itens:
            # notas antigas: usa os itens da despesa ligada (só nome, categoria e subtotal)
            import re as _re_gc
            _m = _re_gc.search(r"Despesa #(\d+)", str(obs_conta or ""))
            if _m:
                try:
                    cursor.execute("""
                        SELECT item, categoria_item, NULL, NULL, valor
                        FROM despesas_itens WHERE id_despesa=? ORDER BY id
                    """, (int(_m.group(1)),))
                    itens = cursor.fetchall()
                except Exception:
                    itens = []

        if itens:
            total_itens = sum(_gc_num(it[4]) for it in itens)
            lbl_total_itens = ttk.Label(jan_det, text=f"TOTAL DOS ITENS: {_gc_brl(total_itens)}",
                                        font=("Segoe UI", 13, "bold"), foreground="#1B8F4D")
            lbl_total_itens.pack(side="bottom", anchor="e", padx=20, pady=(2, 0))
            if abs(total_itens - _gc_num(valor_conta)) > 0.01:
                ttk.Label(jan_det, text="(o total dos itens difere do total da conta)",
                          foreground="#7f8c8d").pack(side="bottom", anchor="e", padx=20)

            ttk.Label(jan_det, text="Itens da Nota:", font=("Arial", 10, "bold")).pack(anchor="w", padx=15, pady=(10, 2))

            f_tree_det = ttk.Frame(jan_det)
            f_tree_det.pack(fill="both", expand=True, padx=15, pady=5)

            cols_det = ("produto", "categoria", "qtd", "v_un", "subtotal")
            nomes_det = {"produto": "PRODUTO", "categoria": "CATEGORIA", "qtd": "QTD",
                         "v_un": "VALOR UNIT.", "subtotal": "SUBTOTAL"}
            tree_det = ttk.Treeview(f_tree_det, columns=cols_det, show="headings", height=8)
            for c in cols_det:
                tree_det.heading(c, text=nomes_det[c])
                tree_det.column(c, anchor="center", width=90)
            tree_det.column("produto", width=200, anchor="w")
            tree_det.column("v_un", anchor="e")
            tree_det.column("subtotal", anchor="e")

            scroll_det = ttk.Scrollbar(f_tree_det, orient="vertical", command=tree_det.yview)
            tree_det.configure(yscrollcommand=scroll_det.set)
            scroll_det.pack(side="right", fill="y")
            tree_det.pack(side="left", fill="both", expand=True)

            for produto, cat_item, qtd, v_un, subtotal in itens:
                cat_label = "PRODUTO ACABADO" if cat_item == "PRODUTO" else "INSUMO"
                tree_det.insert("", "end", values=(
                    produto, cat_label,
                    "-" if qtd is None else f"{_gc_num(qtd):.3f}",
                    "-" if v_un is None else _gc_brl(v_un), _gc_brl(subtotal)
                ))
        else:
            ttk.Label(jan_det, text="(Nenhum item detalhado registrado para esta conta.)",
                      foreground="#7f8c8d").pack(pady=20)

    def pagar_conta():
        selecao = tree_contas.selection()
        
        if not selecao:
            messagebox.showwarning("Aviso", "Selecione uma conta na lista")
            return
        
        # 1. Captura os dados da linha selecionada
        dados = tree_contas.item(selecao, "values")
        id_conta = dados[0]
        if id_conta in ("", None):
            messagebox.showwarning("Aviso", "Selecione uma conta (não a linha do fornecedor).")
            return
        # a descrição exibida na lista é um resumo com os itens; o pagamento continua usando a
        # descrição original gravada na conta (é ela que vai para o caixa e para o log)
        cursor.execute("SELECT descricao FROM contas_pagar WHERE id=?", (id_conta,))
        _rd = cursor.fetchone()
        desc_conta = _rd[0] if _rd and _rd[0] is not None else dados[1]
        valor_bruto = str(dados[4]) # Ex: "R$ 50.00" ou "50,00"

        # 1.1 TRAVA: consulta o status ATUAL direto no banco (não confia só
        # no valor exibido na treeview, que pode estar desatualizado) para
        # impedir pagar a mesma conta duas vezes e dar baixa em dobro no caixa.
        cursor.execute("SELECT status FROM contas_pagar WHERE id=?", (id_conta,))
        status_atual = cursor.fetchone()
        if status_atual and str(status_atual[0]).upper() == "PAGO":
            messagebox.showinfo("Conta já paga", f'A conta "{desc_conta}" já foi paga anteriormente.')
            atualizar_contas()
            return

        # 2. TRATAMENTO DE VALOR (Correção do erro de multiplicar por 10)
        try:
            # Remove o R$ e espaços
            v_limpo = valor_bruto.replace("R$", "").replace(" ", "").strip()
            
            # Se tiver vírgula, é formato BR (1.000,00), então tratamos
            if "," in v_limpo:
                v_limpo = v_limpo.replace(".", "").replace(",", ".")
            
            # Converte para número real
            valor_final = float(v_limpo)
        except Exception as e:
            messagebox.showerror("Erro", f"Erro ao converter valor: {e}")
            return

        # 3. CRIAÇÃO DA JANELA DE PAGAMENTO
        janela_pag = tk.Toplevel(root)
        janela_pag.title("Confirmar Pagamento")
        janela_pag.geometry("300x280")
        janela_pag.grab_set()
        janela_pag.resizable(False, False)

        ttk.Label(janela_pag, text="PAGAMENTO DE CONTA", font=("Arial", 10, "bold")).pack(pady=10)
        ttk.Label(janela_pag, text=f"{desc_conta}", wraplength=250).pack()
        ttk.Label(janela_pag, text=f"R$ {valor_final:.2f}", font=("Arial", 14, "bold"), foreground="red").pack(pady=5)

        # 4. FUNÇÃO INTERNA QUE EXECUTA O BANCO DE DADOS
        def executar_pagamento(forma):
            if not ciclo_caixa_aberto.get("id"):
                messagebox.showerror("Erro", "Caixa Fechado! Abra o caixa antes de pagar.")
                return

            # TRAVA (2ª camada): revalida o status no banco antes de baixar o
            # caixa, evitando pagamento em dobro caso o clique seja duplicado
            # ou a janela de pagamento tenha ficado aberta por engano.
            cursor.execute("SELECT status FROM contas_pagar WHERE id=?", (id_conta,))
            status_check = cursor.fetchone()
            if status_check and str(status_check[0]).upper() == "PAGO":
                messagebox.showinfo("Conta já paga", f'A conta "{desc_conta}" já foi paga anteriormente.')
                janela_pag.destroy()
                atualizar_contas()
                return

            try:
                agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                c_id = ciclo_caixa_aberto["id"]

                # A. Insere no Caixa (Saída) via ponto único (Regras 1, 10, 11)
                novo_id_caixa = registrar_lancamento_caixa(
                    "SAIDA", f"PAGTO: {desc_conta}", valor_final, forma, ciclo_id=c_id
                )

                # B. Marca a conta como Paga (só afeta a linha se ela ainda
                # não estiver PAGA, como reforço final contra corrida)
                cursor.execute("""
                    UPDATE contas_pagar
                    SET status='PAGO', forma_pagamento=?, data_pagamento=?
                    WHERE id=? AND status != 'PAGO'
                """, (padronizar_forma_pagamento(forma), agora, id_conta))
                conn.commit()

                registrar_log("CONTA_PAGA", "FINANCEIRO", id_conta, {"descricao": desc_conta, "valor": valor_final, "forma": forma, "caixa": c_id, "lancamento_caixa_id": novo_id_caixa})

                # --- ATUALIZAÇÃO DO HISTÓRICO VISUAL ---
                if 'lista_despesas' in globals():
                    data_tela = datetime.now().strftime("%d/%m/%Y %H:%M")
                    # Formato da sua tabela: (Objeto, Credor, Valor, Data)
                    lista_despesas.insert("", 0, values=(desc_conta, "Financeiro", f"R$ {valor_final:.2f}", data_tela))

                # C. Atualiza a Interface (registrar_lancamento_caixa já chamou sincronizar_financeiro)
                atualizar_contas()

                janela_pag.destroy()
                messagebox.showinfo("Sucesso", "Pagamento realizado e saldo atualizado!")

            except Exception as e:
                conn.rollback()
                messagebox.showerror("Erro no Banco", f"Falha ao gravar: {e}")

        # 5. BOTÕES DE FORMA DE PAGAMENTO
        ttk.Button(janela_pag, text="💵 DINHEIRO", width=25, 
                   command=lambda: executar_pagamento("Dinheiro")).pack(pady=5)
        
        ttk.Button(janela_pag, text="📱 PIX", width=25, 
                   command=lambda: executar_pagamento("Pix")).pack(pady=5)
        
        ttk.Button(janela_pag, text="💳 CARTÃO", width=25, 
                   command=lambda: executar_pagamento("Cartão")).pack(pady=5)

        ttk.Button(janela_pag, text="❌ Cancelar", width=25, 
                   command=janela_pag.destroy).pack(pady=15)


