# =====================================================
# 🔔 MESSAGEBOX / POPUPS SEMPRE NA FRENTE (VERSÃO CORRIGIDA)
# =====================================================
# CAUSA DO BUG ANTIGO:
#   Os avisos eram sempre abertos com parent=root e o root era trazido
#   para frente (lift + topmost). Como o root fica MAXIMIZADO, ele
#   passava por cima do popup que estava aberto (ex.: pagamento,
#   atualizar cardapio). O popup continuava com grab_set() (bloqueando
#   o resto do sistema) mas ficava ESCONDIDO atras do root -> sistema
#   "travado" ate achar a janela de novo.
#
# CORRECAO:
#   1) O aviso agora e filho da JANELA QUE O CHAMOU (o popup modal, se
#      houver), e nao mais do root.
#   2) O root nunca mais vira topmost nem e trazido para frente.
#   3) Depois do aviso, o popup e trazido de volta e o grab e restaurado.
#   4) (Opcional) Todo Toplevel vira "transient" do dono: o Windows
#      garante que ele fica SEMPRE acima do dono. Para desligar, mude
#      POPUPS_SEMPRE_NA_FRENTE para False.

POPUPS_SEMPRE_NA_FRENTE = True


def _janela_ativa_para_aviso():
    """Devolve a janela que deve ser 'pai' do aviso: o popup modal
    (quem detem o grab), ou a janela com foco, ou o root."""

    def _valida(w):
        try:
            top = w.winfo_toplevel()
            if not top.winfo_exists():
                return None
            if top.winfo_class() not in ("Tk", "Toplevel"):
                return None  # ignora menus, etc.
            if top is not root:
                if top.state() in ("withdrawn", "iconic"):
                    return None
                if top.wm_overrideredirect():
                    return None  # ignora popups de sugestao
            return top
        except Exception:
            return None

    try:
        g = root.grab_current()
        if g is not None:
            top = _valida(g)
            if top is not None:
                return top
    except Exception:
        pass

    try:
        f = root.focus_get()
        if f is not None:
            top = _valida(f)
            if top is not None:
                return top
    except Exception:
        pass

    return root


def _criar_aviso_na_frente(func_original):

    def aviso(*args, **kwargs):
        pai = kwargs.get("parent") or _janela_ativa_para_aviso()
        kwargs["parent"] = pai

        try:
            grab_antes = root.grab_current()
        except Exception:
            grab_antes = None

        # Traz para frente SOMENTE a janela que chamou o aviso
        # (nunca o root maximizado por cima do popup).
        try:
            pai.lift()
            pai.focus_force()
        except Exception:
            pass

        try:
            return func_original(*args, **kwargs)
        finally:
            # Devolve o popup para frente e restaura o bloqueio (grab)
            try:
                if pai is not root and pai.winfo_exists():
                    pai.lift()
                    pai.focus_force()
            except Exception:
                pass

            try:
                if (
                    grab_antes is not None
                    and grab_antes.winfo_exists()
                    and root.grab_current() is None
                ):
                    grab_antes.grab_set()
            except Exception:
                pass

    return aviso


for _nome_msg in (
    "showinfo",
    "showwarning",
    "showerror",
    "askyesno",
    "askokcancel",
    "askyesnocancel",
    "askretrycancel",
    "askquestion",
):
    if hasattr(messagebox, _nome_msg):
        setattr(
            messagebox,
            _nome_msg,
            _criar_aviso_na_frente(getattr(messagebox, _nome_msg))
        )


if POPUPS_SEMPRE_NA_FRENTE:
    _ToplevelOriginal = tk.Toplevel

    class _ToplevelNaFrente(_ToplevelOriginal):
        """Toplevel que ja nasce 'transient' do dono, ficando sempre
        acima dele (nao some atras do root maximizado)."""

        def __init__(self, master=None, *args, **kwargs):
            super().__init__(master, *args, **kwargs)
            try:
                dono = (master if master is not None else root).winfo_toplevel()
                self.transient(dono)
            except Exception:
                pass

    tk.Toplevel = _ToplevelNaFrente

# =====================================================
# 🔒 GRAB_SET SEGURO (CORRECAO DO ERRO "another application has grab")
# =====================================================
# Substitui tk.Misc.grab_set para TODAS as janelas (Toplevel, simpledialog,
# mesa.py, orcamento.py...). Se o grab falhar porque outro widget/interpretador
# Tk esta segurando, o sistema: (1) registra QUEM segura em
# logs\sistema_erros.log ("grab_set falhou"), (2) solta o grab preso,
# (3) tenta de novo, (4) se ainda assim falhar, agenda novas tentativas e
# segue SEM modal -- nunca mais deixa janela em branco nem derruba o pagamento.
_grab_set_original = tk.Misc.grab_set


def _soltar_grabs_presos():
    """Solta qualquer grab preso na root real e na root fantasma do ttk.Style."""
    vistos = []
    for r in (root, getattr(tk, "_default_root", None)):
        if r is None or any(r is v for v in vistos):
            continue
        vistos.append(r)
        try:
            g = r.grab_current()
            if g is not None:
                g.grab_release()
        except Exception:
            pass


def _grab_set_seguro(self, _tentativa=0):
    try:
        return _grab_set_original(self)
    except tk.TclError as erro_grab:
        if _tentativa == 0:
            try:
                fantasma = getattr(tk, "_default_root", None)
                registrar_erro_diagnostico(
                    "grab_set falhou",
                    extra={
                        "janela": str(self),
                        "classe": type(self).__name__,
                        "erro": str(erro_grab),
                        "grab_na_root": str(root.grab_current()),
                        "grab_na_fantasma": (
                            str(fantasma.grab_current())
                            if fantasma is not None and fantasma is not root
                            else "sem fantasma"
                        ),
                        "root_eh_default": fantasma is root,
                    },
                )
            except Exception:
                pass

        _soltar_grabs_presos()

        try:
            return _grab_set_original(self)
        except tk.TclError:
            pass

        # Ainda falhou (ex.: janela ainda nao visivel): tenta mais algumas
        # vezes em segundo plano; se nao der, a janela fica sem modal.
        if _tentativa < 10:
            try:
                self.after(150, lambda: _grab_set_seguro(self, _tentativa + 1))
            except Exception:
                pass
        return None


tk.Misc.grab_set = _grab_set_seguro


def _desbloquear_sistema(event=None):
    """Atalho de emergencia: Ctrl+Alt+G solta qualquer grab preso."""
    _soltar_grabs_presos()
    try:
        root.focus_force()
    except Exception:
        pass


root.bind_all("<Control-Alt-g>", _desbloquear_sistema)
