# Dicionários Auxiliares de Estilização Padrão para os novos componentes CTK
# Use esses parâmetros ao criar novos botões e frames para manter a consistência da imagem


def _valor_ordenacao_treeview(valor):
    import re
    texto = str(valor).strip()
    # Data no formato brasileiro (dd/mm/aaaa [hh:mm[:ss]]): ordena
    # cronologicamente em vez de por texto (que ordenaria pelo dia).
    _m_data = re.fullmatch(
        r"(\d{2})/(\d{2})/(\d{4})(?:\s+(\d{2}):(\d{2})(?::(\d{2}))?)?", texto
    )
    if _m_data:
        _d, _mo, _a, _h, _mi, _se = _m_data.groups()
        return (1, "%s-%s-%s %s:%s:%s" % (_a, _mo, _d, _h or "00", _mi or "00", _se or "00"))
    numero = (
        texto.replace("R$", "")
        .replace("%", "")
        .replace(".", "")
        .replace(",", ".")
        .strip()
    )
    try:
        return (0, float(numero))
    except Exception:
        return (1, texto.lower())


def ordenar_treeview_generico(tv, col, reverse=False):
    itens = [(tv.set(item, col), item) for item in tv.get_children("")]
    itens.sort(key=lambda item: _valor_ordenacao_treeview(item[0]), reverse=reverse)

    for indice, (_valor, item) in enumerate(itens):
        tv.move(item, "", indice)

    texto = tv.heading(col, "text") or col
    tv.heading(col, text=texto, command=lambda: ordenar_treeview_generico(tv, col, not reverse))


def _normalizar_texto_busca(texto):
    """Minúsculo e sem acentos (assim 'Á' é encontrado digitando 'a')."""
    import unicodedata
    txt = unicodedata.normalize("NFD", str(texto if texto is not None else "").lower())
    return "".join(c for c in txt if unicodedata.category(c) != "Mn")


def _pular_para_letra_treeview(event, tv, coluna_busca=None):
    """Busca SIMPLES pela primeira letra (sem acumular letras digitadas):

    - digitou 'b'  -> vai para o primeiro item que começa com B;
    - digitou 'b' de novo -> vai para o segundo, depois o terceiro... e volta
      ao primeiro quando acabam;
    - digitou outra letra, ex. 'i' -> vai para o primeiro item que começa com I.
    """
    if event.keysym in ("Up", "Down", "Left", "Right", "Return", "Tab", "Escape"):
        return

    letra = _normalizar_texto_busca(event.char)
    if len(letra) != 1 or not letra.isalnum():
        return

    itens = tv.get_children("")
    if not itens:
        return

    todas = list(tv["columns"])
    colunas = [coluna_busca] if coluna_busca in todas else todas

    def _comeca_com_letra(item):
        for col in colunas:
            if _normalizar_texto_busca(tv.set(item, col)).lstrip().startswith(letra):
                return True
        return False

    correspondentes = [i for i in itens if _comeca_com_letra(i)]
    if not correspondentes:
        return

    atual = tv.focus()
    if atual in correspondentes:
        # já está num item dessa letra: avança para o próximo (com volta ao início)
        alvo = correspondentes[(correspondentes.index(atual) + 1) % len(correspondentes)]
    else:
        # letra nova: primeiro item que começa com ela
        alvo = correspondentes[0]

    tv.selection_set(alvo)
    tv.focus(alvo)
    tv.see(alvo)


def buscar_digitando_treeview(event, tv, coluna_busca=None):
    _pular_para_letra_treeview(event, tv, coluna_busca)


def buscar_digitando_treeview_prefixo(event, tv, coluna_busca=None):
    # Mantida com este nome porque Opções de Pratos (Cardápio) chama por ela;
    # agora todas as listas usam o mesmo comportamento simples por primeira letra.
    _pular_para_letra_treeview(event, tv, coluna_busca)


def adicionar_lupa_treeview(tv):
    """Coloca uma lupa pequena no canto superior direito da lista.

    Clicou na lupa (ou Ctrl+F na lista) -> aparece um campo de busca; a lista é
    filtrada a cada letra digitada. Clicou fora -> o campo some e a lista volta
    inteira (o item que estava selecionado continua selecionado).
    Enter / seta para baixo -> vai para a lista com o primeiro resultado
    selecionado. Esc -> fecha a busca.
    """
    if getattr(tv, "_lupa_ativa", False):
        return
    tv._lupa_ativa = True

    estado = {"snap": [], "ocultos": set(), "aberta": False, "fechar_id": None}

    try:
        cor = ttk.Style().lookup("Treeview.Heading", "background") or ttk.Style().lookup("Treeview", "background") or "#ffffff"
    except Exception:
        cor = "#ffffff"

    lupa = tk.Label(tv, text="🔍", cursor="hand2", bd=0, padx=2, bg=cor)
    lupa.place(relx=1.0, x=-2, y=1, anchor="ne")
    entry = tk.Entry(tv, bd=1, relief="solid")

    def _texto_do_item(item):
        partes = [str(tv.item(item, "text") or "")]
        try:
            partes.extend(str(v) for v in tv.item(item, "values"))
        except Exception:
            pass
        return _normalizar_texto_busca(" ".join(partes))

    def _sincronizar():
        # Se o sistema recarregou a lista enquanto a busca estava aberta, os
        # itens ocultos antigos ficaram obsoletos: descarta e reinicia o "retrato".
        visiveis = list(tv.get_children(""))
        conhecidos = set(estado["snap"])
        if any(v not in conhecidos for v in visiveis):
            for i in list(estado["ocultos"]):
                try:
                    if tv.exists(i):
                        tv.delete(i)
                except Exception:
                    pass
            estado["ocultos"].clear()
            estado["snap"] = visiveis

    def _filtrar(_e=None):
        if not estado["aberta"]:
            return
        try:
            _sincronizar()
            termo = _normalizar_texto_busca(entry.get()).strip()
            pos = 0
            for item in estado["snap"]:
                if not tv.exists(item):
                    continue
                if not termo or termo in _texto_do_item(item):
                    tv.move(item, "", pos)
                    pos += 1
                    estado["ocultos"].discard(item)
                else:
                    tv.detach(item)
                    estado["ocultos"].add(item)
        except Exception as ex:
            print(f"Erro na busca da lista: {ex}")

    def _restaurar():
        try:
            _sincronizar()
            selecionados = [i for i in tv.selection() if tv.exists(i)]
            pos = 0
            for item in estado["snap"]:
                if tv.exists(item):
                    tv.move(item, "", pos)
                    pos += 1
            estado["ocultos"].clear()
            if selecionados:
                if tuple(tv.selection()) != tuple(selecionados):
                    tv.selection_set(selecionados)
                tv.focus(selecionados[0])
                tv.see(selecionados[0])
        except Exception as ex:
            print(f"Erro ao restaurar a lista: {ex}")

    def _cancelar_fechamento(_e=None):
        if estado["fechar_id"] is not None:
            try:
                tv.after_cancel(estado["fechar_id"])
            except Exception:
                pass
            estado["fechar_id"] = None

    def fechar(_e=None):
        _cancelar_fechamento()
        if not estado["aberta"]:
            return
        estado["aberta"] = False
        entry.place_forget()
        _restaurar()

    def abrir(_e=None):
        _cancelar_fechamento()
        if estado["aberta"]:
            entry.focus_set()
            return
        estado["snap"] = list(tv.get_children(""))
        estado["ocultos"].clear()
        estado["aberta"] = True
        entry.delete(0, "end")
        entry.place(relx=1.0, x=-24, y=1, anchor="ne", width=170)
        entry.lift()
        entry.focus_set()

    def alternar(_e=None):
        if estado["aberta"]:
            fechar()
        else:
            abrir()

    def _decidir_fechamento():
        estado["fechar_id"] = None
        if not estado["aberta"]:
            return
        try:
            foco = tv.focus_get()
        except Exception:
            foco = None
        if foco is entry:
            return
        if foco is tv:
            # Clicou na própria lista: espera um instante (duplo clique) antes
            # de devolver a lista inteira, mantendo o item clicado selecionado.
            estado["fechar_id"] = tv.after(400, fechar)
        else:
            fechar()

    def _perdeu_foco(_e=None):
        _cancelar_fechamento()
        estado["fechar_id"] = tv.after(60, _decidir_fechamento)

    def _ir_para_lista(_e=None):
        itens = tv.get_children("")
        if itens:
            tv.selection_set(itens[0])
            tv.focus(itens[0])
            tv.see(itens[0])
        tv.focus_set()
        return "break"

    def _esc(_e=None):
        fechar()
        tv.focus_set()
        return "break"

    lupa.bind("<Button-1>", alternar)
    entry.bind("<KeyRelease>", _filtrar)
    entry.bind("<FocusIn>", _cancelar_fechamento)
    entry.bind("<FocusOut>", _perdeu_foco)
    entry.bind("<Return>", _ir_para_lista)
    entry.bind("<Down>", _ir_para_lista)
    entry.bind("<Escape>", _esc)
    tv.bind("<Control-f>", abrir, add="+")
    tv.bind("<Control-F>", abrir, add="+")


def ativar_lista_interativa(tv, coluna_busca=None):
    try:
        colunas = list(tv["columns"])
    except Exception:
        return

    for col in colunas:
        texto = tv.heading(col, "text") or col
        tv.heading(col, text=texto, command=lambda c=col: ordenar_treeview_generico(tv, c, False))

    tv.bind("<Key>", lambda event, tree=tv, col=coluna_busca: buscar_digitando_treeview(event, tree, col), add="+")
    tv.bind("<Button-1>", lambda _event, tree=tv: tree.focus_set(), add="+")

    try:
        adicionar_lupa_treeview(tv)
    except Exception as ex:
        print(f"Não foi possível adicionar a lupa na lista: {ex}")


# =====================================================
# 🔎 AUTOCOMPLETE ESTILO "GOOGLE" — MOTOR ÚNICO E REUTILIZÁVEL
# =====================================================
# Este motor reproduz exatamente o comportamento que já existia (e funcionava
# muito bem) no campo "Item" da janela LANÇAR NOTA: enquanto o usuário digita,
# aparece uma sugestão "fantasma" completando o texto, e uma pequena janela
# flutuante (estilo Google) mostra todas as opções que combinam, navegável
# com as setas ↑/↓ e selecionável com ENTER/clique/Tab.
#
# Qualquer ttk.Combobox do sistema pode ganhar esse mesmo comportamento
# chamando ativar_autocomplete_combobox(...) uma única vez, logo depois de
# criar o combobox — sem precisar duplicar toda essa lógica em cada lugar.
def ativar_autocomplete_combobox(combobox, obter_valores, ao_selecionar=None,
                                  proximo_widget=None, apenas_da_lista=False,
                                  max_sugestoes=8):
    """Liga o autocomplete estilo Google (o mesmo do Lançar Nota) a um combobox.

    - combobox: o widget ttk.Combobox (é colocado em modo editável, pois
      digitar é essencial para o autocomplete funcionar).
    - obter_valores: lista de strings, OU uma função sem argumentos que
      devolve a lista atual de valores (use uma função quando a lista é
      recarregada depois, ex.: quando o combobox["values"] muda dinamicamente).
    - ao_selecionar: função opcional chamada com o texto final escolhido pelo
      usuário — é aqui que cada tela pode preencher preço, categoria, etc,
      igual o Lançar Nota faz com aplicar_dados_item().
    - proximo_widget: widget que recebe o foco automaticamente depois que um
      item é confirmado (ENTER, clique na sugestão ou no dropdown nativo).
    - apenas_da_lista: se True, ao sair do campo sem escolher um item que
      realmente existe na lista, o texto digitado é limpo (usado em campos
      que exigem selecionar algo já cadastrado, como "Adicionar Estoque").

    IMPORTANTE (busca pelo NOME, não pelo código): em várias telas do sistema
    os valores do combobox vêm no formato "codigo - nome" (ex.: "015 - Coca-
    Cola"), para que o código possa ser extraído depois com .split(" - ")[0].
    Se a busca comparasse o texto digitado com essa string inteira, o usuário
    só encontraria o item digitando o CÓDIGO primeiro. Por isso a busca aqui
    sempre é feita pelo NOME (a parte depois do "codigo - ", quando existir);
    o valor completo com o código só volta a aparecer no campo quando a
    escolha é confirmada (ENTER, clique na sugestão, seta ou seleção nativa),
    para não quebrar nada que dependa do código.
    """
    janela_pai = combobox.winfo_toplevel()

    try:
        combobox.configure(state="normal")
    except tk.TclError:
        pass

    popup_sug = tk.Toplevel(janela_pai)
    popup_sug.withdraw()
    popup_sug.overrideredirect(True)
    popup_sug.attributes("-topmost", True)
    lista_sug = tk.Listbox(popup_sug, activestyle="none", relief="flat",
                            highlightthickness=1, highlightbackground="#cccccc",
                            selectbackground="#e8e8e8", selectforeground="black",
                            font=("Arial", 10), bd=0)
    lista_sug.pack(fill="both", expand=True)

    estado_ac = {"prefixo": "", "sugestao_ativa": False, "indice": -1}
    TECLAS_NAVEGACAO_AC = ("Left", "Right", "Up", "Down", "Return", "Escape", "Tab",
                            "Shift_L", "Shift_R", "Control_L", "Control_R",
                            "Alt_L", "Alt_R", "Caps_Lock", "Home", "End")

    def _valores_atuais():
        bruto = obter_valores() if callable(obter_valores) else obter_valores
        return sorted([str(v) for v in bruto if str(v).strip()], key=lambda s: s.upper())

    def _chave_busca(item):
        """Parte do valor usada para BUSCAR (o nome). Se o valor estiver no
        formato 'codigo - nome', retorna só o nome; senão, retorna o próprio
        valor (caso do Lançar Nota, cujos valores já são só o nome)."""
        return item.split(" - ", 1)[1] if " - " in item else item

    def _mapa_nome_para_item(itens=None):
        """Mapa NOME (maiúsculo) -> valor completo, para poder recolocar o
        código de volta no campo mesmo quando o usuário só digitou o nome."""
        itens = itens if itens is not None else _valores_atuais()
        return {_chave_busca(item).upper(): item for item in itens}

    def _resolver_valor_final(texto):
        """Se o texto digitado for exatamente o NOME de um item cadastrado,
        devolve o valor completo (com código); senão devolve o texto como
        veio (permite digitar um código/texto livre em campos que aceitam)."""
        if not texto:
            return texto
        return _mapa_nome_para_item().get(texto.upper(), texto)

    def _fechar_popup():
        if popup_sug.winfo_ismapped():
            popup_sug.withdraw()
        estado_ac["indice"] = -1

    def _mostrar_popup(matches):
        if not matches:
            _fechar_popup()
            return
        lista_sug.delete(0, tk.END)
        for m in matches[:max_sugestoes]:
            lista_sug.insert(tk.END, m)
        lista_sug.selection_clear(0, tk.END)
        lista_sug.selection_set(0)
        lista_sug.activate(0)
        estado_ac["indice"] = 0

        combobox.update_idletasks()
        x = combobox.winfo_rootx()
        y = combobox.winfo_rooty() + combobox.winfo_height()
        largura = combobox.winfo_width()
        altura_linha = 22
        altura_total = min(len(matches), max_sugestoes) * altura_linha
        popup_sug.geometry(f"{largura}x{altura_total}+{x}+{y}")
        popup_sug.deiconify()
        popup_sug.lift()

    def _confirmar_valor(valor):
        estado_ac["prefixo"] = valor
        estado_ac["sugestao_ativa"] = False
        if ao_selecionar:
            ao_selecionar(valor)
        _fechar_popup()
        if proximo_widget is not None:
            proximo_widget.focus()

    def _selecionar_da_lista(event=None):
        sel = lista_sug.curselection()
        if not sel:
            return
        nome_sel = lista_sug.get(sel[0])
        item_completo = _mapa_nome_para_item().get(nome_sel.upper(), nome_sel)
        combobox.delete(0, tk.END)
        combobox.insert(0, item_completo)
        _confirmar_valor(item_completo)

    def _navegar_sugestoes(direcao):
        total = lista_sug.size()
        if total == 0:
            return "break"
        atual = estado_ac.get("indice", -1)
        novo = max(0, min(total - 1, atual + direcao))
        estado_ac["indice"] = novo
        lista_sug.selection_clear(0, tk.END)
        lista_sug.selection_set(novo)
        lista_sug.activate(novo)
        lista_sug.see(novo)
        nome_sel = lista_sug.get(novo)
        item_completo = _mapa_nome_para_item().get(nome_sel.upper(), nome_sel)
        combobox.delete(0, tk.END)
        combobox.insert(0, item_completo)
        combobox.icursor(tk.END)
        estado_ac["prefixo"] = item_completo
        estado_ac["sugestao_ativa"] = False
        if ao_selecionar:
            ao_selecionar(item_completo)
        return "break"

    def _preparar_antes_de_digitar(event):
        if event.keysym in ("BackSpace", "Delete"):
            estado_ac["sugestao_ativa"] = False
            return
        if event.keysym in TECLAS_NAVEGACAO_AC:
            return
        if estado_ac["sugestao_ativa"]:
            pos = len(estado_ac["prefixo"])
            combobox.delete(pos, tk.END)
            combobox.icursor(pos)
            estado_ac["sugestao_ativa"] = False

    def _autocomplete_digitacao(event):
        if event.keysym in ("BackSpace", "Delete") or event.keysym in TECLAS_NAVEGACAO_AC:
            return

        texto_digitado = combobox.get()
        estado_ac["prefixo"] = texto_digitado
        estado_ac["sugestao_ativa"] = False

        if not texto_digitado:
            _fechar_popup()
            return

        texto_upper = texto_digitado.upper()
        itens_atuais = _valores_atuais()
        # Busca sempre pelo NOME (ignora o código no início do valor)
        matches = [item for item in itens_atuais if _chave_busca(item).upper().startswith(texto_upper)]

        if matches:
            item_completo = matches[0]
            chave = _chave_busca(item_completo)
            pos = len(texto_digitado)
            # Completa o restante do NOME (efeito "fantasma"), mantendo o
            # código fora do campo enquanto o usuário ainda está digitando —
            # ele só volta quando a escolha é confirmada.
            combobox.delete(0, tk.END)
            combobox.insert(0, texto_digitado + chave[pos:])
            combobox.selection_range(pos, tk.END)
            combobox.icursor(pos)
            estado_ac["prefixo"] = texto_digitado
            estado_ac["sugestao_ativa"] = True
            if ao_selecionar:
                ao_selecionar(item_completo)
            nomes_sugeridos = list(dict.fromkeys(_chave_busca(m) for m in matches))
            _mostrar_popup(nomes_sugeridos)
        else:
            _fechar_popup()

    def _ao_selecionar_evento(event):
        _confirmar_valor(combobox.get())

    def _confirmar_enter(event):
        texto = _resolver_valor_final(combobox.get().strip())
        combobox.delete(0, tk.END)
        combobox.insert(0, texto)
        estado_ac["prefixo"] = texto
        estado_ac["sugestao_ativa"] = False
        if texto and ao_selecionar:
            ao_selecionar(texto)
        _fechar_popup()
        if proximo_widget is not None:
            proximo_widget.focus()
        return "break"

    def _validar_ao_sair(event=None):
        # Recoloca o código de volta no campo (se o usuário só digitou o
        # nome) imediatamente, ANTES de fechar o popup, para não haver
        # atraso caso outro widget (ex.: um botão) já leia o valor em seguida.
        texto_atual = combobox.get().strip()
        texto_resolvido = _resolver_valor_final(texto_atual)
        if texto_resolvido != texto_atual:
            combobox.delete(0, tk.END)
            combobox.insert(0, texto_resolvido)

        def _checar():
            _fechar_popup()
            if apenas_da_lista:
                texto = combobox.get().strip()
                if texto and texto.upper() not in {v.upper() for v in _valores_atuais()}:
                    combobox.delete(0, tk.END)
        janela_pai.after(150, _checar)

    def _seta_para_baixo(event):
        """Seta ↓: se já existe uma sugestão sendo filtrada (popup aberto),
        continua navegando nela normalmente (autocomplete intacto). Se não
        há filtro ativo (campo vazio / popup fechado), mostra a lista
        COMPLETA de itens do combobox — em vez de reaproveitar a sugestão
        (só 1 item) que ficou guardada do último item lançado."""
        if popup_sug.winfo_ismapped():
            return _navegar_sugestoes(1)

        todos = _valores_atuais()
        nomes_todos = list(dict.fromkeys(_chave_busca(item) for item in todos))
        if not nomes_todos:
            return "break"
        _mostrar_popup(nomes_todos)
        return "break"

    lista_sug.bind("<ButtonRelease-1>", _selecionar_da_lista)
    combobox.bind("<KeyPress>", _preparar_antes_de_digitar, add="+")
    combobox.bind("<KeyRelease>", _autocomplete_digitacao, add="+")
    combobox.bind("<<ComboboxSelected>>", _ao_selecionar_evento, add="+")
    combobox.bind("<Down>", _seta_para_baixo)
    combobox.bind("<Up>", lambda e: _navegar_sugestoes(-1))
    combobox.bind("<Return>", _confirmar_enter)
    combobox.bind("<Escape>", lambda e: _fechar_popup())
    combobox.bind("<FocusOut>", _validar_ao_sair, add="+")

    return _fechar_popup


