# --- FUNÇÃO AUXILIAR PARA CONVERTER DATA BR PARA SQL (AAAA-MM-DD) ---
def data_br_para_sql(data_br):
    try:
        dia, mes, ano = data_br.split('/')
        return f"{ano}-{mes}-{dia}"
    except:
        return None

# --- FUNÇÃO DE BUSCA ATUALIZADA ---
def gerar_rel_avancado():
    if _periodo_invalido(e_data_inicio_desp.get(), e_data_fim_desp.get(), e_data_inicio_desp):
        return
    tree_itens.delete(*tree_itens.get_children())

    # CONEXÃO CORRETA
    conn = abrir_conexao_curta()
    cur = conn.cursor()

    d_inicio = e_data_inicio_desp.get().strip()
    d_fim = e_data_fim_desp.get().strip()
    busca = e_busca_desp.get().strip()
    tipo = cb_tipo_relat.get()

    if tipo == "Item":
        select_cols = "di.item, di.categoria_item"
        group_col = "di.item"
    else:
        select_cols = "d.fornecedor, di.categoria_item"
        group_col = "d.fornecedor"

    query = f"""
        SELECT {select_cols}, SUM(di.valor), COUNT(di.id)
        FROM despesas_itens di
        LEFT JOIN despesas d ON di.id_despesa = d.id
        WHERE 1=1
    """
    params = []

    # FILTRO DATA
    if d_inicio and d_fim:
        d_ini = data_br_para_sql(d_inicio)
        d_fim_sql2 = data_br_para_sql(d_fim)
        query += " AND (date(di.data_lancamento) BETWEEN ? AND ? OR di.data_lancamento BETWEEN ? AND ?)"
        params += [d_ini, d_fim_sql2, f"{d_ini} 00:00:00", f"{d_fim_sql2} 23:59:59"]

# FILTRO TEXTO (Melhorado para buscar em Item e Fornecedor)
    if busca:
        query += " AND (di.item LIKE ? OR d.fornecedor LIKE ?)"
        params.extend([f"%{busca}%", f"%{busca}%"])


    query += f" GROUP BY {group_col} ORDER BY SUM(di.valor) DESC"

    print("QUERY:", query)
    print("PARAMS:", params)

    dados = cur.execute(query, params).fetchall()

    if not dados:
        messagebox.showwarning("Relatório", "Nenhum dado encontrado.")
        conn.close()
        return

    for nome, categoria, total, qtd in dados:
        total_br = f"R$ {total:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        tree_itens.insert("", "end", values=(nome, categoria, total_br, qtd))

    conn.close()

def imprimir_despesas_termica():
    if _periodo_invalido(e_data_inicio_desp.get(), e_data_fim_desp.get(), e_data_inicio_desp):
        return
    import os
    conn = abrir_conexao_curta()
    cursor = conn.cursor()

    # Pega as datas dos campos de entrada
    data_ini_br = e_data_inicio_desp.get().strip()
    data_fim_br = e_data_fim_desp.get().strip()
    busca = e_busca_desp.get().strip()
    tipo = cb_tipo_relat.get()

    # Converte para SQL
    d_ini = data_br_para_sql(data_ini_br)
    d_fim = data_br_para_sql(data_fim_br)

    campo = "di.item" if tipo == "Item" else "d.fornecedor"
    titulo = "DESPESAS POR ITEM" if tipo == "Item" else "DESPESAS POR FORNECEDOR"

    # Query IDÊNTICA à de busca para não dar erro de diferença
    query = f"""
        SELECT {campo}, SUM(di.valor)
        FROM despesas_itens di
        LEFT JOIN despesas d ON di.id_despesa = d.id
        WHERE 1=1
    """
    params = []

    if d_ini and d_fim:
        # Usamos LIKE para pegar a data mesmo que tenha HORA junto no banco
        query += " AND di.data_lancamento BETWEEN ? AND ?"
        params.extend([f"{d_ini} 00:00:00", f"{d_fim} 23:59:59"])

    if busca:
        query += " AND (di.item LIKE ? OR d.fornecedor LIKE ?)"
        params.extend([f"%{busca}%", f"%{busca}%"])

    query += f" GROUP BY {campo} ORDER BY SUM(di.valor) DESC"

    cursor.execute(query, params)
    dados = cursor.fetchall()
    conn.close()

    if not dados:
        messagebox.showinfo("Aviso", "Nada para imprimir!\nVerifique se as datas e o filtro de busca são os mesmos da tela.")
        return

    # --- FORMATAÇÃO PARA IMPRESSORA 50mm ---
    L = 32 
    texto = "="*L + "\n"
    texto += "SABORES DA CUMBUCA".center(L) + "\n"
    texto += titulo.center(L) + "\n"
    texto += f"{data_ini_br} a {data_fim_br}".center(L) + "\n"
    texto += "="*L + "\n"
    texto += "DESCRICAO".ljust(21) + "TOTAL".rjust(11) + "\n"
    texto += "-"*L + "\n"

    total_geral = 0
    for nome, valor in dados:
        n = (nome if nome else "DIVERSOS")
        # Se o nome for grande, corta para não quebrar a linha da impressora
        texto += f"{n[:20].ljust(21)} {valor:>10.2f}\n"
        total_geral += valor

    texto += "-"*L + "\n"
    texto += f"TOTAL GERAL: R$ {total_geral:>15.2f}\n"
    texto += "="*L + "\n\n\n\n\n" 

    with open("imp_despesas.txt", "w", encoding="utf-8") as f:
        f.write(texto)
    
    os.startfile("imp_despesas.txt")

