def gerar_relatorio():
    """ Gera relatórios formatados — exibe na tela e gera arquivo para impressora térmica. """
    tree_relatorio.delete(*tree_relatorio.get_children())
    data_ini = e_data_inicio.get().strip()
    data_fim = e_data_fim.get().strip()
    tipo = tipo_relatorio.get()

    if not data_ini or not data_fim:
        messagebox.showwarning("Atenção", "Preencha as datas de Início e Fim antes de gerar o relatório.")
        return

    try:
        data_ini_sql = datetime.strptime(data_ini, "%d/%m/%Y").strftime("%Y-%m-%d")
        data_fim_sql = datetime.strptime(data_fim, "%d/%m/%Y").strftime("%Y-%m-%d")
    except ValueError:
        messagebox.showerror("Erro", "Use o formato DD/MM/AAAA nas datas.")
        return

    conn_rel = abrir_conexao_curta()
    cur_rel = conn_rel.cursor()

    try:
        # --- TOTAL DE VENDAS (base para todos os tipos) ---
        # Mesmo critério da aba Vendas e do Resumo de Caixa: tudo que foi vendido,
        # inclusive pedidos PENDENTES (item já entregue, só não pago). Ficam de
        # fora apenas DESCARTE e CANCELADO.
        cur_rel.execute("""
            SELECT COALESCE(SUM(total), 0) FROM pedidos
            WHERE date(data) BETWEEN ? AND ?
              AND UPPER(pagamento) NOT IN ('DESCARTE', 'CANCELADO')
        """, (data_ini_sql, data_fim_sql))
        total_vendas = cur_rel.fetchone()[0] or 0

        L = 32
        header = "=" * L + "\n"
        line = "-" * L + "\n"
        texto = header + "CUMBUCA DELIVERY".center(L) + "\n" + tipo.upper().center(L) + "\n" + header
        texto += f"PERIODO: {data_ini} a {data_fim}\n" + line

        tem_dados = False

        # ── VENDAS POR ITEM ──────────────────────────────────────
        if tipo in ["Relatório Completo", "Vendas por Item"]:
            if tipo == "Relatório Completo":
                texto += "[1] VENDAS POR ITEM\n"
            texto += "QTD PRODUTO        VALOR\n" + line

            cur_rel.execute("""
                SELECT ip.produto,
                       SUM(ip.quantidade),
                       SUM(ip.quantidade * ip.venda)
                FROM itens_pedido ip
                JOIN pedidos p ON p.id = ip.pedido_id
                WHERE date(p.data) BETWEEN ? AND ?
                  AND UPPER(p.pagamento) NOT IN ('DESCARTE', 'CANCELADO')
                GROUP BY ip.produto
                ORDER BY SUM(ip.quantidade) DESC
            """, (data_ini_sql, data_fim_sql))

            vendas_detalhadas = cur_rel.fetchall()

            if vendas_detalhadas:
                tem_dados = True
                for prod, qtd, valor in vendas_detalhadas:
                    valor = valor or 0
                    texto += f"{str(qtd)[:3]:>3} {prod[:16].ljust(17)} {valor:>8.2f}\n"
                    tree_relatorio.insert("", "end", values=(
                        prod, qtd,
                        f"R$ {valor:,.2f}".replace(",","X").replace(".",",").replace("X","."),
                        "-", "-", "-"
                    ))
            else:
                tree_relatorio.insert("", "end", values=("Nenhuma venda no período", "-", "-", "-", "-", "-"))

            texto += line + f"SUBTOTAL: R$ {total_vendas:>10.2f}\n\n"

        # ── RESUMO DE CAIXA ──────────────────────────────────────
        # REGRA 3: este bloco usa EXCLUSIVAMENTE caixa.data e nunca soma
        # pedidos.total. "Vendas" e "Caixa" são relatórios independentes.
        if tipo in ["Relatório Completo", "Resumo de Caixa"]:
            cur_rel.execute("""
                SELECT COALESCE(SUM(valor), 0) FROM caixa
                WHERE tipo='ENTRADA'
                  AND date(data) BETWEEN ? AND ?
            """, (data_ini_sql, data_fim_sql))
            total_ent = cur_rel.fetchone()[0] or 0

            cur_rel.execute("""
                SELECT COALESCE(SUM(valor), 0) FROM caixa
                WHERE tipo='SAIDA'
                  AND date(data) BETWEEN ? AND ?
            """, (data_ini_sql, data_fim_sql))
            total_sai = cur_rel.fetchone()[0] or 0

            cur_rel.execute("""
                SELECT COALESCE(SUM(saldo_inicial),0) + COALESCE(SUM(saldo_inicial_pix),0)
                FROM ciclos_caixa
                WHERE date(abertura) BETWEEN ? AND ?
            """, (data_ini_sql, data_fim_sql))
            row_ab = cur_rel.fetchone()
            v_abertura = row_ab[0] if row_ab and row_ab[0] is not None else 0

            # REGRA 3: saldo do caixa é SOMENTE abertura + entradas - saídas
            # (todas vindas de `caixa`). Nunca soma total_vendas aqui.
            saldo = (v_abertura + total_ent) - total_sai

            if tipo == "Relatório Completo":
                texto += "[2] CAIXA (dinheiro que efetivamente entrou/saiu)\n"
            texto += line
            texto += f"ABERTURA CAIXA:  R$ {v_abertura:>9.2f}\n"
            texto += f"ENTRADAS (+):    R$ {total_ent:>9.2f}\n"
            texto += f"SAIDAS (-):      R$ {total_sai:>9.2f}\n"
            texto += line + f"SALDO CAIXA:    R$ {saldo:>10.2f}\n"
            texto += f"\n(Vendas do período, por data do pedido: R$ {total_vendas:>.2f} — referência comercial, não soma ao saldo do caixa)\n"

            def fmt(v):
                return f"R$ {v:,.2f}".replace(",","X").replace(".",",").replace("X",".")

            tree_relatorio.insert("", "end", values=("── VENDAS (data do pedido) ──", "", "", "", "", ""))
            tree_relatorio.insert("", "end", values=("Total de Vendas",     "-", fmt(total_vendas), "-", "-", "-"))
            tree_relatorio.insert("", "end", values=("── CAIXA (data do recebimento) ──", "", "", "", "", ""))
            tree_relatorio.insert("", "end", values=("Abertura de Caixa",   "-", fmt(v_abertura), "-", "-", "-"))
            tree_relatorio.insert("", "end", values=("Entradas no Caixa",   "-", fmt(total_ent), "-", "-", "-"))
            tree_relatorio.insert("", "end", values=("Saídas do Caixa",     "-", f"- {fmt(total_sai)}", "-", "-", "-"))
            tree_relatorio.insert("", "end", values=("SALDO DO CAIXA",      "-", fmt(saldo), "-", "-", "-"))
            tem_dados = True

        texto += "\n" + header + "OBRIGADO E BOAS VENDAS!".center(L) + "\n" + header

        if not tem_dados:
            messagebox.showinfo("Relatório", "Nenhum dado encontrado para o período informado.")
            return

        caminho_rel = os.path.join(pasta_real(), "relatorio_termico.txt")
        with open(caminho_rel, "w", encoding="utf-8") as f:
            f.write(texto)
        os.startfile(caminho_rel)

    except Exception as e:
        messagebox.showerror("Erro ao gerar relatório", str(e))
    finally:
        conn_rel.close()


def filtrar_pendencias_por_cliente():
    if _periodo_invalido(e_data_inicio_pend.get(), e_data_fim_pend.get(), e_data_inicio_pend):
        return
    for item in tree_pendencias.get_children():
        tree_pendencias.delete(item)

    cliente_busca = e_busca_cliente_pend.get().strip()
    data_ini = e_data_inicio_pend.get().strip()
    data_fim = e_data_fim_pend.get().strip()

    try:
        # Datas BR → SQL
        d_ini_sql = datetime.strptime(data_ini, "%d/%m/%Y").strftime("%Y-%m-%d") if data_ini else "2000-01-01"
        d_fim_sql = datetime.strptime(data_fim, "%d/%m/%Y").strftime("%Y-%m-%d") if data_fim else "2099-12-31"

        conn = abrir_conexao_curta()
        cursor = conn.cursor()

        query = """
        SELECT 
            id,
            cliente,
            data,
            total,
            COALESCE(valor_pago,0),
            pagamento
        FROM pedidos
        WHERE UPPER(COALESCE(pagamento,'')) NOT IN ('CANCELADO', 'DESCARTE')
        AND (total - COALESCE(valor_pago,0)) > 0.001
        AND (
              UPPER(COALESCE(pagamento,'')) IN ('', 'PENDENTE')
              OR (COALESCE(valor_pago,0) > 0.001 AND COALESCE(valor_pago,0) < total - 0.001)
            )
        AND date(data) BETWEEN ? AND ?
        """
        params = [d_ini_sql, d_fim_sql]

        if cliente_busca:
            _sql_cli, _par_cli = cdb_clausula_cliente(e_busca_cliente_pend)
            query += " AND " + _sql_cli
            params.extend(_par_cli)

        query += " ORDER BY data DESC"

        cursor.execute(query, params)
        pendencias = cursor.fetchall()
        conn.close()

        if not pendencias:
            messagebox.showinfo("Pendências", "Nenhuma pendência encontrada.")
            return

        total_geral = 0

        for p in pendencias:
            id_ped, nome, data_db, total, valor_pago, pagamento = p
        
            valor_restante = total - valor_pago
        
            total_geral += valor_restante

            data_f = data_db[8:10] + "/" + data_db[5:7]
            valor_fmt = f"R$ {valor_restante:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
            tree_pendencias.insert(
                "",
                "end",
                values=(
                    id_ped,
                    nome,
                    data_f,
                    valor_fmt,
                    pagamento
                )
            )

        # Pergunta se quer imprimir
        resp = messagebox.askyesno("Impressão", f"Total a receber: R$ {total_geral:.2f}\n\nDeseja imprimir o relatório?")

        if resp:
            gerar_txt_pendencias_cumbuca(pendencias, total_geral)

    except Exception as e:
        messagebox.showerror("Erro", f"Erro ao filtrar pendências:\n{e}")

def consumo_por_cliente():
    """Abre janela com resumo completo de tudo que o cliente comprou (pedidos não cancelados)."""
    import tkinter as tk
    from tkinter import ttk, messagebox

    cliente_busca = e_busca_cliente_consumo.get().strip()
    data_ini = e_data_inicio_cli.get().strip()
    data_fim = e_data_fim_cli.get().strip()

    if _periodo_invalido(data_ini, data_fim, e_data_inicio_cli):
        return

    try:
        d_ini_sql = datetime.strptime(data_ini, "%d/%m/%Y").strftime("%Y-%m-%d") if data_ini else "2000-01-01"
        d_fim_sql = datetime.strptime(data_fim, "%d/%m/%Y").strftime("%Y-%m-%d") if data_fim else "2099-12-31"
    except ValueError:
        messagebox.showerror("Erro", "Use o formato DD/MM/AAAA nas datas.")
        return

    conn2 = abrir_conexao_curta()
    cur2 = conn2.cursor()

    # --- 1. Busca pedidos do cliente (excluindo cancelados) ---
    q_pedidos = """
        SELECT id, cliente, data, total, COALESCE(valor_pago,0), pagamento
        FROM pedidos
        WHERE UPPER(pagamento) NOT IN ('DESCARTE', 'CANCELADO')
          AND UPPER(COALESCE(observacao,'')) NOT LIKE '%CANCELADO%'
          AND date(data) BETWEEN ? AND ?
    """
    params2 = [d_ini_sql, d_fim_sql]
    if cliente_busca:
        _sql_cli, _par_cli = cdb_clausula_cliente(e_busca_cliente_consumo)
        q_pedidos += " AND " + _sql_cli
        params2.extend(_par_cli)
    q_pedidos += " ORDER BY cliente ASC, data DESC"

    cur2.execute(q_pedidos, params2)
    pedidos = cur2.fetchall()

    if not pedidos:
        messagebox.showinfo("Consumo por Cliente", "Nenhum pedido encontrado para os filtros informados.")
        conn2.close()
        return

    # --- 2. Busca itens dos pedidos encontrados ---
    ids_pedidos = [str(p[0]) for p in pedidos]
    placeholders = ",".join(["?"] * len(ids_pedidos))
    cur2.execute(f"""
        SELECT pedido_id, produto, quantidade, venda
        FROM itens_pedido
        WHERE pedido_id IN ({placeholders})
        ORDER BY pedido_id ASC
    """, ids_pedidos)
    itens_raw = cur2.fetchall()
    conn2.close()

    # Mapeia itens por pedido
    itens_por_pedido = {}
    for pid, prod, qtd, venda in itens_raw:
        itens_por_pedido.setdefault(pid, []).append((prod, qtd, venda))

    # --- 3. Agrupa por cliente ---
    from collections import defaultdict
    resumo = defaultdict(lambda: {
        "total_geral": 0.0,
        "total_pago": 0.0,
        "total_pendente": 0.0,
        "qtd_pedidos": 0,
        "itens": defaultdict(lambda: {"qtd": 0, "valor": 0.0})
    })

    for id_ped, nome, data_db, total, valor_pago, pagamento in pedidos:
        cli = nome.upper().strip()
        r = resumo[cli]
        r["qtd_pedidos"] += 1
        r["total_geral"] += total
        pendente = total - valor_pago
        if pendente < 0:
            pendente = 0
        r["total_pago"] += valor_pago
        if pagamento.upper() == "PENDENTE":
            r["total_pendente"] += pendente
        for prod, qtd, venda in itens_por_pedido.get(id_ped, []):
            r["itens"][prod]["qtd"] += qtd
            r["itens"][prod]["valor"] += qtd * venda

    # --- 4. Janela de exibição ---
    jan = tk.Toplevel(root)
    jan.title("👤 Consumo por Cliente")
    jan.geometry("820x580")
    jan.configure(bg=COR_FUNDO)

    try:
        jan.iconbitmap(CAMINHO_ICONE)
    except Exception:
        pass

    # Cabeçalho
    ctk.CTkLabel(
        jan,
        text="👤  CONSUMO POR CLIENTE",
        font=("Segoe UI Semibold", 15),
        text_color=COR_TEXTO,
        fg_color="transparent"
    ).pack(pady=(12, 2))

    periodo_txt = f"Período: {data_ini or '—'}  até  {data_fim or '—'}"
    if cliente_busca:
        periodo_txt += f"   |   Cliente: {cliente_busca.upper()}"
    ctk.CTkLabel(
        jan,
        text=periodo_txt,
        font=("Segoe UI", 10),
        text_color="#557A65",
        fg_color="transparent"
    ).pack(pady=(0, 8))

    # Frame principal com Notebook (abas por cliente ou lista única)
    frame_central = tk.Frame(jan, bg=COR_FUNDO)
    frame_central.pack(fill="both", expand=True, padx=10, pady=4)

    # Treeview superior: resumo por cliente
    cols_res = ("cliente", "pedidos", "total_geral", "total_pago", "pendente")
    tree_res = ttk.Treeview(frame_central, columns=cols_res, show="headings", height=6)
    tree_res.heading("cliente",      text="👤 Cliente")
    tree_res.heading("pedidos",      text="Pedidos")
    tree_res.heading("total_geral",  text="Total Comprado")
    tree_res.heading("total_pago",   text="Total Pago")
    tree_res.heading("pendente",     text="Pendente")

    tree_res.column("cliente",     width=220, anchor="w")
    tree_res.column("pedidos",     width=70,  anchor="center")
    tree_res.column("total_geral", width=130, anchor="e")
    tree_res.column("total_pago",  width=130, anchor="e")
    tree_res.column("pendente",    width=130, anchor="e")

    sb_res = ttk.Scrollbar(frame_central, orient="vertical", command=tree_res.yview)
    tree_res.configure(yscrollcommand=sb_res.set)
    tree_res.pack(side="left", fill="both", expand=False)
    sb_res.pack(side="left", fill="y")
    ativar_lista_interativa(tree_res, "cliente")

    # Treeview inferior: itens do cliente selecionado
    frame_itens = tk.LabelFrame(jan, text="🛒 Itens Consumidos pelo Cliente Selecionado",
                                 bg=COR_FUNDO, fg=COR_TEXTO, font=("Segoe UI", 10, "bold"))
    frame_itens.pack(fill="both", expand=True, padx=10, pady=(6, 10))

    cols_it = ("produto", "qtd_total", "valor_total")
    tree_it = ttk.Treeview(frame_itens, columns=cols_it, show="headings", height=7)
    tree_it.heading("produto",     text="📦 Produto")
    tree_it.heading("qtd_total",   text="Qtd Total")
    tree_it.heading("valor_total", text="Valor Total (R$)")

    tree_it.column("produto",     width=320, anchor="w")
    tree_it.column("qtd_total",   width=100, anchor="center")
    tree_it.column("valor_total", width=150, anchor="e")

    sb_it = ttk.Scrollbar(frame_itens, orient="vertical", command=tree_it.yview)
    tree_it.configure(yscrollcommand=sb_it.set)
    tree_it.pack(side="left", fill="both", expand=True)
    ativar_lista_interativa(tree_it, "produto")
    sb_it.pack(side="left", fill="y")

    # Popula resumo
    grand_total = 0.0
    for cli, r in sorted(resumo.items()):
        pend_fmt = f"R$ {r['total_pendente']:,.2f}".replace(",","X").replace(".",",").replace("X",".")
        pago_fmt = f"R$ {r['total_pago']:,.2f}".replace(",","X").replace(".",",").replace("X",".")
        tot_fmt  = f"R$ {r['total_geral']:,.2f}".replace(",","X").replace(".",",").replace("X",".")
        grand_total += r["total_geral"]
        tag = "pendente" if r["total_pendente"] > 0 else ""
        tree_res.insert("", "end", iid=cli,
                         values=(cli, r["qtd_pedidos"], tot_fmt, pago_fmt, pend_fmt),
                         tags=(tag,))

    tree_res.tag_configure("pendente", foreground="#B03A2E")

    # Linha TOTAL GERAL
    grand_fmt = f"R$ {grand_total:,.2f}".replace(",","X").replace(".",",").replace("X",".")
    tree_res.insert("", "end", values=("── TOTAL GERAL ──", "", grand_fmt, "", ""), tags=("total",))
    tree_res.tag_configure("total", font=("Segoe UI", 9, "bold"), foreground="#1B5E20")

    # Ao clicar num cliente, carrega os itens dele
    def on_selecionar_cliente(event):
        tree_it.delete(*tree_it.get_children())
        sel = tree_res.selection()
        if not sel:
            return
        cli_sel = sel[0]
        if cli_sel not in resumo:
            return
        itens_cli = resumo[cli_sel]["itens"]
        for prod, dados in sorted(itens_cli.items(), key=lambda x: -x[1]["valor"]):
            val_fmt = f"R$ {dados['valor']:,.2f}".replace(",","X").replace(".",",").replace("X",".")
            tree_it.insert("", "end", values=(prod, dados["qtd"], val_fmt))

    tree_res.bind("<<TreeviewSelect>>", on_selecionar_cliente)

    # Botão fechar
    ctk.CTkButton(
        jan,
        text="✖ Fechar",
        fg_color="#C0392B",
        hover_color="#922B21",
        text_color="white",
        width=120,
        height=34,
        corner_radius=8,
        command=jan.destroy
    ).pack(pady=(0, 10))


def gerar_txt_pendencias_cumbuca(pendencias, total_geral, nome_cliente="GERAL"):
    import os
    from datetime import datetime

    agora = datetime.now().strftime("%d/%m/%Y %H:%M")
    caminho = os.path.join(pasta_real(), "relatorio_pendencias.txt")

    largura_total = 32  # largura máxima da linha
    coluna_nota = 5
    coluna_data = 5
    coluna_valor = 8
    coluna_nome = largura_total - (coluna_nota + coluna_data + coluna_valor + 3)

    with open(caminho, "w", encoding="utf-8") as f:

        # CABEÇALHO
        f.write("SABORES DA CUMBUCA\n")
        f.write("RELATÓRIO DE PENDÊNCIAS\n")
        f.write(f"CLIENTE: {nome_cliente}\n")
        f.write(f"GERADO EM: {agora}\n")
        f.write("-" * largura_total + "\n")

        # TABELA
        f.write(
            f"{'NOTA':<{coluna_nota}} "
            f"{'DATA':<{coluna_data}} "
            f"{'CLI':<{coluna_nome}} "
            f"{'VALOR':>{coluna_valor}}\n"
        )

        f.write("-" * largura_total + "\n")

        for p in pendencias:

            # Compatibilidade com bancos antigos
            # sem valor_pago
            if len(p) == 5:
                id_ped, nome, data_db, total, pagamento = p
                valor_pago = 0
            else:
                id_ped, nome, data_db, total, valor_pago, pagamento = p

            # Calcula restante
            valor_restante = total - valor_pago

            # Evita negativo
            if valor_restante < 0:
                valor_restante = 0

            data_f = data_db[8:10] + "/" + data_db[5:7]

            # Ajusta nome
            if len(nome) > coluna_nome:
                nome = nome[:coluna_nome - 1] + "…"

            f.write(
                f"#{id_ped:<{coluna_nota-1}} "
                f"{data_f:<{coluna_data}} "
                f"{nome:<{coluna_nome}} "
                f"R${valor_restante:>{coluna_valor-2},.2f}\n"
            )

        # TOTAL FINAL
        f.write("-" * largura_total + "\n")

        f.write(
            f"{'TOTAL A RECEBER:':<{largura_total - coluna_valor}} "
            f"R${total_geral:>{coluna_valor-2},.2f}\n"
        )

        f.write("-" * largura_total + "\n")
        f.write("OBRIGADO E VOLTE SEMPRE\n")

    # Abre automaticamente
    os.startfile(caminho)

def abrir_filtro_relatorio_caixa():
    """ Janela de filtro rápido para o Relatório Caixa: Caixa Aberto / Caixa do Dia / Período. """
    janela_filtro = tk.Toplevel(root)
    janela_filtro.title("Relatório Caixa - Filtro")
    janela_filtro.geometry("540x360")
    janela_filtro.grab_set()
    janela_filtro.resizable(False, False)

    ttk.Label(janela_filtro, text="RELATÓRIO CAIXA", font=("Arial", 12, "bold")).pack(pady=(15, 10))

    ttk.Button(
        janela_filtro, text="🟢 Caixa Aberto", width=30,
        command=lambda: [janela_filtro.destroy(), gerar_relatorio_caixa_agrupado("aberto")]
    ).pack(pady=6)

    ttk.Button(
        janela_filtro, text="📅 Caixa do Dia (hoje)", width=30,
        command=lambda: [janela_filtro.destroy(), gerar_relatorio_caixa_agrupado("dia")]
    ).pack(pady=6)

    tk.Frame(janela_filtro, height=2, bd=1, relief="sunken").pack(fill="x", padx=15, pady=12)

    ttk.Label(janela_filtro, text="FILTRAR POR PERÍODO (DD/MM/AAAA):", font=("Arial", 9)).pack()
    frame_datas = tk.Frame(janela_filtro)
    frame_datas.pack(pady=6)

    e_data_ini_rc = CampoData(frame_datas, width=12)
    e_data_ini_rc.pack(side="left", padx=2)
    ttk.Label(frame_datas, text="até").pack(side="left")
    e_data_fim_rc = CampoData(frame_datas, width=12)
    e_data_fim_rc.pack(side="left", padx=2)
    criar_atalhos_periodo(janela_filtro, e_data_ini_rc, e_data_fim_rc).pack(pady=(0, 4))

    def confirmar_periodo_rc():
        d_ini = e_data_ini_rc.get().strip()
        d_fim = e_data_fim_rc.get().strip()
        if _periodo_invalido(d_ini, d_fim, janela_filtro):
            return
        try:
            datetime.strptime(d_ini, "%d/%m/%Y")
            datetime.strptime(d_fim, "%d/%m/%Y")
        except ValueError:
            messagebox.showerror("Erro", "Formato de data inválido! Use DD/MM/AAAA", parent=janela_filtro)
            return
        janela_filtro.destroy()
        gerar_relatorio_caixa_agrupado("periodo", d_ini, d_fim)

    ttk.Button(
        janela_filtro, text="🔍 Gerar por Período", width=30,
        command=confirmar_periodo_rc
    ).pack(pady=12)


def gerar_relatorio_caixa_agrupado(modo, data_ini=None, data_fim=None):
    """
    Gera o Relatório Caixa (aba Pedidos) para impressora 50mm, agrupado
    por forma de pagamento (Pendente, Pix, Cartão, Dinheiro...), com
    subtotal por grupo e total geral no final.

    modo: "aberto"  -> pedidos do ciclo de caixa aberto (comportamento antigo)
          "dia"     -> todos os pedidos com data = hoje (independe de caixa aberto/fechado)
          "periodo" -> todos os pedidos com data entre data_ini e data_fim (DD/MM/AAAA)
    """
    if modo == "aberto":
        if not ciclo_caixa_aberto.get("id"):
            messagebox.showwarning("Aviso", "Não há um ciclo de caixa aberto para listar pedidos.")
            return
        where_extra = "AND ciclo_caixa_id = ?"
        params = [ciclo_caixa_aberto["id"]]
        titulo_modo = f"CAIXA ABERTO (ID {ciclo_caixa_aberto['id']})"

    elif modo == "dia":
        hoje_sql = datetime.now().strftime("%Y-%m-%d")
        where_extra = "AND date(data) = ?"
        params = [hoje_sql]
        titulo_modo = f"CAIXA DO DIA {datetime.now().strftime('%d/%m/%Y')}"

    elif modo == "periodo":
        try:
            d_ini_sql = datetime.strptime(data_ini, "%d/%m/%Y").strftime("%Y-%m-%d")
            d_fim_sql = datetime.strptime(data_fim, "%d/%m/%Y").strftime("%Y-%m-%d")
        except (ValueError, TypeError):
            messagebox.showerror("Erro", "Formato de data inválido! Use DD/MM/AAAA")
            return
        where_extra = "AND date(data) BETWEEN ? AND ?"
        params = [d_ini_sql, d_fim_sql]
        titulo_modo = f"PERIODO {data_ini} a {data_fim}"

    else:
        return

    cursor.execute(f"""
        SELECT id, cliente, total, pagamento
        FROM pedidos
        WHERE 1=1 {where_extra}
          AND UPPER(COALESCE(pagamento,'')) NOT IN ('DESCARTE', 'CANCELADO')
          AND UPPER(COALESCE(observacao,'')) NOT LIKE '%CANCELADO%'
        ORDER BY id ASC
    """, params)

    pedidos = cursor.fetchall()

    if not pedidos:
        messagebox.showinfo("Aviso", "Nenhum pedido encontrado para esse filtro.")
        return

    # --- Agrupa por forma de pagamento (mantém ordem por ID crescente dentro do grupo) ---
    grupos_ordem = ["Pendente", "Pix", "Cartão", "Dinheiro", "Funcionário", "Outros"]
    grupos = {nome: [] for nome in grupos_ordem}

    for id_ped, cliente, total, pagamento in pedidos:
        pagamento_norm = str(pagamento).strip() if pagamento else ""
        if not pagamento_norm:
            chave = "Pendente"
        elif pagamento_norm in grupos:
            chave = pagamento_norm
        else:
            chave = "Outros"
        grupos[chave].append((id_ped, cliente, total or 0))

    L = 32  # largura térmica 50mm
    header = "=" * L + "\n"
    line = "-" * L + "\n"

    texto = header
    texto += "RELATORIO CAIXA".center(L) + "\n"
    texto += titulo_modo[:L].center(L) + "\n"
    texto += header
    texto += f"Gerado: {datetime.now().strftime('%d/%m/%Y %H:%M')}\n"
    texto += line

    total_geral = 0.0

    for nome_grupo in grupos_ordem:
        lista = grupos[nome_grupo]
        if not lista:
            continue

        subtotal = sum(item[2] for item in lista)
        total_geral += subtotal

        texto += f"\n[{nome_grupo.upper()}]\n"
        texto += "ID  CLIENTE        VALOR\n"
        texto += line
        for id_ped, cliente, valor in lista:
            id_fmt = str(id_ped).rjust(3)
            cliente_fmt = str(cliente or "-")[:12].ljust(12)
            texto += f"{id_fmt} {cliente_fmt} {valor:>7.2f}\n"
        texto += line
        texto += f"SUBTOTAL {nome_grupo.upper()}: R$ {subtotal:>8.2f}\n"

    texto += "\n" + header
    texto += "TOTAL GERAL:\n"
    texto += f"R$ {total_geral:,.2f}".center(L) + "\n"
    texto += header

    caminho = "relatorio_caixa.txt"
    with open(caminho, "w", encoding="utf-8") as f:
        f.write(texto)

    try:
        os.startfile(caminho)
    except Exception:
        pass


def gerar_relatorio_vendas():
    """ Vendas por Item no período. Conta tudo que foi vendido/entregue,
    inclusive pedidos com pagamento ainda PENDENTE (o item já saiu do
    estoque e foi entregue — só não foi pago ainda). Só ficam de fora
    pedidos DESCARTE e CANCELADO. """
    if _periodo_invalido(e_data_inicio_vendas.get(), e_data_fim_vendas.get(), e_data_inicio_vendas):
        return
    tree_vendas.delete(*tree_vendas.get_children())
    data_ini = e_data_inicio_vendas.get().strip()
    data_fim = e_data_fim_vendas.get().strip()

    if not data_ini or not data_fim:
        messagebox.showwarning("Atenção", "Preencha as datas de Início e Fim.")
        return

    try:
        data_ini_sql = datetime.strptime(data_ini, "%d/%m/%Y").strftime("%Y-%m-%d")
        data_fim_sql = datetime.strptime(data_fim, "%d/%m/%Y").strftime("%Y-%m-%d")
    except ValueError:
        messagebox.showerror("Erro", "Use o formato DD/MM/AAAA nas datas.")
        return

    conn_v = abrir_conexao_curta()
    cur_v = conn_v.cursor()
    try:
        cur_v.execute("""
            SELECT ip.produto,
                   SUM(ip.quantidade),
                   SUM(ip.quantidade * ip.venda)
            FROM itens_pedido ip
            JOIN pedidos p ON p.id = ip.pedido_id
            WHERE date(p.data) BETWEEN ? AND ?
              AND UPPER(p.pagamento) NOT IN ('DESCARTE', 'CANCELADO')
            GROUP BY ip.produto
            ORDER BY SUM(ip.quantidade) DESC
        """, (data_ini_sql, data_fim_sql))
        vendas = cur_v.fetchall()

        if not vendas:
            lbl_total_vendas.config(text="Total do período: R$ 0,00")
            messagebox.showinfo("Vendas por Item", "Nenhuma venda encontrada para o período informado.")
            return

        total_geral = 0
        for prod, qtd, valor in vendas:
            valor = valor or 0
            total_geral += valor
            valor_fmt = f"R$ {valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
            tree_vendas.insert("", "end", values=(prod, qtd, valor_fmt))

        total_fmt = f"R$ {total_geral:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        lbl_total_vendas.config(text=f"Total do período: {total_fmt}")

    except Exception as e:
        messagebox.showerror("Erro ao gerar relatório de vendas", str(e))
    finally:
        conn_v.close()


def imprimir_relatorio_vendas():
    """ Gera o .txt (formato térmico 50mm) com a Vendas por Item já exibida na tela. """
    linhas = tree_vendas.get_children()
    if not linhas:
        messagebox.showinfo("Aviso", "Gere o relatório de Vendas por Item antes de imprimir.")
        return

    data_ini = e_data_inicio_vendas.get().strip()
    data_fim = e_data_fim_vendas.get().strip()

    L = 32
    header = "=" * L + "\n"
    line = "-" * L + "\n"
    texto = header + "CUMBUCA DELIVERY".center(L) + "\n" + "VENDAS POR ITEM".center(L) + "\n" + header
    texto += f"PERIODO: {data_ini} a {data_fim}\n" + line
    texto += "QTD PRODUTO        VALOR\n" + line

    for iid in linhas:
        prod, qtd, valor = tree_vendas.item(iid)["values"]
        texto += f"{str(qtd)[:3]:>3} {str(prod)[:16].ljust(17)} {str(valor)[:10]:>10}\n"

    texto += line + lbl_total_vendas.cget("text") + "\n"
    texto += "\n" + header + "OBRIGADO E BOAS VENDAS!".center(L) + "\n" + header

    caminho_rel = os.path.join(pasta_real(), "relatorio_vendas.txt")
    with open(caminho_rel, "w", encoding="utf-8") as f:
        f.write(texto)
    os.startfile(caminho_rel)


def gerar_relatorio_caixa_resumo():
    """ Resumo de Caixa. Usa EXCLUSIVAMENTE a tabela `caixa` (dinheiro que
    entrou/saiu de fato) para o saldo — nunca soma pedidos.total nele.
    O Total de Vendas aparece só como referência comercial do período. """
    if _periodo_invalido(e_data_inicio_caixa.get(), e_data_fim_caixa.get(), e_data_inicio_caixa):
        return
    tree_caixa.delete(*tree_caixa.get_children())
    data_ini = e_data_inicio_caixa.get().strip()
    data_fim = e_data_fim_caixa.get().strip()

    if not data_ini or not data_fim:
        messagebox.showwarning("Atenção", "Preencha as datas de Início e Fim.")
        return

    try:
        data_ini_sql = datetime.strptime(data_ini, "%d/%m/%Y").strftime("%Y-%m-%d")
        data_fim_sql = datetime.strptime(data_fim, "%d/%m/%Y").strftime("%Y-%m-%d")
    except ValueError:
        messagebox.showerror("Erro", "Use o formato DD/MM/AAAA nas datas.")
        return

    conn_c = abrir_conexao_curta()
    cur_c = conn_c.cursor()
    try:
        cur_c.execute("""
            SELECT COALESCE(SUM(total), 0) FROM pedidos
            WHERE date(data) BETWEEN ? AND ?
              AND UPPER(pagamento) NOT IN ('DESCARTE', 'CANCELADO')
        """, (data_ini_sql, data_fim_sql))
        total_vendas = cur_c.fetchone()[0] or 0

        cur_c.execute("""
            SELECT COALESCE(SUM(valor), 0) FROM caixa
            WHERE tipo='ENTRADA' AND date(data) BETWEEN ? AND ?
        """, (data_ini_sql, data_fim_sql))
        total_ent = cur_c.fetchone()[0] or 0

        cur_c.execute("""
            SELECT COALESCE(SUM(valor), 0) FROM caixa
            WHERE tipo='SAIDA' AND date(data) BETWEEN ? AND ?
        """, (data_ini_sql, data_fim_sql))
        total_sai = cur_c.fetchone()[0] or 0

        cur_c.execute("""
            SELECT COALESCE(SUM(saldo_inicial),0) + COALESCE(SUM(saldo_inicial_pix),0)
            FROM ciclos_caixa
            WHERE date(abertura) BETWEEN ? AND ?
        """, (data_ini_sql, data_fim_sql))
        row_ab = cur_c.fetchone()
        v_abertura = row_ab[0] if row_ab and row_ab[0] is not None else 0

        saldo = (v_abertura + total_ent) - total_sai

        def fmt(v):
            return f"R$ {v:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

        tree_caixa.insert("", "end", values=("Total de Vendas (data do pedido)", fmt(total_vendas)))
        tree_caixa.insert("", "end", values=("Abertura de Caixa", fmt(v_abertura)))
        tree_caixa.insert("", "end", values=("Entradas no Caixa", fmt(total_ent)))
        tree_caixa.insert("", "end", values=("Saídas do Caixa", f"- {fmt(total_sai)}"))
        tree_caixa.insert("", "end", values=("SALDO DO CAIXA", fmt(saldo)))

    except Exception as e:
        messagebox.showerror("Erro ao gerar resumo de caixa", str(e))
    finally:
        conn_c.close()


def imprimir_relatorio_caixa_resumo():
    """ Gera o .txt (formato térmico 50mm) com o Resumo de Caixa já exibido na tela. """
    linhas = tree_caixa.get_children()
    if not linhas:
        messagebox.showinfo("Aviso", "Gere o resumo de caixa antes de imprimir.")
        return

    data_ini = e_data_inicio_caixa.get().strip()
    data_fim = e_data_fim_caixa.get().strip()

    L = 32
    header = "=" * L + "\n"
    line = "-" * L + "\n"
    texto = header + "CUMBUCA DELIVERY".center(L) + "\n" + "RESUMO DE CAIXA".center(L) + "\n" + header
    texto += f"PERIODO: {data_ini} a {data_fim}\n" + line

    for iid in linhas:
        desc, valor = tree_caixa.item(iid)["values"]
