# =====================================================
# 📈 RESULTADO DO PERÍODO (recebido x gasto)
# Mesma base do Resumo de Caixa: dinheiro que entrou e saiu de fato
# (tabela `caixa`, pela data do lançamento). Só LÊ dados; não altera nada.
# Garantia: Resultado = Entradas − Saídas do Caixa (sem a abertura), então
# Resultado + Abertura = SALDO DO CAIXA do Resumo, sempre.
# =====================================================

# Categorias oferecidas ao lançar uma despesa avulsa (edite a lista à vontade).
# Funcionários, Gás e Estoque (notas) NÃO precisam estar aqui: o sistema já
# os identifica sozinho pelas telas próprias.
CATEGORIAS_DESPESA = [
    "Insumos e alimentos",
    "Carnes e frios",
    "Bebidas",
    "Embalagens",
    "Limpeza e higiene",
    "Manutenção e reparos",
    "Transporte e combustível",
    "Contas fixas (luz, água, aluguel)",
    "Impostos e taxas",
    "Outros",
]

_CAT_FUNCIONARIOS = "Funcionários"
_CAT_GAS = "Gás"
_CAT_ESTOQUE = "Compras de estoque"
_CAT_SEM = "Sem categoria"


def _classificar_lancamento_caixa(tipo, descricao, categoria=None, pedido_id=None):
    """Classifica um lançamento do caixa. Devolve (grupo, rotulo):
    REC_PEDIDO  entrada de venda/ajuste/repasse de pedido
    REC_MANUAL  entrada lançada à mão (receita avulsa, recebimento de conta etc.)
    DEVOLUCAO   saída ligada a pedido (cancelamento, estorno de pedido, ajuste p/ menos)
    GASTO       despesa; rotulo = categoria do gasto
    """
    d = (descricao or "").strip().upper()
    if tipo == "ENTRADA":
        if pedido_id is not None or d.startswith(("PEDIDO #", "AJUSTE", "REPASSE GAR")):
            return "REC_PEDIDO", None
        return "REC_MANUAL", None
    if pedido_id is not None or d.startswith(
            ("CANCELAMENTO PEDIDO", "ESTORNO PEDIDO", "AJUSTE PEDIDO", "AJUSTE FINANCEIRO PEDIDO")):
        return "DEVOLUCAO", None
    if d.startswith(("PAGTO SEMANAL:", "PAGTO SALÁRIO:", "PAGTO SALARIO:", "VALE:")):
        return "GASTO", _CAT_FUNCIONARIOS
    if d.startswith(("COMPRA GÁS (", "COMPRA GAS (")):
        return "GASTO", _CAT_GAS
    if d.startswith(("COMPRA: ", "PAGTO: ", "PAGAMENTO DE CONTA (")):
        return "GASTO", _CAT_ESTOQUE
    cat = (categoria or "").strip()
    return "GASTO", (cat if cat else _CAT_SEM)


def _centavos(v):
    try:
        return int(round(float(v or 0) * 100))
    except Exception:
        return 0


def calcular_resultado_periodo(cur, d_ini, d_fim, agrupar=None, detalhes=True):
    """Calcula o Resultado (recebido − gasto) entre d_ini e d_fim ('YYYY-MM-DD').

    cur     cursor SQLite (somente leitura aqui)
    agrupar None/'auto', 'dia', 'semana' ou 'mes' (como quebrar a série)
    detalhes False -> só totais (usado para o período anterior)
    Todos os valores devolvidos em reais (float, 2 casas).
    """
    from datetime import date as _d, timedelta as _td

    d0 = _d.fromisoformat(d_ini)
    d1 = _d.fromisoformat(d_fim)
    dias = (d1 - d0).days + 1

    tem_cat = any(r[1] == "categoria" for r in cur.execute("PRAGMA table_info(caixa)").fetchall())
    c_cat = "c.categoria" if tem_cat else "NULL"
    o_cat = "o.categoria" if tem_cat else "NULL"
    cur.execute(f"""
        SELECT c.id, c.data, c.tipo, c.descricao, c.valor, c.pagamento, c.pedido_id,
               c.estornado_de, {c_cat},
               o.tipo, o.descricao, o.pedido_id, {o_cat}
        FROM caixa c
        LEFT JOIN caixa o ON o.id = c.estornado_de
        WHERE date(c.data) BETWEEN ? AND ?
        ORDER BY c.data, c.id
    """, (d_ini, d_fim))
    linhas = cur.fetchall()

    # ---- como agrupar a série ----
    modo = (agrupar or "auto").lower()
    if modo not in ("dia", "semana", "mes"):
        modo = "dia" if dias <= 31 else ("semana" if dias <= 140 else "mes")

    def chave_bucket(d):
        if modo == "dia":
            return d
        if modo == "semana":
            return d - _td(days=d.weekday())          # segunda-feira
        return d.replace(day=1)

    buckets = {}
    ordem = []
    if detalhes:
        d = d0
        while d <= d1:
            k = chave_bucket(d)
            if k not in buckets:
                ini_b = max(k, d0)
                if modo == "dia":
                    fim_b = k
                    rot = k.strftime("%d/%m")
                elif modo == "semana":
                    fim_b = min(k + _td(days=6), d1)
                    rot = ini_b.strftime("%d/%m")
                else:
                    nx = (k.replace(day=28) + _td(days=4)).replace(day=1)
                    fim_b = min(nx - _td(days=1), d1)
                    rot = k.strftime("%m/%Y")
                buckets[k] = {"chave": k.isoformat(), "rotulo": rot, "ini": ini_b.isoformat(),
                              "fim": fim_b.isoformat(), "recebido": 0, "gasto": 0}
                ordem.append(k)
            d += _td(days=1)

    tot = {"REC_PEDIDO": 0, "REC_MANUAL": 0, "DEVOLUCAO": 0, "GASTO": 0}
    cats = {}
    formas = {}
    top = []
    soma_ent = soma_sai = 0

    for (cid, data, tipo, desc, valor, pagto, pedido_id, estornado_de, cat,
         o_tipo, o_desc, o_pedido, o_cat_v) in linhas:
        v = _centavos(valor)
        if tipo == "ENTRADA":
            soma_ent += v
        else:
            soma_sai += v

        if estornado_de:
            # Estorno: desfaz o lançamento original, no mesmo grupo dele.
            if o_tipo is not None:
                grupo, rotulo = _classificar_lancamento_caixa(o_tipo, o_desc, o_cat_v, o_pedido)
            elif tipo == "ENTRADA":
                grupo, rotulo = "GASTO", _CAT_SEM
            else:
                grupo, rotulo = "REC_MANUAL", None
            sinal = -1
        else:
            grupo, rotulo = _classificar_lancamento_caixa(tipo, desc, cat, pedido_id)
            sinal = 1
        sv = sinal * v

        tot[grupo] += sv
        if grupo == "GASTO":
            cats[rotulo] = cats.get(rotulo, 0) + sv
            if sinal == 1 and detalhes:
                top.append((desc or "", v, (data or "")[:16], rotulo))
        if grupo in ("REC_PEDIDO", "REC_MANUAL", "DEVOLUCAO"):
            pl = (pagto or "").lower()
            f = ("Pix" if "pix" in pl else "Dinheiro" if "dinheiro" in pl
                 else "Cartão" if "cart" in pl else "Outros")
            formas[f] = formas.get(f, 0) + (sv if grupo != "DEVOLUCAO" else -sv)

        if detalhes:
            try:
                k = chave_bucket(_d.fromisoformat((data or "")[:10]))
                b = buckets.get(k)
            except Exception:
                b = None
            if b is not None:
                if grupo in ("REC_PEDIDO", "REC_MANUAL"):
                    b["recebido"] += sv
                elif grupo == "DEVOLUCAO":
                    b["recebido"] -= sv
                else:
                    b["gasto"] += sv

    rec_bruto = tot["REC_PEDIDO"] + tot["REC_MANUAL"]
    recebido = rec_bruto - tot["DEVOLUCAO"]
    gasto = tot["GASTO"]
    resultado = recebido - gasto

    def r2(c):
        return round(c / 100.0, 2)

    # ---- conferência independente com o Resumo de Caixa (mesmas consultas) ----
    cur.execute("SELECT COALESCE(SUM(valor),0) FROM caixa WHERE tipo='ENTRADA' AND date(data) BETWEEN ? AND ?", (d_ini, d_fim))
    ent_sql = _centavos(cur.fetchone()[0])
    cur.execute("SELECT COALESCE(SUM(valor),0) FROM caixa WHERE tipo='SAIDA' AND date(data) BETWEEN ? AND ?", (d_ini, d_fim))
    sai_sql = _centavos(cur.fetchone()[0])
    cur.execute("""SELECT COALESCE(SUM(saldo_inicial),0) + COALESCE(SUM(saldo_inicial_pix),0)
                   FROM ciclos_caixa WHERE date(abertura) BETWEEN ? AND ?""", (d_ini, d_fim))
    abertura = _centavos(cur.fetchone()[0])
    saldo_caixa = abertura + ent_sql - sai_sql
    dif_conf = (resultado + abertura) - saldo_caixa

    cur.execute("""SELECT COALESCE(SUM(total),0) FROM pedidos
                   WHERE date(data) BETWEEN ? AND ?
                     AND UPPER(pagamento) NOT IN ('DESCARTE','CANCELADO')""", (d_ini, d_fim))
    vendas = _centavos(cur.fetchone()[0])
    cur.execute("""
        SELECT COALESCE(SUM(p.total - COALESCE((SELECT SUM(CASE c.tipo WHEN 'ENTRADA' THEN c.valor ELSE -c.valor END)
                                                FROM caixa c WHERE c.pedido_id = p.id), 0)), 0)
        FROM pedidos p
        WHERE date(p.data) BETWEEN ? AND ? AND UPPER(p.pagamento) = 'PENDENTE'
    """, (d_ini, d_fim))
    fiado = _centavos(cur.fetchone()[0])

    # Pedidos CANCELADOS que mexeram no caixa neste periodo mas nao zeraram
    # (entrou != saiu): distorcem Recebido/Devolucoes. O "Conferido" acima nao
    # pega isso, pois compara o relatorio com o proprio caixa.
    cur.execute("""
        SELECT p.id, SUM(CASE c.tipo WHEN 'ENTRADA' THEN c.valor ELSE -c.valor END)
        FROM pedidos p JOIN caixa c ON c.pedido_id = p.id
        WHERE UPPER(p.pagamento) = 'CANCELADO'
          AND p.id IN (SELECT pedido_id FROM caixa
                       WHERE pedido_id IS NOT NULL AND date(data) BETWEEN ? AND ?)
        GROUP BY p.id
        HAVING ABS(SUM(CASE c.tipo WHEN 'ENTRADA' THEN c.valor ELSE -c.valor END)) > 0.004
        ORDER BY p.id
    """, (d_ini, d_fim))
    alertas_cancelados = [(int(r[0]), round(float(r[1] or 0), 2)) for r in cur.fetchall()]

    res = {
        "ini": d_ini, "fim": d_fim, "dias": dias, "modo": modo,
        "recebido": r2(recebido), "recebido_pedidos": r2(tot["REC_PEDIDO"]),
        "recebido_manual": r2(tot["REC_MANUAL"]), "devolucoes": r2(tot["DEVOLUCAO"]),
        "gasto": r2(gasto), "resultado": r2(resultado),
        "margem": (round(resultado * 100.0 / recebido, 1) if recebido > 0 else None),
        "abertura": r2(abertura), "saldo_caixa": r2(saldo_caixa),
        "conferencia_dif": r2(dif_conf), "conferencia_ok": dif_conf == 0,
        "vendas": r2(vendas), "fiado": r2(fiado),
        "alertas_cancelados": alertas_cancelados,
    }
    if detalhes:
        res["categorias"] = sorted(((k, r2(v)) for k, v in cats.items() if v != 0), key=lambda x: -x[1])
        res["formas"] = sorted(((k, r2(v)) for k, v in formas.items() if v != 0), key=lambda x: -x[1])
        res["serie"] = [{"chave": b["chave"], "rotulo": b["rotulo"], "ini": b["ini"], "fim": b["fim"],
                         "recebido": r2(b["recebido"]), "gasto": r2(b["gasto"]),
                         "resultado": r2(b["recebido"] - b["gasto"])} for b in (buckets[k] for k in ordem)]
        top.sort(key=lambda x: -x[1])
        res["maiores"] = [(d_, r2(v_), dt_, c_) for d_, v_, dt_, c_ in top[:5]]
        ant_fim = d0 - _td(days=1)
        ant_ini = ant_fim - _td(days=dias - 1)
        a = calcular_resultado_periodo(cur, ant_ini.isoformat(), ant_fim.isoformat(), detalhes=False)
        res["anterior"] = {k: a[k] for k in ("ini", "fim", "recebido", "gasto", "resultado")}
    return res


# ---------- utilidades de formatação / desenho (Canvas nativo, sem biblioteca nova) ----------
def _res_brl(v):
    s = f"{abs(v):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return ("-" if v < -0.004 else "") + "R$ " + s


def _res_compacto(v):
    a = abs(v)
    if a >= 1000:
        t = f"{a / 1000:.1f}".replace(".", ",")
        if t.endswith(",0"):
            t = t[:-2]
        return t + "k"
    return f"{a:.0f}"


def _res_nice_max(v):
    import math
    if v <= 0:
        return 1.0
    exp = 10 ** math.floor(math.log10(v))
    f = v / exp
    for m in (1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10):
        if f <= m + 1e-9:
            return m * exp
    return 10 * exp


_RES_PALETA = ["#2E86C1", "#E67E22", "#8E44AD", "#16A085", "#C0392B", "#F1C40F", "#7F8C8D"]
_res_estado = {"dados": None}


def _res_texto_vazio(cv, msg):
    cv.delete("all")
    cv.create_text(max(cv.winfo_width(), 200) / 2, max(cv.winfo_height(), 100) / 2,
                   text=msg, fill="#7F8C8D", font=("Segoe UI", 10))


def _res_desenhar_barras(cv, serie):
    """Barras agrupadas Recebido x Gasto; fundo vermelho claro nos períodos em que
    se gastou mais do que se recebeu. Passe o mouse para ver os valores."""
    cv.delete("all")
    if not serie or all(b["recebido"] == 0 and b["gasto"] == 0 for b in serie):
        _res_texto_vazio(cv, "Sem movimento no período")
        return
    w = max(cv.winfo_width(), 320)
    h = max(cv.winfo_height(), 200)
    ml, mr, mt, mb = 52, 12, 30, 30
    pw, ph = w - ml - mr, h - mt - mb
    vmax = _res_nice_max(max(max(b["recebido"], b["gasto"]) for b in serie))
    for i in range(5):
        y = mt + ph - ph * i / 4
        cv.create_line(ml, y, ml + pw, y, fill="#E3E8EE")
        cv.create_text(ml - 6, y, text=_res_compacto(vmax * i / 4), anchor="e",
                       fill="#5D6D7E", font=("Segoe UI", 8))
    n = len(serie)
    slot = pw / n
    bw = max(2, min(slot * 0.38, 26))
    passo = max(1, int(-(-n // max(1, int(pw / 46)))))
    for idx, b in enumerate(serie):
        x0 = ml + slot * idx
        cx = x0 + slot / 2
        if b["resultado"] < -0.004:
            cv.create_rectangle(x0 + 1, mt, x0 + slot - 1, mt + ph, fill="#FDEDEC", outline="")
        hr = ph * b["recebido"] / vmax
        hg = ph * b["gasto"] / vmax
        if b["recebido"] > 0:
            cv.create_rectangle(cx - bw - 1, mt + ph - hr, cx - 1, mt + ph, fill=COR_RECEITA, outline="")
        if b["gasto"] > 0:
            cv.create_rectangle(cx + 1, mt + ph - hg, cx + bw + 1, mt + ph, fill=COR_DESPESA, outline="")
        if idx % passo == 0:
            cv.create_text(cx, mt + ph + 12, text=b["rotulo"], fill="#5D6D7E", font=("Segoe UI", 8))
    cv.create_line(ml, mt + ph, ml + pw, mt + ph, fill="#95A5A6")
    # legenda
    lx = ml
    for cor, txt in ((COR_RECEITA, "Recebido"), (COR_DESPESA, "Gasto"), ("#FDEDEC", "Período no vermelho")):
        cv.create_rectangle(lx, 9, lx + 11, 20, fill=cor, outline="#D5D8DC")
        t = cv.create_text(lx + 16, 14, text=txt, anchor="w", fill="#2C3E50", font=("Segoe UI", 8))
        lx = cv.bbox(t)[2] + 14

    def mover(ev):
        cv.delete("tip")
        if ev.x < ml or ev.x > ml + pw:
            return
        i = int((ev.x - ml) / slot)
        if 0 <= i < n:
            b = serie[i]
            txt = (f"{b['rotulo']}  Recebido {_res_brl(b['recebido'])}  "
                   f"Gasto {_res_brl(b['gasto'])}  Resultado {_res_brl(b['resultado'])}")
            t = cv.create_text(w - 8, 14, text=txt, anchor="e", fill="#1B2631",
                               font=("Segoe UI", 8, "bold"), tags="tip")
            bb = cv.bbox(t)
            r = cv.create_rectangle(bb[0] - 4, bb[1] - 2, bb[2] + 4, bb[3] + 2,
                                    fill="#FFFFFF", outline="#AEB6BF", tags="tip")
            cv.tag_lower(r, t)

    cv.bind("<Motion>", mover)
    cv.bind("<Leave>", lambda e: cv.delete("tip"))


def _res_desenhar_pizza(cv, categorias):
    """Rosca de gastos por categoria (até 6 fatias + 'Outras') com legenda e %."""
    cv.delete("all")
    itens = [(n, v) for n, v in categorias if v > 0]
    total = sum(v for _, v in itens)
    if total <= 0:
        _res_texto_vazio(cv, "Sem despesas no período")
        return
    if len(itens) > 7:
        itens = itens[:6] + [("Outras", sum(v for _, v in itens[6:]))]
    w = max(cv.winfo_width(), 380)
    h = max(cv.winfo_height(), 200)
    r = max(40, min(92, h / 2 - 16))
    cx, cy = r + 14, h / 2
    ang = 90.0
    for i, (nome, v) in enumerate(itens):
        cor = _RES_PALETA[i % len(_RES_PALETA)]
        ext = -360.0 * v / total
        if len(itens) == 1:
            cv.create_oval(cx - r, cy - r, cx + r, cy + r, fill=cor, outline="white", width=2)
        else:
            cv.create_arc(cx - r, cy - r, cx + r, cy + r, start=ang, extent=ext,
                          fill=cor, outline="white", width=2, style="pieslice")
        ang += ext
    rh = r * 0.55
    cv.create_oval(cx - rh, cy - rh, cx + rh, cy + rh, fill="#FFFFFF", outline="white")
    cv.create_text(cx, cy - 8, text="Gasto", fill="#7F8C8D", font=("Segoe UI", 8))
    cv.create_text(cx, cy + 8, text=_res_brl(total), fill="#1B2631", font=("Segoe UI", 9, "bold"))
    lx = cx + r + 22
    ly = max(14, cy - len(itens) * 10)
    for i, (nome, v) in enumerate(itens):
        cor = _RES_PALETA[i % len(_RES_PALETA)]
        cv.create_rectangle(lx, ly + 3, lx + 11, ly + 14, fill=cor, outline="")
        nm = nome if len(nome) <= 24 else nome[:23] + "…"
        cv.create_text(lx + 17, ly + 9, text=f"{nm}", anchor="w", fill="#2C3E50", font=("Segoe UI", 8))
        cv.create_text(w - 8, ly + 9, text=f"{_res_brl(v)}  ({v * 100.0 / total:.0f}%)", anchor="e",
                       fill="#2C3E50", font=("Segoe UI", 8, "bold"))
        ly += 21


def _res_desenhar_formas(cv, formas):
    """Barra única empilhada: recebido por forma de pagamento."""
    cv.delete("all")
    itens = [(n, v) for n, v in formas if v > 0]
    total = sum(v for _, v in itens)
    w = max(cv.winfo_width(), 300)
    if total <= 0:
        return
    cores = {"Pix": "#2E86C1", "Dinheiro": "#27AE60", "Cartão": "#E67E22"}
    x = 0.0
    for i, (nome, v) in enumerate(itens):
        seg = (w - 2) * v / total
        cor = cores.get(nome, _RES_PALETA[(i + 3) % len(_RES_PALETA)])
        cv.create_rectangle(x, 2, x + seg, 24, fill=cor, outline="white")
        if seg > 90:
            cv.create_text(x + seg / 2, 13, text=f"{nome} {v * 100.0 / total:.0f}%", fill="white",
                           font=("Segoe UI", 8, "bold"))
        x += seg


