def _res_agendar_redesenho(ev=None):
    try:
        if _res_job["id"]:
            cv_res_barras.after_cancel(_res_job["id"])
    except Exception:
        pass
    _res_job["id"] = cv_res_barras.after(120, _res_redesenhar)


