def _res_preencher(d):
    _res_estado["dados"] = d
    cor_res = COR_RECEITA if d["resultado"] >= 0 else COR_DESPESA

    v, s = _res_lbl["rec"]
    v.config(text=_res_brl(d["recebido"]), fg=COR_RECEITA)
    s.config(text=f"vendas {_res_brl(d['recebido_pedidos'])}"
                  + (f" · outras {_res_brl(d['recebido_manual'])}" if abs(d["recebido_manual"]) > 0.004 else "")
                  + (f" · devoluções {_res_brl(d['devolucoes'])}" if abs(d["devolucoes"]) > 0.004 else ""))
    v, s = _res_lbl["gas"]
    v.config(text=_res_brl(d["gasto"]), fg=COR_DESPESA)
    s.config(text=(f"maior: {d['categorias'][0][0]}" if d["categorias"] else "sem despesas"))
    v, s = _res_lbl["res"]
    v.config(text=_res_brl(d["resultado"]), fg=cor_res)
    if abs(d["recebido"]) < 0.005 and abs(d["gasto"]) < 0.005:
        s.config(text="sem movimento no período")
    elif d["resultado"] > 0.004:
        s.config(text=("sobrou" + (f" · margem {d['margem']:.1f}%".replace(".", ",") if d["margem"] is not None else "")))
    elif d["resultado"] < -0.004:
        s.config(text="gastou mais do que recebeu")
    else:
        s.config(text="recebeu e gastou o mesmo valor")
    v, s = _res_lbl["fia"]
    v.config(text=_res_brl(d["fiado"]), fg="#7D6608")
    s.config(text="pedidos do período ainda não pagos")

    a = d["anterior"]

    def var(atual, ant):
        if abs(ant) < 0.005:
            return "—"
        p = (atual - ant) * 100.0 / abs(ant)
        return f"{'▲' if p >= 0 else '▼'} {abs(p):.1f}%".replace(".", ",")

    def br(iso):
        return f"{iso[8:10]}/{iso[5:7]}/{iso[2:4]}"
    lbl_res_comp.config(
        text=(f"Comparado ao período anterior ({br(a['ini'])} a {br(a['fim'])}):  "
              f"Recebido {var(d['recebido'], a['recebido'])}   ·   Gasto {var(d['gasto'], a['gasto'])}   ·   "
              f"Resultado {_res_brl(d['resultado'] - a['resultado'])} de diferença"))
    if d["conferencia_ok"]:
        lbl_res_conf.config(
            text=(f"✔ Conferido: Resultado {_res_brl(d['resultado'])} + Abertura {_res_brl(d['abertura'])} "
                  f"= Saldo do Caixa {_res_brl(d['saldo_caixa'])}"), foreground="#1E8449")
    else:
        lbl_res_conf.config(
            text=(f"⚠ ATENÇÃO: não fecha com o Saldo do Caixa (diferença de {_res_brl(d['conferencia_dif'])}). "
                  f"Não use estes números até conferir."), foreground="#C0392B")
    _alertas_canc = d.get("alertas_cancelados") or []
    if _alertas_canc:
        _ids = ", ".join(f"#{i} ({_res_brl(s)})" for i, s in _alertas_canc[:4])
        _mais = f" e mais {len(_alertas_canc) - 4}" if len(_alertas_canc) > 4 else ""
        lbl_res_conf.config(
            text=(lbl_res_conf.cget("text") + f"\n⚠ {len(_alertas_canc)} pedido(s) cancelado(s) com saldo no caixa: "
                  f"{_ids}{_mais}. Isso distorce Recebido/Devoluções — confira estes pedidos."),
            foreground="#C0392B")

    lbl_res_formas.config(text="   ·   ".join(f"{n}: {_res_brl(v_)}" for n, v_ in d["formas"]) or "sem recebimentos")

    tree_res_serie.delete(*tree_res_serie.get_children())
    for b in d["serie"]:
        if abs(b["recebido"]) < 0.005 and abs(b["gasto"]) < 0.005:
            continue
        tree_res_serie.insert("", "end", values=(b["rotulo"], _res_brl(b["recebido"]), _res_brl(b["gasto"]),
                                                 _res_brl(b["resultado"])),
                              tags=("neg",) if b["resultado"] < -0.004 else ())
    tree_res_serie.insert("", "end", values=("TOTAL", _res_brl(d["recebido"]), _res_brl(d["gasto"]),
                                             _res_brl(d["resultado"])),
                          tags=("tot", "neg") if d["resultado"] < -0.004 else ("tot",))

    tree_res_maiores.delete(*tree_res_maiores.get_children())
    for desc, val, dt, cat in d["maiores"]:
        dh = f"{dt[8:10]}/{dt[5:7]} {dt[11:16]}" if len(dt) >= 16 else dt
        tree_res_maiores.insert("", "end", values=(dh, desc[:40], cat, _res_brl(val)))

    _res_redesenhar()


def gerar_relatorio_resultado():
    if _periodo_invalido(e_data_inicio_resultado.get(), e_data_fim_resultado.get(), e_data_inicio_resultado):
        return
    try:
        ini = datetime.strptime(e_data_inicio_resultado.get().strip(), "%d/%m/%Y").strftime("%Y-%m-%d")
        fim = datetime.strptime(e_data_fim_resultado.get().strip(), "%d/%m/%Y").strftime("%Y-%m-%d")
    except ValueError:
        messagebox.showerror("Erro", "Use o formato DD/MM/AAAA nas datas.")
        return
    modo = {"Automático": None, "Dia": "dia", "Semana": "semana", "Mês": "mes"}.get(cb_res_agrupar.get())
    conn_r = abrir_conexao_curta()
    try:
        dados = calcular_resultado_periodo(conn_r.cursor(), ini, fim, agrupar=modo)
    except Exception as e:
        messagebox.showerror("Erro ao gerar o resultado", str(e))
        return
    finally:
        conn_r.close()
    _res_preencher(dados)


def imprimir_relatorio_resultado():
    """Gera o .txt térmico (50mm) do Resultado exibido na tela (sem gráficos)."""
    d = _res_estado.get("dados")
    if not d:
        messagebox.showinfo("Aviso", "Gere o resultado antes de imprimir.")
        return

    def fm(v):
        return _res_brl(v)

    def br(iso):
        return f"{iso[8:10]}/{iso[5:7]}/{iso[0:4]}"
    L = 32
    header = "=" * L + "\n"
    line = "-" * L + "\n"

    def par(rot, val):
        return f"{rot[:19].ljust(19)} {val:>12}\n"
    t = header + "CUMBUCA DELIVERY".center(L) + "\n" + "RESULTADO DO PERIODO".center(L) + "\n" + header
    t += f"PERIODO: {br(d['ini'])} a {br(d['fim'])}\n" + line
    t += par("Recebido", fm(d["recebido"]))
    t += par("Gasto", "-" + fm(d["gasto"]).lstrip("-"))
    t += line + par("RESULTADO", fm(d["resultado"]))
    if d["margem"] is not None:
        t += par("Margem", f"{d['margem']:.1f}%".replace(".", ","))
    t += par("Fiado a receber", fm(d["fiado"]))
    if d.get("alertas_cancelados"):
        t += par("ATENCAO canc.c/saldo", str(len(d["alertas_cancelados"])))
    t += line + "GASTOS POR CATEGORIA\n"
    tot = sum(v for _, v in d["categorias"] if v > 0) or 1
    for n, v in d["categorias"]:
        t += par(f"{n}", fm(v))
        t += f"{'':19} {v * 100.0 / tot:>11.0f}%\n"
    t += line + "RECEBIDO POR FORMA\n"
    for n, v in d["formas"]:
        t += par(n, fm(v))
    t += line + "POR PERIODO\n"
    for b in d["serie"]:
        if abs(b["recebido"]) < 0.005 and abs(b["gasto"]) < 0.005:
            continue
        t += f"{b['rotulo'][:7]:<7}{fm(b['recebido']):>12}{fm(b['gasto']):>13}\n"
        t += f"{'':7}{'result.':>12}{fm(b['resultado']):>13}\n"
    t += line + ("Conferido com o Saldo do Caixa\n" if d["conferencia_ok"] else "ATENCAO: nao fecha c/ o Caixa!\n")
    t += header + "OBRIGADO E BOAS VENDAS!".center(L) + "\n" + header
    caminho = os.path.join(pasta_real(), "relatorio_resultado.txt")
    with open(caminho, "w", encoding="utf-8") as f:
        f.write(t)
    os.startfile(caminho)


