def listar_estoque():
    # Limpa as duas tabelas novas
    tabela_insumos.delete(*tabela_insumos.get_children())
    tabela_produtos.delete(*tabela_produtos.get_children())
    
    # Busca e distribui Insumos
    cursor.execute("SELECT codigo, produto, custo, quantidade FROM estoque WHERE categoria = 'INSUMO'")
    for r in cursor.fetchall():
        tabela_insumos.insert("", "end", values=r)
        
    # Busca e distribui Produtos
    cursor.execute("SELECT codigo, produto, venda, quantidade FROM estoque WHERE categoria = 'PRODUTO'")
    for r in cursor.fetchall():
        tabela_produtos.insert("", "end", values=r)

    # NOVO: Atualiza os menus de seleção da Ficha Técnica e Produção
    if 'atualizar_menus_producao' in globals():
        atualizar_menus_producao()

    if 'carregar_itens_estoque' in globals():
        carregar_itens_estoque()


def cadastrar_produto():
    if not e_prod.get() or not e_qtd.get():
        messagebox.showerror("Erro","Preencha Nome e Quantidade")
        return
    codigo = f"P{int(datetime.now().timestamp())}"
    cursor.execute("""
        INSERT INTO estoque (codigo, produto, custo, venda, quantidade, categoria) 
        VALUES (?,?,?,?,?,?)
    """, (codigo, e_prod.get(), float(e_custo.get() or 0), 
          float(e_venda.get() or 0), int(e_qtd.get()), cb_categoria.get()))
    conn.commit()
    registrar_log("ESTOQUE_ENTRADA", "ESTOQUE", codigo, {"produto": e_prod.get(), "quantidade": e_qtd.get(), "categoria": cb_categoria.get(), "origem": "cadastro"})
    listar_estoque()
    carregar_produtos_add()
    for e in [e_prod, e_custo, e_venda, e_qtd]: e.delete(0, "end")

def carregar_dados_para_editar(event):
    # Detecta qual tabela foi clicada
    tabela = event.widget
    item_selecionado = tabela.selection()
    if not item_selecionado: return
    valores = tabela.item(item_selecionado, "values")
    
    global id_item_editando
    id_item_editando = valores[0] # Código
    
    e_prod.delete(0, "end"); e_prod.insert(0, valores[1])
    # Se for Insumo, valores[2] é custo. Se for Produto, valores[2] é venda. 
    # Para simplificar na edição, buscamos o registro completo:
    cursor.execute("SELECT categoria, custo, venda, quantidade FROM estoque WHERE codigo=?", (id_item_editando,))
    detalhes = cursor.fetchone()
    cb_categoria.set(detalhes[0])
    e_custo.delete(0, "end"); e_custo.insert(0, detalhes[1])
    e_venda.delete(0, "end"); e_venda.insert(0, detalhes[2])
    e_qtd.delete(0, "end"); e_qtd.insert(0, detalhes[3])

def atualizar_produto_total():
    if not id_item_editando: 
        messagebox.showwarning("Aviso", "Selecione um item com duplo clique primeiro!")
        return
    cursor.execute("""
        UPDATE estoque SET produto=?, categoria=?, custo=?, venda=?, quantidade=? WHERE codigo=?
    """, (e_prod.get(), cb_categoria.get(), float(e_custo.get()), 
          float(e_venda.get()), int(e_qtd.get()), id_item_editando))
    conn.commit()
    registrar_log("ESTOQUE_EDITADO", "ESTOQUE", id_item_editando, {"produto": e_prod.get(), "categoria": cb_categoria.get(), "custo": e_custo.get(), "venda": e_venda.get(), "quantidade": e_qtd.get()})
    listar_estoque()
    messagebox.showinfo("Sucesso", "Item atualizado!")

