def carregar_historico_gas():

    tree_g.delete(*tree_g.get_children())

    cursor.execute("""
    SELECT data_compra, fornecedor, preco, status, data_troca
    FROM gas
    ORDER BY datetime(data_compra) DESC
    """)

    for linha in cursor.fetchall():

        data_db, forn, preco, status, troca = linha

        data_tela = datetime.strptime(
            data_db, "%Y-%m-%d %H:%M:%S"
        ).strftime("%d/%m/%Y %H:%M")

        preco_txt = f"R$ {preco:.2f}"

        if troca:
            troca_txt = datetime.strptime(
                troca, "%Y-%m-%d %H:%M:%S"
            ).strftime("%d/%m/%Y %H:%M")
        else:
            troca_txt = "-"

        tree_g.insert(
            "",
            "end",
            values=(data_tela, forn, preco_txt, status, troca_txt)
        )



def registrar_compra_gas(forma_pagamento):

    janela_compra = tk.Toplevel(root)
    janela_compra.title(f"Comprar Gás - {forma_pagamento}")
    janela_compra.geometry("300x250")
    
    janela_compra.transient(root)
    janela_compra.grab_set()

    ttk.Label(janela_compra, text="Fornecedor:", font=("Arial", 10, "bold")).pack(pady=5)

    ent_fornecedor = ttk.Entry(janela_compra, width=30)
    ent_fornecedor.pack()

    ttk.Label(janela_compra, text="Preço Pago (R$):", font=("Arial", 10, "bold")).pack(pady=5)

    ent_preco = ttk.Entry(janela_compra, width=30)
    ent_preco.pack()

    def salvar_compra():

        forn = ent_fornecedor.get().strip()
        preco_raw = ent_preco.get().strip()

        if not forn or not preco_raw:
            messagebox.showwarning("Aviso", "Preencha todos os campos.")
            return

        try:
            valor = float(preco_raw.replace(",", "."))
        except:
            messagebox.showerror("Erro", "Valor inválido.")
            return

        if not ciclo_caixa_aberto.get("id"):
            messagebox.showwarning("Aviso", "Abra o caixa antes de comprar!")
            return

        data_agora = datetime.now()
        data_db = data_agora.strftime("%Y-%m-%d %H:%M:%S")
        data_tela = data_agora.strftime("%d/%m/%Y %H:%M")

        descricao = f"COMPRA GÁS ({forn})"

        try:

            # DESPESA NO RELATÓRIO (sem commit; o commit do caixa grava os dois juntos)
            registrar_despesa_relatorio(forn, "GÁS", valor, "COMPRA GÁS", "GÁS", data_db)

            # REGISTRA NO CAIXA
            registrar_lancamento_caixa("SAIDA", descricao, valor, forma_pagamento)

            cursor.execute("""
            INSERT INTO gas (data_compra, fornecedor, preco, pagamento, status, data_troca)
            VALUES (?, ?, ?, ?, ?, ?)
            """, (data_db, forn, valor, forma_pagamento, "📦 ESTOQUE", None))
    
            conn.commit()

            # REGISTRA NA TABELA DA ABA GÁS
            tree_g.insert("", "end",
                values=(data_tela, forn, f"R$ {valor:.2f}", "📦 ESTOQUE", "-")
            )

            # ATUALIZA LISTA DE DESPESAS
            if 'lista_despesas' in globals():
                lista_despesas.insert("", 0,
                    values=("COMPRA GÁS", forn, f"R$ {valor:.2f}", data_tela)
                )

            atualizar_saldo()

            messagebox.showinfo("Sucesso", "Compra de gás registrada!")

            janela_compra.destroy()

        except Exception as e:
            try:
                conn.rollback()
            except Exception:
                pass
            messagebox.showerror("Erro", f"Erro ao registrar no caixa\n{e}")

    carregar_historico_gas()

    ttk.Button(
        janela_compra,
        text="✅ CONFIRMAR COMPRA",
        command=salvar_compra
    ).pack(pady=20)

