# -----------------------------------------------------
# CALCULAR DIAS ENTRE DATAS
# -----------------------------------------------------
def calcular_dias(data_inicio):

    if not data_inicio:
        return "-"

    try:
        d1 = datetime.strptime(data_inicio, "%Y-%m-%d %H:%M:%S")
        d2 = datetime.now()

        dias = (d2 - d1).days

        return f"{dias} dias"

    except:
        return "-"


# -----------------------------------------------------
# BUSCAR STATUS DO FOGÃO
# -----------------------------------------------------

def obter_status_fogao(nome):
    # O ERRO ESTAVA AQUI: Para o card, precisamos do botijão que está '🔥 EM USO'
    # E precisamos selecionar as colunas corretas para bater com o desempacotamento abaixo
    cursor.execute("""
        SELECT data_instalacao, duracao_dias
        FROM gas 
        WHERE status = '🔥 EM USO' AND fogao = ?
        ORDER BY id DESC LIMIT 1
    """, (nome,))

    dado = cursor.fetchone()
    
    if dado:
        # Agora o desempacotamento funciona (2 colunas no SELECT, 2 variáveis aqui)
        data_instalacao, duracao = dado
        dias_uso = calcular_dias(data_instalacao)
        
        try:
            data_formatada = datetime.strptime(data_instalacao, "%Y-%m-%d %H:%M:%S").strftime("%d/%m/%Y")
        except:
            data_formatada = "-"
            
        # Retorna a data para o card, os dias que está lá, e a duração do ANTERIOR (se houver)
        return data_formatada, dias_uso, (duracao if duracao else "-")
    
    return "-", "-", "-"

# -----------------------------------------------------
# TROCAR BOTIJÃO
# -----------------------------------------------------
def trocar_gas_fogao(nome):

    confirmar = messagebox.askyesno(
        "Confirmar troca",
        f"Confirmar troca de botijão do {nome}?"
    )

    if not confirmar:
        return

    data_agora = datetime.now()
    data_db = data_agora.strftime("%Y-%m-%d %H:%M:%S")

    # ------------------------------------------------
    # 1️⃣ VERIFICAR SE O FOGÃO JÁ TEM BOTIJÃO INSTALADO
    # ------------------------------------------------
    cursor.execute("""
    SELECT id, data_instalacao, preco
    FROM gas
    WHERE status='🔥 EM USO'
    AND fogao=?
    ORDER BY id DESC
    LIMIT 1
    """, (nome,))

    antigo = cursor.fetchone()

    if antigo:

        id_antigo, data_inst, preco = antigo

        try:

            d1 = datetime.strptime(data_inst, "%Y-%m-%d %H:%M:%S")
            d2 = datetime.now()

            duracao = (d2 - d1).days

            if duracao <= 0:
                duracao = 1

        except:
            duracao = None

        cursor.execute("""
        UPDATE gas
        SET status='VAZIO',
            data_troca=?,
            duracao_dias=?
        WHERE id=?
        """, (data_db, duracao, id_antigo))


    # ------------------------------------------------
    # 2️⃣ BUSCAR NOVO BOTIJÃO NO ESTOQUE
    # ------------------------------------------------
    cursor.execute("""
    SELECT id
    FROM gas
    WHERE status='📦 ESTOQUE'
    ORDER BY data_compra ASC
    LIMIT 1
    """)

    estoque = cursor.fetchone()

    if not estoque:

        messagebox.showerror(
            "Sem estoque",
            "Não há botijão disponível no estoque."
        )

        return

    id_estoque = estoque[0]


    # ------------------------------------------------
    # 3️⃣ INSTALAR BOTIJÃO NO FOGÃO
    # ------------------------------------------------
    cursor.execute("""
    UPDATE gas
    SET status='🔥 EM USO',
        fogao=?,
        data_instalacao=?
    WHERE id=?
    """, (nome, data_db, id_estoque))


    conn.commit()


    # ------------------------------------------------
    # 4️⃣ ATUALIZAR INTERFACE
    # ------------------------------------------------
    carregar_historico_gas()

    try:
        carregar_metricas_gas()
    except:
        pass

    atualizar_cards_fogao()


    # ------------------------------------------------
    # 5️⃣ MENSAGEM
    # ------------------------------------------------
    messagebox.showinfo(
        "Troca realizada",
        f"Novo botijão instalado no {nome}."
    )

# -----------------------------------------------------
# ATUALIZAR CARDS
# -----------------------------------------------------
def atualizar_cards_fogao():

    for nome in ["FOGÃO A", "FOGÃO B", "FOGÃO C"]:

        data_inst, dias_uso, duracao = obter_status_fogao(nome)

        labels_fogao[nome]["instalado"].config(
            text=f"Instalado em: {data_inst}"
        )

        labels_fogao[nome]["dias"].config(
            text=f"Dias em uso: {dias_uso}"
        )

        labels_fogao[nome]["duracao"].config(
            text=f"Última duração: {duracao if duracao else '-'} dias"
        )


