# --- FUNÇÕES DE APOIO ---

def listar_ingredientes_da_marmita(event=None):
    if not cb_pai_rec.get(): return
    cod_pai = cb_pai_rec.get().split(" - ")[0]
    tabela_ficha.delete(*tabela_ficha.get_children())
    query = """
        SELECT f.id, e.produto, f.quantidade_necessaria, (f.quantidade_necessaria * e.custo) 
        FROM fichas_tecnicas f JOIN estoque e ON f.insumo_codigo = e.codigo WHERE f.produto_pai_codigo = ?
    """
    cursor.execute(query, (cod_pai,))
    for r in cursor.fetchall():
        tabela_ficha.insert("", "end", values=(r[0], r[1], f"{r[2]:.3f}", f"R$ {r[3]:.2f}"))

def remover_ingrediente_ficha():
    item_sel = tabela_ficha.selection()
    if not item_sel:
        messagebox.showwarning("Aviso", "Selecione um ingrediente na tabela para remover!")
        return
    valores = tabela_ficha.item(item_sel, "values")
    if messagebox.askyesno("Confirmar", f"Remover este ingrediente da receita?"):
        cursor.execute("DELETE FROM fichas_tecnicas WHERE id = ?", (valores[0],))
        conn.commit()
        listar_ingredientes_da_marmita()
        calcular_financeiro_marmita()

def calcular_financeiro_marmita(event=None):
    if not cb_pai_rec.get(): return
    cod_pai = cb_pai_rec.get().split(" - ")[0]
    cursor.execute("""
        SELECT f.quantidade_necessaria, e.custo 
        FROM fichas_tecnicas f JOIN estoque e ON f.insumo_codigo = e.codigo WHERE f.produto_pai_codigo = ?
    """, (cod_pai,))
    itens = cursor.fetchall()
    custo_producao = sum(float(qtd) * float(c_un) for qtd, c_un in itens)
    lbl_custo_total.config(text=f"Custo: R$ {custo_producao:.2f}")
    try:
        sugestao = custo_producao * (1 + (float(e_margem.get() or 0) / 100))
        lbl_preco_sugerido.config(text=f"Sugestão: R$ {sugestao:.2f}")
    except: pass

def salvar_ingrediente():
    if not cb_pai_rec.get() or not cb_insumo_rec.get(): return
    cod_pai = cb_pai_rec.get().split(" - ")[0]
    cod_ins = cb_insumo_rec.get().split(" - ")[0]
    try:
        qtd = float(e_qtd_necessaria.get().replace(",", "."))
        cursor.execute("INSERT INTO fichas_tecnicas (produto_pai_codigo, insumo_codigo, quantidade_necessaria) VALUES (?,?,?)", (cod_pai, cod_ins, qtd))
        conn.commit()
        calcular_financeiro_marmita()
        listar_ingredientes_da_marmita() # Atualiza a lista na hora
        messagebox.showinfo("Sucesso", "Ingrediente vinculado!")
    except: messagebox.showerror("Erro", "Verifique a quantidade")

def aplicar_preco_sugerido():
    if not cb_pai_rec.get(): return
    cod_pai = cb_pai_rec.get().split(" - ")[0]
    preco_texto = lbl_preco_sugerido.cget("text").replace("Sugestão: R$ ", "")
    custo_texto = lbl_custo_total.cget("text").replace("Custo: R$ ", "")
    if messagebox.askyesno("Confirmar", f"Aplicar R$ {preco_texto} como preço de venda?"):
        cursor.execute("UPDATE estoque SET venda = ?, custo = ? WHERE codigo = ?", (float(preco_texto), float(custo_texto), cod_pai))
        conn.commit()
        listar_estoque()
        messagebox.showinfo("Sucesso", "Preço atualizado!")

def finalizar_producao_dia():
    if not cb_produzir_marmita.get() or not e_qtd_lote.get(): return
    cod_pai = cb_produzir_marmita.get().split(" - ")[0]
    try:
        qtd_feita = int(e_qtd_lote.get())
        cursor.execute("SELECT insumo_codigo, quantidade_necessaria FROM fichas_tecnicas WHERE produto_pai_codigo=?", (cod_pai,))
        receita = cursor.fetchall()
        if not receita: return
        for ins, qtd_unit in receita:
            cursor.execute("UPDATE estoque SET quantidade = quantidade - ? WHERE codigo = ?", (qtd_unit * qtd_feita, ins))
        cursor.execute("UPDATE estoque SET quantidade = quantidade + ? WHERE codigo = ?", (qtd_feita, cod_pai))
        conn.commit()
        listar_estoque()
        e_qtd_lote.delete(0, "end")
        messagebox.showinfo("Sucesso", "Estoque atualizado!")
    except: pass

# =====================================================
# 🧾 FUNÇÃO: LANÇAR NOTA DE COMPRA (ESTOQUE + CAIXA)
# =====================================================

def validar_data_br(data_str):
    """Valida uma data no formato brasileiro (dd/mm/aaaa), inclusive dias
    inexistentes para o mês/ano informado (ex.: 31/02/2026, 29/02/2027).
    Retorna a data normalizada (com zeros à esquerda) em dd/mm/aaaa, ou
    None se a data for inválida/mal formatada."""
    if not data_str:
        return None
    try:
        d = datetime.strptime(data_str.strip(), "%d/%m/%Y")
        return d.strftime("%d/%m/%Y")
    except (ValueError, AttributeError):
        return None


