_NOTA_TIPOS_CARDAPIO = ("Carnes e frios", "Insumos e alimentos")


def _dialogo_confirmar_nota(parent, mensagem, total_v):
    """Confirmação da nota (substitui o Sim/Não simples). Devolve None se cancelou,
    ou (tipo, valor): tipo = None (nada além do normal) ou um de _NOTA_TIPOS_CARDAPIO;
    valor = quanto da nota entra na despesa do cardápio."""
    resultado = {"v": None}
    jan = tk.Toplevel(parent)
    jan.title("Confirmar")
    jan.transient(parent)
    jan.resizable(False, False)

    ttk.Label(jan, text=mensagem, wraplength=440, justify="left").pack(padx=18, pady=(16, 10), anchor="w")

    quadro = ttk.LabelFrame(jan, text=" Despesa do cardápio (opcional) ")
    quadro.pack(fill="x", padx=18, pady=(0, 10))
    ttk.Label(quadro, text="Esta compra entra na despesa do cardápio do caixa aberto?",
              wraplength=420, justify="left").grid(row=0, column=0, columnspan=2, sticky="w", padx=8, pady=(6, 4))
    ttk.Label(quadro, text="Tipo:").grid(row=1, column=0, sticky="w", padx=8)
    opcoes = ["Não — só o lançamento normal"] + list(_NOTA_TIPOS_CARDAPIO)
    cb_tipo = ttk.Combobox(quadro, values=opcoes, state="readonly", width=32)
    cb_tipo.set(opcoes[0])
    cb_tipo.grid(row=1, column=1, sticky="w", padx=8, pady=2)
    ttk.Label(quadro, text="Valor (R$):").grid(row=2, column=0, sticky="w", padx=8)
    ent_val = ttk.Entry(quadro, width=14)
    ent_val.insert(0, f"{total_v:.2f}".replace(".", ","))
    ent_val.grid(row=2, column=1, sticky="w", padx=8, pady=(2, 8))
    ttk.Label(quadro, text="(se só parte da nota é carne/insumo, ajuste o valor)",
              foreground="#7F8C8D").grid(row=3, column=0, columnspan=2, sticky="w", padx=8, pady=(0, 6))

    def confirmar():
        tipo = cb_tipo.get()
        if tipo not in _NOTA_TIPOS_CARDAPIO:
            resultado["v"] = (None, 0.0)
            jan.destroy()
            return
        try:
            valor = round(float(ent_val.get().strip().replace(".", "").replace(",", ".")
                                if ("," in ent_val.get()) else ent_val.get().strip()), 2)
        except Exception:
            messagebox.showwarning("Valor inválido", "Informe um valor válido para a despesa do cardápio.", parent=jan)
            return
        if valor <= 0 or valor > round(total_v, 2) + 0.005:
            messagebox.showwarning("Valor inválido",
                                   f"O valor deve ser maior que zero e no máximo R$ {total_v:.2f} (total da nota).",
                                   parent=jan)
            return
        if not _obter_ciclo_aberto_id():
            messagebox.showwarning("Caixa fechado",
                                   "Para lançar esta despesa no cardápio é preciso ter o caixa aberto "
                                   "(a despesa fica ligada ao caixa).\n\nAbra o caixa ou escolha "
                                   "\"Não\" para lançar só a nota normalmente.", parent=jan)
            return
        resultado["v"] = (tipo, valor)
        jan.destroy()

    def cancelar():
        resultado["v"] = None
        jan.destroy()

    f_b = ttk.Frame(jan)
    f_b.pack(pady=(0, 14))
    ttk.Button(f_b, text="Confirmar", command=confirmar, width=14).pack(side="left", padx=8)
    ttk.Button(f_b, text="Cancelar", command=cancelar, width=14).pack(side="left", padx=8)
    jan.protocol("WM_DELETE_WINDOW", cancelar)
    jan.bind("<Escape>", lambda _e: cancelar())

    jan.update_idletasks()
    try:
        x = parent.winfo_rootx() + (parent.winfo_width() - jan.winfo_width()) // 2
        y = parent.winfo_rooty() + (parent.winfo_height() - jan.winfo_height()) // 3
        jan.geometry(f"+{max(0, x)}+{max(0, y)}")
    except Exception:
        pass
    jan.grab_set()
    jan.focus_set()
    parent.wait_window(jan)
    return resultado["v"]


def _gravar_despesa_cardapio_nota(tipo, valor, fornecedor, referencia, id_despesa, id_conta):
    """Grava (SEM commit) a despesa da nota no histórico do cardápio, ligada ao caixa
    aberto. Roda dentro da transação da nota: se algo falhar, o rollback desfaz tudo."""
    ciclo = _obter_ciclo_aberto_id()
    if not ciclo:
        raise RuntimeError("Caixa fechado: não é possível ligar a despesa ao cardápio.")
    cursor.execute("""
        INSERT INTO cardapio_historico_despesas
            (ciclo_id, tipo, valor, fornecedor, referencia, id_despesa, id_conta, data_lancamento)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (ciclo, tipo, valor, fornecedor, referencia, id_despesa, id_conta,
          datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
    return ciclo


def lancar_nota_estoque():
    if not ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Aviso", "Abra o caixa antes de lançar notas!")
        return

    jan_n = tk.Toplevel(root)
    jan_n.title("Lançamento Profissional de Nota")

    # --- TAMANHO E POSIÇÃO SEGUROS PARA A TELA DO USUÁRIO ---
    # Em vez de fixar 950x700 (que pode ultrapassar a altura útil da tela,
    # empurrando os botões de finalizar para fora da área visível), calculamos
    # o tamanho com base na tela real e centralizamos a janela.
    LARG_JAN = 950
    ALT_JAN_DESEJADA = 700
    tela_larg = jan_n.winfo_screenwidth()
    tela_alt = jan_n.winfo_screenheight()

    margem_seguranca = 90  # espaço para barra de tarefas / decoração da janela
    alt_jan = min(ALT_JAN_DESEJADA, tela_alt - margem_seguranca)
    larg_jan = min(LARG_JAN, tela_larg - 40)

    pos_x = max(0, (tela_larg - larg_jan) // 2)
    pos_y = max(0, (tela_alt - alt_jan) // 2)

    jan_n.geometry(f"{larg_jan}x{alt_jan}+{pos_x}+{pos_y}")
    jan_n.minsize(min(900, larg_jan), min(650, alt_jan))
    jan_n.resizable(True, True)  # garante que o botão de maximizar apareça

    jan_n.transient(root)
    jan_n.grab_set()

    # --- RODAPÉ FIXO (reserva espaço ANTES da área expansível, assim o botão
    # de finalizar nunca fica escondido, mesmo com muitos itens na lista) ---
    f_botoes = ttk.Frame(jan_n)
    f_botoes.pack(side="bottom", fill="x", pady=15)

    # --- VARIÁVEIS E BUSCA DE DADOS ---
    # Agora carrega TODOS os itens do estoque (Insumos e Produtos Acabados),
    # guardando código, preço de custo e categoria de cada um, indexados
    # pelo NOME do produto (sem o código na frente), para permitir um
    # autocomplete no estilo Google (busca só pelo nome digitado).
    def carregar_dados_itens():
        dados = {}
        for r in cursor.execute("SELECT codigo, produto, custo, categoria FROM estoque ORDER BY produto ASC"):
            dados[r[1]] = {"codigo": r[0], "preco": r[2] or 0, "categoria": r[3] or "INSUMO"}
        return dados

    dict_itens = carregar_dados_itens()
    # Ordem alfabética (case-insensitive), garantindo que o autocomplete
    # sempre sugira o primeiro item em ordem alfabética que combine.
    lista_itens_original = sorted(dict_itens.keys(), key=lambda s: s.upper())
    # Índice auxiliar (chave em MAIÚSCULO -> nome original no banco), usado
    # para localizar um item já existente mesmo quando o usuário digita com
    # acentuação/maiúsculas diferentes do cadastro (evita que o item apareça
    # como "NOVO" na tabela mesmo já existindo no estoque).
    dict_itens_upper = {nome.upper(): nome for nome in dict_itens}

    def buscar_item_existente(nome_digitado):
        """Retorna (nome_original, dados) se o item já existir no estoque,
        comparando de forma case-insensitive; senão retorna (None, None)."""
        nome_real = dict_itens_upper.get(nome_digitado.upper())
        if nome_real:
            return nome_real, dict_itens[nome_real]
        return None, None

    # Controla manualmente o estado da sugestão "fantasma" atual, para não
    # depender da seleção de texto do Tkinter (que é frágil em Combobox e
    # não garante que a próxima tecla substitua o trecho sugerido).
    estado_autocomplete = {"prefixo": "", "sugestao_ativa": False, "indice": -1}

    TECLAS_NAVEGACAO = ("Left", "Right", "Up", "Down", "Return", "Escape", "Tab",
                         "Shift_L", "Shift_R", "Control_L", "Control_R",
                         "Alt_L", "Alt_R", "Caps_Lock", "Home", "End")

    def aplicar_dados_item(nome_item):
        """Preenche o valor unitário e ajusta a categoria quando o item
        digitado/selecionado já existe no estoque (comparação sem diferenciar
        maiúsculas/minúsculas, para não perder o item por causa da caixa)."""
        _, info = buscar_item_existente(nome_item)
        if info:
            ent_vu.delete(0, "end")
            ent_vu.insert(0, f"{info['preco']:.2f}")
            # Deixa o valor já selecionado, facilitando sobrescrever
            ent_vu.selection_range(0, tk.END)
            ent_vu.icursor(tk.END)
            # Item já existente: a categoria real do banco prevalece
            # sobre a última categoria "lembrada" no combobox.
            cb_cat.set("PRODUTO ACABADO" if info["categoria"] == "PRODUTO" else "INSUMO")

    def preparar_antes_de_digitar(event):
        # Roda ANTES da tecla ser inserida no campo (bind de <KeyPress> do
        # próprio widget é avaliado antes do binding padrão de inserção).
        if event.keysym in ("BackSpace", "Delete"):
            # Usuário está apagando: cancela qualquer sugestão pendente e
            # deixa o apagar acontecer normalmente, sem interferência.
            estado_autocomplete["sugestao_ativa"] = False
            return
        if event.keysym in TECLAS_NAVEGACAO:
            return
        if estado_autocomplete["sugestao_ativa"]:
            # Existe uma sugestão "fantasma" no campo. Remove ela ANTES de
            # inserir a nova letra, para a letra cair exatamente depois do
            # que o usuário realmente digitou — sem se misturar com o
            # texto sugerido anteriormente.
            pos = len(estado_autocomplete["prefixo"])
            cb_i.delete(pos, tk.END)
            cb_i.icursor(pos)
            estado_autocomplete["sugestao_ativa"] = False

    def fechar_popup_sugestoes():
        if popup_sug.winfo_ismapped():
            popup_sug.withdraw()
        estado_autocomplete["indice"] = -1

    def mostrar_popup_sugestoes(matches):
        """Exibe a lista de sugestões (estilo Google) logo abaixo do campo
        Item, com a primeira opção realçada (a mesma do texto 'fantasma')."""
        if not matches:
            fechar_popup_sugestoes()
            return
        lista_sug.delete(0, tk.END)
        for m in matches[:8]:
            lista_sug.insert(tk.END, m)
        lista_sug.selection_clear(0, tk.END)
        lista_sug.selection_set(0)
        lista_sug.activate(0)
        estado_autocomplete["indice"] = 0

        cb_i.update_idletasks()
        x = cb_i.winfo_rootx()
        y = cb_i.winfo_rooty() + cb_i.winfo_height()
        largura = cb_i.winfo_width()
        altura_linha = 22
        altura_total = min(len(matches), 8) * altura_linha
        popup_sug.geometry(f"{largura}x{altura_total}+{x}+{y}")
        popup_sug.deiconify()
        popup_sug.lift()

    def selecionar_da_lista(event=None):
        # Disparado ao clicar (com o mouse) numa sugestão da lista suspensa
        sel = lista_sug.curselection()
        if not sel:
            return
        valor = lista_sug.get(sel[0])
        cb_i.delete(0, tk.END)
        cb_i.insert(0, valor)
        estado_autocomplete["prefixo"] = valor
        estado_autocomplete["sugestao_ativa"] = False
        aplicar_dados_item(valor)
        fechar_popup_sugestoes()
        ent_q.focus()

    def navegar_sugestoes(direcao):
        """Navega pela lista de sugestões com as setas ↑/↓, atualizando o
        campo Item para refletir a opção realçada — igual ao Google."""
        total = lista_sug.size()
        if total == 0:
            return "break"
        atual = estado_autocomplete.get("indice", -1)
        novo = max(0, min(total - 1, atual + direcao))
        estado_autocomplete["indice"] = novo
        lista_sug.selection_clear(0, tk.END)
        lista_sug.selection_set(novo)
        lista_sug.activate(novo)
        lista_sug.see(novo)
        valor = lista_sug.get(novo)
        cb_i.delete(0, tk.END)
        cb_i.insert(0, valor)
        cb_i.icursor(tk.END)
        estado_autocomplete["prefixo"] = valor
        estado_autocomplete["sugestao_ativa"] = False
        aplicar_dados_item(valor)
        return "break"

    def autocomplete_digitacao(event):
        # Roda DEPOIS da tecla já inserida (KeyRelease). Graças à limpeza
        # feita em preparar_antes_de_digitar, o texto aqui já está correto.
        if event.keysym in ("BackSpace", "Delete") or event.keysym in TECLAS_NAVEGACAO:
            return

        texto_digitado = cb_i.get()
        estado_autocomplete["prefixo"] = texto_digitado
        estado_autocomplete["sugestao_ativa"] = False

        if not texto_digitado:
            fechar_popup_sugestoes()
            return

        texto_upper = texto_digitado.upper()

        # Busca por "COMEÇA COM" (estilo Google), nunca "contém"
        matches = [nome for nome in lista_itens_original if nome.upper().startswith(texto_upper)]

        if matches:
            nome = matches[0]
            pos = len(texto_digitado)
            # Mantém o texto digitado intacto e só completa o restante,
            # deixando a parte sugerida selecionada (efeito "fantasma")
            cb_i.delete(0, tk.END)
            cb_i.insert(0, texto_digitado + nome[pos:])
            cb_i.selection_range(pos, tk.END)
            cb_i.icursor(pos)
            estado_autocomplete["prefixo"] = texto_digitado
            estado_autocomplete["sugestao_ativa"] = True
            # Já aproveita para sugerir preço/categoria deste item
            aplicar_dados_item(nome)
            # Mostra a lista de sugestões (todas as que combinam), igual ao print do Google
            mostrar_popup_sugestoes(matches)
        else:
            # Nenhuma correspondência: fecha a lista e não faz mais nada,
            # permitindo cadastrar um item totalmente novo sem travar.
            fechar_popup_sugestoes()

    def ao_selecionar_item(event):
        # Disparado ao clicar numa opção do dropdown nativo do Combobox
        selecionado = cb_i.get()
        estado_autocomplete["prefixo"] = selecionado
        estado_autocomplete["sugestao_ativa"] = False
        aplicar_dados_item(selecionado)
        fechar_popup_sugestoes()
        ent_q.focus() # Pula para quantidade para agilizar

    def confirmar_item_enter(event):
        # Disparado ao apertar ENTER no campo Item: garante que os dados
        # (preço/categoria) do item sugerido/selecionado sejam aplicados
        # antes de pular para o campo de quantidade.
        texto = cb_i.get().strip()
        estado_autocomplete["prefixo"] = texto
        estado_autocomplete["sugestao_ativa"] = False
        if texto:
            aplicar_dados_item(texto)
        fechar_popup_sugestoes()
        ent_q.focus()
        return "break"

    # --- FRAME CABEÇALHO DA NOTA ---
    f_header = ttk.LabelFrame(jan_n, text=" Dados da Nota Fiscal ")
    f_header.pack(fill="x", padx=10, pady=5)

    ttk.Label(f_header, text="Fornecedor:").grid(row=0, column=0, sticky="w")
    ent_fornecedor = ttk.Entry(f_header, width=40)
    ent_fornecedor.grid(row=1, column=0, padx=5)

    ttk.Label(f_header, text="Nº da Nota (Opcional):").grid(row=0, column=1, sticky="w")
    ent_num_nota = ttk.Entry(f_header, width=20)
    ent_num_nota.grid(row=1, column=1, padx=5)

    ttk.Label(f_header, text="Vencimento (se Pendente):").grid(row=0, column=2, sticky="w")
    # Pré-preenche com a data de hoje; o usuário escolhe no calendário (✕ limpa)
    ent_vencimento = CampoData(f_header, valor=_date_imp.today(), pode_vazio=True)
    ent_vencimento.grid(row=1, column=2, padx=5)

    # --- FRAME LANÇAMENTO DE ITENS ---
    f_item = ttk.LabelFrame(jan_n, text=" Inserir Itens (Navegue com ENTER) ")
    f_item.pack(fill="x", padx=10, pady=5)

    ttk.Label(f_item, text="Item:").grid(row=0, column=0, sticky="w")
    cb_i = ttk.Combobox(f_item, width=40)
    cb_i["values"] = lista_itens_original
    cb_i.grid(row=1, column=0, padx=5)

    # --- LISTA DE SUGESTÕES ESTILO GOOGLE (janela flutuante logo abaixo do campo) ---
    # Em vez de depender só do dropdown nativo do ttk.Combobox (que exige
    # clique/tecla especial para abrir), usamos uma pequena janela sem
    # bordas com um Listbox, exibida automaticamente enquanto o usuário
    # digita — reproduzindo o efeito de sugestões do Google.
    popup_sug = tk.Toplevel(jan_n)
    popup_sug.withdraw()
    popup_sug.overrideredirect(True)
    popup_sug.attributes("-topmost", True)
    lista_sug = tk.Listbox(popup_sug, activestyle="none", relief="flat",
                            highlightthickness=1, highlightbackground="#cccccc",
                            selectbackground="#e8e8e8", selectforeground="black",
                            font=("Arial", 10), bd=0)
    lista_sug.pack(fill="both", expand=True)
    lista_sug.bind("<ButtonRelease-1>", selecionar_da_lista)

    # Binds do Autocomplete
    # <KeyPress> roda ANTES da tecla ser inserida (limpa a sugestão fantasma
    # se necessário); <KeyRelease> roda DEPOIS (recalcula a nova sugestão)
    cb_i.bind('<KeyPress>', preparar_antes_de_digitar)
    cb_i.bind('<KeyRelease>', autocomplete_digitacao)
    cb_i.bind('<<ComboboxSelected>>', ao_selecionar_item)
    cb_i.bind('<Down>', lambda e: navegar_sugestoes(1))
    cb_i.bind('<Up>', lambda e: navegar_sugestoes(-1))
    cb_i.bind('<Escape>', lambda e: fechar_popup_sugestoes())
    # Fecha a lista de sugestões quando o foco sai do campo (com um pequeno
    # atraso, para dar tempo do clique numa sugestão ser processado antes)
    cb_i.bind('<FocusOut>', lambda e: jan_n.after(150, fechar_popup_sugestoes))

    ttk.Label(f_item, text="Qtd:").grid(row=0, column=1, sticky="w")
    ent_q = ttk.Entry(f_item, width=10)
    ent_q.grid(row=1, column=1, padx=5)

    ttk.Label(f_item, text="Vlr Unitário:").grid(row=0, column=2, sticky="w")
    ent_vu = ttk.Entry(f_item, width=12)
    ent_vu.grid(row=1, column=2, padx=5)

    ttk.Label(f_item, text="Categoria:").grid(row=0, column=3, sticky="w")
    cb_cat = ttk.Combobox(f_item, width=16, state="readonly",
                           values=["INSUMO", "PRODUTO ACABADO"])
    cb_cat.set("INSUMO")  # valor inicial; depois disso o combobox "lembra" a última escolha
    cb_cat.grid(row=1, column=3, padx=5)

    # --- TABELA DE ITENS ---
    f_tree = ttk.Frame(jan_n)
    f_tree.pack(fill="both", expand=True, padx=10)

    cols = ("cod", "prod", "qtd", "v_un", "subtotal", "categoria")
    tree_n = ttk.Treeview(f_tree, columns=cols, show="headings", height=10)
    for c in cols:
        tree_n.heading(c, text=c.upper())
        tree_n.column(c, anchor="center", width=100)
    tree_n.column("prod", width=300, anchor="w")
    tree_n.column("categoria", width=130, anchor="center")

    scroll_tree_n = ttk.Scrollbar(f_tree, orient="vertical", command=tree_n.yview)
    tree_n.configure(yscrollcommand=scroll_tree_n.set)
    scroll_tree_n.pack(side="right", fill="y")
    tree_n.pack(side="left", fill="both", expand=True)
    ativar_lista_interativa(tree_n, "prod")

    lbl_total_nota = ttk.Label(jan_n, text="TOTAL DA NOTA: R$ 0,00", font=("Arial", 18, "bold"), foreground="#2c3e50")
    lbl_total_nota.pack(pady=10)

    # --- LÓGICA AUXILIAR ---
    def atualizar_total_nota():
        total = 0.0
        for item in tree_n.get_children():
            v_str = tree_n.item(item, "values")[4].replace("R$ ", "").replace(",", ".")
            total += float(v_str)
        lbl_total_nota.config(text=f"TOTAL DA NOTA: R$ {total:.2f}")

    def adicionar_item_na_lista(event=None):
        try:
            prod_val = cb_i.get().strip()
            if not prod_val: return
            q = float(ent_q.get().replace(",", "."))
            vu = float(ent_vu.get().replace(",", "."))
            sub = q * vu

            # Código real se o item já existir no estoque (comparação sem
            # diferenciar maiúsculas/minúsculas); senão será criado ao
            # finalizar. Usa o nome exatamente como está cadastrado no banco
            # quando o item já existe, para manter consistência.
            nome_existente, info_existente = buscar_item_existente(prod_val)
            if info_existente:
                cod = info_existente["codigo"]
                nome = nome_existente
            else:
                cod = "NOVO"
                nome = prod_val

            categoria_sel = "PRODUTO" if cb_cat.get() == "PRODUTO ACABADO" else "INSUMO"
            categoria_label = "PRODUTO ACABADO" if categoria_sel == "PRODUTO" else "INSUMO"

            tree_n.insert("", "end", values=(cod, nome, f"{q:.3f}", f"R$ {vu:.2f}", f"R$ {sub:.2f}", categoria_label))
            atualizar_total_nota()

            cb_i.set(""); ent_q.delete(0, "end"); ent_vu.delete(0, "end")
            # cb_cat NÃO é resetado: mantém a última categoria selecionada
            # para o próximo item, conforme combinado.
            estado_autocomplete["prefixo"] = ""
            estado_autocomplete["sugestao_ativa"] = False
            fechar_popup_sugestoes()
            cb_i.focus()
        except:
            messagebox.showerror("Erro", "Verifique Quantidade e Valor!")

    # Botão Inserir e Binds de Navegação
    ttk.Button(f_item, text="📥 INSERIR ITEM", command=adicionar_item_na_lista).grid(row=1, column=4, padx=10)
    cb_i.bind("<Return>", confirmar_item_enter)
    ent_q.bind("<Return>", lambda e: ent_vu.focus())
    ent_vu.bind("<Return>", adicionar_item_na_lista)

    # --- FINALIZAÇÃO ---
    def finalizar_processo_nota(forma):
        total_v = float(lbl_total_nota.cget("text").replace("TOTAL DA NOTA: R$ ", ""))
        if total_v <= 0:
            messagebox.showwarning("Aviso", "A nota está vazia!")
            return

        fornecedor = ent_fornecedor.get().strip() or "Diversos"
        num_nota = ent_num_nota.get().strip()
        referencia = f"NF {num_nota}" if num_nota else "S/N"

        eh_pendente = (forma == "Pendente")
        venc = ent_vencimento.get().strip()

        if eh_pendente and not venc:
            messagebox.showwarning("Aviso", "Informe a data de vencimento para lançar como Pendente.")
            return

        if eh_pendente:
            # Valida a data de vencimento no formato brasileiro (dd/mm/aaaa),
            # rejeitando datas inexistentes (ex.: 31/02/2026) e formatos
            # incorretos, mas sempre mantendo/normalizando para dd/mm/aaaa.
            venc_normalizado = validar_data_br(venc)
            if not venc_normalizado:
                messagebox.showwarning(
                    "Data inválida",
                    f'A data de vencimento "{venc}" não é válida.\n'
                    "Use o formato brasileiro dd/mm/aaaa (ex.: 30/09/2026)."
                )
                ent_vencimento.focus()
                return
            venc = venc_normalizado

        if eh_pendente:
            msg_confirma = f"Lançar nota como PENDENTE (vencimento {venc})?\nValor: R$ {total_v:.2f}\nFornecedor: {fornecedor}\n\nO estoque será atualizado agora, mas o caixa só será debitado quando a conta for liquidada em Contas a Pagar."
        else:
            msg_confirma = f"Pagar R$ {total_v:.2f} no {forma}?\nFornecedor: {fornecedor}"

        _esc_nota = _dialogo_confirmar_nota(jan_n, msg_confirma, total_v)
        if _esc_nota is not None:
                    tipo_card_nota, valor_card_nota = _esc_nota
                    try:
                        data_agora_sql = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

                        # 1. INSERE NA TABELA 'despesas' (Mãe) PARA O RELATÓRIO
                        # (registrado independente da forma, pois representa a
                        # compra em si; o pagamento em caixa é tratado à parte)
                        cursor.execute("""
                            INSERT INTO despesas (fornecedor, valor_total, data_lancamento, categoria) 
                            VALUES (?, ?, ?, ?)
                        """, (fornecedor, total_v, data_agora_sql, "COMPRA ESTOQUE"))
                
                        # Pega o ID dessa despesa que acabou de ser criada
                        id_despesa_mae = cursor.lastrowid

                        # Se for pendente, já cria a conta a pagar para vincular os itens
                        id_conta_pagar = None
                        if eh_pendente:
                            cursor.execute("""
                                INSERT INTO contas_pagar
                                (descricao, fornecedor, categoria, valor, data_emissao, data_vencimento, status, observacao)
                                VALUES (?, ?, ?, ?, ?, ?, 'PENDENTE', ?)
                            """, (f"COMPRA ESTOQUE ({referencia})", fornecedor, "COMPRA ESTOQUE",
                                  total_v, data_agora_sql, venc, f"Despesa #{id_despesa_mae}"))
                            id_conta_pagar = cursor.lastrowid

                        # Nota paga na hora (saída de caixa): registra também em Contas / Faturas
                        # já como PAGO, com os itens, para aparecer na lista por fornecedor e
                        # abrir no duplo clique. NÃO mexe no caixa nem nos relatórios (isso
                        # continua sendo feito só pelos lançamentos já existentes abaixo).
                        id_conta_nota = id_conta_pagar
                        if not eh_pendente:
                            cursor.execute("""
                                INSERT INTO contas_pagar
                                (descricao, fornecedor, categoria, valor, data_emissao, data_vencimento,
                                 status, forma_pagamento, data_pagamento, ciclo_caixa_id, observacao)
                                VALUES (?, ?, ?, ?, ?, ?, 'PAGO', ?, ?, ?, ?)
                            """, (f"COMPRA ESTOQUE ({referencia})", fornecedor, "COMPRA ESTOQUE",
                                  total_v, data_agora_sql, datetime.now().strftime("%d/%m/%Y"),
                                  padronizar_forma_pagamento(forma), data_agora_sql,
                                  ciclo_caixa_aberto.get("id"), f"Despesa #{id_despesa_mae}"))
                            id_conta_nota = cursor.lastrowid

                        # 2. LOOP PELOS ITENS DA TREEVIEW
                        for item in tree_n.get_children():
                            c, n, q, vu, sub, cat_item = tree_n.item(item, "values")
                            qtd_f = float(q)
                            v_un_f = float(vu.replace("R$ ", "").replace(",", "."))
                            v_sub_f = float(sub.replace("R$ ", "").replace(",", "."))
                            categoria_bd = "PRODUTO" if cat_item == "PRODUTO ACABADO" else "INSUMO"

                            # SALVA CADA ITEM NA TABELA 'despesas_itens' (Filha) PARA O RELATÓRIO
                            cursor.execute("""
                                INSERT INTO despesas_itens (id_despesa, item, categoria_item, valor, data_lancamento)
                                VALUES (?, ?, ?, ?, ?)
                            """, (id_despesa_mae, n, categoria_bd, v_sub_f, data_agora_sql))

                            # Guarda também o detalhamento do item vinculado à conta (pendente ou paga)
                            if id_conta_nota:
                                cursor.execute("""
                                    INSERT INTO contas_pagar_itens (id_conta, produto, categoria_item, quantidade, valor_unitario, subtotal)
                                    VALUES (?, ?, ?, ?, ?, ?)
                                """, (id_conta_nota, n, categoria_bd, qtd_f, v_un_f, v_sub_f))

                            # Lógica original de atualização de Estoque (roda sempre,
                            # inclusive quando Pendente, pois o estoque já entra)
                            # VERIFICA SE PRODUTO JÁ EXISTE PELO NOME
                            cursor.execute("SELECT codigo FROM estoque WHERE UPPER(produto)=?", (n.upper(),))
                            ja_existe = cursor.fetchone()

                            if ja_existe:
                                cod_existente = ja_existe[0]
                                # Atualiza estoque existente (categoria original é preservada)
                                cursor.execute("""
                                    UPDATE estoque 
                                    SET quantidade = quantidade + ?, custo = ?
                                    WHERE codigo = ?
                                """, (qtd_f, v_un_f, cod_existente))

                            else:
                                # GERA CÓDIGO ÚNICO PROFISSIONAL (COM MICROSEGUNDO)
                                novo_c = f"P{datetime.now().strftime('%Y%m%d%H%M%S%f')}{n[:2].upper()}"
                                
                                cursor.execute("""
                                    INSERT INTO estoque (codigo, produto, custo, venda, quantidade, categoria)
                                    VALUES (?, ?, ?, 0, ?, ?)
                                """, (novo_c, n, v_un_f, qtd_f, categoria_bd))

                        # 2.1 (opcional) despesa do histórico de cardápios — só se marcou
                        # Carnes/Insumos na confirmação. Fica na mesma transação da nota.
                        if tipo_card_nota:
                            _gravar_despesa_cardapio_nota(tipo_card_nota, valor_card_nota, fornecedor,
                                                          referencia, id_despesa_mae, id_conta_pagar)

                        # 3. LANÇAMENTO NO CAIXA — só ocorre se NÃO for Pendente.
                        # Quando Pendente, o caixa só será debitado na liquidação
                        # feita pela aba Contas a Pagar (fluxo já existente).
                        if not eh_pendente:
                            desc_caixa = f"COMPRA: {fornecedor} ({referencia})"
                            c_id = ciclo_caixa_aberto.get("id") # Pega o ID do caixa atual

                            registrar_lancamento_caixa("SAIDA", desc_caixa, total_v, forma, ciclo_id=c_id)
                            registrar_log("SAIDA_CAIXA", "FINANCEIRO", desc_caixa, {"valor": total_v, "forma": forma, "caixa": c_id})

                        conn.commit()
                        registrar_log("DESPESA_LANCADA", "FINANCEIRO", id_despesa_mae, {"fornecedor": fornecedor, "valor": total_v, "categoria": "COMPRA ESTOQUE", "forma": forma, "referencia": referencia})
                        registrar_log("ESTOQUE_ENTRADA", "ESTOQUE", referencia, {"fornecedor": fornecedor, "valor_total": total_v, "itens": len(tree_n.get_children())})
                        if eh_pendente:
                            registrar_log("CONTA_PENDENTE_LANCADA", "FINANCEIRO", id_conta_pagar, {"fornecedor": fornecedor, "valor": total_v, "vencimento": venc, "referencia": referencia})

                        # --- ATUALIZAÇÃO VISUAL ---
                        # Formata a data para o padrão brasileiro no histórico visual
                        data_pt = datetime.now().strftime("%d/%m/%Y %H:%M")
                        
                        if not eh_pendente and 'lista_despesas' in globals():
                            # Certifique-se que as colunas aqui batem com sua Treeview de histórico
                            lista_despesas.insert("", 0, values=(referencia, fornecedor, f"R$ {total_v:.2f}", data_pt))
                        
                        if 'listar_estoque' in globals(): 
                            listar_estoque()
                            
                        if 'atualizar_saldo' in globals(): 
                            atualizar_saldo()

                        if 'atualizar_contas' in globals():
                            atualizar_contas()
                
                        jan_n.destroy()
                        if eh_pendente:
                            messagebox.showinfo("Sucesso", "Nota lançada como Pendente! Estoque atualizado e conta criada em Contas a Pagar.")
                        else:
                            messagebox.showinfo("Sucesso", "Nota, Estoque e Relatórios atualizados!")

                    except Exception as e:
                        conn.rollback() # Desfaz se der erro
                        messagebox.showerror("Erro", f"Erro ao processar: {e}")

    # --- RODAPÉ E REMOÇÃO ---
    # (f_botoes já foi criado e fixado com side="bottom" no início da função,
    # antes da árvore expansível, para garantir que fique sempre visível)

    ttk.Button(f_botoes, text="🗑️ Remover Item Selecionado",
           command=lambda: [tree_n.delete(tree_n.selection()), atualizar_total_nota()]).pack(pady=5)

    btn_din = ttk.Button(f_botoes, text="💵 FINALIZAR EM DINHEIRO", bootstyle="success", 
                        command=lambda: finalizar_processo_nota("Dinheiro"), height=2, width=26)
    btn_din.pack(side="left", padx=15, expand=True)
    
    btn_pix = ttk.Button(f_botoes, text="📱 FINALIZAR EM PIX", bootstyle="success", 
                        command=lambda: finalizar_processo_nota("Pix"), height=2, width=26)
    btn_pix.pack(side="left", padx=15, expand=True)

    btn_pendente = ttk.Button(f_botoes, text="🕒 FINALIZAR PENDENTE", bootstyle="warning",
                        command=lambda: finalizar_processo_nota("Pendente"), height=2, width=26)
    btn_pendente.pack(side="left", padx=15, expand=True)

