def adicionar_estoque():
    if not cb_add.get() or not e_add_qtd.get(): return
    codigo = cb_add.get().split(" - ")[0]
    cursor.execute("UPDATE estoque SET quantidade = quantidade + ? WHERE codigo = ?", (int(e_add_qtd.get()), codigo))
    conn.commit()
