def _fmt_brl(valor):
    """Formata no padrão brasileiro (R$ 1.234,56). Somente exibição."""
    try:
        texto = f"{float(valor):,.2f}"
    except Exception:
        texto = "0.00"
    return "R$ " + texto.replace(",", "X").replace(".", ",").replace("X", ".")


