@somente_thread_principal
def atualizar_saldo():
    if not ciclo_caixa_aberto.get("id"):
        # Se o caixa estiver fechado, zera as labels
        lbl_resumo_pix.config(text=_fmt_brl(0))
        lbl_resumo_dinheiro.config(text=_fmt_brl(0))
        lbl_resumo_cartao.config(text=_fmt_brl(0))
        lbl_resumo_pendente.config(text=_fmt_brl(0))
        lbl_saldo.config(text=_fmt_brl(0))
        _atualizar_cards_caixa(0, 0, 0)
        _atualizar_card_troco_estornar(0.0)   # conferencia visual: zera o card (nao altera o caixa)
        return

    c_id = ciclo_caixa_aberto["id"]
    abertura_data = ciclo_caixa_aberto["abertura"]

    # --- 1. CÁLCULO PIX ---
    # Soma entradas em Pix
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Pix' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (c_id, abertura_data,))
    entradas_pix = cursor.fetchone()[0] or 0.0
    
    # Soma SAÍDAS em Pix (O que faltava!)
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Pix' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (c_id, abertura_data,))
    saidas_pix = cursor.fetchone()[0] or 0.0
    
    abertura_pix = ciclo_caixa_aberto.get("saldo_inicial_pix", 0)
    # Cálculo final do Pix considerando entradas e saídas de Pix
    total_pix_final = round((abertura_pix + entradas_pix) - saidas_pix, 2)
    lbl_resumo_pix.config(text=_fmt_brl(total_pix_final))


    # --- 2. CÁLCULO DINHEIRO ---
    # Soma entradas em Dinheiro
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Dinheiro' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (c_id, abertura_data,))
    entradas_din = cursor.fetchone()[0] or 0.0
    
    # Soma SAÍDAS apenas em Dinheiro (Corrigido para não pegar as de Pix)
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Dinheiro' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (c_id, abertura_data,))
    saidas_din = cursor.fetchone()[0] or 0.0
    
    abertura_din = ciclo_caixa_aberto.get("saldo_inicial", 0)
    # Cálculo final do Dinheiro
    total_din_final = round((abertura_din + entradas_din) - saidas_din, 2)
    lbl_resumo_dinheiro.config(text=_fmt_brl(total_din_final))


    # --- 3. CÁLCULO CARTÃO ---
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Cartão' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (c_id, abertura_data,))
    entradas_cartao = cursor.fetchone()[0] or 0.0

    # Saídas em Cartão (estorno/cancelamento de pedido pago no cartão, compra no cartão):
    # antes eram ignoradas aqui e o valor estornado continuava no saldo do caixa.
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Cartão' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (c_id, abertura_data,))
    saidas_cartao = cursor.fetchone()[0] or 0.0

    total_cartao = round(entradas_cartao - saidas_cartao, 2)
    lbl_resumo_cartao.config(text=_fmt_brl(total_cartao))


    # --- 4. CÁLCULO PENDÊNCIAS ---
    cursor.execute("SELECT SUM(total) FROM pedidos WHERE (pagamento IS NULL OR pagamento = '' OR pagamento = 'Pendente') AND ciclo_caixa_id = ?", (c_id,))
    total_pendente = cursor.fetchone()[0] or 0.0
    lbl_resumo_pendente.config(text=_fmt_brl(total_pendente))


    # --- 5. SALDO TOTAL (Soma tudo o que entrou de fato) ---
    total_geral = round(total_pix_final + total_din_final + total_cartao, 2)
    saldo_atual.set(total_geral)
    lbl_saldo.config(text=_fmt_brl(total_geral))
    _atualizar_cards_caixa(
        (abertura_pix or 0) + (abertura_din or 0),
        entradas_pix + entradas_din + entradas_cartao,
        saidas_pix + saidas_din + saidas_cartao
    )
    # Conferencia visual (somente exibicao): card "VALOR RECEBIDO A ESTORNAR".
    # Nao altera nenhum valor acima; usa o Dinheiro ja calculado apenas para somar na tela.
    _atualizar_card_troco_estornar(total_din_final)


# =====================================================
# 🟠 CONFERENCIA VISUAL: TROCOS DE ENTREGA A ESTORNAR
# Tudo daqui para baixo e SOMENTE informativo: nunca grava em `caixa`, nunca altera
# `pedidos` e nunca entra nos totais/saldo/fechamento do caixa.
# =====================================================
_trocos_backfill_feito = set()                    # ciclos ja lidos do log nesta sessao
_trocos_janela = {"win": None, "recarregar": None}

# Pedido cancelado/descartado sai do card e da lista sozinho (mesmo criterio usado
# em outros relatorios do sistema), sem precisar tocar no fluxo de cancelamento.
_TROCO_FILTRO_VALIDO = (
    "UPPER(COALESCE(p.pagamento,'')) NOT IN ('CANCELADO','DESCARTE') "
    "AND UPPER(COALESCE(p.observacao,'')) NOT LIKE '%CANCELADO%'"
)


def registrar_troco_entrega(id_baixa, pedido_id, ciclo_id, entregador_id, entregador_nome,
                            valor_recebido, valor_devido, excedente):
    """Guarda o excedente de uma baixa em dinheiro (so conferencia visual).
    Idempotente (id_baixa UNIQUE) e nunca levanta erro para quem chamou."""
    sql = ("INSERT OR IGNORE INTO trocos_entrega "
           "(id_baixa, pedido_id, ciclo_id, entregador_id, entregador_nome, "
           " valor_recebido, valor_devido, excedente, criado_em) VALUES (?,?,?,?,?,?,?,?,?)")
    params = (str(id_baixa), pedido_id if isinstance(pedido_id, int) else None, ciclo_id,
              str(entregador_id or ""), str(entregador_nome or ""),
              None if valor_recebido is None else round(float(valor_recebido), 2),
              None if valor_devido is None else round(float(valor_devido), 2),
              round(float(excedente), 2), datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
    try:
        if _eh_thread_principal():
            try:
                cursor.execute(sql, params)
                conn.commit()
            except Exception:
                try:
                    conn.rollback()   # nao deixa transacao aberta atrapalhar o resto do sistema
                except Exception:
                    pass
                raise
        else:
            conn_t = abrir_conexao_curta()
            try:
                conn_t.execute(sql, params)
                conn_t.commit()
            finally:
                conn_t.close()
    except Exception as erro:
        print(f"[TROCOS] Falha ao registrar troco da baixa {id_baixa}: {erro}")


def _trocos_backfill_auditoria(c_id, abertura):
    """Uma vez por ciclo/sessao: le do log (auditoria) os trocos de baixas feitas ANTES
    desta atualizacao no caixa aberto, para o card ja aparecer certo hoje.
    INSERT OR IGNORE: nunca duplica o que ja foi gravado ao vivo."""
    if not c_id or c_id in _trocos_backfill_feito:
        return
    _trocos_backfill_feito.add(c_id)
    try:
        cursor.execute(
            "SELECT data_hora, referencia, detalhes FROM auditoria "
            "WHERE acao='BAIXA_ENTREGA_TROCO_PROVAVEL' AND data_hora >= ?", (abertura,))
        for data_hora, ref, det in cursor.fetchall():
            try:
                d = json.loads(det)
                exc = round(float(d.get("excedente") or 0), 2)
                id_b = str(d.get("id_baixa") or "").strip()
            except Exception:
                continue
            if exc <= 0.009 or not id_b:
                continue
            try:
                ped = int(str(ref).strip())
            except Exception:
                ped = None
            cursor.execute(
                "INSERT OR IGNORE INTO trocos_entrega "
                "(id_baixa, pedido_id, ciclo_id, entregador_id, entregador_nome, "
                " valor_recebido, valor_devido, excedente, criado_em) VALUES (?,?,?,?,?,?,?,?,?)",
                (id_b, ped, c_id, "", "", d.get("valor_recebido"), d.get("restante"), exc, data_hora))
        conn.commit()
    except Exception as erro:
        try:
            conn.rollback()
        except Exception:
            pass
        print(f"[TROCOS] Nao foi possivel ler trocos antigos do log: {erro}")


def _pintar_card_troco(ativo):
    cor = _TROCO_COR_ATIVO if ativo else _TROCO_COR_ZERO
    card_troco.config(bg=cor["bg"], highlightbackground=cor["borda"], highlightcolor=cor["borda"])
    lbl_troco_tit.config(bg=cor["bg"], fg=cor["tit"])
    lbl_troco_valor.config(bg=cor["bg"], fg=cor["val"])
    lbl_troco_soma.config(bg=cor["bg"], fg=cor["sub"])
    _linha_troco.config(bg=cor["bg"])


def _atualizar_card_troco_estornar(total_dinheiro=0.0):
    """Atualiza o card (somente exibicao). Qualquer erro aqui e ignorado: nunca
    interfere no calculo do caixa que chamou."""
    try:
        total_troco = 0.0
        c_id = ciclo_caixa_aberto.get("id")
        if c_id:
            _trocos_backfill_auditoria(c_id, ciclo_caixa_aberto.get("abertura"))
            cursor.execute(
                "SELECT COALESCE(SUM(t.excedente),0) FROM trocos_entrega t "
                "LEFT JOIN pedidos p ON p.id = t.pedido_id "
                "WHERE t.ciclo_id = ? AND " + _TROCO_FILTRO_VALIDO, (c_id,))
            total_troco = round(float(cursor.fetchone()[0] or 0), 2)
        lbl_troco_valor.config(text=_fmt_brl(total_troco))
        lbl_troco_soma.config(text="Dinheiro + estornar: " + _fmt_brl(round(float(total_dinheiro or 0) + total_troco, 2)))
        _pintar_card_troco(total_troco > 0.009)
        win = _trocos_janela.get("win")
        recarregar = _trocos_janela.get("recarregar")
        if win is not None and recarregar is not None:
            try:
                if win.winfo_exists():
                    recarregar()
            except Exception:
                pass
    except Exception as erro:
        print(f"[TROCOS] Falha ao atualizar o card (caixa nao afetado): {erro}")


def abrir_lista_trocos_estornar():
    """Lista de conferencia dos trocos do ciclo, com a caixinha 'ja devolvi'.
    Marcar a caixinha so anota na lista: NAO altera o card nem o caixa."""
    c_id_inicial = ciclo_caixa_aberto.get("id")
    if not c_id_inicial:
        messagebox.showinfo("Trocos a estornar", "Abra o caixa para ver os trocos do ciclo.")
        return
    try:
        w_exist = _trocos_janela.get("win")
        if w_exist is not None and w_exist.winfo_exists():
            w_exist.deiconify()
            w_exist.lift()
            w_exist.focus_force()
            return
    except Exception:
        pass

    win = tk.Toplevel(root)
    win.title("Trocos a estornar - conferência")
    win.geometry("940x470")
    win.minsize(760, 340)
    win.transient(root)
    try:
        _centralizar_dialogo(win)
    except Exception:
        pass

    topo = tk.Frame(win, bg="#FFF3E0", highlightthickness=1, highlightbackground="#EF6C00")
    topo.pack(fill="x", padx=10, pady=(10, 6))
    tk.Label(topo, text="TROCOS A ESTORNAR (conferência)", font=("Segoe UI", 11, "bold"),
             bg="#FFF3E0", fg="#BF360C").pack(anchor="w", padx=10, pady=(6, 0))
    tk.Label(topo, text="Somente para conferir. Marcar \"já devolvi\" é só uma anotação sua: "
                        "não altera o caixa, o saldo nem o card.",
             font=("Segoe UI", 9), bg="#FFF3E0", fg="#6D4C41").pack(anchor="w", padx=10, pady=(0, 6))

    colunas = ("ok", "pedido", "cliente", "entregador", "recebido", "nota", "excedente", "hora")
    meio = ttk.Frame(win)
    meio.pack(fill="both", expand=True, padx=10)
    tree = ttk.Treeview(meio, columns=colunas, show="headings", selectmode="browse")
    for col, titulo, larg, anc in (
            ("ok", "Devolvi", 70, "center"), ("pedido", "Pedido", 70, "center"),
            ("cliente", "Cliente", 220, "w"), ("entregador", "Entregador", 130, "w"),
            ("recebido", "Recebido", 100, "e"), ("nota", "Valor do pedido", 110, "e"),
            ("excedente", "A estornar", 100, "e"), ("hora", "Hora", 90, "center")):
        tree.heading(col, text=titulo)
        tree.column(col, width=larg, anchor=anc, stretch=(col == "cliente"))
    barra = ttk.Scrollbar(meio, orient="vertical", command=tree.yview)
    tree.configure(yscrollcommand=barra.set)
    tree.pack(side="left", fill="both", expand=True)
    barra.pack(side="right", fill="y")
    tree.tag_configure("feito", foreground="#2E7D32")

    rodape = tk.Frame(win)
    rodape.pack(fill="x", padx=10, pady=(6, 10))
    lbl_rodape = tk.Label(rodape, text="", font=("Segoe UI", 10, "bold"), anchor="w")
    lbl_rodape.pack(side="left")
    tk.Button(rodape, text="Fechar", command=lambda: _fechar(), relief="flat",
              bg="#E0E0E0", padx=14).pack(side="right")
    tk.Label(rodape, text="Clique no ☐ (ou barra de espaço) para marcar   ",
             font=("Segoe UI", 8), fg="#757575").pack(side="right")

    estado = {}   # iid -> devolvido (0/1)

    def carregar():
        try:
            c_id = ciclo_caixa_aberto.get("id")
            sel = tree.selection()
            sel_id = sel[0] if sel else None
            tree.delete(*tree.get_children())
            estado.clear()
            total = feito = 0.0
            if c_id:
                cursor.execute(
                    "SELECT t.id, t.pedido_id, COALESCE(p.cliente,''), COALESCE(t.entregador_nome,''), "
                    "t.valor_recebido, t.valor_devido, t.excedente, COALESCE(t.criado_em,''), "
                    "COALESCE(t.devolvido,0) FROM trocos_entrega t "
                    "LEFT JOIN pedidos p ON p.id = t.pedido_id "
                    "WHERE t.ciclo_id = ? AND " + _TROCO_FILTRO_VALIDO + " ORDER BY t.id DESC", (c_id,))
                for tid, ped, cli, ent, rec, dev, exc, quando, ok in cursor.fetchall():
                    iid = str(tid)
                    estado[iid] = 1 if ok else 0
                    exc = float(exc or 0)
                    total += exc
                    if ok:
                        feito += exc
                    hora = (quando[8:10] + "/" + quando[5:7] + " " + quando[11:16]) if len(quando) >= 16 else ""
                    tree.insert("", "end", iid=iid, tags=(("feito",) if ok else ()), values=(
                        "☑" if ok else "☐", f"#{ped}" if ped is not None else "—", cli or "—", ent or "—",
                        _fmt_brl(rec) if rec is not None else "—",
                        _fmt_brl(dev) if dev is not None else "—", _fmt_brl(exc), hora))
            if sel_id and tree.exists(sel_id):
                tree.selection_set(sel_id)
            lbl_rodape.config(
                text=f"A estornar: {_fmt_brl(total)}   ·   Já devolvido (marcado): {_fmt_brl(feito)}"
                     f"   ·   Falta devolver: {_fmt_brl(round(total - feito, 2))}")
        except Exception as erro:
            print(f"[TROCOS] Falha ao carregar a lista: {erro}")

    def alternar(iid):
        try:
            novo = 0 if estado.get(iid) else 1
            cursor.execute("UPDATE trocos_entrega SET devolvido=?, devolvido_em=? WHERE id=?",
                           (novo, datetime.now().strftime("%Y-%m-%d %H:%M:%S") if novo else None, int(iid)))
            conn.commit()
        except Exception as erro:
            try:
                conn.rollback()
            except Exception:
                pass
            messagebox.showerror("Trocos a estornar", f"Não foi possível salvar a marcação:\n{erro}", parent=win)
        carregar()

    def _clique(ev):
        if tree.identify_region(ev.x, ev.y) == "cell" and tree.identify_column(ev.x) == "#1":
            iid = tree.identify_row(ev.y)
            if iid:
                tree.selection_set(iid)
                alternar(iid)
                return "break"

    def _espaco(_ev):
        sel = tree.selection()
        if sel:
            alternar(sel[0])
        return "break"

    def _fechar():
        _trocos_janela["win"] = None
        _trocos_janela["recarregar"] = None
        try:
            win.destroy()
        except Exception:
            pass

    tree.bind("<Button-1>", _clique)
    tree.bind("<space>", _espaco)
    win.bind("<Escape>", lambda _e: _fechar())
    win.protocol("WM_DELETE_WINDOW", _fechar)
    _trocos_janela["win"] = win
    _trocos_janela["recarregar"] = carregar
    carregar()


def calcular_saldo_geral_total():
    # 1. Soma saldo final de todos os caixas já fechados
    cursor.execute("SELECT SUM(saldo_final) FROM ciclos_caixa WHERE status = 'FECHADO'")
    saldo_fechados = cursor.fetchone()[0] or 0.0

    # 2. Soma o que entrou/saiu no caixa atual (se estiver aberto)
    # REGRA 1: fonte única é a tabela `caixa`. Nunca somar pedidos.total aqui.
    saldo_atual_valor = 0.0
    if ciclo_caixa_aberto.get("id"):
        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_caixa_aberto['id'], ciclo_caixa_aberto['abertura'],))
        total_entradas = cursor.fetchone()[0] or 0.0

        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_caixa_aberto['id'], ciclo_caixa_aberto['abertura'],))
        total_despesas = cursor.fetchone()[0] or 0.0

        saldo_atual_valor = ciclo_caixa_aberto["saldo_inicial"] + total_entradas - total_despesas

    return saldo_fechados + saldo_atual_valor

def adicionar_receita():
    origem = e_rec_origem.get().strip()
    valor_raw = e_rec_valor.get().strip()
    
    if not origem or not valor_raw:
        messagebox.showwarning("Aviso", "Preencha origem e valor!")
        return
    
    try:
        valor = float(valor_raw.replace(",", "."))
    except:
        messagebox.showerror("Erro", "Valor de receita inválido!")
        return

    if not ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Aviso", "Abra o caixa antes de lançar receitas!")
        return

    # JANELA DE SELEÇÃO (Estilo Confirmação de Pedido)
    janela_pag = tk.Toplevel(root)
    janela_pag.title("Forma de Recebimento")
    janela_pag.geometry("300x200")
    janela_pag.grab_set()
    janela_pag.resizable(False, False)
    
    # Centralizar a janelinha
    janela_pag.transient(root)

    ttk.Label(janela_pag, text="Como este valor entrou?", font=("Arial", 10, "bold")).pack(pady=15)

    def confirmar_receita(forma):
        registrar_lancamento_caixa("ENTRADA", origem, valor, forma)
        forma_padrao = padronizar_forma_pagamento(forma)
        registrar_log("ENTRADA_CAIXA", "FINANCEIRO", origem, {"valor": valor, "forma": forma_padrao})

        # Interface (registrar_lancamento_caixa já sincronizou saldo/histórico)
        lista_receitas.insert("", "end", values=("Manual", origem, forma_padrao, f"R$ {valor:.2f}", datetime.now().strftime("%d/%m/%Y %H:%M")))

        e_rec_origem.delete(0, tk.END)
        e_rec_valor.delete(0, tk.END)
        janela_pag.destroy()
        messagebox.showinfo("Sucesso", f"Receita em {forma} lançada!")

    ttk.Button(janela_pag, text="💵 DINHEIRO", width=25, command=lambda: confirmar_receita("Dinheiro")).pack(pady=5)
    ttk.Button(janela_pag, text="📱 PIX", width=25, command=lambda: confirmar_receita("Pix")).pack(pady=5)

def adicionar_despesa():
    objeto = e_des_obj.get().strip()
    credor = e_des_credor.get().strip()
    valor_raw = e_des_valor.get().strip()

    categoria = cb_des_categoria.get().strip()

    if not objeto or not credor or not valor_raw:
        messagebox.showwarning("Aviso", "Preencha todos os campos da despesa!")
        return

    if not categoria:
        messagebox.showwarning("Aviso", "Escolha a categoria da despesa!")
        return

    try:
        # Conversão segura de valor
        valor = float(valor_raw.replace(",", "."))
    except:
        messagebox.showerror("Erro", "Valor de despesa inválido!")
        return

    if not ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Aviso", "Abra o caixa antes de lançar despesas!")
        return

    # JANELA DE SELEÇÃO DE FORMA DE PAGAMENTO
    janela_pag = tk.Toplevel(root)
    janela_pag.title("Forma de Pagamento")
    janela_pag.geometry("300x200")
    janela_pag.grab_set()

    def confirmar_despesa(forma):
        data_agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        c_id = ciclo_caixa_aberto["id"]
        
        try:
            # 0. Despesa no relatório (Relatórios > Despesas). Sem commit aqui:
            #    o commit do lançamento no caixa logo abaixo grava os dois juntos.
            registrar_despesa_relatorio(credor, objeto, valor, "DESPESA AVULSA", categoria, data_agora)

            # 1. Registro no Banco via ponto único (Regras 1, 10, 11)
            registrar_lancamento_caixa("SAIDA", f"{objeto} ({credor})", valor, forma, ciclo_id=c_id, categoria=categoria)
            registrar_log("DESPESA_LANCADA", "FINANCEIRO", objeto, {"credor": credor, "valor": valor, "forma": forma, "caixa": c_id})
            registrar_log("SAIDA_CAIXA", "FINANCEIRO", objeto, {"credor": credor, "valor": valor, "forma": forma, "caixa": c_id})

            # 2. Interface já sincronizada por registrar_lancamento_caixa

            # 3. Insere no histórico visual (lista_despesas)
            if 'lista_despesas' in globals():
                data_tela = datetime.now().strftime("%d/%m/%Y %H:%M")
                lista_despesas.insert("", 0, values=(objeto, credor, f"R$ {valor:.2f}", data_tela))
            
            # Limpeza
            e_des_obj.delete(0, tk.END)
            e_des_credor.delete(0, tk.END)
            e_des_valor.delete(0, tk.END)
            cb_des_categoria.set("")
            janela_pag.destroy()
            messagebox.showinfo("Sucesso", "Despesa lançada!")
            
        except Exception as e:
            try:
                conn.rollback()
            except Exception:
                pass
            messagebox.showerror("Erro", f"Erro ao gravar: {e}")

    ttk.Button(janela_pag, text="💵 DINHEIRO", width=25, command=lambda: confirmar_despesa("Dinheiro")).pack(pady=5)
    ttk.Button(janela_pag, text="📱 PIX", width=25, command=lambda: confirmar_despesa("Pix")).pack(pady=5)

def excluir_receita():
    sel = lista_receitas.selection()
    if not sel:
        return

    # Pega os valores da linha selecionada na tela
    valores = lista_receitas.item(sel)["values"]
    # cols: Pedido, Origem, Forma, Valor, Data
    origem = valores[1]
    valor_str = str(valores[3]).replace("R$", "").replace(".", "").replace(",", ".").strip()
    valor = float(valor_str)
    data_lanc = valores[4]

    if messagebox.askyesno("Confirmar", f"Excluir permanentemente '{origem}'?"):
        try:
            # REGRA 8: nunca DELETE em caixa. Localiza o lançamento original
            # e gera um ESTORNO rastreável (com log), preservando o histórico.
            data_db = datetime.strptime(data_lanc, "%d/%m/%Y %H:%M").strftime("%Y-%m-%d %H:%M")
            cursor.execute("""
                SELECT id, pedido_id FROM caixa
                WHERE tipo='ENTRADA' AND descricao=? AND valor=? AND data LIKE ?
                  AND (estornado_de IS NULL)
                ORDER BY id DESC LIMIT 1
            """, (origem, valor, f"{data_db}%"))
            row = cursor.fetchone()
            if not row:
                messagebox.showwarning("Aviso", "Lançamento original não encontrado no caixa (nada a estornar).")
                return

            # Receita de um PEDIDO: o estorno tira o dinheiro do caixa, mas o pedido
            # continua marcado como pago. Avisa para o operador nao achar que a venda
            # foi desfeita (para isso, use CANCELAR PEDIDO no Histórico).
            if row[1] is not None:
                if not messagebox.askyesno(
                    "Receita de pedido",
                    f"Este lançamento é o pagamento do Pedido #{row[1]}.\n\n"
                    "Excluir a receita tira o valor do caixa, mas o pedido continua "
                    "marcado como PAGO.\n\n"
                    "Se a intenção é desfazer a venda, cancele o pedido (botão direito > "
                    "CANCELAR PEDIDO).\n\nExcluir somente a receita mesmo assim?"
                ):
                    return

            estornar_lancamento_caixa(row[0], motivo="Exclusão de receita pela tela de Histórico")

            # ATUALIZA O SALDO E A JANELA DE HISTÓRICO
            lista_receitas.delete(sel)
            sincronizar_financeiro()
            messagebox.showinfo("Sucesso", "Receita estornada com sucesso! (histórico preservado)")
        except Exception as e:
            messagebox.showerror("Erro", f"Erro ao excluir: {e}")

def excluir_despesa():
    item_selecionado = lista_despesas.selection()
    if not item_selecionado:
        messagebox.showwarning("Aviso", "Selecione uma despesa na lista para excluir!")
        return

    if not messagebox.askyesno("Confirmar", "Deseja excluir esta despesa? O valor retornará ao saldo."):
        return

    valores = lista_despesas.item(item_selecionado)['values']
    # No seu sis.py: valores[0]=Objeto, [1]=Credor, [2]=Valor, [3]=Data
    objeto_credor = f"{valores[0]} ({valores[1]})"
    valor_str = str(valores[2]).replace("R$ ", "").replace(",", ".")
    data_tela = valores[3]

    try:
        # Converter data da tela (DD/MM/YYYY HH:MM) para o formato do banco (YYYY-MM-DD HH:MM:SS)
        data_dt = datetime.strptime(data_tela, "%d/%m/%Y %H:%M")
        data_db_inicio = data_dt.strftime("%Y-%m-%d %H:%M:00")
        data_db_fim = data_dt.strftime("%Y-%m-%d %H:%M:59")

        # REGRA 8: nunca DELETE em caixa. Localiza o lançamento original
        # e gera um ESTORNO rastreável (com log), preservando o histórico.
        cursor.execute("""
            SELECT id FROM caixa
            WHERE tipo='SAIDA'
              AND (descricao=? OR descricao LIKE ?)
              AND data BETWEEN ? AND ?
              AND (estornado_de IS NULL)
            ORDER BY id DESC LIMIT 1
        """, (objeto_credor, f"%{valores[0]}%", data_db_inicio, data_db_fim))
        row = cursor.fetchone()
        if not row:
            messagebox.showwarning("Aviso", "Lançamento original não encontrado no caixa (nada a estornar).")
            return

        # Retira a despesa do relatório de Despesas (sem commit; o commit do
        # estorno grava os dois juntos).
        remover_despesa_relatorio_do_lancamento(row[0])

        estornar_lancamento_caixa(row[0], motivo="Exclusão de despesa pela tela de Histórico")

        # REMOVER DA TELA
        lista_despesas.delete(item_selecionado)

        # RECALCULAR SALDOS a partir do banco
        sincronizar_financeiro()

        messagebox.showinfo("Sucesso", "Despesa estornada com sucesso! (histórico preservado)")

    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        messagebox.showerror("Erro", f"Erro ao processar exclusão: {e}")

# Função auxiliar para converter a data da lista de volta para o formato do banco
def data_agora_para_db(data_tela):
    # Converte '15/05/2023 14:30' para '2023-05-15 14:30:00' (ajuste conforme seu formato)
    try:
        d = datetime.strptime(data_tela, "%d/%m/%Y %H:%M")
        return d.strftime("%Y-%m-%d %H:%M:%S")
    except:
        return data_tela # Retorna a original se falhar


# =====================================================
# 🟢 AÇÕES + EXTRATO ÚNICO DO CAIXA  (SOMENTE APARÊNCIA)
# =====================================================
# As listas "lista_receitas" e "lista_despesas" CONTINUAM existindo (ocultas):
# todo o resto do sistema (carregar_receitas_caixa, estornos, baixa de contas,
# salários, notas, etc.) grava nelas exatamente como antes.
# O que o usuário vê é UM ÚNICO extrato (tree_extrato_caixa), montado a partir
# das duas. As funções adicionar_receita / adicionar_despesa / excluir_receita /
# excluir_despesa NÃO foram alteradas: os botões e janelas novos apenas as chamam.

_extrato_map = {}                      # iid do extrato -> ("R"/"D", iid na lista oculta)
_extrato_refresh_id = [None]
_filtro_extrato_caixa = {"tipo": "todos"}


def _atualizar_extrato_caixa_agendado():
    _extrato_refresh_id[0] = None
    _atualizar_extrato_caixa()


def _agendar_atualizar_extrato(*_args):
    """Agrupa várias mudanças seguidas nas listas ocultas em UMA atualização do extrato."""
    if _extrato_refresh_id[0] is not None:
        return
    try:
        _extrato_refresh_id[0] = root.after(40, _atualizar_extrato_caixa_agendado)
    except Exception:
        _extrato_refresh_id[0] = None


def _espelhar_mudancas_no_extrato(tv):
    """Faz a lista oculta avisar o extrato quando alguém inserir/apagar linhas nela."""
    _insert_original = tv.insert
    _delete_original = tv.delete

    def _insert(*args, **kwargs):
        resultado = _insert_original(*args, **kwargs)
        _agendar_atualizar_extrato()
        return resultado

    def _delete(*items):
        _delete_original(*items)
        _agendar_atualizar_extrato()

    tv.insert = _insert
    tv.delete = _delete


def _brl_para_float(texto):
    """'R$ 1.234,56' / 'R$ 12.50' / '- R$ 3,00' -> float (somente para exibição)."""
    t = str(texto or "").replace("R$", "").replace("−", "-").strip()
    negativo = t.startswith("-")
    t = t.replace("-", "").replace("+", "").replace(" ", "")
    if "," in t:
        t = t.replace(".", "").replace(",", ".")
    try:
        v = float(t)
    except ValueError:
        v = 0.0
    return -v if negativo else v


def _data_para_datetime(texto):
    try:
        return datetime.strptime(str(texto)[:16], "%d/%m/%Y %H:%M")
    except Exception:
        return datetime.min


def _info_saidas_caixa():
    """Lê (forma, categoria) das saídas do caixa aberto SÓ PARA EXIBIR no extrato.
    Leitura apenas, em conexão própria e curta. Se algo falhar, devolve vazio."""
    info = {}
    ciclo = globals().get("ciclo_caixa_aberto") or {}
    if not ciclo.get("id"):
        return info
    conn_leitura = None
    try:
        conn_leitura = abrir_conexao_curta()
        parametros = (ciclo.get("id"), ciclo.get("abertura", ""))
        filtro = "tipo='SAIDA' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))"
        try:
            linhas = conn_leitura.execute(
                "SELECT data, valor, pagamento, categoria, descricao FROM caixa WHERE " + filtro,
                parametros
            ).fetchall()
        except Exception:
            linhas = [
                (d, v, p, None, ds) for d, v, p, ds in conn_leitura.execute(
                    "SELECT data, valor, pagamento, descricao FROM caixa WHERE " + filtro,
                    parametros
                ).fetchall()
            ]
        for data_db, valor, pagamento, categoria, descricao in linhas:
            chave = (round(float(valor or 0), 2), str(data_db or "")[:16])
            info.setdefault(chave, []).append((pagamento, categoria, str(descricao or "")))
    except Exception:
        pass
    finally:
        if conn_leitura is not None:
            try:
                conn_leitura.close()
            except Exception:
                pass
    return info


def _atualizar_texto_selecao_extrato(_event=None):
    try:
        sel = tree_extrato_caixa.selection()
        if sel:
            v = tree_extrato_caixa.item(sel[0], "values")
            lbl_sel_extrato.config(text=f"Selecionado: {v[2]}  •  {v[5]}  •  {v[0]}")
        else:
            lbl_sel_extrato.config(text="Selecione um lançamento para excluir")
    except Exception:
        pass


def _atualizar_extrato_caixa():
    """Reconstrói o extrato único (mais recente primeiro) a partir das listas ocultas."""
    tv = globals().get("tree_extrato_caixa")
    if tv is None:
        return
    try:
        if not tv.winfo_exists():
            return

        sel_antes = None
        sel = tv.selection()
        if sel and sel[0] in _extrato_map:
            sel_antes = _extrato_map[sel[0]]

        tv_rec = globals().get("lista_receitas")
        tv_des = globals().get("lista_despesas")
        filtro = _filtro_extrato_caixa["tipo"]

        linhas = []   # (datetime, ordem, chave, valores, tag)
        ordem = 0

        # ---------- RECEITAS ----------
        if tv_rec is not None and filtro in ("todos", "receitas"):
            for iid in tv_rec.get_children(""):
                tags = tv_rec.item(iid, "tags")
                vals = tv_rec.item(iid, "values")
                if not vals or len(vals) < 5:
                    continue
                if not tags:
                    # Linha colocada direto por adicionar_receita (a mesma já veio
                    # do banco via carregar_receitas_caixa): evita aparecer em duplicidade.
                    continue
                pedido, origem, forma, valor_txt, data_txt = (str(v) for v in vals[:5])
                if "cancelado" in tags:
                    tipo_txt, tag, valor_exib = "Cancelado", "extrato_cancelado", valor_txt
                    categoria = "Pedido" if pedido.startswith("#") else ""
                else:
                    tipo_txt, tag, valor_exib = "Receita", "extrato_receita", "+ " + valor_txt
                    categoria = "Pedido" if pedido.startswith("#") else "Avulsa"
                linhas.append((
                    _data_para_datetime(data_txt), ordem, ("R", iid),
                    (data_txt, tipo_txt, origem.strip(), forma, categoria, valor_exib), tag
                ))
                ordem += 1

        # ---------- DESPESAS ----------
        if tv_des is not None and filtro in ("todos", "despesas"):
            itens_des = tv_des.get_children("")
            info = _info_saidas_caixa() if itens_des else {}
            for iid in itens_des:
                vals = tv_des.item(iid, "values")
                if not vals or len(vals) < 4:
                    continue
                objeto, credor, valor_txt, data_txt = (str(v) for v in vals[:4])
                dt = _data_para_datetime(data_txt)
                valor_f = _brl_para_float(valor_txt)
                forma, categoria = "—", "—"
                try:
                    chave_db = (round(valor_f, 2), dt.strftime("%Y-%m-%d %H:%M"))
                except Exception:
                    chave_db = None
                candidatos = info.get(chave_db, []) if chave_db else []
                if candidatos:
                    escolhido = next(
                        (c for c in candidatos if objeto and objeto.lower() in c[2].lower()),
                        candidatos[0]
                    )
                    forma = escolhido[0] or "—"
                    categoria = escolhido[1] or "—"
                desc = f"{objeto} ({credor})" if credor else objeto
                linhas.append((
                    dt, ordem, ("D", iid),
                    (data_txt, "Despesa", desc, forma, categoria, "− " + _fmt_brl(abs(valor_f))),
                    "extrato_despesa"
                ))
                ordem += 1

        linhas.sort(key=lambda x: (x[0], x[1]), reverse=True)

        tv.delete(*tv.get_children(""))
        _extrato_map.clear()
        nova_sel = None
        for _dt, _ordem, chave, valores, tag in linhas:
            novo = tv.insert("", "end", values=valores, tags=(tag,))
            _extrato_map[novo] = chave
            if sel_antes is not None and chave == sel_antes:
                nova_sel = novo
        if nova_sel:
            tv.selection_set(nova_sel)
            tv.focus(nova_sel)
            tv.see(nova_sel)
        _atualizar_texto_selecao_extrato()
    except Exception as e:
        print(f"Erro ao atualizar o extrato do caixa: {e}")


def _estilizar_filtros_extrato():
    tipo = _filtro_extrato_caixa["tipo"]
    for t, botao in (("todos", btn_filtro_todos), ("receitas", btn_filtro_receitas), ("despesas", btn_filtro_despesas)):
        try:
            botao.configure(bootstyle=("primary" if t == tipo else "secondary-outline"))
        except Exception:
            pass


def _definir_filtro_extrato(tipo):
    _filtro_extrato_caixa["tipo"] = tipo
    _estilizar_filtros_extrato()
    _atualizar_extrato_caixa()


def excluir_lancamento_selecionado():
    """Um único botão Excluir: aplica a função original de acordo com o tipo da linha."""
    sel = tree_extrato_caixa.selection()
    if not sel:
        messagebox.showwarning("Aviso", "Selecione um lançamento na lista para excluir!")
        return
    tipo, iid_real = _extrato_map.get(sel[0], (None, None))
    if tipo == "R":
        lista_receitas.selection_set(iid_real)
        excluir_receita()
    elif tipo == "D":
        lista_despesas.selection_set(iid_real)
        excluir_despesa()


# ---------------- JANELAS DE LANÇAMENTO ----------------
def _centralizar_dialogo(dlg):
    try:
        dlg.update_idletasks()
        w, h = dlg.winfo_reqwidth(), dlg.winfo_reqheight()
        x = root.winfo_rootx() + max(0, (root.winfo_width() - w) // 2)
        y = root.winfo_rooty() + max(0, (root.winfo_height() - h) // 3)
        dlg.geometry(f"+{x}+{y}")
    except Exception:
        pass


def _seguir_dialogo_apos_pagamento(dlg, antes, campos):
    """A função original abre a janelinha 'Forma de Pagamento'. Enquanto ela estiver
    aberta o formulário fica escondido; ao terminar, se o lançamento foi feito
    (campos vazios) o formulário fecha; se o usuário cancelou, ele volta."""
    novos = [w for w in root.winfo_children() if w not in antes and isinstance(w, tk.Toplevel)]
    if not novos:
        return   # validação falhou: a mensagem já foi exibida e o formulário continua aberto
    janela_pag = novos[0]
    dlg.withdraw()

    def _ao_fechar_pagamento(evento):
        if evento.widget is not janela_pag:
            return
        try:
            if not dlg.winfo_exists():
                return
            if any(str(c.get()).strip() for c in campos):
                dlg.deiconify()
                dlg.lift()
                try:
                    dlg.grab_set()
                except Exception:
                    pass
            else:
                dlg.destroy()
        except Exception:
            pass

    janela_pag.bind("<Destroy>", _ao_fechar_pagamento, add="+")


def _novo_dialogo_caixa(titulo):
    dlg = tk.Toplevel(root)
    dlg.title(titulo)
    dlg.transient(root)
    dlg.resizable(False, False)
    corpo = ttk.Frame(dlg, padding=20)
    corpo.pack(fill="both", expand=True)
    return dlg, corpo


def _finalizar_dialogo_caixa(dlg, confirmar, primeiro_campo):
    dlg.bind("<Return>", confirmar)
    dlg.bind("<Escape>", lambda _e: dlg.destroy())
    _centralizar_dialogo(dlg)
    try:
        dlg.grab_set()
    except Exception:
        pass
    primeiro_campo.focus_set()


