def atualizar_totais_receita():
    """
    Recalcula totais por forma de pagamento no rodapé.
    Conta APENAS linhas com tag 'normal' (não canceladas).
    Assim o rodapé bate com o saldo exibido no topo.
    """
    totais = {}
    for iid in lista_receitas.get_children():
        tags = lista_receitas.item(iid, "tags")
        if "cancelado" in tags:
            continue   # ignora cancelados e linhas de estorno
        vals = lista_receitas.item(iid, "values")
        # cols: Pedido, Origem, Forma, Valor, Data
        forma = str(vals[2])
        try:
            val = float(str(vals[3]).replace("R$", "").replace(".", "").replace(",", ".").strip())
        except:
            val = 0.0
        totais[forma] = totais.get(forma, 0.0) + val

    def fmt(v):
        return f"R$ {v:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    lbl_tot_rec_din.config(text=f"💵 Dinheiro: {fmt(totais.get('Dinheiro', 0.0))}")
    lbl_tot_rec_pix.config(text=f"📱 Pix: {fmt(totais.get('Pix', 0.0))}")
    lbl_tot_rec_cart.config(text=f"💳 Cartão: {fmt(totais.get('Cartão', 0.0) + totais.get('Cartao', 0.0))}")

def carregar_receitas_caixa():
    """
    Recarrega o histórico de receitas do banco de dados.
    - Entradas normais: aparecem normalmente
    - Cancelamentos: aparecem em vermelho/tachado como CANCELADO
    - Os totais do rodapé somam SOMENTE as entradas líquidas (entrada - cancelamento)
    - O saldo exibido no topo (atualizar_saldo) bate com esses totais
    """
    lista_receitas.delete(*lista_receitas.get_children())

    # Configura tags visuais (cancelado em vermelho com itálico)
    lista_receitas.tag_configure("cancelado", foreground="#cc0000", font=("Segoe UI", 8, "italic"))
    lista_receitas.tag_configure("normal",    foreground="#1a5c2e")

    if not ciclo_caixa_aberto.get("id"):
        atualizar_totais_receita()
        return

    abertura = ciclo_caixa_aberto.get("abertura", "")

    # 1. Busca ENTRADAS da sessão
    cursor.execute("""
        SELECT descricao, pagamento, valor, data
        FROM caixa
        WHERE tipo = 'ENTRADA'
          AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))
        ORDER BY data ASC
    """, (ciclo_caixa_aberto.get("id"), abertura,))
    entradas = cursor.fetchall()

    # 2. Busca SAIDAS de cancelamento da sessão (para marcar entradas como canceladas)
    cursor.execute("""
        SELECT descricao, valor
        FROM caixa
        WHERE tipo = 'SAIDA'
          AND descricao LIKE 'Cancelamento Pedido #%'
          AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))
    """, (ciclo_caixa_aberto.get("id"), abertura,))
    # Monta set dos pedido_ids que foram cancelados
    cancelados_ids = set()
    for desc_s, _ in cursor.fetchall():
        try:
            num = desc_s.replace("Cancelamento Pedido #", "").strip()
            cancelados_ids.add(int(num))
        except:
            pass

    def fmt_val(v):
        return f"R$ {v:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def fmt_data(data_db):
        try:
            return datetime.strptime(data_db, "%Y-%m-%d %H:%M:%S").strftime("%d/%m/%Y %H:%M")
        except:
            return str(data_db)[:16]

    for desc, forma, valor, data_db in entradas:
        # Detecta número do pedido
        pedido_num = None
        if "Pedido #" in str(desc):
            try:
                pedido_num = int(str(desc).replace("Pedido #", "").strip())
                num_display = f"#{pedido_num}"
            except:
                num_display = "-"
        else:
            num_display = "Manual"

        eh_cancelado = (pedido_num is not None and pedido_num in cancelados_ids)

        if eh_cancelado:
            origem_display = f"❌ CANCELADO — {desc}"
            tag = "cancelado"
        else:
            origem_display = str(desc)
            tag = "normal"

        lista_receitas.insert("", "end",
            values=(num_display, origem_display, str(forma), fmt_val(valor), fmt_data(data_db)),
            tags=(tag,)
        )

        # Também exibe a linha de cancelamento como informação
        if eh_cancelado:
            lista_receitas.insert("", "end",
                values=("", f"  ↩ Estorno debitado", str(forma), f"- {fmt_val(valor)}", fmt_data(data_db)),
                tags=("cancelado",)
            )

    atualizar_totais_receita()


