def excluir_produto_selecionado():
    # 1. Tenta pegar a seleção de ambas as tabelas (Insumos ou Produtos)
    selecionado_ins = tabela_insumos.selection()
    selecionado_pro = tabela_produtos.selection()
    
    item_id = None
    tabela_ativa = None
    
    if selecionado_ins:
        item_id = selecionado_ins
        tabela_ativa = tabela_insumos
    elif selecionado_pro:
        item_id = selecionado_pro
        tabela_ativa = tabela_produtos
    else:
        messagebox.showwarning("Aviso", "Selecione um item na tabela (Insumos ou Produtos) para excluir!")
        return

    # 2. Extrai os dados do item selecionado
    valores = tabela_ativa.item(item_id, "values")
    codigo = valores[0]
    nome_produto = valores[1]

    # 3. VERIFICAÇÃO DE SEGURANÇA: O produto já foi vendido/usado em algum pedido?
    cursor.execute("SELECT COUNT(*) FROM itens_pedido WHERE codigo=?", (codigo,))
    total_vendas = cursor.fetchone()[0]

    if total_vendas > 0:
        msg_vendas = f"\n\n⚠️ ATENÇÃO: Este item já foi vendido {total_vendas} vezes!\nExcluí-lo pode afetar relatórios antigos de vendas."
    else:
        msg_vendas = ""

    # 4. Confirmação com o usuário
    if messagebox.askyesno("Confirmação de Exclusão", 
                           f"Tem certeza que deseja excluir permanentemente:\n'{nome_produto}'?{msg_vendas}"):
        try:
            # A. Remove primeiro das Fichas Técnicas (evita erro de restrição de chave)
            cursor.execute("DELETE FROM fichas_tecnicas WHERE produto_pai_codigo=? OR insumo_codigo=?", (codigo, codigo))
            
            # B. Remove do Estoque
            cursor.execute("DELETE FROM estoque WHERE codigo=?", (codigo,))
            
            conn.commit()
            registrar_log("ESTOQUE_EXCLUIDO", "ESTOQUE", codigo, {"produto": nome_produto, "vendas_registradas": total_vendas})
            
            # C. Atualiza todas as visualizações do sistema
            listar_estoque()
            if 'carregar_produtos' in globals(): carregar_produtos()
            carregar_produtos_add()
            
            messagebox.showinfo("Sucesso", f"O item '{nome_produto}' foi removido do sistema.")
            
        except Exception as e:
            messagebox.showerror("Erro", f"Não foi possível excluir o item: {e}")




