import threading
import time

# --- VARIAVEIS DE CONTROLE ---
autocompletando = False
lista_produtos_original = []

from pathlib import Path

# Define o caminho base como a pasta onde o script está
PATH_SISTEMA = Path(__file__).parent.resolve()

# Cria o caminho da subpasta
PASTA_ENTRADA = PATH_SISTEMA / 'pedidos_entrada'

# Garante que a pasta exista para não dar erro
if not os.path.exists(PASTA_ENTRADA):
    os.makedirs(PASTA_ENTRADA)

# 🔵 FUNÇÃO DE MONITORAMENTO (O "RADAR" DO BOT)
def monitorar_pedidos_novos():
    while True:
        try:
            # Verifica se a pasta existe antes de listar
            if not os.path.exists(PASTA_ENTRADA):
                os.makedirs(PASTA_ENTRADA)

            arquivos = [f for f in os.listdir(PASTA_ENTRADA) if f.endswith(".json")]
            
            for arquivo in arquivos:
                caminho_arquivo = os.path.join(PASTA_ENTRADA, arquivo)
                
                # Pequena pausa para garantir que o arquivo terminou de ser escrito pelo Node
                time.sleep(0.5) 

                with open(caminho_arquivo, 'r', encoding='utf-8') as f:
                    dados = json.load(f)
                dados = normalizar_pedido_entrada(dados)

                cliente = dados.get('cliente', 'BOT').upper()
                telefone = str(dados.get("telefone", "")).strip()
                pagamento = dados.get('pagamento', 'Pendente')
                observacao = anexar_contato_whatsapp_observacao(
                    dados.get('obs', ''),
                    telefone,
                    dados.get("jid", ""),
                )
                itens = dados.get('itens', [])
                data_agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

                # 1. cria pedido (cabeçalho)
                cursor.execute("""
                    INSERT INTO pedidos (
                        data,
                        cliente,
                        endereco,
                        pagamento,
                        observacao
                    )
                    VALUES (?, ?, ?, ?, ?)
                """, (
                    data_agora,
                    cliente,
                    dados.get("endereco", ""),
                    pagamento,
                    observacao
                ))
                
                pedido_id = cursor.lastrowid
                
                # 2. insere itens corretamente
                for item in itens:
                    cod_id = item.get('codigo') or item.get('nome_id')
                    cod_id = str(cod_id or "").split(" - ")[0].strip()
                    qtd = item.get('qtd', 1)
                
                    cursor.execute("""
                        INSERT INTO itens_pedido (pedido_id, codigo, quantidade)
                        VALUES (?, ?, ?)
                    """, (pedido_id, cod_id, qtd))
                
                # SALVA O TELEFONE NO CADASTRO LOCAL
                if cliente:
                    salvar_cliente(
                        cliente,
                        dados.get("endereco", ""),
                        telefone
                    )
                
                conn.commit()
                
                
                # 🔔 ALERTA SONORO
                root.after(0, lambda: winsound.PlaySound("SystemNotification", winsound.SND_ALIAS))
                
                # Deleta o arquivo IMEDIATAMENTE após salvar no banco
                os.remove(caminho_arquivo)
                
                print(f"✅ Pedido de {cliente} processado!")
                

                # --- INTEGRAÇÃO COM A INTERFACE ---
                # Usamos root.after para atualizar a tela de forma segura
                if 'atualizar_lista_pedidos' in globals():
                    root.after(0, atualizar_lista_pedidos)

                # 3. Impressão Automática
                if v_auto_print.get():
                    print(f"🖨️ Enviando para impressora...")
                    # Se tiver a função de imprimir pronta, chame-a aqui:
                    # root.after(0, lambda: sua_funcao_imprimir(cliente))

        except Exception as e:
            print(f"Erro no monitor de pedidos: {e}")
        
        time.sleep(5)

# ================= INTEGRACAO COM APP DE ENTREGAS =================
def endereco_e_retirada(endereco):
    valor = (endereco or "").strip().lower()
    termos_retirada = ["retirada", "retirar", "balcao", "balc\u00e3o", "buscar", "cliente retira"]
    return any(termo in valor for termo in termos_retirada)


def salvar_json_atomico(caminho, dados):
    os.makedirs(os.path.dirname(caminho), exist_ok=True)
    temporario = f"{caminho}.tmp"
    with open(temporario, "w", encoding="utf-8") as arquivo:
        json.dump(dados, arquivo, indent=4, ensure_ascii=False)
    os.replace(temporario, caminho)


def mover_arquivo_unico(origem, destino_dir):
    os.makedirs(destino_dir, exist_ok=True)
    nome = os.path.basename(origem)
    destino = os.path.join(destino_dir, nome)
    if os.path.exists(destino):
        base, ext = os.path.splitext(nome)
        sufixo = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
        destino = os.path.join(destino_dir, f"{base}_{sufixo}{ext}")
    os.replace(origem, destino)
    return destino

def enviar_pedido_para_entrega(pedido_id, cliente, endereco, pagamento, total, observacao, itens, telefone=""):
    if endereco_e_retirada(endereco):
        print(f"[ENTREGAS] Pedido #{pedido_id} e retirada. Nao enviado ao app.")
        return

    itens_app = []
    for codigo, nome, qtd, custo, venda in itens:
        itens_app.append({
            "codigo": codigo,
            "nome": nome,
            "qtd": qtd,
            "valor_unitario": venda,
            "subtotal": qtd * venda,
        })

    # Telefone DIGITADO no pedido (o certo, mesmo com cliente homônimo). Só se vier vazio
    # procura pelo nome (base nova primeiro; homônimo = não chuta; depois JSON antigo).
    telefone = str(telefone or "").strip()
    if not telefone:
        telefone = telefone_cadastrado_por_nome(cliente)

    pedido_app = {
        "id": str(pedido_id),
        "cliente": cliente,
        "nome": cliente,
        "endereco": endereco,
        "telefone": telefone,   # Mantido por compatibilidade local
        "fone": telefone,       # CORREÇÃO: Adicionado para o servidor.py e Firebase aceitarem!
        "valor": round(float(total or 0), 2),
        "forma_pagamento": pagamento,
        "pagamento": pagamento,
        "observacao": observacao,
        "itens": itens_app,
        "motoboy": "motoboy_teste",
        "status": "Pendente",
        "recebido_em": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }

    caminho = os.path.join(PASTA_ENTREGAS_NOVOS, f"pedido_{pedido_id}.json")
    salvar_json_atomico(caminho, pedido_app)
    registrar_log("PEDIDO_ENVIADO_ENTREGA", "ENTREGAS", pedido_id, {"cliente": cliente, "endereco": endereco, "pagamento": pagamento, "total": total})
    print(f"[ENTREGAS] Pedido #{pedido_id} enviado para o app com o telefone: {telefone}")

def forma_pagamento_baixa(valor):
    forma = str(valor or "").strip()
    mapa = {
        "pix": "Pix",
        "dinheiro": "Dinheiro",
        "cartao": "Cart\u00e3o",
        "cart\u00e3o": "Cart\u00e3o",
        "credito": "Cart\u00e3o",
        "cr\u00e9dito": "Cart\u00e3o",
        "debito": "Cart\u00e3o",
        "d\u00e9bito": "Cart\u00e3o",
    }
    return mapa.get(forma.lower(), forma)


def baixa_sem_pagamento(forma):
    valor = str(forma or "").strip().lower()
    return valor in ["", "pendente", "nao informado", "n\u00e3o informado", "descarte"]


def baixa_pix_confirmada_mercado_pago(dados, forma):
    return (
        str(forma or "").strip().lower() == "pix"
        and str(dados.get("origem_confirmacao") or "").strip().lower() == "mercado_pago"
        and bool(str(dados.get("mercado_pago_payment_id") or "").strip())
    )


class PedidoAindaNaoGravadoErro(ValueError):
    """Baixa chegou antes do pedido existir no SQLite do sis.py: pode ser so
    questao de timing, entao nao vai direto para erros/ (ver
    processar_baixas_entrega_agendadas)."""


BAIXA_ESPERA_PEDIDO_SEGUNDOS = 600   # ate 10 min esperando o pedido aparecer
BAIXA_REPETIR_A_CADA = 15            # tenta de novo a cada 15s
baixas_entrega_espera = {}           # caminho -> {"inicio": t, "proxima": t}


BAIXA_ENTREGA_REAVISAR_A_CADA = 60   # segundos entre avisos "caixa fechado"
baixas_entrega_adiadas = {}          # caminho -> instante do ultimo aviso (baixa aguardando o caixa abrir)


def _numero_baixa(valor):
    """Converte um numero vindo do JSON da baixa ('12,50', '1.234,50', 12.5).
    Retorna None se ausente ou invalido (=> comportamento antigo: quita o restante)."""
    if valor is None or isinstance(valor, bool):
        return None
    try:
        if isinstance(valor, str):
            texto = valor.replace("R$", "").replace(" ", "").strip()
            if not texto:
                return None
            if "," in texto:
                texto = texto.replace(".", "").replace(",", ".")
            valor = texto
        numero = float(valor)
    except (TypeError, ValueError):
        return None
    if numero != numero or numero in (float("inf"), float("-inf")):
        return None
    return round(numero, 2)


def _id_baixa_estavel(dados, caminho_arquivo, pedido_id, forma_padrao, valor_recebido):
    """Chave de idempotencia da baixa: `id_baixa` do JSON; senao, o payment_id do
    Mercado Pago; senao, um hash ESTAVEL (pedido + forma + valor_recebido +
    carimbo de data do JSON ou, se nao houver, o nome do arquivo)."""
    import hashlib
    explicito = str(dados.get("id_baixa") or "").strip()
    if explicito:
        return explicito[:120]
    payment_id = str(dados.get("mercado_pago_payment_id") or "").strip()
    if payment_id:
        return f"mp-{payment_id}"
    carimbo = ""
    for campo in ("timestamp", "concluido_em", "data_conclusao", "data_hora"):
        valor = dados.get(campo)
        if valor not in (None, ""):
            carimbo = str(valor)
            break
    if not carimbo:
        carimbo = os.path.basename(caminho_arquivo)
    valor_txt = "" if valor_recebido is None else f"{valor_recebido:.2f}"
    base = f"{pedido_id}|{forma_padrao}|{valor_txt}|{carimbo}"
    return "auto-" + hashlib.sha1(base.encode("utf-8")).hexdigest()[:32]


def aplicar_baixa_entrega(caminho_arquivo):
    """
    Baixa do app de entrega. Roda na thread principal (processar_baixas_entrega_agendadas).
    Retorna: "OK", "DUPLICADA", "IGNORADA" ou "ADIADA" (caixa fechado: o arquivo
    permanece na pasta e entra sozinho quando o caixa for aberto).

    Dinheiro aceita `valor_recebido` OPCIONAL (quanto do PEDIDO foi pago em
    dinheiro, sem troco): ausente/invalido => quita o restante (apps antigos).
    UPDATE pedidos + INSERT no caixa + idempotencia (baixas_entrega_aplicadas)
    + log ficam na MESMA transacao (BEGIN IMMEDIATE), com um unico commit.
    """
    # Caixa fechado ja avisado ha pouco: nao relê o arquivo nem dorme de novo.
    ultimo_aviso = baixas_entrega_adiadas.get(caminho_arquivo)
    if (ultimo_aviso is not None and not ciclo_caixa_aberto.get("id")
            and time.time() - ultimo_aviso < BAIXA_ENTREGA_REAVISAR_A_CADA):
        return "ADIADA"

    if ultimo_aviso is None:
        time.sleep(0.2)  # primeira leitura: da tempo do app terminar de gravar o arquivo
    with open(caminho_arquivo, "r", encoding="utf-8") as arquivo:
        dados = json.load(arquivo)

    pedido_id = str(dados.get("id") or dados.get("id_pedido") or "").strip()
    forma = forma_pagamento_baixa(
        dados.get("forma_pagamento_real")
        or dados.get("forma_pagamento")
    )

    if not pedido_id:
        raise ValueError("Baixa sem id do pedido")

    # O servidor_embutido manda pagamento parcial como "Dinheiro Parcial" (com
    # valor_recebido_dinheiro=0). Se veio `valor_recebido` valido (> 0), e um
    # parcial em DINHEIRO e passa a ser aplicado. Sem `valor_recebido` (servidor
    # antigo) continua ignorado, como sempre foi.
    if forma.strip().lower() == "dinheiro parcial":
        _vr_parcial = _numero_baixa(dados.get("valor_recebido"))
        if _vr_parcial is not None and _vr_parcial > VALOR_TOLERANCIA:
            forma = "Dinheiro"

    # 🔒 SOMENTE DINHEIRO PODE ALTERAR O FINANCEIRO
    eh_pix_mp = baixa_pix_confirmada_mercado_pago(dados, forma)
    if forma.lower() != "dinheiro" and not eh_pix_mp:
        mover_arquivo_unico(
            caminho_arquivo,
            PASTA_ENTREGAS_BAIXAS_PROCESSADAS
        )
        baixas_entrega_adiadas.pop(caminho_arquivo, None)
        registrar_log("PEDIDO_CONCLUIDO", "ENTREGAS", pedido_id, {"forma": forma, "financeiro": "nao_alterado"})
        registrar_log("PEDIDO_BAIXADO", "ENTREGAS", pedido_id, {"forma": forma, "financeiro": "nao_alterado"})

        print(
            f"[ENTREGAS] Pedido #{pedido_id} entregue em "
            f"{forma or 'sem pagamento'}. Nenhuma alteração financeira."
        )

        return "OK"

    try:
        pedido_id_db = int(pedido_id)
    except ValueError:
        pedido_id_db = pedido_id  # comportamento antigo: deixa o SQLite comparar o texto

    forma_padrao = padronizar_forma_pagamento(forma)

    # valor_recebido so vale para DINHEIRO. Pix confirmado pelo Mercado Pago e
    # tudo-ou-nada: quita o restante.
    valor_recebido = None
    if not eh_pix_mp:
        bruto = dados.get("valor_recebido")
        valor_recebido = _numero_baixa(bruto)
        if valor_recebido is not None and valor_recebido <= VALOR_TOLERANCIA:
            # Pagamento zero (ou negativo) informado explicitamente NAO e quitacao:
            # nada e lancado no caixa e o pedido continua como esta.
            mover_arquivo_unico(caminho_arquivo, PASTA_ENTREGAS_BAIXAS_PROCESSADAS)
            baixas_entrega_adiadas.pop(caminho_arquivo, None)
            registrar_log("BAIXA_ENTREGA_VALOR_ZERO", "ENTREGAS", pedido_id,
                          {"valor_recebido": valor_recebido, "forma": forma,
                           "obs": "valor_recebido <= 0: baixa ignorada, nada lancado no caixa."})
            print(f"[ENTREGAS] Pedido #{pedido_id}: valor_recebido={valor_recebido:.2f} "
                  f"(zero/negativo). Baixa ignorada; nenhum lancamento no caixa.")
            return "IGNORADA"
        if valor_recebido is None and bruto not in (None, ""):
            print(f"[ENTREGAS] Pedido #{pedido_id}: valor_recebido invalido ({bruto!r}); "
                  f"mantendo o comportamento antigo (quita o restante).")

    # Pix confirmado pelo Mercado Pago: usa o valor REALMENTE pago (o servidor ja validou
    # que ele bate com o do QR). Se for menor que o restante do pedido, vira baixa PARCIAL
    # (o pedido continua Pendente com o saldo) em vez de quitar o total.
    if eh_pix_mp:
        _vr_mp = _numero_baixa(dados.get("valor"))
        if _vr_mp is not None and _vr_mp > VALOR_TOLERANCIA:
            valor_recebido = _vr_mp

    id_baixa = _id_baixa_estavel(dados, caminho_arquivo, pedido_id, forma_padrao, valor_recebido)

    # --- Verificacoes baratas (sem transacao) ---
    cursor.execute(
        "SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?",
        (pedido_id_db,)
    )
    pedido = cursor.fetchone()

    if not pedido:
        raise PedidoAindaNaoGravadoErro(f"Pedido #{pedido_id} nao encontrado no sis.py")

    cursor.execute("SELECT 1 FROM baixas_entrega_aplicadas WHERE id_baixa=?", (id_baixa,))
    if cursor.fetchone():
        mover_arquivo_unico(caminho_arquivo, PASTA_ENTREGAS_BAIXAS_PROCESSADAS)
        baixas_entrega_adiadas.pop(caminho_arquivo, None)
        registrar_log("BAIXA_ENTREGA_DUPLICADA", "ENTREGAS", pedido_id, {"id_baixa": id_baixa})
        print(f"[ENTREGAS] Baixa {id_baixa} do pedido #{pedido_id} ja aplicada. Nao reaplicada.")
        return "DUPLICADA"

    pagamento_atual = pedido[2]

    # 🔒 Evita baixa duplicada
    if str(pagamento_atual).strip().lower() != "pendente":
        mover_arquivo_unico(
            caminho_arquivo,
            PASTA_ENTREGAS_BAIXAS_PROCESSADAS
        )
        baixas_entrega_adiadas.pop(caminho_arquivo, None)

        print(
            f"[ENTREGAS] Pedido #{pedido_id} já estava pago "
            f"({pagamento_atual}). Ignorado."
        )

        return "IGNORADA"

    # --- Caixa fechado: ADIA (nunca lanca no caixa sem ciclo_id) ---
    ciclo_id = ciclo_caixa_aberto.get("id")
    if not ciclo_id:
        baixas_entrega_adiadas[caminho_arquivo] = time.time()
        print(f"[ENTREGAS] Baixa do pedido #{pedido_id} recebida, mas o caixa esta fechado. "
              f"Sera aplicada assim que o caixa for aberto.")
        return "ADIADA"

    # --- Transacao unica: pedidos + caixa + idempotencia + log ---
    resultado = "OK"
    info_log = None
    try:
        iniciar_transacao_imediata()

        # Relê DENTRO da transacao (ja com o lock de escrita).
        cursor.execute(
            "SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?",
            (pedido_id_db,)
        )
        pedido = cursor.fetchone()
        if not pedido:
            conn.rollback()
            raise PedidoAindaNaoGravadoErro(f"Pedido #{pedido_id} nao encontrado no sis.py")

        total_p = round(float(pedido[0] or 0), 2)
        pago_p = round(float(pedido[1] or 0), 2)
        pagamento_atual = pedido[2]

        cursor.execute("SELECT 1 FROM baixas_entrega_aplicadas WHERE id_baixa=?", (id_baixa,))
        if cursor.fetchone():
            conn.rollback()
            resultado = "DUPLICADA"
        elif str(pagamento_atual).strip().lower() != "pendente":
            conn.rollback()
            resultado = "IGNORADA"
        else:
            # REGRA 5: valor_pago e sempre aditivo, nunca sobrescrito.
            restante = round(total_p - pago_p, 2)
            if restante <= VALOR_TOLERANCIA:
                conn.rollback()
                resultado = "IGNORADA"
            else:
                if valor_recebido is None:
                    valor_aplicado = restante
                else:
                    valor_aplicado = round(min(valor_recebido, restante), 2)
                quita = valor_aplicado >= restante - VALOR_TOLERANCIA
                if quita:
                    valor_aplicado = restante  # sem sobra de centavo por arredondamento
                excedente = 0.0
                if valor_recebido is not None and valor_recebido > restante + VALOR_TOLERANCIA:
                    excedente = round(valor_recebido - restante, 2)
                restante_apos = 0.0 if quita else round(restante - valor_aplicado, 2)

                if quita:
                    cursor.execute(
                        "UPDATE pedidos SET pagamento=?, valor_pago=? WHERE id=?",
                        (forma_padrao, total_p, pedido_id_db)
                    )
                else:
                    # Parcial: pagamento permanece "Pendente".
                    cursor.execute(
                        "UPDATE pedidos SET valor_pago=? WHERE id=?",
                        (round(pago_p + valor_aplicado, 2), pedido_id_db)
                    )

                cursor.execute("""
                    INSERT OR IGNORE INTO baixas_entrega_aplicadas (id_baixa, pedido_id, valor, aplicado_em)
                    VALUES (?, ?, ?, ?)
                """, (id_baixa, pedido_id_db if isinstance(pedido_id_db, int) else None,
                      valor_aplicado, datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
                if cursor.rowcount == 0:
                    conn.rollback()
                    resultado = "DUPLICADA"
                else:
                    registrar_lancamento_caixa(
                        "ENTRADA", f"Pedido #{pedido_id}", valor_aplicado, forma_padrao,
                        pedido_id=pedido_id_db, ciclo_id=ciclo_id, commit=False
                    )
                    detalhes = {
                        "valor_recebido": valor_recebido,
                        "valor_aplicado": valor_aplicado,
                        "restante_apos": restante_apos,
                        "id_baixa": id_baixa,
                    }
                    registrar_log(
                        "BAIXA_ENTREGA_TOTAL" if quita else "BAIXA_ENTREGA_PARCIAL",
                        "ENTREGAS", pedido_id, detalhes, commit=False
                    )
                    registrar_log("PEDIDO_CONCLUIDO", "ENTREGAS", pedido_id,
                                  {"forma": forma_padrao, "total": total_p}, commit=False)
                    if quita:
                        registrar_log("PEDIDO_BAIXADO", "ENTREGAS", pedido_id,
                                      {"forma": forma_padrao, "total": total_p}, commit=False)
                        registrar_log("ALTERACAO_PAGAMENTO", "PEDIDOS", pedido_id,
                                      {"forma_antiga": pagamento_atual, "forma_nova": forma_padrao}, commit=False)
                    if excedente > VALOR_TOLERANCIA:
                        registrar_log("BAIXA_ENTREGA_TROCO_PROVAVEL", "ENTREGAS", pedido_id, {
                            "valor_recebido": valor_recebido, "restante": restante,
                            "excedente": excedente, "id_baixa": id_baixa,
                            "obs": "valor_recebido maior que o restante; provavel troco. Quitado so o restante."
                        }, commit=False)
                    conn.commit()
                    info_log = (quita, valor_aplicado, restante_apos, excedente,
                                restante, total_p, valor_recebido)
    except PedidoAindaNaoGravadoErro:
        raise
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        registrar_erro_diagnostico(
            "aplicar_baixa_entrega", pedido=pedido_id,
            extra={"arquivo": os.path.basename(caminho_arquivo), "id_baixa": id_baixa}
        )
        raise  # arquivo permanece e vai para erros/ -> reprocessado (idempotente, sem duplicar)

    if resultado in ("DUPLICADA", "IGNORADA"):
        mover_arquivo_unico(caminho_arquivo, PASTA_ENTREGAS_BAIXAS_PROCESSADAS)
        baixas_entrega_adiadas.pop(caminho_arquivo, None)
        print(f"[ENTREGAS] Baixa {id_baixa} do pedido #{pedido_id}: {resultado.lower()} (nada reaplicado).")
        return resultado

    quita, valor_aplicado, restante_apos, excedente, restante_devido, total_pedido_baixa, valor_recebido_bruto = info_log

    # --- CONFERENCIA VISUAL: guarda o troco (excedente) so para o card informativo. ---
    # Roda DEPOIS do commit da baixa e dentro de try/except: se falhar, a baixa e o
    # caixa NAO sao afetados (nada aqui altera pedidos, caixa ou valores).
    try:
        if excedente > VALOR_TOLERANCIA and not eh_pix_mp:
            registrar_troco_entrega(
                id_baixa, pedido_id_db, ciclo_id,
                str(dados.get("entregador_id") or "").strip(),
                str(dados.get("entregador_nome") or "").strip(),
                valor_recebido_bruto, restante_devido, excedente)
    except Exception as _erro_troco:
        print(f"[TROCOS] Falha ao guardar o troco do pedido #{pedido_id} (baixa nao afetada): {_erro_troco}")

    # Se essa baixa veio de uma confirmação real do Mercado Pago (Pix), avisa
    # em tempo real o app do garçom (se estiver de pé), para a tela do QR
    # code trocar "aguardando pagamento" por "pago" na hora, sem depender
    # só do polling da tela. Falha aqui nunca deve travar a baixa em si.
    if eh_pix_mp:
        try:
            modulo_garcom = sys.modules.get("garcom_api")
            if modulo_garcom and hasattr(modulo_garcom, "notificar_pagamento_pedido"):
                modulo_garcom.notificar_pagamento_pedido(pedido_id)
        except Exception as erro:
            print(f"[ENTREGAS] Aviso: falha ao notificar app do garcom sobre o pagamento: {erro}")

    baixas_entrega_adiadas.pop(caminho_arquivo, None)
    mover_arquivo_unico(caminho_arquivo, PASTA_ENTREGAS_BAIXAS_PROCESSADAS)
    sincronizar_financeiro()  # REGRA 11: depois do commit
    if eh_pix_mp:
        tocar_som_caixa()  # Pix confirmado pelo Mercado Pago
    else:
        # Dinheiro recebido pelo entregador na rua (total, parcial ou com excedente):
        # som exclusivo para o operador lembrar de prestar contas com o motoboy.
        tocar_som_entrega_dinheiro()
        # Valor que o entregador tem NA MAO para repassar (inclui o excedente/troco).
        # App antigo (sem valor_recebido): assume o proprio valor aplicado.
        valor_na_mao = valor_recebido_bruto if valor_recebido_bruto is not None else valor_aplicado
        mostrar_aviso_dinheiro_entrega(
            pedido_id_db, valor_aplicado, quita, restante_apos, excedente,
            valor_recebido=valor_na_mao, devido=restante_devido, total_pedido=total_pedido_baixa,
            entregador_id=str(dados.get("entregador_id") or "").strip(),
            entregador_nome=str(dados.get("entregador_nome") or "").strip())
    if quita:
        print(f"[ENTREGAS] Pedido #{pedido_id} marcado como pago via {forma_padrao} "
              f"(R$ {valor_aplicado:.2f} no caixa).")
    else:
        print(f"[ENTREGAS] Pedido #{pedido_id}: pagamento PARCIAL de R$ {valor_aplicado:.2f} em "
              f"{forma_padrao}. Restam R$ {restante_apos:.2f} (continua Pendente).")
    if excedente > VALOR_TOLERANCIA:
        print(f"[ENTREGAS] ⚠️ Pedido #{pedido_id}: valor_recebido excede o restante em "
              f"R$ {excedente:.2f} (provavel troco). Caixa recebeu so o restante.")
    return "OK"


def agendar_baixa_entrega(caminho):
    with baixas_entrega_lock:
        if caminho in baixas_entrega_agendadas:
            return
        baixas_entrega_agendadas.add(caminho)

    baixas_entrega_queue.put(caminho)


def processar_baixas_entrega_agendadas():
    while True:
        try:
            caminho = baixas_entrega_queue.get_nowait()
        except queue.Empty:
            break

        try:
            info_espera = baixas_entrega_espera.get(caminho)
            if info_espera and time.time() < info_espera["proxima"]:
                continue  # ainda aguardando o pedido ser gravado (o finally libera o agendamento)
            aplicar_baixa_entrega(caminho)
            baixas_entrega_espera.pop(caminho, None)
        except PedidoAindaNaoGravadoErro as erro:
            arquivo = os.path.basename(caminho)
            agora_t = time.time()
            info_espera = baixas_entrega_espera.setdefault(caminho, {"inicio": agora_t, "proxima": 0})
            if agora_t - info_espera["inicio"] < BAIXA_ESPERA_PEDIDO_SEGUNDOS:
                if info_espera["proxima"] == 0:
                    print(f"[ENTREGAS] {arquivo}: {erro}. Aguardando o pedido ser gravado "
                          f"(tenta de novo por ate {BAIXA_ESPERA_PEDIDO_SEGUNDOS // 60} min).")
                info_espera["proxima"] = agora_t + BAIXA_REPETIR_A_CADA
            else:
                print(f"[ENTREGAS] Erro na baixa {arquivo}: {erro} (desisti apos "
                      f"{BAIXA_ESPERA_PEDIDO_SEGUNDOS // 60} min; movida para erros).")
                baixas_entrega_espera.pop(caminho, None)
                try:
                    if os.path.exists(caminho):
                        mover_arquivo_unico(caminho, PASTA_ENTREGAS_ERROS)
                except Exception:
                    pass
        except Exception as erro:
            baixas_entrega_espera.pop(caminho, None)
            arquivo = os.path.basename(caminho)
            print(f"[ENTREGAS] Erro na baixa {arquivo}: {erro}")
            try:
                if os.path.exists(caminho):
                    mover_arquivo_unico(caminho, PASTA_ENTREGAS_ERROS)
            except Exception:
                pass
        finally:
            with baixas_entrega_lock:
                baixas_entrega_agendadas.discard(caminho)

    root.after(500, processar_baixas_entrega_agendadas)


def monitorar_baixas_entrega():
    while True:
        try:
            os.makedirs(PASTA_ENTREGAS_BAIXAS, exist_ok=True)
            for arquivo in os.listdir(PASTA_ENTREGAS_BAIXAS):
                if not arquivo.startswith("baixa_") or not arquivo.endswith(".json"):
                    continue
                caminho = os.path.join(PASTA_ENTREGAS_BAIXAS, arquivo)
                agendar_baixa_entrega(caminho)
        except Exception as erro:
            print(f"[ENTREGAS] Erro no monitor de baixas: {erro}")
        time.sleep(1)


# =====================================================
# 📲 CONTAS A RECEBER — BAIXA AUTOMATICA DO PIX (Mercado Pago)
# Mesmo padrao de baixas do entregador: a THREAD so olha a pasta e enfileira;
# quem grava no SQLite e mexe nas telas e o Tk (root.after), na thread principal.
# =====================================================
# True  = se o caixa estiver fechado quando o Pix confirmar, a baixa fica
#         aguardando (arquivo permanece na pasta) e entra sozinha no ciclo
#         certo assim que o caixa for aberto.
# False = da a baixa na hora, mesmo sem caixa aberto (lancamento sem ciclo_id).
PIX_RECEBER_ADIAR_SE_CAIXA_FECHADO = True
PIX_RECEBER_MAX_TENTATIVAS = 10

pix_receber_lock = threading.Lock()
pix_receber_agendados = set()
pix_receber_queue = queue.Queue()
pix_receber_tentativas = {}
pix_receber_avisados = set()
pix_receber_ultimo_aviso = {}
TITULO_BASE_JANELA = "Sistema Delivery - Cumbuca"
PIX_RECEBER_REAVISAR_A_CADA = 60  # segundos


# =====================================================
# COBRANCAS PIX x PEDIDOS: sincronizacao, cancelamento e reabertura do QR
# -----------------------------------------------------
# Regra: so existe UMA cobranca Pix valida por pedido (ou grupo de pedidos).
# Se o pedido for cancelado, editado (valor/forma), quitado por outro caminho ou
# a cobranca vencer, a cobranca sai da fila (status CANCELADO/EXPIRADO) e o
# servidor cancela o Pix no Mercado Pago. Se o cliente ja tiver pago, o servidor
# NAO cancela: confirma o pagamento e a baixa e aplicada em cada pedido do grupo.
# =====================================================
PIX_RECEBER_VALIDADE_LOCAL_HORAS = 26     # Pix do MP expira em 24h (+2h de folga, igual ao servidor)
PIX_RECEBER_SWEEP_INTERVALO = 15          # s entre as varreduras de cobrancas desatualizadas
pix_receber_ultimo_sweep = 0.0


def _ids_pedidos_da_cobranca(ids_json):
    try:
        return [int(x) for x in json.loads(ids_json or "[]")]
    except Exception:
        return []


def solicitar_cancelamento_pix_mp(id_cobranca, payment_id, motivo):
    """Pede ao servidor (pasta compartilhada) que cancele o Pix no Mercado Pago."""
    try:
        salvar_json_atomico(
            os.path.join(PASTA_PIX_RECEBER_CANCELAMENTOS, f"{id_cobranca}.json"),
            {
                "id_cobranca": id_cobranca,
                "payment_id": str(payment_id or ""),
                "motivo": motivo,
                "pedido_em": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            }
        )
        return True
    except Exception as erro:
        print(f"[PIX_RECEBER] Nao consegui pedir o cancelamento de {id_cobranca} ao servidor: {erro}")
        return False


def cancelar_cobranca_pix_local(id_cobranca, payment_id, motivo, status_novo="CANCELADO",
                                pedir_ao_servidor=True, detalhes=None):
    """
    Tira a cobranca da fila (AGUARDANDO -> CANCELADO/EXPIRADO) e, se pedir_ao_servidor,
    manda cancelar no Mercado Pago. Se o pedido ao servidor nao puder ser gravado, NADA
    e alterado (a proxima varredura tenta de novo): nunca deixa um Pix vivo no Mercado
    Pago com a cobranca ja "cancelada" aqui.
    """
    if pedir_ao_servidor and not solicitar_cancelamento_pix_mp(id_cobranca, payment_id, motivo):
        return False
    cursor.execute(
        "UPDATE contas_receber_pix_pendentes SET status=? WHERE id_cobranca=? AND status='AGUARDANDO'",
        (status_novo, id_cobranca)
    )
    conn.commit()
    registrar_log("CONTAS_A_RECEBER_PIX_CANCELADO", "FINANCEIRO", id_cobranca, {
        "motivo": motivo, "status_novo": status_novo, "payment_id": str(payment_id or ""),
        **(detalhes or {})
    })
    pix_receber_avisados.discard(id_cobranca)
    pix_receber_ultimo_aviso.pop(id_cobranca, None)
    print(f"[PIX_RECEBER] Cobranca {id_cobranca} -> {status_novo} ({motivo}).")
    return True


def buscar_cobrancas_pix_abertas(pedido_ids):
    """Cobrancas AGUARDANDO (ainda dentro da validade) que cobrem algum destes pedidos."""
    foco = {int(p) for p in pedido_ids}
    encontradas = []
    try:
        cursor.execute("""
            SELECT id_cobranca, pedido_ids, valor_total, payment_id, criado_em, COALESCE(qr_code,'')
            FROM contas_receber_pix_pendentes WHERE status='AGUARDANDO'
        """)
    except Exception:   # coluna qr_code indisponivel: nada sera reaproveitado
        cursor.execute("""
            SELECT id_cobranca, pedido_ids, valor_total, payment_id, criado_em, ''
            FROM contas_receber_pix_pendentes WHERE status='AGUARDANDO'
        """)
    for id_c, ids_json, valor_total, payment_id, criado_em, qr_code in cursor.fetchall():
        ids = _ids_pedidos_da_cobranca(ids_json)
        if foco & set(ids):
            encontradas.append({
                "id": id_c, "pedido_ids": ids, "valor": float(valor_total or 0),
                "payment_id": payment_id or "", "criado_em": criado_em or "", "qr_code": qr_code or "",
            })
    return encontradas


PIX_REUTILIZAR_MAX_HORAS = 23   # o QR do Mercado Pago vale 24h: acima disso gera outro


def separar_cobranca_reutilizavel(conflitos, pedido_ids, valor_total):
    """
    Entre as cobrancas abertas, acha a que pode ser REABERTA em vez de gerar outra:
    mesmos pedidos, mesmo valor e ainda dentro da validade. Se o codigo do QR nao estiver
    guardado no banco, ele e pedido de volta ao servidor (que tem o MESMO codigo).
    Retorna (cobranca_reutilizavel_ou_None, demais_cobrancas).
    """
    alvo = sorted(int(p) for p in pedido_ids)
    for c in conflitos:
        try:
            idade_h = (datetime.now() - datetime.strptime(c["criado_em"], "%Y-%m-%d %H:%M:%S")).total_seconds() / 3600
        except Exception:
            continue
        if (sorted(c["pedido_ids"]) == alvo
                and abs(c["valor"] - float(valor_total)) <= 0.009
                and idade_h <= PIX_REUTILIZAR_MAX_HORAS):
            return c, [x for x in conflitos if x["id"] != c["id"]]
    return None, conflitos


PIX_QR_RECEM_CRIADO_SEG = 90   # ate 90s: o QR ainda esta sendo gerado, nao precisa pedir de novo


def solicitar_reenvio_qr_pix(cobranca):
    """
    Cobranca reaberta sem o codigo guardado: pede o MESMO QR ao servidor (resposta na pasta
    de respostas, como na criacao). Nada novo e criado no Mercado Pago. Se a cobranca e bem
    recente, o servidor ainda esta gerando: so espera a resposta normal. Retorna False se
    nao conseguiu gravar o pedido.
    """
    try:
        idade = (datetime.now() - datetime.strptime(cobranca["criado_em"], "%Y-%m-%d %H:%M:%S")).total_seconds()
    except Exception:
        idade = 10**6
    if idade <= PIX_QR_RECEM_CRIADO_SEG:
        return True
    try:
        salvar_json_atomico(
            os.path.join(PASTA_PIX_RECEBER_REENVIOS, f"{cobranca['id']}.json"),
            {"id_cobranca": cobranca["id"], "pedido_em": datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
        )
        return True
    except Exception as erro:
        print(f"[PIX_RECEBER] Nao consegui pedir o QR de {cobranca['id']} ao servidor: {erro}")
        return False


def sincronizar_cobrancas_pix_pendentes(pedido_ids=None, avisar=False):
    """
    Confere cada cobranca AGUARDANDO com o estado ATUAL dos pedidos dela e cancela
    as desatualizadas:
      - vencida (mais de 26h)                      -> EXPIRADO (nao precisa cancelar no MP)
      - pedido cancelado / inexistente             -> CANCELADO
      - pedido ja quitado ou alterado por outro
        caminho (ex.: marcado Pix/Dinheiro a mao)  -> CANCELADO
      - valor dos pedidos mudou (edicao, parcial)  -> CANCELADO
    pedido_ids: so as cobrancas que contem algum destes pedidos (None = todas).
    avisar: mostra ao operador o que foi cancelado e que precisa gerar novo QR.
    Em cobranca de varios pedidos (Contas a Receber) o grupo inteiro e cancelado,
    porque o valor do QR deixou de ser a soma certa.
    Retorna a lista das cobrancas canceladas agora.
    """
    canceladas = []
    try:
        cursor.execute("""
            SELECT id_cobranca, pedido_ids, valor_total, cliente, payment_id, criado_em
            FROM contas_receber_pix_pendentes WHERE status='AGUARDANDO'
        """)
        linhas = cursor.fetchall()
    except Exception as erro:
        print(f"[PIX_RECEBER] Falha ao ler cobrancas para sincronizar: {erro}")
        return canceladas

    foco = {int(p) for p in pedido_ids} if pedido_ids else None
    agora = datetime.now()

    for id_c, ids_json, valor_total, cliente, payment_id, criado_em in linhas:
        ids = _ids_pedidos_da_cobranca(ids_json)
        if foco is not None and not (foco & set(ids)):
            continue

        try:
            idade_h = (agora - datetime.strptime(criado_em, "%Y-%m-%d %H:%M:%S")).total_seconds() / 3600
        except Exception:
            idade_h = 0.0
        if idade_h > PIX_RECEBER_VALIDADE_LOCAL_HORAS:
            cancelar_cobranca_pix_local(id_c, payment_id, "vencida", status_novo="EXPIRADO",
                                        pedir_ao_servidor=False)
            continue

        motivo = None
        soma_aberta = 0.0
        for pid in ids:
            cursor.execute(
                "SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?", (pid,)
            )
            row = cursor.fetchone()
            if not row:
                motivo = f"o pedido #{pid} nao existe mais"
                break
            total_p, pago_p, forma_p = row
            if str(forma_p or "").strip().upper() == "CANCELADO":
                motivo = f"o pedido #{pid} foi cancelado"
                break
            if not pedido_elegivel_contas_receber(total_p, pago_p, forma_p):
                motivo = f"o pedido #{pid} ja foi quitado/alterado por outro caminho ({forma_p})"
                break
            soma_aberta += round(float(total_p or 0) - float(pago_p or 0), 2)
        if motivo is None and abs(round(soma_aberta, 2) - float(valor_total or 0)) > 0.009:
            motivo = (f"o valor mudou (QR de R$ {float(valor_total or 0):.2f}, "
                      f"pedidos agora somam R$ {soma_aberta:.2f})")
        if motivo is None:
            continue

        if cancelar_cobranca_pix_local(id_c, payment_id, motivo, detalhes={"pedidos": ids}):
            canceladas.append({
                "id": id_c, "pedidos": ids, "valor": float(valor_total or 0),
                "cliente": cliente or "", "motivo": motivo,
            })

    if avisar and canceladas:
        partes = []
        for c in canceladas:
            lista = ", ".join(f"#{p}" for p in c["pedidos"])
            partes.append(f"- Pix de R$ {c['valor']:.2f} ({lista}): {c['motivo']}.")
        texto = (
            "Cobranca(s) Pix cancelada(s), porque os pedidos mudaram:\n\n" + "\n".join(partes) +
            "\n\nO QR/codigo antigo deixa de valer (o cancelamento e feito tambem no Mercado Pago).\n"
            "Se ainda precisar cobrar por Pix, gere um novo QR (Contas a Receber).\n"
            "Em cobranca de varios pedidos, gere de novo para os pedidos que continuam em aberto."
        )
        try:
            messagebox.showinfo("Pix cancelado", texto)
        except Exception:
            pass
    return canceladas


def rotina_periodica_pix_receber():
    """Roda na thread principal (chamada pelo agendador de confirmacoes), no maximo a cada 15s."""
    global pix_receber_ultimo_sweep
    agora = time.time()
    if agora - pix_receber_ultimo_sweep < PIX_RECEBER_SWEEP_INTERVALO:
        return
    pix_receber_ultimo_sweep = agora
    try:
        sincronizar_cobrancas_pix_pendentes(avisar=False)
    except Exception as erro:
        print(f"[PIX_RECEBER] Erro na sincronizacao periodica de cobrancas: {erro}")


def atualizar_titulo_pix_aguardando():
    """Mostra no titulo da janela quantos Pix ja pagos aguardam o caixa abrir."""
    try:
        n = len(pix_receber_avisados)
        sufixo = f"  |  \u26a0 {n} Pix pago(s) aguardando abrir o caixa" if n else ""
        root.title(TITULO_BASE_JANELA + sufixo)
    except Exception:
        pass


def aplicar_confirmacao_pix_receber(caminho_arquivo):
    """
    Aplica a baixa de UMA cobranca Pix confirmada, somente nos pedidos do
    snapshot (contas_receber_pix_pendentes). Roda na thread principal do Tk.
    Retorna: "OK", "DUPLICADA", "DESCONHECIDA" ou "ADIADA".
    """
    with open(caminho_arquivo, "r", encoding="utf-8") as arquivo:
        dados = json.load(arquivo)

    id_cobranca = str(dados.get("id_cobranca") or "").strip()
    payment_id = str(dados.get("payment_id") or "").strip()
    try:
        valor_confirmado = round(float(dados.get("valor_pago") or 0), 2)
    except (TypeError, ValueError):
        valor_confirmado = 0.0

    if not id_cobranca:
        raise ValueError("Confirmacao Pix sem id_cobranca")

    cursor.execute("""
        SELECT pedido_ids, valor_total, status FROM contas_receber_pix_pendentes
        WHERE id_cobranca=?
    """, (id_cobranca,))
    registro = cursor.fetchone()

    if not registro:
        print(f"[PIX_RECEBER] Cobranca {id_cobranca} nao encontrada no banco. "
              f"Arquivo movido para 'erros' (verificar manualmente).")
        registrar_log("PIX_RECEBER_COBRANCA_DESCONHECIDA", "FINANCEIRO", id_cobranca, {
            "payment_id": payment_id, "valor_pago": valor_confirmado
        })
        mover_arquivo_unico(caminho_arquivo, PASTA_PIX_RECEBER_ERROS)
        return "DESCONHECIDA"

    pedido_ids_json, valor_total, status_atual = registro

    # 🔒 Trava contra webhook duplicado (Mercado Pago reenvia as vezes)
    if status_atual == "PAGO":
        mover_arquivo_unico(caminho_arquivo, PASTA_PIX_RECEBER_PROCESSADOS)
        pix_receber_avisados.discard(id_cobranca)
        atualizar_titulo_pix_aguardando()
        return "DUPLICADA"

    # Caixa fechado: espera reabrir para o lancamento cair no ciclo correto
    # (atualizar_saldo so enxerga lancamentos do ciclo aberto).
    if PIX_RECEBER_ADIAR_SE_CAIXA_FECHADO and not ciclo_caixa_aberto.get("id"):
        if id_cobranca not in pix_receber_avisados:
            pix_receber_avisados.add(id_cobranca)
            atualizar_titulo_pix_aguardando()
        agora_t = time.time()
        if agora_t - pix_receber_ultimo_aviso.get(id_cobranca, 0) >= PIX_RECEBER_REAVISAR_A_CADA:
            pix_receber_ultimo_aviso[id_cobranca] = agora_t
            print(f"[PIX_RECEBER] Cobranca {id_cobranca} PAGA, mas o caixa esta fechado. "
                  f"A baixa sera aplicada assim que o caixa for aberto.")
        return "ADIADA"

    pedido_ids = json.loads(pedido_ids_json)
    forma_pix = padronizar_forma_pagamento("Pix")
    baixados = []
    ignorados = []
    total_baixado = 0.0

    # Pix pago numa cobranca que o sistema ja tinha CANCELADO (ex.: o cliente pagou o QR
    # antigo de um pedido que foi editado). So da baixa se o valor recebido for exatamente
    # o que os pedidos ainda devem; senao NAO baixa nada sozinho (evita lancar no caixa um
    # valor que nao entrou) e avisa o operador.
    if status_atual in ("CANCELADO", "EXPIRADO"):
        soma_abertos = 0.0
        for pid in pedido_ids:
            cursor.execute(
                "SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?", (pid,)
            )
            row_chk = cursor.fetchone()
            if row_chk and pedido_elegivel_contas_receber(*row_chk):
                soma_abertos += round(float(row_chk[0] or 0) - float(row_chk[1] or 0), 2)
        soma_abertos = round(soma_abertos, 2)
        registrar_log("PIX_RECEBER_PAGO_APOS_CANCELAR", "FINANCEIRO", id_cobranca, {
            "payment_id": payment_id, "valor_pago": valor_confirmado,
            "status_cobranca": status_atual, "pedidos_em_aberto_somam": soma_abertos,
        })
        if valor_confirmado > 0 and abs(valor_confirmado - soma_abertos) > 0.01:
            aviso = (f"O Pix {id_cobranca} (R$ {valor_confirmado:.2f}) foi PAGO, mas essa cobranca ja "
                     f"tinha sido cancelada e os pedidos dela mudaram (hoje ainda devem R$ {soma_abertos:.2f}).\n"
                     f"Pedidos: {pedido_ids}\nPagamento Mercado Pago: {payment_id}\n\n"
                     f"NENHUMA baixa foi feita automaticamente.\n"
                     f"Lance o recebimento em Contas a Receber > Pagar > Pix (pelo valor correto) "
                     f"ou devolva a diferenca ao cliente.")
            registrar_log("PIX_RECEBER_DIVERGENCIA", "FINANCEIRO", id_cobranca, aviso)
            mover_arquivo_unico(caminho_arquivo, PASTA_PIX_RECEBER_PROCESSADOS)
            pix_receber_avisados.discard(id_cobranca)
            pix_receber_ultimo_aviso.pop(id_cobranca, None)
            atualizar_titulo_pix_aguardando()
            root.after(100, lambda a=aviso: messagebox.showwarning("Pix - Contas a Receber", a))
            return "CANCELADA_DIVERGENTE"

    try:
        for pid in pedido_ids:
            cursor.execute(
                "SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?",
                (pid,)
            )
            row = cursor.fetchone()
            if not row:
                ignorados.append(pid)
                continue

            total_p, pago_p, pagamento_atual = row

            # Pedido ja pago/cancelado/alterado por outro caminho enquanto o Pix
            # estava pendente: nao reaplica (mesma regra da lista de Contas a Receber).
            if not pedido_elegivel_contas_receber(total_p, pago_p, pagamento_atual):
                ignorados.append(pid)
                continue

            total_p = round(float(total_p or 0), 2)
            restante_p = round(total_p - float(pago_p or 0), 2)

            # Pix do Mercado Pago e tudo-ou-nada: quita o pedido inteiro (sem FIFO).
            cursor.execute(
                "UPDATE pedidos SET valor_pago=?, pagamento=? WHERE id=?",
                (total_p, forma_pix, pid)
            )
            # registrar_lancamento_caixa faz o commit (UPDATE + INSERT juntos).
            registrar_lancamento_caixa(
                "ENTRADA", f"Pedido #{pid}", restante_p, "Pix", pedido_id=pid
            )
            registrar_log("CONTAS_A_RECEBER_PIX", "FINANCEIRO", pid, {
                "id_cobranca": id_cobranca, "payment_id": payment_id, "valor": restante_p
            })
            baixados.append(pid)
            total_baixado = round(total_baixado + restante_p, 2)
    except Exception:
        conn.rollback()
        raise  # o arquivo permanece na pasta e sera tentado de novo (idempotente)

    cursor.execute("""
        UPDATE contas_receber_pix_pendentes
        SET status='PAGO', payment_id=COALESCE(NULLIF(?, ''), payment_id), confirmado_em=?
        WHERE id_cobranca=?
    """, (payment_id, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), id_cobranca))
    conn.commit()

    registrar_log("CONTAS_A_RECEBER_PIX_CONFIRMADO", "FINANCEIRO", id_cobranca, {
        "payment_id": payment_id, "valor_pago": valor_confirmado,
        "baixados": baixados, "ignorados": ignorados, "total_baixado": total_baixado
    })

    mover_arquivo_unico(caminho_arquivo, PASTA_PIX_RECEBER_PROCESSADOS)
    pix_receber_avisados.discard(id_cobranca)
    pix_receber_ultimo_aviso.pop(id_cobranca, None)
    atualizar_titulo_pix_aguardando()
    sincronizar_financeiro()
    print(f"[PIX_RECEBER] Cobranca {id_cobranca} baixada: {len(baixados)} pedido(s), "
          f"R$ {total_baixado:.2f} ({len(ignorados)} ignorado(s)).")

    tocar_som_caixa()

    # Situacoes que pedem atencao humana (dinheiro entrou, mas nao bate).
    aviso = None
    if not baixados:
        aviso = (f"O Pix {id_cobranca} (R$ {valor_confirmado:.2f}) foi pago, mas NENHUM pedido "
                 f"dele estava mais em aberto.\nPedidos: {pedido_ids}\n\n"
                 f"Se voce JA lancou esses pedidos manualmente como Pix, nao ha nada a fazer "
                 f"(o dinheiro ja esta no caixa). Caso contrario o valor entrou no Mercado Pago "
                 f"sem lancamento: confira e, se for duplicidade, devolva ao cliente.")
    elif valor_confirmado > 0 and abs(valor_confirmado - total_baixado) > 0.01:
        aviso = (f"O Pix {id_cobranca} recebeu R$ {valor_confirmado:.2f}, mas foram baixados "
                 f"R$ {total_baixado:.2f} (pedidos ignorados: {ignorados or 'nenhum'}).\n\n"
                 f"Confira a diferenca no caixa.")
    if aviso:
        registrar_log("PIX_RECEBER_DIVERGENCIA", "FINANCEIRO", id_cobranca, aviso)
        root.after(100, lambda a=aviso: messagebox.showwarning("Pix - Contas a Receber", a))

    return "OK"


def agendar_confirmacao_pix_receber(caminho):
    with pix_receber_lock:
        if caminho in pix_receber_agendados:
            return
        pix_receber_agendados.add(caminho)
    pix_receber_queue.put(caminho)


def processar_confirmacoes_pix_receber_agendadas():
    try:
        while True:
            try:
                caminho = pix_receber_queue.get_nowait()
            except queue.Empty:
                break

            try:
                if not os.path.exists(caminho):
                    # Ja processado (corrida entre o monitor e esta fila): nada a fazer.
                    pix_receber_tentativas.pop(caminho, None)
                    continue
                aplicar_confirmacao_pix_receber(caminho)
                pix_receber_tentativas.pop(caminho, None)
            except Exception as erro:
                arquivo = os.path.basename(caminho)
                tentativas = pix_receber_tentativas.get(caminho, 0) + 1
                pix_receber_tentativas[caminho] = tentativas
                print(f"[PIX_RECEBER] Erro ao aplicar {arquivo} "
                      f"(tentativa {tentativas}/{PIX_RECEBER_MAX_TENTATIVAS}): {erro}")
                if tentativas >= PIX_RECEBER_MAX_TENTATIVAS:
                    try:
                        if os.path.exists(caminho):
                            mover_arquivo_unico(caminho, PASTA_PIX_RECEBER_ERROS)
                        registrar_log("PIX_RECEBER_ERRO", "FINANCEIRO", arquivo, str(erro))
                    except Exception:
                        pass
                    pix_receber_tentativas.pop(caminho, None)
            finally:
                with pix_receber_lock:
                    pix_receber_agendados.discard(caminho)
    finally:
        try:
            rotina_periodica_pix_receber()
        except Exception as erro_rot:
            print(f"[PIX_RECEBER] Erro na rotina periodica: {erro_rot}")
        root.after(500, processar_confirmacoes_pix_receber_agendadas)


PIX_REPROCESSAR_MAX = 3  # quantas vezes um arquivo de erros/ volta para a fila


def reprocessar_arquivos_com_erro(pasta_erros, pasta_destino, prefixo=""):
    """
    Devolve para a pasta de entrada os JSON que foram parar em erros/ (o
    motivo pode ter sido passageiro: caixa fechado, pedido ainda nao gravado,
    banco ocupado...). Cada arquivo volta no maximo PIX_REPROCESSAR_MAX vezes
    (contador no proprio JSON) para nao gerar loop. Idempotente: as rotinas
    de baixa ja ignoram o que esta pago.
    """
    movidos = 0
    if not os.path.isdir(pasta_erros):
        return 0
    for nome in os.listdir(pasta_erros):
        if not nome.endswith(".json") or (prefixo and not nome.startswith(prefixo)):
            continue
        origem = os.path.join(pasta_erros, nome)
        try:
            with open(origem, "r", encoding="utf-8") as arquivo:
                dados = json.load(arquivo)
            if not isinstance(dados, dict):
                continue
            tentativas = int(dados.get("_reprocessamentos") or 0)
            if tentativas >= PIX_REPROCESSAR_MAX:
                continue
            dados["_reprocessamentos"] = tentativas + 1
            salvar_json_atomico(origem, dados)
            mover_arquivo_unico(origem, pasta_destino)
            movidos += 1
        except Exception as erro:
            print(f"[PIX_RECEBER] Nao consegui reprocessar {nome}: {erro}")
    return movidos


def reprocessar_erros_pix_e_baixas():
    """Roda ao iniciar o sistema e ao abrir o caixa."""
    try:
        n_pix = reprocessar_arquivos_com_erro(PASTA_PIX_RECEBER_ERROS, PASTA_PIX_RECEBER_CONFIRMADOS)
        n_baixas = reprocessar_arquivos_com_erro(PASTA_ENTREGAS_ERROS, PASTA_ENTREGAS_BAIXAS, prefixo="baixa_")
        if n_pix or n_baixas:
            print(f"[PIX_RECEBER] Reprocessando arquivos que estavam em erros/: "
                  f"{n_pix} confirmacao(oes) de Pix, {n_baixas} baixa(s) de pedido.")
    except Exception as erro:
        print(f"[PIX_RECEBER] Erro ao reprocessar arquivos de erros/: {erro}")


def monitorar_confirmacoes_pix_receber():
    # Thread de fundo: SO enxerga a pasta e enfileira. Nao toca em SQLite nem em Tk.
    while True:
        try:
            os.makedirs(PASTA_PIX_RECEBER_CONFIRMADOS, exist_ok=True)
            os.makedirs(PASTA_PIX_RECEBER_PROCESSADOS, exist_ok=True)
            for arquivo in os.listdir(PASTA_PIX_RECEBER_CONFIRMADOS):
                if not arquivo.endswith(".json"):
                    continue
                agendar_confirmacao_pix_receber(
                    os.path.join(PASTA_PIX_RECEBER_CONFIRMADOS, arquivo)
                )
        except Exception as erro:
            print(f"[PIX_RECEBER] Erro no monitor: {erro}")
        time.sleep(1)


# ======================= MAQUININHA POINT - BAIXA AUTOMATICA =================
# Espelha o fluxo do Pix a receber, com estado proprio (nao compartilha nada).
# A thread de fundo so enxerga a pasta e enfileira. Quem toca no SQLite e no Tk
# e o agendador (root.after), na thread principal.
POINT_ADIAR_SE_CAIXA_FECHADO = True
POINT_MAX_TENTATIVAS = 10
POINT_REAVISAR_A_CADA = 60  # segundos entre avisos de "pago, mas caixa fechado"

point_lock = threading.Lock()
point_agendados = set()
point_queue = queue.Queue()
point_tentativas = {}
point_ultimo_aviso = {}

# forma_usada que o servidor grava (vem da API do Mercado Pago) -> forma do caixa.
# "debit_card" foi visto no teste real. "qr"/"pix" (Pix) e "credit_card"/
# "prepaid_card" (cartao) seguem a documentacao e AINDA NAO foram vistos em
# teste real. Qualquer outro valor NAO e adivinhado: a confirmacao vai para
# erros/ e um aviso aparece (nenhuma baixa e feita).
POINT_FORMAS_PIX = {"qr", "pix"}
POINT_FORMAS_CARTAO = {"debit_card", "credit_card", "prepaid_card"}


def forma_caixa_point(forma_usada):
    """Devolve 'Pix' ou 'Cartão' (ja padronizado) ou None se desconhecida."""
    chave = str(forma_usada or "").strip().lower()
    if chave in POINT_FORMAS_PIX:
        return padronizar_forma_pagamento("Pix")
    if chave in POINT_FORMAS_CARTAO:
        return padronizar_forma_pagamento("Cartão")
    return None


def aplicar_confirmacao_point(caminho_arquivo):
    """
    Aplica a baixa de UMA cobranca da maquininha confirmada pelo servidor.
    Roda na thread principal do Tk.
    Retorna: "OK", "DUPLICADA", "DESCONHECIDA", "ADIADA", "DIVERGENTE" ou
    "FORMA_DESCONHECIDA".
    """
    with open(caminho_arquivo, "r", encoding="utf-8") as arquivo:
        dados = json.load(arquivo)

    id_cobranca = str(dados.get("id_cobranca") or "").strip()
    payment_id = str(dados.get("payment_id") or "").strip()
    forma_usada = str(dados.get("forma_usada") or "").strip()
    try:
        valor_pago_mp = round(float(dados.get("valor_pago") or 0), 2)
    except (TypeError, ValueError):
        valor_pago_mp = 0.0

    if not id_cobranca:
        raise ValueError("Confirmacao Point sem id_cobranca")

    cursor.execute("""
        SELECT pedido_id, valor, status FROM point_cobrancas WHERE id_cobranca=?
    """, (id_cobranca,))
    registro = cursor.fetchone()

    if not registro:
        print(f"[POINT] Cobranca {id_cobranca} nao encontrada no banco. "
              f"Arquivo movido para 'erros' (verificar manualmente).")
        registrar_log("POINT_COBRANCA_DESCONHECIDA", "FINANCEIRO", id_cobranca, {
            "payment_id": payment_id, "valor_pago": valor_pago_mp
        })
        mover_arquivo_unico(caminho_arquivo, PASTA_POINT_ERROS)
        return "DESCONHECIDA"

    pedido_id, valor_esperado, status_atual = registro
    valor_esperado = round(float(valor_esperado or 0), 2)

    # Trava contra confirmacao duplicada.
    if status_atual == "PAGO":
        mover_arquivo_unico(caminho_arquivo, PASTA_POINT_PROCESSADOS)
        point_ultimo_aviso.pop(id_cobranca, None)
        return "DUPLICADA"

    # Caixa fechado: espera reabrir para o lancamento cair no ciclo correto.
    if POINT_ADIAR_SE_CAIXA_FECHADO and not ciclo_caixa_aberto.get("id"):
        agora_t = time.time()
        if agora_t - point_ultimo_aviso.get(id_cobranca, 0) >= POINT_REAVISAR_A_CADA:
            point_ultimo_aviso[id_cobranca] = agora_t
            print(f"[POINT] Cobranca {id_cobranca} PAGA, mas o caixa esta fechado. "
                  f"A baixa sera aplicada assim que o caixa for aberto.")
        return "ADIADA"

    # Forma real: vem do que a maquininha registrou, nao do que foi pedido.
    forma_caixa = forma_caixa_point(forma_usada)
    if forma_caixa is None:
        aviso = (f"A maquininha confirmou R$ {valor_pago_mp:.2f} (cobranca {id_cobranca}, "
                 f"pedido #{pedido_id}), mas com uma forma de pagamento que o sistema "
                 f"nao conhece: \"{forma_usada}\".\n\nNenhuma baixa foi feita. "
                 f"Confira no Mercado Pago e lance manualmente.")
        registrar_log("POINT_FORMA_DESCONHECIDA", "FINANCEIRO", id_cobranca, aviso)
        mover_arquivo_unico(caminho_arquivo, PASTA_POINT_ERROS)
        root.after(100, lambda a=aviso: messagebox.showwarning("Maquininha", a))
        return "FORMA_DESCONHECIDA"

    # Valor aprovado precisa bater com o valor cobrado (tolerancia de R$ 0,01).
    if valor_esperado > 0 and abs(valor_pago_mp - valor_esperado) > 0.01:
        aviso = (f"A maquininha recebeu R$ {valor_pago_mp:.2f}, mas a cobranca "
                 f"{id_cobranca} (pedido #{pedido_id}) era de R$ {valor_esperado:.2f}.\n\n"
                 f"Nenhuma baixa foi feita. Confira o valor no Mercado Pago.")
        registrar_log("POINT_DIVERGENCIA", "FINANCEIRO", id_cobranca, aviso)
        mover_arquivo_unico(caminho_arquivo, PASTA_POINT_ERROS)
        root.after(100, lambda a=aviso: messagebox.showwarning("Maquininha", a))
        return "DIVERGENTE"

    baixou = False
    restante = 0.0
    try:
        cursor.execute(
            "SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?",
            (pedido_id,)
        )
        row = cursor.fetchone()

        if row and pedido_elegivel_contas_receber(row[0], row[1], row[2]):
            total_p = round(float(row[0] or 0), 2)
            restante = round(total_p - float(row[1] or 0), 2)

            # O pedido pode ter recebido pagamento parcial enquanto a cobranca
            # estava aberta: o valor recebido nao bate mais com o restante.
            if abs(restante - valor_pago_mp) > 0.01:
                aviso = (f"A cobranca {id_cobranca} recebeu R$ {valor_pago_mp:.2f}, mas o "
                         f"pedido #{pedido_id} agora tem R$ {restante:.2f} em aberto "
                         f"(foi alterado depois do envio).\n\nNenhuma baixa foi feita. "
                         f"Confira e lance manualmente.")
                registrar_log("POINT_DIVERGENCIA", "FINANCEIRO", id_cobranca, aviso)
                mover_arquivo_unico(caminho_arquivo, PASTA_POINT_ERROS)
                root.after(100, lambda a=aviso: messagebox.showwarning("Maquininha", a))
                return "DIVERGENTE"

            cursor.execute(
                "UPDATE pedidos SET valor_pago=?, pagamento=? WHERE id=?",
                (total_p, forma_caixa, pedido_id)
            )
            # registrar_lancamento_caixa faz o commit (UPDATE + INSERT juntos).
            registrar_lancamento_caixa(
                "ENTRADA", f"Pedido #{pedido_id}", restante, forma_caixa,
                pedido_id=pedido_id
            )
            registrar_log("CONTAS_A_RECEBER_POINT", "FINANCEIRO", pedido_id, {
                "id_cobranca": id_cobranca, "payment_id": payment_id,
                "valor": restante, "forma_real": forma_usada
            })
            baixou = True
    except Exception:
        conn.rollback()
        raise  # o arquivo permanece na pasta e sera tentado de novo (idempotente)

    cursor.execute("""
        UPDATE point_cobrancas
        SET status='PAGO', payment_id=COALESCE(NULLIF(?, ''), payment_id),
            confirmado_em=?, forma_real=?
        WHERE id_cobranca=?
    """, (payment_id, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), forma_usada, id_cobranca))
    conn.commit()

    registrar_log("POINT_CONFIRMADO", "FINANCEIRO", id_cobranca, {
        "pedido_id": pedido_id, "payment_id": payment_id, "valor_pago": valor_pago_mp,
        "forma_real": forma_usada, "baixou": baixou
    })

    mover_arquivo_unico(caminho_arquivo, PASTA_POINT_PROCESSADOS)
    point_ultimo_aviso.pop(id_cobranca, None)
    sincronizar_financeiro()
    print(f"[POINT] Cobranca {id_cobranca} confirmada: pedido #{pedido_id}, "
          f"R$ {valor_pago_mp:.2f} ({forma_caixa}). Baixa aplicada: {baixou}.")

    tocar_som_caixa()

    # Dinheiro entrou, mas o pedido ja nao estava em aberto (pago por outro caminho).
    if not baixou:
        aviso = (f"A maquininha recebeu R$ {valor_pago_mp:.2f} (cobranca {id_cobranca}), "
                 f"mas o pedido #{pedido_id} nao estava mais em aberto.\n\n"
                 f"Provavel pagamento em duplicidade: verifique se precisa devolver o valor.")
        registrar_log("POINT_DIVERGENCIA", "FINANCEIRO", id_cobranca, aviso)
        root.after(100, lambda a=aviso: messagebox.showwarning("Maquininha", a))

    return "OK"


def agendar_confirmacao_point(caminho):
    with point_lock:
        if caminho in point_agendados:
            return
        point_agendados.add(caminho)
    point_queue.put(caminho)


def processar_confirmacoes_point_agendadas():
    try:
        while True:
            try:
                caminho = point_queue.get_nowait()
            except queue.Empty:
                break

            try:
                if not os.path.exists(caminho):
                    point_tentativas.pop(caminho, None)
                    continue
                aplicar_confirmacao_point(caminho)
                point_tentativas.pop(caminho, None)
            except Exception as erro:
                arquivo = os.path.basename(caminho)
                tentativas = point_tentativas.get(caminho, 0) + 1
                point_tentativas[caminho] = tentativas
                print(f"[POINT] Erro ao aplicar {arquivo} "
                      f"(tentativa {tentativas}/{POINT_MAX_TENTATIVAS}): {erro}")
                if tentativas >= POINT_MAX_TENTATIVAS:
                    try:
                        if os.path.exists(caminho):
                            mover_arquivo_unico(caminho, PASTA_POINT_ERROS)
                        registrar_log("POINT_ERRO", "FINANCEIRO", arquivo, str(erro))
                    except Exception:
                        pass
                    point_tentativas.pop(caminho, None)
            finally:
                with point_lock:
                    point_agendados.discard(caminho)
    finally:
        root.after(500, processar_confirmacoes_point_agendadas)


def monitorar_confirmacoes_point():
    # Thread de fundo: SO enxerga a pasta e enfileira. Nao toca em SQLite nem em Tk.
    while True:
        try:
            os.makedirs(PASTA_POINT_CONFIRMADOS, exist_ok=True)
            os.makedirs(PASTA_POINT_PROCESSADOS, exist_ok=True)
            for arquivo in os.listdir(PASTA_POINT_CONFIRMADOS):
                if not arquivo.endswith(".json"):
                    continue
                agendar_confirmacao_point(os.path.join(PASTA_POINT_CONFIRMADOS, arquivo))
        except Exception as erro:
            print(f"[POINT] Erro no monitor: {erro}")
        time.sleep(1)


def reprocessar_erros_point():
    """Devolve para a fila os JSON de point_confirmados/erros (max. 3 vezes cada).
    Roda ao iniciar o sistema e ao abrir o caixa. Idempotente."""
    try:
        n = reprocessar_arquivos_com_erro(PASTA_POINT_ERROS, PASTA_POINT_CONFIRMADOS)
        if n:
            print(f"[POINT] Reprocessando {n} confirmacao(oes) que estavam em erros/.")
    except Exception as erro:
        print(f"[POINT] Erro ao reprocessar arquivos de erros/: {erro}")


PASTA_ROTA_ATIVA = os.path.join(PASTA_NOVO_APP, "rota_ativa")


def buscar_pedidos_em_rota():
    if not os.path.exists(PASTA_ROTA_ATIVA):
        return []
    pedidos = []
    try:
        for arquivo in os.listdir(PASTA_ROTA_ATIVA):
            if arquivo.startswith("EM_ROTA_") and arquivo.endswith(".json"):
                pedido_id = arquivo[8:-5]  # remove "EM_ROTA_" e ".json"
                if pedido_id:
                    pedidos.append(pedido_id)
    except Exception:
        pass
    return pedidos


def monitorar_pedidos_em_rota():
    while True:
        try:
            for pedido_id in buscar_pedidos_em_rota():
                caminho_arquivo = os.path.join(PASTA_ROTA_ATIVA, f"EM_ROTA_{pedido_id}.json")
                try:
                    os.remove(caminho_arquivo)
                except Exception:
                    pass
                # A2(b): thread de fundo nao usa root.after/Tk direto.
                enfileirar_acao_ui(
                    lambda p=pedido_id: atualizar_status_entrega(
                        p,
                        marcar=True,
                    )
                )
                enfileirar_acao_ui(carregar_historico, chave="carregar_historico")
        except Exception:
            pass
        time.sleep(3)


# Iniciar monitores em segundo plano
root.after(500, processar_baixas_entrega_agendadas)
root.after(700, processar_confirmacoes_pix_receber_agendadas)

# O motor_marinete_banco() abaixo é o fluxo oficial de pedidos.
