# --- FUNÇÃO AUTOCOMPLETE CORRIGIDA ---
# NOTA: esta função não é mais usada — foi substituída pelo autocomplete
# estilo Google (ativar_autocomplete_combobox) aplicado ao cb_prod mais
# abaixo, que tem o mesmo comportamento do campo Item do Lançar Nota.
def autocomplete_produto(event):
    global autocompletando
    if autocompletando:
        return

    # Ignorar teclas de navegação e controle
    if event.keysym in ("BackSpace", "Delete", "Left", "Right", "Up", "Down", "Return", "Escape", "Tab"):
        return

    texto_digitado = cb_prod.get().upper()
    if len(texto_digitado) < 3:
        return

    if not lista_produtos_original:
        carregar_produtos()

    for item in lista_produtos_original:
        # Extrai o nome após o "código - " se existir
        nome_no_item = item.split(" - ", 1)[1].upper() if " - " in item else item.upper()
        
        if nome_no_item.startswith(texto_digitado):
            pos = len(texto_digitado)
            autocompletando = True
            cb_prod.set(item)
            cb_prod.selection_range(pos, tk.END)
            cb_prod.icursor(pos)
            autocompletando = False
            break


# 🚚 ================= TAXA DE ENTREGA AUTOMATICA =================
# Valores vem da subaba Config > Taxa de Entrega (config_taxa.py).
# Regra (so para pedido NOVO e so se o campo Ajuste estiver vazio ou "0"):
#   sem endereco / retirada ........................ sem taxa
#   pedido de pedidos_entrada + caixa 'zerar' ...... taxa zero (com ou sem endereco)
#   com endereco ou referencia ..................... taxa configurada
# Ajuste digitado a mao (qualquer valor, inclusive 0,00) SEMPRE vale.
def _assinatura_pedido_tela():
    return (e_cliente.get().strip().lower(), e_telefone.get().strip())

def _marcar_pedido_do_site():
    """Chamada quando o motor carrega um JSON de pedidos_entrada na tela."""
    global _pedido_site_assinatura
    try:
        _pedido_site_assinatura = _assinatura_pedido_tela()
    except Exception:
        _pedido_site_assinatura = None

def _limpar_marca_pedido_do_site():
    global _pedido_site_assinatura
    _pedido_site_assinatura = None

def _pedido_da_tela_e_do_site():
    # a marca so vale se cliente/telefone ainda sao os do pedido carregado:
    # se a tela foi limpa e digitaram outro pedido, nao herda 'taxa zero'
    try:
        return _pedido_site_assinatura is not None and _pedido_site_assinatura == _assinatura_pedido_tela()
    except Exception:
        return False

def _taxa_entrega_automatica():
    """Valor que entra sozinho no Ajuste. 0.0 = nao aplicar nada."""
    try:
        import config_taxa
        if pedido_em_edicao:
            return 0.0                       # edicao: nunca mexe no ajuste gravado
        if e_ajuste.get().strip() not in ("", "0"):
            return 0.0                       # ajuste digitado a mao sempre vale
        endereco = e_endereco.get().strip()
        if not endereco or endereco_e_retirada(endereco):
            return 0.0                       # retirada
        if _pedido_da_tela_e_do_site() and config_taxa.zerar_taxa_pedidos_entrada():
            return 0.0                       # pedido do site: taxa zero
        return float(config_taxa.obter_taxa_entrega() or 0.0)
    except Exception:
        return 0.0                           # na duvida, nao cobra

def atualizar_total_pedido():
    # 🔵 LISTA TEMPORÁRIA: Calcula multiplicando Quantidade (item[2]) por Valor de Venda (item[4])
    total_produtos = 0
    for item in pedido_itens:
        try:
            # Garante a conversão correta mesmo se os valores vierem formatados ou como string
            qtd = int(item[2])
            venda = float(str(item[4]).replace(",", "."))
            total_produtos += qtd * venda
        except Exception as e:
            print(f"[ERRO CÁLCULO] Falha ao somar item: {e}")

    # 🔥 PREVIEW DO ITEM QUE ESTÁ SENDO DIGITADO
    try:
        qtd_texto = e_qtd_item.get().strip()
        
        if qtd_texto.isdigit():
            qtd_temp = int(qtd_texto)
        else:
            qtd_temp = 0
        conteudo = cb_prod.get().strip()

        if conteudo:
            codigo = conteudo.split(" - ")[0].strip()

            cursor.execute("SELECT venda FROM estoque WHERE codigo=?", (codigo,))
            res = cursor.fetchone()

            if res:
                valor_unit = res[0]
                total_produtos += qtd_temp * valor_unit
    except:
        pass

    # 🔥 AJUSTE CORRIGIDO
    try:
        texto_ajuste = e_ajuste.get().replace(",", ".").strip()
        ajuste = float(texto_ajuste)
    except:
        ajuste = 0

    # 🚚 taxa automatica (mesma regra do finalizar_pedido, para o total da tela bater)
    _taxa_auto = _taxa_entrega_automatica()
    if _taxa_auto > 0:
        ajuste = _taxa_auto

    total = total_produtos + ajuste

    # Atualiza a String de texto do total
    texto_total = (
        f"TOTAL DO PEDIDO: R$ {total:,.2f}"
        .replace(",", "X").replace(".", ",").replace("X", ".")
    )
    
    lbl_total.configure(text=texto_total)

