# =====================================================
# ⌨️ NAVEGAÇÃO RÁPIDA POR ENTER (aba Novo Pedido)
# Ordem: Cliente -> Endereço -> Telefone -> Pagamento -> Produto -> Qtd
#        -> (Adiciona o item automaticamente) -> Observação -> Ajuste
#        -> (Finaliza o pedido automaticamente)
#
# Em nenhum passo o conteúdo do campo é apagado: só "confirmamos" o
# texto (tirando o realce/seleção, sem deletar nada) e movemos o foco
# para o próximo campo. Por isso é seguro apertar Enter mesmo quando
# o campo de destino chega com texto selecionado/destacado (ex.: o
# autocomplete de produto, que seleciona o trecho completado).
# =====================================================

def _avancar_foco(widget_destino):
    """Confirma o campo atual (sem apagar nada) e move o foco adiante."""
    def _handler(event):
        origem = event.widget
        try:
            origem.selection_clear()
        except Exception:
            pass
        try:
            origem.icursor(tk.END)
        except Exception:
            pass
        widget_destino.focus_set()
        try:
            widget_destino.selection_clear()
        except Exception:
            pass
        return "break"
    return _handler

def _enter_qtd_item(event):
    """Enter na Qtd: confirma, adiciona o item e segue para Observação."""
    try:
        event.widget.selection_clear()
    except Exception:
        pass
    atualizar_total_pedido()
    adicionar_item()
    e_observacao.focus_set()
    return "break"

def _enter_ajuste(event):
    """Enter no Ajuste: confirma o total e finaliza o pedido."""
    try:
        event.widget.selection_clear()
    except Exception:
        pass
    atualizar_total_pedido()
    finalizar_pedido()
    return "break"

# ---- escolha entre os endereços cadastrados do cliente (campo Endereço) ----
_cdb_ctx_enderecos = {"cid": None, "lista": []}


def _cdb_atualizar_lista_enderecos():
    """postcommand do campo Endereço (roda antes de abrir a lista): só mostra os
    endereços se o cliente escolhido ainda for o que está no campo Cliente."""
    try:
        sel = cdb_selecao_filtro(e_cliente)
        if sel and sel.get("cid") == _cdb_ctx_enderecos.get("cid"):
            e_endereco.configure(values=tuple(_cdb_ctx_enderecos.get("lista") or ()))
        else:
            e_endereco.configure(values=())
    except Exception:
        pass


def _cdb_abrir_lista_enderecos():
    """Abre a lista de endereços do cliente escolhido (só quando tem mais de um)."""
    try:
        if len(_cdb_ctx_enderecos.get("lista") or []) < 2:
            return
        sel = cdb_selecao_filtro(e_cliente)
        if not sel or sel.get("cid") != _cdb_ctx_enderecos.get("cid"):
            return
        e_endereco.focus_set()
        try:
            e_endereco.tk.call("ttk::combobox::Post", str(e_endereco))
        except tk.TclError:
            e_endereco.event_generate("<Down>")
    except Exception:
        pass


e_endereco.configure(postcommand=_cdb_atualizar_lista_enderecos)
e_endereco.bind("<<ComboboxSelected>>", lambda e: atualizar_total_pedido(), add="+")   # 🚚 endereço novo pode mudar a taxa


def _preencher_pedido_com_cliente(s):
    """Cliente escolhido na lista: preenche Endereço e Telefone (o nome já está no campo).
    Se o cliente tem mais de um endereço, abre a lista para escolher (↑/↓ + Enter ou clique);
    Esc mantém o mais recente, que já vem preenchido. Depois, a setinha ▼ ou ↓ no campo
    Endereço reabre a lista."""
    _cdb_ctx_enderecos["cid"] = s.get("cid")
    _cdb_ctx_enderecos["lista"] = list(s.get("lista_enderecos") or [])
    e_endereco.delete(0, tk.END)
    e_endereco.insert(0, s["endereco"])
    e_telefone.delete(0, tk.END)
    e_telefone.insert(0, s["telefone_fmt"])
    try:
        atualizar_total_pedido()   # 🚚 o endereço preenchido pode gerar taxa de entrega
    except Exception:
        pass
    verificar_cliente_funcionario()
    if len(_cdb_ctx_enderecos["lista"]) > 1:
        e_endereco.after(80, _cdb_abrir_lista_enderecos)   # depois que o foco já foi para o Endereço

def _texto_e_codigo_de_funcionario(texto):
    """Código de funcionário digitado no campo Cliente: não sugerir clientes para ele."""
    try:
        cursor.execute("SELECT 1 FROM servidores WHERE codigo = ?", (str(texto).strip(),))
        return cursor.fetchone() is not None
    except Exception:
        return False

