import os

# Pega o caminho de onde o script está rodando
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.path.join(BASE_DIR, "sistema.db")

def carregar_produtos():
    global lista_produtos_original

    conn = abrir_conexao_curta()
    cur = conn.cursor()

    query = """
    SELECT codigo, produto 
    FROM estoque 
    WHERE categoria = 'PRODUTO' AND quantidade > 0
    ORDER BY produto
    """

    lista_produtos_original = [f"{r[0]} - {r[1]}" for r in cur.execute(query)]
    cb_prod["values"] = lista_produtos_original
    cb_prod.set("")

    conn.close()



def atualizar_lista_temp():
    lista_temp.delete(*lista_temp.get_children())
    for i in pedido_itens:
        subtotal = i[2] * i[4]
        lista_temp.insert("", "end", values=(
            i[1],
            i[2],
            f"R$ {subtotal:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        ))

def adicionar_item():
    global pedido_itens  # Garante que a lista global seja atualizada

    # 1. Validação básica de preenchimento
    conteudo_combo = cb_prod.get().strip()
    if not conteudo_combo or not e_qtd_item.get():
        messagebox.showerror("Erro", "Selecione o produto e a quantidade!")
        return

    try:
        # 2. Extração segura do código
        # Tenta dividir por " - ". Se não conseguir, usa o texto todo como código.
        if " - " in conteudo_combo:
            partes = conteudo_combo.split(" - ")
            codigo = partes[0].strip()
            nome_display = partes[1].strip()
        else:
            codigo = conteudo_combo
            nome_display = "" # Será preenchido pelo banco abaixo

        qtd = int(e_qtd_item.get())
        if qtd <= 0:
            raise ValueError
    except Exception as e:
        messagebox.showerror("Erro", "Quantidade ou formato de produto inválido!")
        return

    # 3. Busca produto no estoque de forma precisa
    cursor.execute("SELECT produto, custo, venda, quantidade FROM estoque WHERE codigo=?", (codigo,))
    resultado = cursor.fetchone()

    if not resultado:
        messagebox.showerror("Erro", f"Código [{codigo}] não encontrado no estoque!")
        return

    # No banco a ordem é: produto (nome), custo, venda, quantidade
    nome_real, custo, venda, est = resultado

    # 4. Verifica estoque
    if qtd > est:
        messagebox.showerror("Erro", f"Estoque insuficiente! Disponível: {est}")
        return

    # 5. Adiciona item na lista temporária (usando os dados reais do banco)
    # Formato: [codigo, nome, qtd, custo, venda]
    pedido_itens.append([codigo, nome_real, qtd, custo, venda])

    # 6. Limpa campos PRIMEIRO (remove preview)
    e_qtd_item.delete(0, "end")
    cb_prod.set("")
    
    # 7. Atualiza interface
    atualizar_lista_temp()
    atualizar_total_pedido()


def remover_item():
    sel = lista_temp.selection()
    if not sel:
        return
    
    if not messagebox.askyesno("Confirmar", "Deseja remover este item do pedido?"):
        return

    idx = lista_temp.index(sel)
    pedido_itens.pop(idx)

    atualizar_lista_temp()
    atualizar_total_pedido()


# 🔹 Inicialização global
pedido_em_edicao = None  # garante que não dê NameError

# ==================== FUNÇÃO EDITAR PEDIDO CORRIGIDA ====================
def editar_pedido():
    global pedido_em_edicao, pedido_itens
    
    selecao = lista_caixa_atual.selection() or lista_caixa_fechado.selection()
    if not selecao:
        messagebox.showwarning("Aviso", "Selecione um pedido!")
        return

    tabela = lista_caixa_atual if lista_caixa_atual.selection() else lista_caixa_fechado
    valores = tabela.item(selecao[0], 'values')
    pedido_id = valores[0]  # O ID do pedido sempre deve ser a primeira coluna

    try:
        # Limpa tudo antes de carregar
        pedido_itens.clear()
        e_cliente.delete(0, "end")
        e_endereco.delete(0, "end")
        e_telefone.delete(0, "end")
        e_observacao.delete(0, "end")
        e_ajuste.delete(0, "end")

        # 🔥 BUSCA OS DADOS DA CAPA DO PEDIDO DIRETO NO BANCO (Evita erro de coluna na tabela)
        cursor.execute("SELECT cliente, endereco, pagamento, observacao, ajuste FROM pedidos WHERE id = ?", (pedido_id,))
        pedido_capa = cursor.fetchone()

        if pedido_capa:
            cli, ender, pag, obs, aju = pedido_capa
            telefone_pedido = extrair_telefone_observacao(obs)
            obs_limpa = limpar_observacao_telefone(obs)
            if not telefone_pedido and cli:
                telefone_pedido = telefone_cadastrado_por_nome(cli)
            
            # Preenche os campos da tela com os dados REAIS e exatos do banco
            e_cliente.insert(0, cli if cli else "")
            e_endereco.insert(0, ender if ender else "")
            e_telefone.insert(0, telefone_pedido if telefone_pedido else "")
            cb_pag.set(pag if pag else "Pendente")
            e_observacao.insert(0, obs_limpa if obs_limpa else "")
            e_ajuste.insert(0, str(aju) if aju is not None else "0")
        else:
            messagebox.showerror("Erro", "Dados do pedido não encontrados no banco de dados.")
            return
        
        # BUSCA OS ITENS NO BANCO
        cursor.execute("SELECT codigo, produto, quantidade, custo, venda FROM itens_pedido WHERE pedido_id = ?", (pedido_id,))
        itens_do_banco = cursor.fetchall()
        
        for it in itens_do_banco:
            pedido_itens.append([it[0], it[1], it[2], it[3], it[4]])

        pedido_em_edicao = pedido_id
        _limpar_marca_pedido_do_site()
        
        # ATUALIZA A TABELA VISUAL
        atualizar_lista_temp()
        atualizar_total_pedido()
        
        messagebox.showinfo("Edição", f"Editando Pedido #{pedido_id}")

    except Exception as e:
        messagebox.showerror("Erro", f"Erro ao carregar itens: {e}")



# ==================== FUNÇÃO FINALIZAR PEDIDO ====================

def processar_pedido_direto_no_banco():
    import os, json, sqlite3
    from datetime import datetime
    
    pasta = "pedidos_entrada"
    # Se a pasta não existir, ele cria para não dar erro
    if not os.path.exists(pasta):
        try: os.makedirs(pasta)
        except: pass
        return

    # Lista os arquivos na pasta
    try:
        arquivos = [f for f in os.listdir(pasta) if f.endswith(".json")]
    except:
        root.after(3000, processar_pedido_direto_no_banco)
        return

    for arquivo in arquivos:
        caminho_arquivo = os.path.join(pasta, arquivo)
        try:
            with open(caminho_arquivo, 'r', encoding='utf-8') as f:
                dados = json.load(f)
            dados = normalizar_pedido_entrada(dados)
            
            # --- CONEXÃO COM O BANCO ---
            conn_bot = abrir_conexao_curta()  # A2(c): caminho absoluto + timeout=30 (antes: "sistema.db" relativo)
            cur_bot = conn_bot.cursor()
            
            # 1. PEGA O ID DO CAIXA ABERTO (Segurança)
            cur_bot.execute("SELECT id FROM ciclos_caixa WHERE status='aberto' ORDER BY id DESC LIMIT 1")
            ciclo = cur_bot.fetchone()
            id_ciclo = ciclo[0] if ciclo else None

            if not id_ciclo:
                print("⚠️ Bot: Pedido recebido, mas o CAIXA ESTÁ FECHADO. Ignorando...")
                conn_bot.close()
                continue # Pula para o próximo arquivo

            # 2. PROCESSA ITENS E CALCULA TOTAL
            total_venda = 0
            itens_para_gravar = []
            
            for item in dados.get('itens', []):
                cod = str(item.get('codigo') or item.get('nome_id', '')).strip()
                cod = cod.split(" - ")[0].strip()
                qtd = int(item['qtd'])
                
                cur_bot.execute("SELECT produto, custo, venda FROM estoque WHERE codigo=?", (cod,))
                prod = cur_bot.fetchone()
                
                if prod:
                    nome_p, custo_p, venda_p = prod
                    subtotal = qtd * venda_p
                    total_venda += subtotal
                    itens_para_gravar.append((cod, nome_p, qtd, custo_p, venda_p))

            # 3. GRAVA A CAPA DO PEDIDO
            data_agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            telefone_bot = str(dados.get("telefone", "") or dados.get("fone", "")).strip()
            observacao_bot = anexar_contato_whatsapp_observacao(
                dados.get('obs', ''),
                telefone_bot,
                dados.get("jid", ""),
            )
            cur_bot.execute("""
                INSERT INTO pedidos (data, cliente, pagamento, total, ciclo_caixa_id, observacao, ajuste) 
                VALUES (?,?,?,?,?,?,0)
            """, (data_agora, dados['cliente'], "Pendente", total_venda, id_ciclo, observacao_bot))
            
            pedido_id = cur_bot.lastrowid

            # 4. GRAVA OS ITENS E BAIXA ESTOQUE
            for it in itens_para_gravar:
                # it = (codigo, nome, qtd, custo, venda)
                cur_bot.execute("""
                    INSERT INTO itens_pedido (pedido_id, codigo, produto, quantidade, custo, venda) 
                    VALUES (?,?,?,?,?,?)
                """, (pedido_id, it[0], it[1], it[2], it[3], it[4]))
                
                # Baixa de estoque automática
                cur_bot.execute("UPDATE estoque SET quantidade = quantidade - ? WHERE codigo=?", (it[2], it[0]))

            conn_bot.commit()
            conn_bot.close()
            # 5. FINALIZAÇÃO E LIMPEZA
            conn_bot.close() # Fecha a conexão antes de mandar imprimir
            os.remove(caminho_arquivo) 
            print(f"✅ Pedido #{pedido_id} gravado. Tentando imprimir...")

            # 6. ATUALIZA A TELA (Histórico)
            root.after(100, carregar_historico)
            
            # 7. DISPARA A IMPRESSÃO
            # Forçamos a impressão se o ID existir, ignorando o Checkbutton por um momento para testar
            if pedido_id:
                print(f"🖨️ Enviando Pedido {pedido_id} para a impressora...")
                root.after(500, lambda: gerar_nota(pedido_id))

        except Exception as e:
            print(f"❌ Erro ao processar arquivo do bot: {e}")

# ================= MOTOR DE INTEGRAÇÃO CORRIGIDO =================

# ================= PEDIDO DO SITE/BOT x TELA OCUPADA =================
# Se chegar pedido do site/bot enquanto o operador esta lancando um pedido manual,
# o motor NAO mexe na tela e NAO apaga o JSON: o arquivo fica guardado na pasta
# pedidos_entrada e este cartao avisa (com som) ate a tela ficar livre. Quando o
# operador finaliza/limpa o pedido manual, o motor carrega o pedido sozinho.
PEDIDO_ESPERA_REAVISAR_S = 60   # repete o som a cada N segundos enquanto houver pedido esperando
_pedido_espera = {"card": None, "lbl_qtd": None, "qtd_som": 0, "ultimo_som": 0.0,
                  "timer_pisca": None, "ligado": True, "arr": None}
_pedido_espera_avisados = set()   # JSONs cujo som ja tocou na fila (nao repetir ao confirmar)


def tela_pedido_ocupada():
    """True se o operador esta com um pedido em andamento na tela: itens lancados,
    algum campo preenchido ou edicao de um pedido ja existente."""
    try:
        if pedido_em_edicao:
            return True
        if pedido_itens:
            return True
        for campo in (e_cliente, e_endereco, e_telefone, e_observacao):
            if campo.get().strip():
                return True
    except Exception:
        return False
    return False


def _tocar_som_pedido_novo():
    try:
        som = recurso("WhatsApp.wav")
        winsound.PlaySound(som, winsound.SND_FILENAME | winsound.SND_ASYNC)
    except Exception:
        pass


def _criar_cartao_pedido_espera():
    est = _pedido_espera
    cor_a, cor_b = "#E65100", "#FB8C00"
    card = tk.Toplevel(root)
    card.withdraw()
    card.overrideredirect(True)
    card.attributes("-topmost", True)
    card.configure(bg=cor_a, highlightthickness=2, highlightbackground=cor_a, highlightcolor=cor_a)

    lbl_topo = tk.Label(card, text="\U0001F6D2 PEDIDO AGUARDANDO", bg=cor_a, fg="#FFFFFF",
                        font=("Segoe UI", 9, "bold"), anchor="w", cursor="fleur")
    lbl_qtd = tk.Label(card, text="", bg=cor_a, fg="#FFFFFF", width=18,
                       font=("Segoe UI", 16, "bold"), anchor="w", cursor="fleur")
    lbl_nota = tk.Label(card, text="Finalize ou limpe o pedido atual\npara carregar o proximo.",
                        bg=cor_a, fg="#FFFFFF", font=("Segoe UI", 8), anchor="w",
                        justify="left", cursor="fleur")
    lbl_topo.pack(fill="x", padx=10, pady=(6, 0))
    lbl_qtd.pack(fill="x", padx=10)
    lbl_nota.pack(fill="x", padx=10, pady=(0, 6))
    widgets = (card, lbl_topo, lbl_qtd, lbl_nota)

    def _pintar(cor):
        for w in widgets:
            try:
                w.configure(bg=cor)
            except Exception:
                pass
        try:
            card.configure(highlightbackground=cor, highlightcolor=cor)
        except Exception:
            pass

    def _pisca():
        est["timer_pisca"] = None
        if est.get("card") is not card:
            return
        est["ligado"] = not est["ligado"]
        _pintar(cor_a if est["ligado"] else cor_b)
        est["timer_pisca"] = card.after(700, _pisca)

    # permite arrastar o cartao (para nao ficar em cima de algo que o operador use)
    def _press(e):
        est["arr"] = {"x0": e.x_root, "y0": e.y_root, "wx": card.winfo_x(), "wy": card.winfo_y()}

    def _move(e):
        a = est.get("arr")
        if a:
            card.geometry(f"+{a['wx'] + e.x_root - a['x0']}+{a['wy'] + e.y_root - a['y0']}")

    def _solta(e):
        est["arr"] = None

    for w in widgets:
        w.bind("<ButtonPress-1>", _press, add="+")
        w.bind("<B1-Motion>", _move, add="+")
        w.bind("<ButtonRelease-1>", _solta, add="+")

    est["card"] = card
    est["lbl_qtd"] = lbl_qtd
    est["ligado"] = True

    # posicao inicial: canto inferior esquerdo, acima da barra de tarefas
    # (o canto inferior direito ja e usado pelos cartoes de dinheiro do entregador)
    try:
        esq, topo, direita, base = _area_util_tela()
        card.update_idletasks()
        card.geometry(f"+{esq + 12}+{base - card.winfo_reqheight() - 12}")
    except Exception:
        pass
    card.deiconify()
    card.lift()
    est["timer_pisca"] = card.after(700, _pisca)


def _avisar_pedidos_em_espera(qtd, nomes=()):
    """Mostra/atualiza o cartao e toca o som: quando chega pedido novo na fila e,
    depois, a cada PEDIDO_ESPERA_REAVISAR_S segundos enquanto continuar esperando."""
    est = _pedido_espera
    try:
        if est["card"] is None:
            _criar_cartao_pedido_espera()
        est["lbl_qtd"].config(text="1 pedido na fila" if qtd == 1 else f"{qtd} pedidos na fila")
        agora = time.time()
        if qtd > est["qtd_som"] or agora - est["ultimo_som"] >= PEDIDO_ESPERA_REAVISAR_S:
            _tocar_som_pedido_novo()
            est["ultimo_som"] = agora
        est["qtd_som"] = qtd
        _pedido_espera_avisados.intersection_update(nomes)   # esquece arquivos que sairam da pasta
        _pedido_espera_avisados.update(nomes)
    except Exception as erro:
        print(f"[AVISO] Falha ao mostrar o aviso de pedido aguardando: {erro}")


def _limpar_aviso_pedidos_em_espera():
    est = _pedido_espera
    card = est.get("card")
    if card is None:
        return
    try:
        if est.get("timer_pisca"):
            card.after_cancel(est["timer_pisca"])
    except Exception:
        pass
    try:
        card.destroy()
    except Exception:
        pass
    est.update({"card": None, "lbl_qtd": None, "qtd_som": 0, "ultimo_som": 0.0,
                "timer_pisca": None, "arr": None})


def _janela_confirmar_pedido_bot(dados, itens_formatados):
    """Janela modal SEM opcao de recusar: so o botao 'Confirmar e imprimir'.
    O pedido ja esta na tela de venda; ao confirmar, segue para o finalizar_pedido()."""
    fundo, texto, suave = "#263238", "#FFFFFF", "#B0BEC5"
    win = tk.Toplevel(root)
    win.title("Marinete Bot - Novo Pedido")
    win.configure(bg=fundo)
    win.resizable(False, False)
    win.protocol("WM_DELETE_WINDOW", lambda: None)   # nao ha como recusar/fechar sem confirmar

    tk.Label(win, text="\U0001F6D2 NOVO PEDIDO RECEBIDO", bg=fundo, fg=texto,
             font=("Segoe UI", 12, "bold")).pack(anchor="w", padx=16, pady=(14, 8))

    def _linha(rotulo, valor):
        valor = str(valor or "").strip()
        if not valor:
            return
        f = tk.Frame(win, bg=fundo)
        f.pack(fill="x", padx=16, pady=1)
        tk.Label(f, text=rotulo, bg=fundo, fg=suave, font=("Segoe UI", 9, "bold"),
                 width=11, anchor="nw").pack(side="left")
        tk.Label(f, text=valor, bg=fundo, fg=texto, font=("Segoe UI", 10), anchor="w",
                 justify="left", wraplength=380).pack(side="left", fill="x")

    _linha("Cliente:", dados.get("cliente", ""))
    _linha("Telefone:", dados.get("telefone", "") or dados.get("fone", ""))
    _linha("Endereco:", dados.get("endereco", ""))
    _linha("Pagamento:", dados.get("pagamento", ""))
    _linha("Obs:", limpar_observacao_telefone(dados.get("obs", "")))

    tk.Frame(win, bg="#455A64", height=1).pack(fill="x", padx=16, pady=8)

    total = 0.0
    for it in itens_formatados:
        try:
            _cod, nome, qtd, _custo, venda = it
            sub = float(qtd) * float(venda)
            total += sub
            tk.Label(win, text=f"{qtd}x {nome}    {_dinheiro_br(sub)}", bg=fundo, fg=texto,
                     font=("Segoe UI", 10), anchor="w", justify="left",
                     wraplength=440).pack(fill="x", padx=16)
        except Exception:
            pass
    tk.Label(win, text=f"TOTAL  {_dinheiro_br(total)}", bg=fundo, fg="#A5D6A7",
             font=("Segoe UI", 13, "bold"), anchor="w").pack(fill="x", padx=16, pady=(8, 0))

    # aviso: item do JSON que nao existe no estoque fica de fora do pedido
    try:
        faltando = len(dados.get("itens") or []) - len(itens_formatados)
    except Exception:
        faltando = 0
    if faltando > 0:
        tk.Label(win, text=f"\u26A0 {faltando} item(ns) do pedido nao foram encontrados no estoque "
                           f"e ficaram de fora.", bg=fundo, fg="#FFCC80", font=("Segoe UI", 9, "bold"),
                 anchor="w", justify="left", wraplength=440).pack(fill="x", padx=16, pady=(6, 0))

    # aviso de estoque baixo (previsão, só leitura): fica nesta janela, sem caixa extra depois
    try:
        _baixo_site = _estoque_baixo_previsto()
    except Exception as erro_prev_site:
        print(f"[AVISO] Nao consegui prever o estoque baixo do pedido do site: {erro_prev_site}")
        _baixo_site = []
    if _baixo_site:
        _linhas_baixo = [f"\u2022 {n} \u2014 {q} un." for n, q in _baixo_site[:8]]
        if len(_baixo_site) > 8:
            _linhas_baixo.append(f"... e mais {len(_baixo_site) - 8} item(ns)")
        tk.Label(win, text="\u26A0 Estoque baixo apos este pedido:\n" + "\n".join(_linhas_baixo),
                 bg=fundo, fg="#FFCC80", font=("Segoe UI", 9, "bold"),
                 anchor="w", justify="left", wraplength=440).pack(fill="x", padx=16, pady=(6, 0))

    btn = tk.Button(win, text="\u2714 Confirmar e imprimir", bg="#2E7D32", fg="#FFFFFF",
                    activebackground="#388E3C", activeforeground="#FFFFFF",
                    font=("Segoe UI", 11, "bold"), relief="flat", bd=0, padx=18, pady=8,
                    cursor="hand2", command=win.destroy)
    btn.pack(pady=(14, 14))

    # centraliza sobre a janela principal
    try:
        win.update_idletasks()
        w, h = win.winfo_reqwidth(), win.winfo_reqheight()
        x = root.winfo_rootx() + max((root.winfo_width() - w) // 2, 0)
        y = root.winfo_rooty() + max((root.winfo_height() - h) // 2, 0)
        win.geometry(f"+{x}+{y}")
    except Exception:
        pass
    trazer_janela_para_frente(win)
    try:
        win.wait_visibility()
        win.grab_set()
    except Exception:
        pass
    try:
        btn.focus_set()
    except Exception:
        pass
    root.wait_window(win)


def confirmar_pedido_bot(dados, itens_formatados, ja_avisado=False):
    global pedido_em_tela, _finalizacao_automatica_ativa

    # WhatsApp.wav = aviso de chegada. Se o pedido ja esperou na fila (cartao + som),
    # nao toca de novo aqui; ao confirmar fica so o som padrao do Windows que o
    # finalizar_pedido ja toca nos pedidos finalizados.
    if not ja_avisado:
        _tocar_som_pedido_novo()

    # Config > Configurações do Sistema: "imprimir pedidos do site sem confirmação".
    # Ligado = pula SÓ a janela "Confirmar e imprimir"; o resto (som, gravar, estoque, caixa,
    # cobrança Mercado Pago e impressão) segue o mesmo caminho. Exceção de segurança: se algum
    # item do pedido não existe no estoque (ficou de fora), a janela abre mesmo assim.
    sem_confirmacao = False
    try:
        import config_taxa
        sem_confirmacao = bool(config_taxa.imprimir_site_sem_confirmacao())
        if sem_confirmacao and (len(dados.get("itens") or []) - len(itens_formatados)) > 0:
            sem_confirmacao = False
    except Exception:
        sem_confirmacao = False   # na dúvida, mantém a janela de confirmação

    try:
        if not sem_confirmacao:
            _janela_confirmar_pedido_bot(dados, itens_formatados)
    except Exception as erro_janela:
        # se a janela nova falhar, cai num aviso simples (sem opcao de recusar)
        print(f"[AVISO] Falha na janela de confirmacao do pedido: {erro_janela}")
        try:
            _msg_info("Marinete Bot - Novo Pedido",
                      "Pedido recebido. Clique OK para FINALIZAR e IMPRIMIR.")
        except Exception:
            pass

    # confirmou: roda a finalizacao oficial (a propria finalizar_pedido solta a trava)
    try:
        _finalizacao_automatica_ativa = True   # pedido do site/bot: sem alerta de telefone; grava e imprime sempre
        finalizar_pedido()
    finally:
        _finalizacao_automatica_ativa = False
        # se finalizar falhar (ex.: caixa fechado) o pedido continua na tela e a
        # trava de tela ocupada impede que o proximo JSON o sobrescreva
        pedido_em_tela = False


def motor_marinete_banco():
    global pedido_em_tela
    try:
        # 🔴 TRAVA 1: Se a tela já tiver um pedido, o motor para aqui e tenta de novo em 3s
        if pedido_em_tela:
            root.after(3000, motor_marinete_banco)
            return

        if not os.path.exists(PASTA_JSON):
            root.after(3000, motor_marinete_banco)
            return 
            
        # Busca apenas arquivos JSON
        arquivos = [f for f in os.listdir(PASTA_JSON) if f.endswith(".json")]
        
        if not arquivos:
            _limpar_aviso_pedidos_em_espera()
            root.after(3000, motor_marinete_banco)
            return

        # mais antigo primeiro (a ordem do os.listdir nao garante isso)
        try:
            arquivos.sort(key=lambda a: os.path.getmtime(os.path.join(PASTA_JSON, a)))
        except Exception:
            pass

        # 🟠 TELA OCUPADA: operador lancando pedido manual (ou editando um pedido).
        # Nao mexe na tela e NAO apaga o JSON: ele fica na pasta e entra sozinho
        # quando a tela ficar livre. Enquanto isso, cartao + som avisam.
        if tela_pedido_ocupada():
            _avisar_pedidos_em_espera(len(arquivos), arquivos)
            root.after(3000, motor_marinete_banco)
            return
        _limpar_aviso_pedidos_em_espera()

        # 🔴 TRAVA 2: Achou arquivo? Tranca a porta antes de começar!
        pedido_em_tela = True
        
        # Pega apenas o primeiro da fila (o mais antigo)
        arquivo = arquivos[0]
        caminho_json = os.path.join(PASTA_JSON, arquivo)
        ja_avisado_som = arquivo in _pedido_espera_avisados
        _pedido_espera_avisados.discard(arquivo)
        
        try:
            with open(caminho_json, 'r', encoding='utf-8') as f:
                dados = json.load(f)
            dados = normalizar_pedido_entrada(dados)
            
            # 1. LIMPEZA DA TELA
            pedido_itens.clear()
            e_cliente.delete(0, "end")
            e_telefone.delete(0, "end")
            e_observacao.delete(0, "end")
            e_ajuste.delete(0, "end")
            e_ajuste.insert(0, "0")

            # 2. PREENCHIMENTO DOS CAMPOS
            e_cliente.insert(0, dados.get('cliente', 'Bot WhatsApp'))
            
            # ✅ NOVO
            e_endereco.delete(0, "end")
            e_endereco.insert(0, dados.get('endereco', ''))
            e_telefone.insert(0, str(dados.get('telefone', '') or dados.get('fone', '')).strip())
            
            e_observacao.insert(0, dados.get('obs', ''))
            
            cb_pag.set(dados.get('pagamento', 'Pendente'))
            _marcar_pedido_do_site()  # 🚚 veio de pedidos_entrada: taxa zero se a caixa da Config estiver marcada

            # 3. CARREGAMENTO DOS ITENS
            for it in dados.get('itens', []):
                texto_id = str(it.get('nome_id', '')).strip()
                cod_final = texto_id.split(" - ")[0].strip() if " - " in texto_id else texto_id
                qtd = int(it.get('qtd', 1))
                
                cursor.execute("SELECT produto, custo, venda FROM estoque WHERE UPPER(codigo) = UPPER(?)", (cod_final,))
                res = cursor.fetchone()
                if res:
                    nome_p, custo_p, venda_p = res
                    pedido_itens.append([cod_final, nome_p, qtd, custo_p, venda_p])

            # 4. ATUALIZA INTERFACE
            atualizar_lista_temp()
            atualizar_total_pedido()
            
            # 5. REMOVE O ARQUIVO (Já carregou na tela, pode apagar o JSON)
            if os.path.exists(caminho_json):
                os.remove(caminho_json)

            # 6. DISPARA A PERGUNTA DE IMPRESSÃO
            root.after(200, lambda ja=ja_avisado_som: confirmar_pedido_bot(dados, pedido_itens, ja_avisado=ja))

        except Exception as e_file:
            print(f"⚠️ Erro ao processar arquivo {arquivo}: {e_file}")
            _limpar_marca_pedido_do_site()
            pedido_em_tela = False # Libera se der erro no arquivo

    except Exception as e:
        print(f"⚠️ Erro no Motor: {e}")
        pedido_em_tela = False

    # Mantém o motor rodando
    root.after(3000, motor_marinete_banco)


# =====================================================
# 📞 ALERTA DE TELEFONE VAZIO + CAIXA ÚNICA PÓS-FINALIZAÇÃO
# Alerta de telefone / Retirada / caixa única: SÓ para pedido digitado à mão.
# Pedido do site/bot (confirmar_pedido_bot e executar_finalizacao_automatica ligam a marca
# abaixo): sem alerta e sem caixas depois de gravar; imprime sempre (um clique só).
# =====================================================
_finalizacao_automatica_ativa = False
# False = alerta só com endereço de entrega (regra combinada). True = alerta em TODO pedido manual
# sem telefone, inclusive retirada / endereço vazio.
ALERTA_TELEFONE_TAMBEM_NA_RETIRADA = False


def _alerta_telefone_vazio():
    """
    Aviso vermelho e piscante: o telefone está vazio num pedido com endereço.
    NÃO é trava: retorna True se o operador clicou "SIM" (segue sem telefone) e
    False em qualquer outro caso (botão NÃO, Enter, Esc ou fechar a janela).
    "NÃO" já nasce selecionado. O campo e_telefone pisca junto com a janela.
    """
    resultado = {"seguir": False}
    estado = {"on": False, "timer": None, "aberta": True}
    cor_a, cor_b = "#B71C1C", "#FF1744"

    # --- estilos do campo telefone (se algo falhar, só não pisca o campo) ---
    estilo_original = ""
    campo_pode_piscar = False
    try:
        estilo_original = str(e_telefone.cget("style") or "")
        st = ttk.Style()
        for nome_st, cor_fundo in (("AlertaTelA.TEntry", "#FF8A80"), ("AlertaTelB.TEntry", "#FFFFFF")):
            st.configure(nome_st, fieldbackground=cor_fundo, bordercolor="#D50000",
                         lightcolor="#D50000", darkcolor="#D50000")
            st.map(nome_st,
                   fieldbackground=[("!disabled", cor_fundo)],
                   bordercolor=[("!disabled", "#D50000")],
                   lightcolor=[("!disabled", "#D50000")],
                   darkcolor=[("!disabled", "#D50000")])
        campo_pode_piscar = True
    except Exception as erro_estilo:
        print(f"[ALERTA_TEL] Nao consegui preparar o pisca do campo: {erro_estilo}")

    win = tk.Toplevel(root)
    win.title("ATENÇÃO - TELEFONE NÃO PREENCHIDO")
    win.configure(bg=cor_a)
    win.resizable(False, False)

    fundos = [win]
    quadro = tk.Frame(win, bg=cor_a)
    quadro.pack(padx=28, pady=22)
    fundos.append(quadro)

    lbl_topo = tk.Label(quadro, text="⚠  ATENÇÃO  ⚠", bg=cor_a, fg="#FFFFFF",
                        font=("Segoe UI", 20, "bold"))
    lbl_topo.pack()
    fundos.append(lbl_topo)
    lbl_msg = tk.Label(
        quadro,
        text="O campo TELEFONE está VAZIO!\n\nSem telefone não será possível\ncontatar o cliente deste pedido.\n\n"
             "Deseja finalizar mesmo assim?",
        bg=cor_a, fg="#FFFFFF", font=("Segoe UI", 13, "bold"), justify="center")
    lbl_msg.pack(pady=(10, 16))
    fundos.append(lbl_msg)

    def _parar_timer():
        estado["aberta"] = False
        if estado["timer"] is not None:
            try:
                root.after_cancel(estado["timer"])
            except Exception:
                pass
            estado["timer"] = None

    def _fechar(seguir):
        if not estado["aberta"]:
            return
        resultado["seguir"] = bool(seguir)
        _parar_timer()
        try:
            e_telefone.configure(style=estilo_original)   # devolve a aparência original
        except Exception:
            pass
        try:
            win.destroy()
        except Exception:
            pass

    botoes = tk.Frame(quadro, bg=cor_a)
    botoes.pack()
    fundos.append(botoes)
    btn_nao = tk.Button(botoes, text="NÃO - voltar e preencher", bg="#FFFFFF", fg="#B71C1C",
                        activebackground="#FFEBEE", activeforeground="#B71C1C",
                        font=("Segoe UI", 12, "bold"), relief="solid", bd=3, padx=16, pady=8,
                        cursor="hand2", highlightthickness=3, highlightbackground="#FFFFFF",
                        highlightcolor="#FFEB3B", command=lambda: _fechar(False))
    btn_nao.pack(side="left", padx=(0, 14))
    btn_sim = tk.Button(botoes, text="SIM - finalizar sem telefone", bg="#4E0000", fg="#FFFFFF",
                        activebackground="#6D0000", activeforeground="#FFFFFF",
                        font=("Segoe UI", 10, "bold"), relief="flat", bd=0, padx=12, pady=8,
                        cursor="hand2", command=lambda: _fechar(True))
    btn_sim.pack(side="left")

    def _pisca():
        if not estado["aberta"]:
            return
        estado["on"] = not estado["on"]
        cor = cor_a if estado["on"] else cor_b
        for w in fundos:
            try:
                w.configure(bg=cor)
            except Exception:
                pass
        if campo_pode_piscar:
            try:
                e_telefone.configure(style="AlertaTelA.TEntry" if estado["on"] else "AlertaTelB.TEntry")
            except Exception:
                pass
        estado["timer"] = root.after(350, _pisca)

    # Enter só confirma "SIM" se o foco estiver no botão SIM; em qualquer outro caso = NÃO
    win.bind("<Return>", lambda e: _fechar(e.widget is btn_sim))
    win.bind("<Escape>", lambda e: _fechar(False))
    win.protocol("WM_DELETE_WINDOW", lambda: _fechar(False))

    try:
        win.update_idletasks()
        w, h = win.winfo_reqwidth(), win.winfo_reqheight()
        x = root.winfo_rootx() + max((root.winfo_width() - w) // 2, 0)
        y = root.winfo_rooty() + max((root.winfo_height() - h) // 2, 0)
        win.geometry(f"+{x}+{y}")
    except Exception:
        pass
    trazer_janela_para_frente(win)
    try:
        winsound.MessageBeep(winsound.MB_ICONHAND)
    except Exception:
        pass
    try:
        win.wait_visibility()
        win.grab_set()
    except Exception:
        pass
    try:
        btn_nao.focus_force()
    except Exception:
        pass
    _pisca()
    try:
        root.wait_window(win)
    finally:
        _parar_timer()
        try:
            e_telefone.configure(style=estilo_original)
        except Exception:
            pass
    if not resultado["seguir"]:
        try:
            e_telefone.focus_set()
        except Exception:
            pass
    return resultado["seguir"]


def _estoque_baixo_previsto():
    """
    Itens que ficariam com 3 unidades ou menos se o pedido da tela fosse gravado agora.
    Só LÊ o banco (nada é alterado). Em edição, conta a devolução dos itens antigos do pedido,
    igual ao que o finalizar_pedido faz ao gravar. Retorna lista de (nome, quantidade_restante).
    """
    pedido_qtd, nomes = {}, {}
    for it in pedido_itens:
        pedido_qtd[it[0]] = pedido_qtd.get(it[0], 0) + it[2]
        nomes[it[0]] = it[1]
    devolvido = {}
    if pedido_em_edicao:
        cursor.execute("SELECT codigo, quantidade FROM itens_pedido WHERE pedido_id=?", (pedido_em_edicao,))
        for cod, q in cursor.fetchall():
            devolvido[cod] = devolvido.get(cod, 0) + (q or 0)
    baixo = []
    for codigo, qtd in pedido_qtd.items():
        cursor.execute("SELECT quantidade FROM estoque WHERE codigo=?", (codigo,))
        r = cursor.fetchone()
        if not r:
            continue
        apos = (r[0] or 0) + devolvido.get(codigo, 0) - qtd
        if apos <= 3:
            baixo.append((nomes[codigo], apos))
    return baixo


def _janela_confirmar_finalizacao(info, estoque_baixo):
    """
    Caixa ÚNICA, mostrada ANTES de gravar. Nada é salvo, cobrado ou impresso até o clique.
    Substitui: aviso de estoque baixo (um por item), "Deseja imprimir o pedido?",
    "Deseja imprimir o cupom?" e "Pedido finalizado".
    Retorna "imprimir" (grava + gera o Pix do Mercado Pago + imprime), "salvar" (só grava)
    ou "voltar" (não grava nada; volta para corrigir). Esc / fechar no X = "voltar".
    """
    escolha = {"v": "voltar"}
    editando = info.get("edicao_id")
    win = tk.Toplevel(root)
    titulo = f"Confirmar alterações do Pedido #{editando}" if editando else "Confirmar pedido"
    win.title(titulo)
    win.configure(bg="#FFFFFF")
    win.resizable(False, False)

    tk.Label(win, text=titulo, bg="#FFFFFF", fg="#263238",
             font=("Segoe UI", 14, "bold")).pack(padx=26, pady=(16, 8))

    def _brl(v):
        try:
            return "R$ " + f"{float(v):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return str(v)

    resumo = tk.Frame(win, bg="#F5F7F8", highlightthickness=1, highlightbackground="#CFD8DC")
    resumo.pack(fill="x", padx=22, pady=(0, 6))
    tel_txt = info.get("telefone") or ("NÃO INFORMADO" if info.get("tel_alerta") else "—")
    linhas = [
        ("Cliente:", info.get("cliente") or "—", "#263238"),
        ("Endereço:", info.get("endereco") or "—", "#263238"),
        ("Telefone:", tel_txt, "#C62828" if (info.get("tel_alerta") and not info.get("telefone")) else "#263238"),
        ("Pagamento:", info.get("pagamento") or "—", "#263238"),
        ("Total:", _brl(info.get("total", 0)), "#2E7D32"),
    ]
    for i, (rot, val, cor) in enumerate(linhas):
        tk.Label(resumo, text=rot, bg="#F5F7F8", fg="#607D8B", font=("Segoe UI", 10, "bold"),
                 anchor="ne").grid(row=i, column=0, sticky="ne", padx=(10, 6), pady=2)
        tk.Label(resumo, text=val, bg="#F5F7F8", fg=cor, font=("Segoe UI", 10, "bold"),
                 wraplength=300, justify="left", anchor="nw").grid(row=i, column=1, sticky="nw", padx=(0, 10), pady=2)

    if estoque_baixo:
        caixa = tk.Frame(win, bg="#FFF3E0", highlightthickness=1, highlightbackground="#FB8C00")
        caixa.pack(fill="x", padx=22, pady=(6, 4))
        if len(estoque_baixo) == 1:
            nome, qtd = estoque_baixo[0]
            tk.Label(caixa, text=f"⚠ Estoque baixo: '{nome}' vai ficar com apenas {qtd} unidade(s)!",
                     bg="#FFF3E0", fg="#E65100", font=("Segoe UI", 10, "bold"),
                     wraplength=380, justify="left").pack(anchor="w", padx=10, pady=8)
        else:
            tk.Label(caixa, text=f"⚠ Estoque baixo em {len(estoque_baixo)} itens:",
                     bg="#FFF3E0", fg="#E65100", font=("Segoe UI", 10, "bold")).pack(anchor="w", padx=10, pady=(8, 2))
            linha_lista = tk.Frame(caixa, bg="#FFF3E0")
            linha_lista.pack(fill="x", padx=10, pady=(0, 8))
            lista = tk.Listbox(linha_lista, height=min(len(estoque_baixo), 8), width=46,
                               font=("Segoe UI", 10), bg="#FFF3E0", fg="#BF360C",
                               bd=0, highlightthickness=0, activestyle="none",
                               selectbackground="#FFF3E0", selectforeground="#BF360C")
            for nome, qtd in estoque_baixo:
                lista.insert("end", f"• {nome} — {qtd} un.")
            lista.pack(side="left", fill="x", expand=True)
            if len(estoque_baixo) > 8:
                barra = tk.Scrollbar(linha_lista, orient="vertical", command=lista.yview)
                lista.configure(yscrollcommand=barra.set)
                barra.pack(side="right", fill="y")

    tk.Label(win, text="Nada é salvo até você escolher uma opção abaixo.\n"
                       "“Salvar e imprimir” também gera o Pix do Mercado Pago.",
             bg="#FFFFFF", fg="#546E7A", font=("Segoe UI", 9), justify="center").pack(pady=(8, 8))

    def _fechar(v):
        escolha["v"] = v
        try:
            win.destroy()
        except Exception:
            pass

    botoes = tk.Frame(win, bg="#FFFFFF")
    botoes.pack(pady=(0, 18), padx=14)
    btn_imp = tk.Button(botoes, text="🖨️ Salvar e imprimir", bg="#2E7D32", fg="#FFFFFF",
                        activebackground="#388E3C", activeforeground="#FFFFFF",
                        font=("Segoe UI", 11, "bold"), relief="flat", bd=0, padx=14, pady=8,
                        cursor="hand2", command=lambda: _fechar("imprimir"))
    btn_imp.pack(side="left", padx=(0, 8))
    btn_sal = tk.Button(botoes, text="💾 Só salvar", bg="#ECEFF1", fg="#37474F",
                        activebackground="#CFD8DC", activeforeground="#37474F",
                        font=("Segoe UI", 11, "bold"), relief="flat", bd=0, padx=14, pady=8,
                        cursor="hand2", command=lambda: _fechar("salvar"))
    btn_sal.pack(side="left", padx=(0, 8))
    btn_vol = tk.Button(botoes, text="↩ Voltar e corrigir", bg="#FFF3E0", fg="#E65100",
                        activebackground="#FFE0B2", activeforeground="#E65100",
                        font=("Segoe UI", 11, "bold"), relief="flat", bd=0, padx=14, pady=8,
                        cursor="hand2", command=lambda: _fechar("voltar"))
    btn_vol.pack(side="left")

    def _enter(e):
        if e.widget is btn_vol:
            _fechar("voltar")
        elif e.widget is btn_sal:
            _fechar("salvar")
        else:
            _fechar("imprimir")

    win.bind("<Return>", _enter)
    win.bind("<Escape>", lambda e: _fechar("voltar"))
    win.protocol("WM_DELETE_WINDOW", lambda: _fechar("voltar"))

    try:
        win.update_idletasks()
        w, h = win.winfo_reqwidth(), win.winfo_reqheight()
        x = root.winfo_rootx() + max((root.winfo_width() - w) // 2, 0)
        y = root.winfo_rooty() + max((root.winfo_height() - h) // 2, 0)
        win.geometry(f"+{x}+{y}")
    except Exception:
        pass
    trazer_janela_para_frente(win)
    try:
        win.wait_visibility()
        win.grab_set()
    except Exception:
        pass
    try:
        btn_imp.focus_force()
    except Exception:
        pass
    root.wait_window(win)
    return escolha["v"]


def finalizar_pedido():
    global pedido_itens, pedido_em_edicao

    cursor.execute("SELECT changes()")
    print("Linhas afetadas:", cursor.fetchone()[0])

    # 1. VERIFICAÇÕES DE SEGURANÇA
    if not ciclo_caixa_aberto or not ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Caixa Fechado", "Você precisa ABRIR O CAIXA antes de lançar pedidos!")
        return

    if not pedido_itens:
        messagebox.showwarning("Aviso", "Não há itens no pedido")
        return

    cliente = e_cliente.get().strip()
    endereco = e_endereco.get().strip()
    telefone = e_telefone.get().strip()
    pagamento = cb_pag.get().strip()
    observacao = limpar_observacao_telefone(e_observacao.get().strip())
    observacao_db = anexar_telefone_observacao(observacao, telefone)
    
    # Captura o Ajuste (Trata erro se o campo estiver vazio ou com letras)
    try:
        # Substitui vírgula por ponto para o banco de dados entender
        valor_ajuste = float(e_ajuste.get().replace(",", ".") or 0)
    except ValueError:
        messagebox.showerror("Erro", "Valor de Ajuste inválido! Use apenas números (Ex: -5.00 ou 5.00)")
        return

    if not cliente or not pagamento:
        messagebox.showwarning("Aviso", "Preencha cliente e pagamento")
        return

    # 🧑‍🍳 Verifica se o pedido é de um funcionário (desconto do valor semanal)
    servidor_vinculado = buscar_servidor_por_codigo(cliente)
    if pagamento == "Funcionário" and not servidor_vinculado:
        messagebox.showwarning(
            "Aviso",
            "A forma de pagamento está como 'Funcionário', mas o campo Cliente\n"
            "não corresponde a nenhum código de servidor cadastrado.\n\n"
            "Digite o código correto ou escolha outra forma de pagamento."
        )
        return

    # 📞 RETIRADA + ALERTA DE TELEFONE (SÓ pedido digitado à mão; pedido do site/bot
    # passa direto, exatamente como sempre foi).
    #  - endereço vazio  -> grava "Retirada" (assim não vai para o app de entrega)
    #  - endereço de entrega (não retirada) com telefone vazio -> aviso vermelho, sem trava
    sem_telefone_confirmado = False
    if not _finalizacao_automatica_ativa:
        if not endereco:
            endereco = "Retirada"
        if not telefone and (ALERTA_TELEFONE_TAMBEM_NA_RETIRADA or not endereco_e_retirada(endereco)):
            try:
                seguir_sem_telefone = _alerta_telefone_vazio()
            except Exception as erro_alerta:
                print(f"[ALERTA_TEL] Falha no alerta vermelho, usando aviso simples: {erro_alerta}")
                seguir_sem_telefone = messagebox.askyesno(
                    "ATENÇÃO - TELEFONE VAZIO",
                    "O campo TELEFONE está VAZIO!\n\nDeseja finalizar mesmo assim?",
                    icon="warning", default="no")
            if not seguir_sem_telefone:
                return
            sem_telefone_confirmado = True

    # 🚚 TAXA DE ENTREGA AUTOMATICA (ver _taxa_entrega_automatica)
    # So pedido novo, so com Ajuste vazio/"0", e nunca em retirada.
    _taxa_auto = _taxa_entrega_automatica()
    if _taxa_auto > 0:
        valor_ajuste = _taxa_auto

    # Cálculo do total (Soma dos itens + Ajuste)
    total_produtos = sum(i[2] * i[4] for i in pedido_itens)
    total_final = total_produtos + valor_ajuste

    # 🧾 CAIXA ÚNICA ANTES DE GRAVAR (só pedido digitado à mão; site/bot segue o fluxo antigo).
    # Nada é salvo, cobrado ou impresso até o operador escolher. "Voltar" = não grava nada.
    escolha_final = "salvar"
    precalc_estoque_ok = False
    if not _finalizacao_automatica_ativa:
        estoque_previsto = []
        try:
            estoque_previsto = _estoque_baixo_previsto()
            precalc_estoque_ok = True
        except Exception as erro_prev:
            print(f"[FINALIZAR] Nao consegui prever o estoque baixo (avisa depois de gravar): {erro_prev}")
        info_confirma = {
            "edicao_id": pedido_em_edicao,
            "cliente": cliente,
            "endereco": endereco,
            "telefone": telefone,
            "tel_alerta": (not telefone) and not endereco_e_retirada(endereco),
            "pagamento": pagamento,
            "total": total_final,
        }
        try:
            escolha_final = _janela_confirmar_finalizacao(info_confirma, estoque_previsto)
        except Exception as erro_caixa:
            print(f"[FINALIZAR] Falha na caixa unica, usando pergunta simples: {erro_caixa}")
            try:
                r_simples = messagebox.askyesnocancel(
                    "Finalizar pedido",
                    "Salvar o pedido?\n\nSim = salvar e imprimir\nNão = só salvar\nCancelar = voltar e corrigir")
                escolha_final = "imprimir" if r_simples is True else ("salvar" if r_simples is False else "voltar")
            except Exception as erro_simples:
                print(f"[FINALIZAR] Falha tambem na pergunta simples: {erro_simples}")
                escolha_final = "voltar"
        if escolha_final == "voltar":
            try:
                e_cliente.focus_set()
            except Exception:
                pass
            return
    
    data_agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    id_ciclo_atual = ciclo_caixa_aberto.get("id")
    estoque_baixo_aviso = {}   # pedido manual: junta os itens e mostra tudo na caixa única

    try:
        if pedido_em_edicao:
            # --- LÓGICA DE EDIÇÃO ---
            pedido_id = pedido_em_edicao
            
            # 1. Busca valor antigo para estornar do saldo do caixa
            cursor.execute("SELECT cliente, pagamento, total, observacao FROM pedidos WHERE id = ?", (pedido_id,))
            dados_antigos_pedido = cursor.fetchone()
            cursor.execute("SELECT total, pagamento FROM pedidos WHERE id = ?", (pedido_id,))
            res_antigo = cursor.fetchone()
            v_antigo = 0.0
            p_antigo = "Pendente"
            if res_antigo:
                v_antigo, p_antigo = res_antigo
                v_antigo = float(v_antigo or 0)
            
            # 3. Devolve o estoque dos itens antigos antes de gravar os novos
            cursor.execute("SELECT codigo, quantidade FROM itens_pedido WHERE pedido_id=?", (pedido_id,))
            for cod_ant, qtd_ant in cursor.fetchall():
                cursor.execute("UPDATE estoque SET quantidade = quantidade + ? WHERE codigo=?", (qtd_ant, cod_ant))
            
            # 4. Limpa itens antigos e atualiza a capa do pedido (agora com campo ajuste)
            cursor.execute("DELETE FROM itens_pedido WHERE pedido_id=?", (pedido_id,))
            cursor.execute("""
                UPDATE pedidos 
                SET cliente=?, endereco=?, pagamento=?, total=?, observacao=?, ajuste=?
                WHERE id=?
            """, (cliente, endereco, pagamento, total_final, observacao_db, valor_ajuste, pedido_id))
        
        else:
            # --- NOVO PEDIDO ---
            cursor.execute("""
                INSERT INTO pedidos (
                    data,
                    cliente,
                    endereco,
                    pagamento,
                    total,
                    ciclo_caixa_id,
                    observacao,
                    ajuste
                ) 
                VALUES (?,?,?,?,?,?,?,?)
            """, (
                data_agora,
                cliente,
                endereco,
                pagamento,
                total_final,
                id_ciclo_atual,
                observacao_db,
                valor_ajuste
            ))
            
            pedido_id = cursor.lastrowid

        # 2. INSERÇÃO DOS ITENS E BAIXA DE ESTOQUE
        for item in pedido_itens:
            codigo, nome, qtd, custo, venda = item
            # Grava o custo e venda do MOMENTO (Protege o passado)
            cursor.execute("""
                INSERT INTO itens_pedido (pedido_id, codigo, produto, quantidade, custo, venda) 
                VALUES (?, ?, ?, ?, ?, ?)
            """, (pedido_id, codigo, nome, qtd, custo, venda))
            
            # Executa a baixa de estoque
            cursor.execute("UPDATE estoque SET quantidade = quantidade - ? WHERE codigo=?", (qtd, codigo))

            # --- VERIFICAÇÃO DE ESTOQUE BAIXO (Simples) ---
            cursor.execute("SELECT quantidade FROM estoque WHERE codigo=?", (codigo,))
            estoque_apos_venda = cursor.fetchone()[0]
            if estoque_apos_venda <= 3:
                # nunca abre caixa aqui (a transação ainda está aberta): só anota.
                # Manual: a caixa única já avisou antes de gravar. Site/bot: a janela
                # "Confirmar e imprimir" já mostrou o aviso de estoque baixo.
                estoque_baixo_aviso[codigo] = (nome, estoque_apos_venda)

        # 3. LANCAMENTO NO CAIXA (REGRA 6: editar pedido nunca altera lançamento
        #    antigo; aumento gera nova ENTRADA, redução gera nova SAIDA, ambos
        #    identificados como "Ajuste Financeiro" e nunca sobrescrevem o histórico)
        # "Funcionário" NUNCA gera entrada de caixa: o valor é descontado
        # diretamente do saldo semanal do servidor (ver bloco 3B abaixo).
        FORMAS_SEM_ENTRADA_CAIXA = ["Pendente", "Descarte", "CANCELADO", "Funcionário", ""]

        if pedido_em_edicao:
            valor_financeiro_antigo = v_antigo if p_antigo not in FORMAS_SEM_ENTRADA_CAIXA else 0.0
            valor_financeiro_novo = total_final if pagamento not in FORMAS_SEM_ENTRADA_CAIXA else 0.0
            diferenca_caixa = round(float(valor_financeiro_novo or 0) - float(valor_financeiro_antigo or 0), 2)

            if diferenca_caixa != 0:
                tipo_caixa = "ENTRADA" if diferenca_caixa > 0 else "SAIDA"
                forma_caixa = pagamento if diferenca_caixa > 0 else (p_antigo or pagamento)
                registrar_lancamento_caixa(
                    tipo_caixa, f"Ajuste Financeiro Pedido #{pedido_id}", abs(diferenca_caixa), forma_caixa,
                    pedido_id=pedido_id
                )

            # REGRA 5: valor_pago sempre reflete exatamente o total já recebido
            # (aqui o pedido é tratado como pago integralmente ao ser confirmado
            # com uma forma de pagamento real, e não fica pendente novamente;
            # "Funcionário" também conta como pago, só que via desconto salarial)
            novo_valor_pago = total_final if pagamento not in ["Pendente", "Descarte"] else 0.0
            cursor.execute("UPDATE pedidos SET valor_pago=? WHERE id=?", (novo_valor_pago, pedido_id))

        elif pagamento not in FORMAS_SEM_ENTRADA_CAIXA:
            registrar_lancamento_caixa("ENTRADA", f"Pedido #{pedido_id}", total_final, pagamento, pedido_id=pedido_id)
            cursor.execute("UPDATE pedidos SET valor_pago=? WHERE id=?", (total_final, pedido_id))
        elif pagamento == "Funcionário":
            # Pedido de funcionário: não é "Pendente" de verdade, é pago via
            # desconto salarial (tratado no bloco 3B logo abaixo).
            cursor.execute("UPDATE pedidos SET valor_pago=? WHERE id=?", (total_final, pedido_id))

        # 3B. CONSUMO DE FUNCIONÁRIO (desconto automático do valor semanal)
        # Se este pedido já tinha um consumo vinculado a um servidor (caso de
        # edição), primeiro devolve o valor antigo ao saldo dele antes de
        # aplicar o novo valor — evita duplicar ou perder desconto.
        cursor.execute("SELECT id_servidor, valor FROM consumos_servidores WHERE pedido_id=?", (pedido_id,))
        consumo_antigo = cursor.fetchone()
        if consumo_antigo:
            id_serv_antigo, valor_antigo_consumo = consumo_antigo
            cursor.execute("DELETE FROM consumos_servidores WHERE pedido_id=?", (pedido_id,))
            # Saldo do servidor é recalculado a partir das tabelas (fonte única)
            recalcular_falta_pagar(id_serv_antigo)

        if pagamento == "Funcionário" and servidor_vinculado:
            id_serv, nome_serv, _falta_atual = servidor_vinculado
            cursor.execute("""
                INSERT INTO consumos_servidores (id_servidor, pedido_id, valor, data, observacao)
                VALUES (?, ?, ?, ?, ?)
            """, (id_serv, pedido_id, total_final, data_agora, f"Pedido #{pedido_id}"))
            recalcular_falta_pagar(id_serv)
            registrar_log("CONSUMO_FUNCIONARIO", "SERVIDORES", id_serv, {
                "servidor": nome_serv, "pedido_id": pedido_id, "valor": total_final
            })

        _ref_tree_serv = globals().get('_atualizar_tree_servidores_ref')
        if callable(_ref_tree_serv):
            try:
                _ref_tree_serv()
            except Exception:
                pass

        conn.commit()
        if pedido_em_edicao:
            registrar_log("PEDIDO_EDITADO", "PEDIDOS", pedido_id, {"antes": dados_antigos_pedido, "depois": {"cliente": cliente, "pagamento": pagamento, "total": total_final, "observacao": observacao}, "valor_anterior": dados_antigos_pedido[2] if dados_antigos_pedido else None, "valor_novo": total_final, "pagamento_anterior": dados_antigos_pedido[1] if dados_antigos_pedido else None, "pagamento_novo": pagamento, "cliente_anterior": dados_antigos_pedido[0] if dados_antigos_pedido else None, "cliente_novo": cliente})
            if dados_antigos_pedido and dados_antigos_pedido[1] != pagamento:
                registrar_log("ALTERACAO_PAGAMENTO", "PEDIDOS", pedido_id, {"forma_antiga": dados_antigos_pedido[1], "forma_nova": pagamento})
            if dados_antigos_pedido and float(dados_antigos_pedido[2] or 0) != float(total_final or 0):
                registrar_log("ALTERACAO_VALOR", "PEDIDOS", pedido_id, {"valor_anterior": dados_antigos_pedido[2], "valor_novo": total_final})
            # 💳 Se existia QR Pix gerado (pedido ou grupo de Contas a Receber) e o valor/forma
            # mudou, a cobranca antiga nao vale mais: cancela (inclusive no Mercado Pago) e avisa.
            try:
                sincronizar_cobrancas_pix_pendentes(pedido_ids=[int(pedido_id)], avisar=True)
            except Exception as erro_pix:
                print(f"[PIX_RECEBER] Falha ao sincronizar cobrancas Pix do pedido #{pedido_id}: {erro_pix}")
            # 🧾 Pix da NOTA / "Copiar chave Pix" (endpoint /api/mercadopago/pix): nao fica em
            # contas_receber_pix_pendentes, entao a sincronizacao acima nao o enxerga.
            # Se o valor mudou (ou o pedido passou a ser pago por outra forma), derruba o QR antigo.
            try:
                _valor_mudou = abs(float(v_antigo or 0) - float(total_final or 0)) > 0.009
                _quitado_outra_forma = (str(p_antigo or "").strip().lower() == "pendente"
                                        and str(pagamento or "").strip().lower() != "pendente")
                if _valor_mudou or _quitado_outra_forma:
                    res_nota = cancelar_pix_nota_mercado_pago(pedido_id, "pedido_editado")
                    registrar_log("PEDIDO_PIX_NOTA_CANCELADO", "FINANCEIRO", pedido_id, {
                        "resultado": res_nota, "valor_anterior": v_antigo, "valor_novo": total_final})
                    if res_nota is None:
                        messagebox.showwarning(
                            "Pix da nota",
                            f"Nao consegui cancelar o QR Pix antigo do pedido #{pedido_id} no Mercado Pago "
                            "(servidor indisponivel?).\n\nSe a nota antiga ja foi impressa ou enviada, "
                            "o cliente ainda pode pagar o valor ANTIGO. Recolha a nota antiga e tente de novo.")
                    elif res_nota == "pago":
                        messagebox.showwarning(
                            "Pix ja pago",
                            f"ATENCAO: o cliente ja PAGOU o Pix antigo do pedido #{pedido_id} "
                            f"(R$ {float(v_antigo or 0):.2f}).\n\nConfira o saldo do pedido: o valor novo e "
                            f"R$ {float(total_final or 0):.2f}.")
            except Exception as erro_nota:
                print(f"[MP] Falha ao tratar o Pix da nota do pedido #{pedido_id}: {erro_nota}")
        else:
            registrar_log("PEDIDO_CRIADO", "PEDIDOS", pedido_id, {"cliente": cliente, "valor": total_final, "pagamento": pagamento, "data": data_agora[:10], "hora": data_agora[11:19], "id_pedido": pedido_id})

        # 🔵 PRIMEIRO: Salva no cadastro local (Garante o telefone no HD)
        cliente_memoria = e_cliente.get().strip()
        endereco_memoria = e_endereco.get().strip()
        telefone_memoria = e_telefone.get().strip()
        
        if cliente_memoria:
            salvar_cliente(
                cliente_memoria,
                endereco_memoria,
                telefone_memoria
            )

        # 👥 Base nova de clientes (clientes.db): UMA vez por pedido NOVO (edição não conta de novo).
        # Cliente = telefone; nome entra como apelido; endereço novo se acumula; nada é sobrescrito.
        # Nunca dá erro: sem telefone válido ou com qualquer falha, simplesmente não grava.
        if cliente_memoria and not pedido_em_edicao:
            cdb_registrar_pedido(cliente_memoria, endereco_memoria, telefone_memoria)

        # 🟢 SEGUNDO: Envia para o aplicativo (telefone digitado no pedido)
        enviar_pedido_para_entrega(
            pedido_id,
            cliente,
            endereco,
            pagamento,
            total_final,
            observacao,
            list(pedido_itens),
            telefone=telefone_memoria
        )

        # 4. IMPRESSÃO
        if _finalizacao_automatica_ativa:
            # pedido do site/bot: um clique só (o da janela "Confirmar e imprimir").
            # Sem caixas aqui e SEM opção de só salvar: imprime sempre (mesma rotina que a
            # gerar_nota() chamava após o "Sim": gera o Pix do Mercado Pago e imprime o cupom).
            try:
                imprimir_cupom_pedido(pedido_id)
            except Exception as erro_imp_site:
                print(f"[FINALIZAR] Falha ao imprimir o pedido do site #{pedido_id}: {erro_imp_site}")
                try:
                    messagebox.showerror("Erro de Impressão", f"O pedido #{pedido_id} foi salvo, mas a impressão falhou:\n{erro_imp_site}")
                except Exception:
                    pass
        else:
            # pedido digitado à mão: o operador já escolheu na caixa única, ANTES de gravar.
            # O pedido já está gravado (commit feito); nada abaixo pode impedir a limpeza da tela.
            if sem_telefone_confirmado:
                try:
                    registrar_log("PEDIDO_SEM_TELEFONE_CONFIRMADO", "PEDIDOS", pedido_id,
                                  {"cliente": cliente, "endereco": endereco})
                except Exception:
                    pass
            # se a previsão de estoque falhou antes de gravar, avisa agora (uma única caixa)
            if not precalc_estoque_ok and estoque_baixo_aviso:
                try:
                    linhas_baixo = "\n".join(f"• {n} — {q} un." for n, q in estoque_baixo_aviso.values())
                    messagebox.showwarning("Estoque Baixo", f"Estoque baixo:\n{linhas_baixo}")
                except Exception:
                    pass
            if escolha_final == "imprimir":
                try:
                    # mesma rotina que a gerar_nota() chamava depois do "Sim": gera o Pix do
                    # Mercado Pago (obter_pix_mercado_pago_para_nota) e imprime o cupom
                    imprimir_cupom_pedido(pedido_id)
                except Exception as erro_imp:
                    print(f"[FINALIZAR] Falha ao imprimir o pedido #{pedido_id}: {erro_imp}")
                    try:
                        messagebox.showerror("Erro de Impressão", f"O pedido #{pedido_id} foi salvo, mas a impressão falhou:\n{erro_imp}")
                    except Exception:
                        pass
        
        # 🔵 SALVA CLIENTE E ENDEREÇO ANTES DE LIMPAR
        cliente_memoria = e_cliente.get().strip()
        endereco_memoria = e_endereco.get().strip()
        telefone_memoria = e_telefone.get().strip()
        
        if cliente_memoria:
            salvar_cliente(
                cliente_memoria,
                endereco_memoria,
                telefone_memoria
            )
        
        # 5. LIMPEZA TOTAL DA TELA
        pedido_itens.clear()
        pedido_em_edicao = None
        
        e_cliente.delete(0, "end")
        e_endereco.delete(0, "end")
        e_telefone.delete(0, "end")
        e_observacao.delete(0, "end")
        
        e_ajuste.delete(0, "end")
        e_ajuste.insert(0, "0") # Volta para zero
        
        atualizar_total_pedido()
        
        atualizar_lista_temp()
        listar_estoque()
        carregar_produtos()
        carregar_historico() 
        
        if 'carregar_receitas_caixa' in globals():
            carregar_receitas_caixa()
        elif 'carregar_receitas' in globals(): 
            carregar_receitas() 

        _limpar_marca_pedido_do_site()
        pedido_em_tela = False 
        print("🚀 Tela liberada! Buscando próximo pedido da fila...")

    except Exception as e:
        conn.rollback()
        messagebox.showerror("Erro", f"Falha ao finalizar o pedido: {e}")


btn_add = ttk.Button(frame_botoes, text="Adicionar Item", command=adicionar_item)
btn_add.pack(side="left", padx=5)

