# ================= BOT INTEGRAÇÃO AUTOMÁTICA - CORRIGIDO =================

def adicionar_item_bot_interface(codigo, qtd):
    """Adiciona o item enviado pelo Bot diretamente no pedido, ignorando combobox."""
    try:
        cursor.execute("SELECT produto, custo, venda, quantidade FROM estoque WHERE codigo=?", (codigo,))
        res = cursor.fetchone()
        if not res:
            print(f"⚠️ Erro Bot: Produto {codigo} não encontrado no estoque.")
            return

        nome, custo, venda, est = res

        # Verifica estoque
        if qtd > est:
            print(f"⚠️ Estoque insuficiente para {nome}. Pedido ignorado.")
            return

        # Adiciona diretamente na lista interna
        pedido_itens.append([codigo, nome, qtd, custo, venda])

        # Atualiza a interface
        atualizar_lista_temp()
        atualizar_total_pedido()

    except Exception as e:
        print(f"❌ Erro ao adicionar item via Bot: {e}")

def finalizar_pedido_bot(dados):
    """
    Processa o pedido vindo do WhatsApp garantindo a limpeza 
    dos dados anteriores e automação total.
    """
    print(f"🤖 PROCESSANDO PEDIDO: {dados.get('cliente')}")

    # 1. LIMPEZA TOTAL ANTES DE COMEÇAR (Evita mesclar pedidos)
    pedido_itens.clear()
    
    atualizar_lista_temp()
    
    e_cliente.delete(0, "end")
    e_endereco.delete(0, "end")
    e_telefone.delete(0, "end")
    e_observacao.delete(0, "end")
    
    e_ajuste.delete(0, "end")
    e_ajuste.insert(0, "0")

    # 2. PREENCHIMENTO DOS DADOS DO NOVO PEDIDO
    e_cliente.insert(0, dados.get("cliente", "Cliente WhatsApp"))
    e_endereco.insert(0, dados.get("endereco", ""))
    e_telefone.insert(0, str(dados.get("telefone", "") or dados.get("fone", "")).strip())
    cb_pag.set("Pendente") # Padrão para pedidos automáticos
    e_observacao.insert(0, dados.get("obs", "Vindo do Bot"))

    # 3. ADIÇÃO DOS ITENS
    for item in dados.get("itens", []):
        adicionar_item_bot_interface(item["nome_id"], item["qtd"])

    # 4. VALIDAÇÃO DE CAIXA (Segurança para não travar)
    global ciclo_caixa_aberto
    if not ciclo_caixa_aberto or not ciclo_caixa_aberto.get("id"):
        print("🚨 BOT AVISO: Tentativa de pedido com caixa fechado. Ignorando trava para o Bot.")
        # Se você quiser que o bot abra o caixa sozinho, precisaria de uma lógica aqui.

    # 5. FINALIZAÇÃO E IMPRESSÃO
    # Usamos o root.after para garantir que o Tkinter processe a interface
    root.after(100, lambda: executar_finalizacao_automatica())

def executar_finalizacao_automatica():
    """Chama a função oficial de finalizar e garante a impressão"""
    # Salva o ID atual antes de limpar para poder imprimir
    global _finalizacao_automatica_ativa
    _finalizacao_automatica_ativa = True   # fluxo automatico: comportamento antigo
    try:
        finalizar_pedido()
    finally:
        _finalizacao_automatica_ativa = False
    
    # Se a caixa de impressão automática estiver marcada, 
    # o finalizar_pedido() já chamará a gerar_nota(pedido_id) 
    # pois você já tem essa lógica dentro da sua finalizar_pedido original.
    print("✅ Pedido do Bot Finalizado com Sucesso.")

def processar_pedidos_bot():
    arquivos = glob.glob(os.path.join(PASTA_JSON, "*.json"))
    for arquivo in arquivos:
        with open(arquivo, 'r', encoding='utf-8') as f:
            dados = json.load(f)
        dados = normalizar_pedido_entrada(dados)
            # Use o cursor global que já está aberto no topo do script
            # Não abra outra conexão aqui!
        for item in dados.get("itens", []):
            codigo = item.get("codigo") or str(item.get("nome_id", "")).split(" - ")[0].strip()
            qtd = item.get("qtd", item.get("quantidade", 1))
            if codigo:
                adicionar_item_bot_interface(codigo, qtd)
        os.remove(arquivo) # Limpa o JSON processado

