cursor.execute("""
CREATE TABLE IF NOT EXISTS ciclos_caixa (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    abertura TEXT,
    fechamento TEXT,
    saldo_inicial REAL,
    saldo_final REAL,
    status TEXT
)
""")
conn.commit()

# =====================================================
# 🟢 CONTROLE DO CICLO ATUAL
# =====================================================
ciclo_caixa_aberto = {
    "id": None,
    "saldo_inicial": 0.0
}

# =====================================================
# 🟢 FUNÇÃO: ABRIR CAIXA
# =====================================================

def abrir_caixa():
    if ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Aviso", "O caixa já está aberto!")
        return

    # Janela customizada para pegar os dois valores
    janela_pop = tk.Toplevel(root)
    janela_pop.title("Abertura de Caixa")
    janela_pop.geometry("300x250")
    
    janela_pop.transient(root)
    janela_pop.grab_set()

    ttk.Label(janela_pop, text="Valor em DINHEIRO (R$):", font=("Arial", 10, "bold")).pack(pady=5)
    ent_din = ttk.Entry(janela_pop)
    ent_din.pack(pady=5)
    ent_din.insert(0, "0.00")

    ttk.Label(janela_pop, text="Valor em PIX (R$):", font=("Arial", 10, "bold")).pack(pady=5)
    ent_pix = ttk.Entry(janela_pop)
    ent_pix.pack(pady=5)
    ent_pix.insert(0, "0.00")

    def confirmar_abertura():
        try:
            v_din = float(ent_din.get().replace(",", "."))
            v_pix = float(ent_pix.get().replace(",", "."))
            
            data_agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            cursor.execute("""
                INSERT INTO ciclos_caixa (abertura, saldo_inicial, saldo_inicial_pix, status)
                VALUES (?, ?, ?, 'ABERTO')
            """, (data_agora, v_din, v_pix))
            conn.commit()
            id_ciclo_criado = cursor.lastrowid
            registrar_log("ABERTURA_CAIXA", "CAIXA", id_ciclo_criado, {"saldo_inicial_dinheiro": v_din, "saldo_inicial_pix": v_pix, "abertura": data_agora})
            
            # Atualiza a variável global
            ciclo_caixa_aberto["id"] = id_ciclo_criado
            ciclo_caixa_aberto["abertura"] = data_agora
            ciclo_caixa_aberto["saldo_inicial"] = v_din
            ciclo_caixa_aberto["saldo_inicial_pix"] = v_pix
            
            atualizar_saldo()
            if 'carregar_receitas_caixa' in globals():
                carregar_receitas_caixa()
            messagebox.showinfo("Sucesso", "Caixa aberto com sucesso!")
            janela_pop.destroy()
            # Pix pagos que esperavam o caixa abrir (e arquivos em erros/) entram agora.
            root.after(500, reprocessar_erros_pix_e_baixas)
            # Confirmacoes da maquininha que esperavam o caixa abrir (e as de erros/).
            root.after(700, reprocessar_erros_point)
        except ValueError:
            messagebox.showerror("Erro", "Valores inválidos!")

    ttk.Button(janela_pop, text="Confirmar Abertura", command=confirmar_abertura).pack(pady=20)

def verificar_caixa_aberto():
    """Busca no banco se existe algum ciclo com status 'ABERTO'"""
    global ciclo_caixa_aberto
    
    cursor.execute("SELECT id, saldo_inicial, abertura FROM ciclos_caixa WHERE status = 'ABERTO' LIMIT 1")
    res = cursor.fetchone()
    
    if res:
        ciclo_caixa_aberto["id"] = res[0]
        ciclo_caixa_aberto["saldo_inicial"] = res[1]
        ciclo_caixa_aberto["abertura"] = res[2]
        
        # Opcional: Recalcular o saldo atual com base nas movimentações já feitas
        # Para simplificar, vamos setar o saldo inicial:
        saldo_atual.set(res[1])
        atualizar_saldo()
        if 'carregar_receitas_caixa' in globals():
            carregar_receitas_caixa()
        print(f"Sistema iniciado com caixa {res[0]} aberto.")
    else:
        ciclo_caixa_aberto["id"] = None
        print("Sistema iniciado com caixa fechado.")

