def gerar_relatorio_conferencia(modo, valor_busca=None, data_ini=None, data_fim=None):
    try:
        if modo == "atual":
            if not ciclo_caixa_aberto.get("id"):
                messagebox.showwarning("Erro", "Não há caixa aberto no momento.")
                return
            c_id = ciclo_caixa_aberto["id"]
            abertura = ciclo_caixa_aberto["abertura"]
            fechamento = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            ini_din = ciclo_caixa_aberto.get("saldo_inicial", 0.0)
            ini_pix = ciclo_caixa_aberto.get("saldo_inicial_pix", 0.0)
            titulo = "CONFERENCIA PARCIAL (X)"
        
        elif modo == "por_id":
            cursor.execute("SELECT id, abertura, fechamento, saldo_inicial, saldo_inicial_pix FROM ciclos_caixa WHERE id=?", (valor_busca,))
            res = cursor.fetchone()
            if not res:
                messagebox.showerror("Erro", "Caixa não encontrado!")
                return
            c_id, abertura, fechamento, ini_din, ini_pix = res
            titulo = f"RELATORIO CAIXA #{c_id}"
            if not fechamento: fechamento = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        elif modo == "periodo":
            if _periodo_invalido(data_ini, data_fim):
                return
            # Converte as datas de DD/MM/AAAA para AAAA-MM-DD
            try:
                d_ini = datetime.strptime(data_ini, "%d/%m/%Y").strftime("%Y-%m-%d 00:00:00")
                d_fim = datetime.strptime(data_fim, "%d/%m/%Y").strftime("%Y-%m-%d 23:59:59")
            except:
                messagebox.showerror("Erro", "Formato de data inválido! Use DD/MM/AAAA")
                return
            
            abertura = d_ini
            fechamento = d_fim
            ini_din = 0.0 # Em período longo, o saldo inicial é irrelevante ou zero
            ini_pix = 0.0
            titulo = f"PERIODO: {data_ini} a {data_fim}"

        # --- BUSCA NO BANCO (CONSIDERA O INTERVALO DE DATAS) ---
        
        # Dinheiro
        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Dinheiro' AND data BETWEEN ? AND ?", (abertura, fechamento))
        ent_din = cursor.fetchone()[0] or 0.0
        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Dinheiro' AND data BETWEEN ? AND ?", (abertura, fechamento))
        sai_din = cursor.fetchone()[0] or 0.0
        sub_din = (ini_din + ent_din) - sai_din

        # Pix
        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Pix' AND data BETWEEN ? AND ?", (abertura, fechamento))
        ent_pix = cursor.fetchone()[0] or 0.0
        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Pix' AND data BETWEEN ? AND ?", (abertura, fechamento))
        sai_pix = cursor.fetchone()[0] or 0.0
        sub_pix = (ini_pix + ent_pix) - sai_pix

        # Cartão
        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Cartão' AND data BETWEEN ? AND ?", (abertura, fechamento))
        ent_car = cursor.fetchone()[0] or 0.0
        cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Cartão' AND data BETWEEN ? AND ?", (abertura, fechamento))
        sai_car = cursor.fetchone()[0] or 0.0
        total_car = ent_car - sai_car
        
        total_geral = sub_din + sub_pix + total_car

        # --- FORMATAÇÃO PARA 50mm (Igual ao seu padrão lindo) ---
        L = 32
        relat = "================================\n"
        relat += f"{titulo[:30]}".center(L) + "\n"
        relat += "================================\n"
        relat += f"Gerado em: {datetime.now().strftime('%d/%m %H:%M')}\n"
        relat += "--------------------------------\n"
        relat += "MOVIMENTACAO DINHEIRO:\n"
        if modo != "periodo": relat += f"(+) Inicial:    R$ {ini_din:>9.2f}\n"
        relat += f"(+) Entradas:   R$ {ent_din:>9.2f}\n"
        relat += f"(-) Saidas:     R$ {sai_din:>9.2f}\n"
        relat += f"SUBTOTAL:       R$ {sub_din:>9.2f}\n\n"
        relat += "MOVIMENTACAO PIX:\n"
        if modo != "periodo": relat += f"(+) Inicial:    R$ {ini_pix:>9.2f}\n"
        relat += f"(+) Entradas:   R$ {ent_pix:>9.2f}\n"
        relat += f"(-) Saidas:     R$ {sai_pix:>9.2f}\n"
        relat += f"SUBTOTAL:       R$ {sub_pix:>9.2f}\n\n"
        if sai_car > 0.004:
            relat += f"CART.ENTRADAS:  R$ {ent_car:>9.2f}\n"
            relat += f"(-) Estornos:   R$ {sai_car:>9.2f}\n"
        relat += f"CARTAO:         R$ {total_car:>9.2f}\n"
        relat += "--------------------------------\n"
        relat += "TOTAL NO PERIODO:\n"
        relat += f"R$ {total_geral:,.2f}".center(L) + "\n"
        relat += "================================\n\n\n\n"

        with open("conferencia_caixa.txt", "w", encoding="utf-8") as f:
            f.write(relat)
        
        os.startfile("conferencia_caixa.txt")

    except Exception as e:
        messagebox.showerror("Erro", f"Falha ao gerar relatório: {e}")

def fechar_caixa():
    if not ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Aviso", "Não há caixa aberto.")
        return

    # Autorização do encarregado: usa a MESMA senha do admin das entregas (botão "Encerrar dia").
    # Sem a senha correta o caixa continua aberto.
    senha = simpledialog.askstring("Fechar Caixa", "Senha do encarregado:", show="*", parent=root)
    if senha is None:
        return  # desistiu
    try:
        import entregas_tela
        senha_ok = entregas_tela.verificar_senha_admin(senha)
    except Exception as _e_senha:
        messagebox.showerror("Fechar Caixa", f"Não foi possível validar a senha: {_e_senha}\nO caixa continua aberto.")
        return
    if not senha_ok:
        try:
            registrar_log("FECHAMENTO_CAIXA_SENHA_INCORRETA", "CAIXA", ciclo_caixa_aberto.get("id"), {})
        except Exception:
            pass
        messagebox.showwarning("Fechar Caixa", "Senha incorreta. O caixa continua aberto.")
        return

    if not messagebox.askyesno("Confirmar", "Deseja fechar o caixa agora?"):
        return

    # Encerrar dia das ENTREGAS junto com o fechamento (a senha do admin já foi validada acima).
    # Tudo zerado = encerra em silêncio. Se houver dinheiro a receber de entregador ou pedido
    # em aberto, a função pergunta antes; CANCELAR = volta e o caixa continua aberto.
    # Servidor fora do ar não bloqueia o fechamento.
    try:
        import entregas_tela
        if not entregas_tela.encerrar_dia_ao_fechar(root):
            return
    except Exception as _e_enc:
        print("Erro ao encerrar o dia das entregas:", _e_enc)

    ciclo_id = ciclo_caixa_aberto["id"]
    fechamento = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    abertura = ciclo_caixa_aberto['abertura']

    # --- 1. CÁLCULOS FINANCEIROS DETALHADOS ---
    
    # DINHEIRO (Vendas + Entradas Manuais - Saídas Dinheiro)
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Dinheiro' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_id, abertura,))
    vendas_din = cursor.fetchone()[0] or 0.0
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Dinheiro' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_id, abertura,))
    sai_din = cursor.fetchone()[0] or 0.0
    ini_din = ciclo_caixa_aberto.get("saldo_inicial", 0.0)
    subtotal_dinheiro = (ini_din + vendas_din) - sai_din

    # PIX (Vendas + Entradas Manuais - Saídas Pix)
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Pix' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_id, abertura,))
    vendas_pix = cursor.fetchone()[0] or 0.0
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Pix' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_id, abertura,))
    sai_pix = cursor.fetchone()[0] or 0.0
    ini_pix = ciclo_caixa_aberto.get("saldo_inicial_pix", 0.0)
    subtotal_pix = (ini_pix + vendas_pix) - sai_pix

    # CARTÃO E PENDENTES
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='ENTRADA' AND pagamento='Cartão' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_id, abertura,))
    entradas_cartao = cursor.fetchone()[0] or 0.0
    # Saídas em Cartão (estorno/cancelamento de pedido pago no cartão) também descontam,
    # como já acontece com Dinheiro e Pix; senão o saldo_final do caixa fechado fica inflado.
    cursor.execute("SELECT SUM(valor) FROM caixa WHERE tipo='SAIDA' AND pagamento='Cartão' AND (ciclo_id = ? OR (ciclo_id IS NULL AND data >= ?))", (ciclo_id, abertura,))
    saidas_cartao = cursor.fetchone()[0] or 0.0
    total_cartao = round(entradas_cartao - saidas_cartao, 2)
    cursor.execute("SELECT SUM(total) FROM pedidos WHERE (pagamento IS NULL OR pagamento='' OR pagamento='Pendente') AND ciclo_caixa_id=?", (ciclo_id,))
    total_pendente = cursor.fetchone()[0] or 0.0

    # Valor Total Final para salvar no Banco
    valor_liquido_total = round(subtotal_dinheiro + subtotal_pix + total_cartao, 2)

    # --- 2. GERAR O TXT PARA IMPRESSORA 50mm (L=32) ---
    L = 32
    relat = "================================\n"
    relat += "        CUMBUCA DELIVERY        \n"
    relat += "================================\n"
    relat += "    RELATORIO DE FECHAMENTO     \n"
    relat += f"Caixa No: {ciclo_id}\n"
    relat += f"Abertura: {abertura[8:10]}/{abertura[5:7]} {abertura[11:16]}\n"
    relat += f"Fechado : {fechamento[8:10]}/{fechamento[5:7]} {fechamento[11:16]}\n"
    relat += "--------------------------------\n"
    
    relat += "1. MOVIMENTACAO DE DINHEIRO\n"
    relat += f"(+) Saldo Inicial:  R$ {ini_din:>9.2f}\n"
    relat += f"(+) Vendas/Rec:     R$ {vendas_din:>9.2f}\n"
    relat += f"(-) Despesas/Sang:  R$ {sai_din:>9.2f}\n"
    relat += "--------------------------------\n"
    relat += f"SUBTOTAL DINHEIRO:  R$ {subtotal_dinheiro:>9.2f}\n\n"

    relat += "2. MOVIMENTACAO DE PIX\n"
    relat += f"(+) Saldo Inicial:  R$ {ini_pix:>9.2f}\n"
    relat += f"(+) Vendas/Rec:     R$ {vendas_pix:>9.2f}\n"
    relat += f"(-) Despesas Pix:   R$ {sai_pix:>9.2f}\n"
    relat += "--------------------------------\n"
    relat += f"SUBTOTAL PIX:       R$ {subtotal_pix:>9.2f}\n\n"

    relat += "3. OUTROS TOTAIS\n"
    if saidas_cartao > 0.004:
        relat += f"(+) Cartao:         R$ {entradas_cartao:>9.2f}\n"
        relat += f"(-) Estorno Cartao: R$ {saidas_cartao:>9.2f}\n"
        relat += f"SUBTOTAL CARTAO:    R$ {total_cartao:>9.2f}\n"
    else:
        relat += f"(+) Cartao:         R$ {total_cartao:>9.2f}\n"
    relat += f"(!) Pendentes:      R$ {total_pendente:>9.2f}\n"
    relat += "--------------------------------\n"
    relat += "TOTAL GERAL EM CAIXA:\n"
    relat += f"R$ {valor_liquido_total:,.2f}".center(L) + "\n"
    relat += "================================\n\n\n\n"

    # Salva e abre o arquivo
    with open("fechamento_caixa.txt", "w", encoding="utf-8") as f:
        f.write(relat)
    
    try:
        os.startfile("fechamento_caixa.txt")
    except:
        pass

    # --- 3. ATUALIZA BANCO E FECHA ---
    cursor.execute("UPDATE ciclos_caixa SET fechamento=?, saldo_final=?, status='FECHADO' WHERE id=?",
                   (fechamento, valor_liquido_total, ciclo_id))
    conn.commit()
    registrar_log("FECHAMENTO_CAIXA", "CAIXA", ciclo_id, {"abertura": abertura, "fechamento": fechamento, "saldo_final": valor_liquido_total, "pendentes": total_pendente})

    messagebox.showinfo("Sucesso", "Caixa fechado com sucesso!")
    
    # Encerra o sistema
    ciclo_caixa_aberto["id"] = None
    
    try:
        backup_automatico()
    except Exception as e:
        print("Erro ao criar backup:", e)
    
    root.quit()
    root.destroy()

