mostrar_total_oculto = False

def obter_caixa_aberto():
    cursor.execute("""
        SELECT id FROM ciclos_caixa
        WHERE status = 'ABERTO'
        ORDER BY id DESC
        LIMIT 1
    """)
    return cursor.fetchone()

