def gerar_pix_com_valor(valor_total):
    """
    Monta o código Pix Estático inserindo o valor total do pedido.
    Baseado no seu código do Mercado Pago.
    """
    # Valor formatado para o padrão Pix (ex: 13.00)
    valor_str = f"{valor_total:.2f}"
    len_valor = f"{len(valor_str):02d}"
    
    # Parte inicial do seu código até antes do valor (tag 54 é moeda, 58 é país)
    # Vamos remontar a estrutura para garantir que o valor entre no lugar certo (Tag 54)
    base_pix = "00020101021126810014BR.GOV.BCB.PIX2559pix-qr.mercadopago.com/instore/ol/v2/3Z9Ui6vkoYkas1HRS1DIFX52040000"
    parte_moeda_valor = f"53039865{len_valor}{valor_str}"
    final_pix = "5802BR5907Cumbuca6009SAO PAULO62080504mpis6304"
    
    # Monta o código completo
    codigo_completo = base_pix + parte_moeda_valor + final_pix
    
    # Cálculo de CRC16 (Simplificado para o padrão fixo do seu código)
    # Como o CRC final muda com o valor, o ideal é usar o código fornecido, 
    # mas para Pix estáticos de valor variável, o app do banco costuma recalcular.
    return codigo_completo

# Crie essa variável no topo do seu código Python, fora das funções
pedido_em_tela = False 

def importar_pedido_json():
    """Lê o arquivo JSON e só carrega se a tela estiver vazia"""
    global pedido_em_tela
    
    # 🔴 TRAVA: Se já tem um pedido na tela sendo editado, não busca outro!
    if pedido_em_tela:
        root.after(3000, importar_pedido_json)
        return

    diretorio_atual = os.path.dirname(os.path.abspath(__file__))
    diretorio_pedidos = os.path.join(diretorio_atual, 'pedidos_entrada')
    
    if not os.path.exists(diretorio_pedidos):
        os.makedirs(diretorio_pedidos, exist_ok=True)
        root.after(3000, importar_pedido_json)
        return

    arquivos = [f for f in os.listdir(diretorio_pedidos) if f.endswith('.json')]
    if not arquivos: 
        root.after(3000, importar_pedido_json)
        return

    # Se chegou aqui, achou um arquivo e a tela está livre
    caminho_arquivo = os.path.join(diretorio_pedidos, arquivos[0])

    try:
        with open(caminho_arquivo, 'r', encoding='utf-8') as f:
            dados = json.load(f)

            
        # 1. Limpa a tela e MARCA QUE A TELA ESTÁ OCUPADA
        pedido_em_tela = True # 🔒 Ativa a trava
        pedido_itens.clear() 
        atualizar_lista_temp()
        e_cliente.delete(0, "end")
        e_endereco.delete(0, "end")
        e_telefone.delete(0, "end")
        e_observacao.delete(0, "end")
        
        dados = normalizar_pedido_entrada(dados)
        e_cliente.insert(0, dados.get('cliente', 'CLIENTE APP'))
        e_endereco.insert(0, dados.get('endereco', ''))
        e_telefone.insert(0, str(dados.get('telefone', '') or dados.get('fone', '')).strip())
        cb_pag.set(dados.get('pagamento', 'Pendente'))
        e_observacao.insert(0, dados.get('obs', ''))

        itens = dados.get('itens', [])
        for item in itens:
            cod_vix = str(item.get('nome_id', '')).strip() if isinstance(item, dict) else str(item).strip()
            qtd_vix = str(item.get('qtd', '1')) if isinstance(item, dict) else "1"

            cursor.execute("SELECT produto FROM estoque WHERE codigo = ?", (cod_vix,))
            res = cursor.fetchone()
            
            if res:
                nome_completo = f"{cod_vix} - {res[0]}"
                cb_prod.set(nome_completo)
                e_qtd_item.delete(0, "end")
                e_qtd_item.insert(0, qtd_vix)
                adicionar_item() 

        # Remove o arquivo para não processar de novo
        os.remove(caminho_arquivo)
        atualizar_total_pedido()
        print(f"✅ Pedido de {dados.get('cliente')} carregado na tela. Aguardando finalização...")

    except Exception as e:
        print(f"❌ Erro ao processar: {e}")
        pedido_em_tela = False # Se der erro, libera para tentar o próximo
    
    root.after(3000, importar_pedido_json)


def gerar_nota(pedido_id):
    if not messagebox.askyesno("Imprimir", "Deseja imprimir o cupom?"):
        return
    imprimir_cupom_pedido(pedido_id)


def _cupom_formatar_valor(valor):
    """Valor com 2 casas e virgula decimal (ex.: 24,00). So para exibicao."""
    return f"{float(valor):.2f}".replace(".", ",")


def _cupom_data_hora_pedido(data_db):
    """
    Converte pedidos.data para (data_str, hora_str) de impressao.
    - hora_str vem None quando o registro tem so a data (nao inventa hora).
    - Se nada funcionar, cai no comportamento antigo (agora) e avisa no print.
    Nunca levanta excecao.
    """
    try:
        texto = str(data_db).strip().replace("T", " ")
        tem_hora = ":" in texto
        dt = None
        try:
            dt = datetime.fromisoformat(texto)
        except Exception:
            dt = None
        if dt is None:
            for fmt, com_hora in (("%Y-%m-%d %H:%M:%S", True),
                                  ("%Y-%m-%d %H:%M", True),
                                  ("%Y-%m-%d", False)):
                try:
                    dt = datetime.strptime(texto, fmt)
                    tem_hora = com_hora
                    break
                except Exception:
                    dt = None
        if dt is not None:
            return dt.strftime("%d/%m/%Y"), (dt.strftime("%H:%M") if tem_hora else None)
        print(f"Aviso: data do pedido ilegivel ({data_db!r}); usando data/hora atuais na nota.")
    except Exception as erro:
        print(f"Aviso: falha ao ler data do pedido ({erro}); usando data/hora atuais na nota.")
    agora = datetime.now()
    return agora.strftime("%d/%m/%Y"), agora.strftime("%H:%M")


def _cupom_quebrar_texto(texto, largura, largura_cont=None):
    """
    Quebra por palavra. A 1a linha tem ate `largura` colunas e as demais ate
    `largura_cont` (padrao: a mesma). Palavra maior que a linha e dividida.
    """
    if largura_cont is None:
        largura_cont = largura
    palavras = str(texto).split()
    linhas, atual = [], ""
    for palavra in palavras:
        while True:
            limite = largura if not linhas else largura_cont
            if len(palavra) <= limite:
                break
            if atual:
                linhas.append(atual)
                atual = ""
                continue
            linhas.append(palavra[:limite])
            palavra = palavra[limite:]
        limite = largura if not linhas else largura_cont
        tentativa = palavra if not atual else atual + " " + palavra
        if len(tentativa) <= limite:
            atual = tentativa
        else:
            linhas.append(atual)
            atual = palavra
    if atual or not linhas:
        linhas.append(atual)
    return linhas


def imprimir_cupom_pedido(pedido_id):
    """
    Lógica de impressão do cupom (POS-58), extraída de gerar_nota() para
    poder ser chamada sem o messagebox de confirmação — usada quando a
    confirmação já foi dada em outro lugar (ex.: o garçom tocou em
    "Imprimir Nota" na tela do celular depois que o Pix foi confirmado).
    gerar_nota() continua com exatamente o mesmo comportamento de antes,
    só chamando esta função depois do "Sim" na caixa de diálogo.
    Retorna True se a impressão foi enviada, False se falhou.
    """
    # --- Textos do rodape de eventos (troque aqui) ---
    TXT_EVENTO_FAIXA = "TEMOS ESPAÇO PARA EVENTOS"
    TXT_EVENTO_L1 = "Festas, aniversários e reuniões"
    TXT_EVENTO_L2 = "Reserve sua data:"
    TXT_EVENTO_WHATS = "WHATSAPP (85) 99242-5223"
    TXT_AGRADECIMENTO = "Obrigado e volte sempre!"
    TXT_EVENTO_FALLBACK_1 = "*** TEMOS ESPACO PARA EVENTOS ***"
    TXT_EVENTO_FALLBACK_2 = "Reserve: (85) 99242-5223"

    try:
        cursor.execute("SELECT cliente, endereco, pagamento, total, data, observacao, ajuste FROM pedidos WHERE id = ?", (pedido_id,))
        res = cursor.fetchone()
        if not res: return False
        cliente, endereco, pagamento, total, data_db, observacao, ajuste = res
        observacao = limpar_observacao_telefone(observacao)

        cursor.execute("SELECT produto, quantidade, venda FROM itens_pedido WHERE pedido_id = ?", (pedido_id,))
        itens = cursor.fetchall()

        pix_mp = obter_pix_mercado_pago_para_nota(pedido_id, float(total), cliente)
        pix_codigo = (pix_mp or {}).get("qr_code") or gerar_pix_com_valor(float(total), pedido_id)
        qr = qrcode.QRCode(version=1, box_size=3, border=1)
        qr.add_data(pix_codigo)
        qr.make(fit=True)
        img_qr = qr.make_image(fill_color="black", back_color="white")
        img_qr.save("temp_pix.png")

        printer_name = "POS-58"
        hDC = win32ui.CreateDC()
        hDC.CreatePrinterDC(printer_name)
        hDC.StartDoc(f"Pedido_{pedido_id}")
        hDC.StartPage()
        desenhar_logo_titulo_cupom(hDC)
        
        # Altura 22 e Largura 28 é o ajuste ideal para 58mm
        font = win32ui.CreateFont({'name': 'Courier New', 'height': 21, 'weight': 400})
        hDC.SelectObject(font)
        # Mesma fonte em negrito usada na comanda da cozinha (imprimir_comanda_cozinha),
        # so que na altura 21 pra bater com o cupom do cliente.
        font_negrito = win32ui.CreateFont({'name': 'Courier New', 'height': 21, 'weight': 700})
        font_titulo = win32ui.CreateFont({'name': 'Courier New', 'height': 26, 'weight': 700})
        font_total = win32ui.CreateFont({'name': 'Courier New', 'height': 30, 'weight': 700})
        font_faixa = win32ui.CreateFont({'name': 'Courier New', 'height': 22, 'weight': 700})

        L, espaco_linha = 32, 22 
        y = 88
        # Data/hora gravadas no pedido (reimpressao sai com a data original).
        data_atual, hora_atual = _cupom_data_hora_pedido(data_db)

        # Largura em pixels de 32 colunas na fonte normal (centralizar / alinhar a direita).
        # Se a medicao falhar, usa 290 so para o texto; o QR mantem o x antigo (55).
        largura_medida = None
        try:
            hDC.SelectObject(font)
            largura_medida = int(hDC.GetTextExtent("0" * L)[0])
        except Exception as erro:
            print(f"Largura do texto nao medida: {erro}")
        largura_texto = largura_medida if largura_medida and largura_medida > 0 else 290

        def p_centro(texto):
            nonlocal y
            hDC.SelectObject(font)
            hDC.TextOut(0, y, str(texto).center(L))
            y += espaco_linha

        def p_esq(texto, negrito=False):
            nonlocal y
            hDC.SelectObject(font_negrito if negrito else font)
            texto_str = str(texto)
            while len(texto_str) > L:
                quebra = texto_str[:L]
                hDC.TextOut(0, y, quebra)
                y += espaco_linha
                texto_str = texto_str[L:]
            hDC.TextOut(0, y, texto_str)
            y += espaco_linha

        def p_centro_px(texto, fonte, extra=4):
            """Centraliza pelo tamanho real do texto (GetTextExtent) na fonte dada."""
            nonlocal y
            hDC.SelectObject(fonte)
            texto_str = str(texto)
            w, h = hDC.GetTextExtent(texto_str)
            x = max(0, (largura_texto - w) // 2)
            hDC.TextOut(x, y, texto_str)
            y += max(espaco_linha, h) + extra

        def p_lr(esquerda, direita, negrito=False):
            """Texto a esquerda e valor a direita, fechando as 32 colunas."""
            esquerda, direita = str(esquerda), str(direita)
            miolo = max(1, L - len(esquerda) - len(direita))
            p_esq(esquerda + " " * miolo + direita, negrito=negrito)

        def p_campo(rotulo, valor):
            """Campo com rotulo; texto longo quebra com recuo alinhado apos o rotulo."""
            recuo = len(rotulo)
            linhas = _cupom_quebrar_texto(str(valor or "").upper(), L - recuo)
            for i, linha in enumerate(linhas):
                p_esq((rotulo if i == 0 else " " * recuo) + linha)

        def restaurar_dc():
            """Devolve cor do texto, modo e cor de fundo do DC ao padrao (cada um isolado)."""
            for acao in (lambda: hDC.SetTextColor(0x000000),
                         lambda: hDC.SetBkMode(2),
                         lambda: hDC.SetBkColor(0xFFFFFF)):
                try:
                    acao()
                except Exception as erro_dc:
                    print(f"Estado do DC nao restaurado: {erro_dc}")

        # --- LAYOUT REVISADO ---
        p_centro("=" * L)
        p_centro_px(f"PEDIDO Nº {pedido_id}", font_titulo)
        p_centro("=" * L)

        # Data a esquerda, hora a direita (so a data se o pedido nao tiver hora)
        if hora_atual:
            p_lr(data_atual, hora_atual)
        else:
            p_esq(data_atual)

        p_campo("CLIENTE: ", cliente)
        p_campo("ENTREGA: ", endereco)
        pagamento_txt = str(pagamento or "").strip()
        if pagamento_txt and pagamento_txt.lower() != "pendente":
            p_campo("PGTO: ", pagamento_txt)
        
        if observacao:
            # So o trecho dos ITENS (prato + obs de cada item) fica em
            # negrito -- o resto da observacao (cabecalho "PEDIDO SITE",
            # "Pagamento escolhido..." e o codigo WEB-xxx) imprime normal.
            # Se a observacao nao tiver a secao "ITENS:" (pedido digitado
            # direto no sis, por exemplo), nada fica em negrito -- imprime
            # tudo normal, como sempre foi.
            p_esq("OBS:")
            linhas_obs = [l.strip() for l in str(observacao).upper().split("\n")]
            linhas_obs = [l for l in linhas_obs if l]
            dentro_itens = False
            for linha in linhas_obs:
                if linha == "PEDIDO SITE":
                    continue
                if linha == "ITENS:":
                    dentro_itens = True
                    continue
                if linha.startswith("PAGAMENTO ESCOLHIDO"):
                    dentro_itens = False
                p_esq(linha, negrito=dentro_itens)
            
        p_esq("-" * L)
        # Colunas: 2 (qtd) + "x" + espaco + 18 (nome) + 10 (total) = 32
        p_esq("QTD ITEM".ljust(L - 5) + "TOTAL")
        p_esq("-" * L)

        soma_itens = 0.0  # so para exibir o SUBTOTAL; o Pix usa float(total) do banco
        for prod, qtd, valor in itens:
            sub = qtd * valor
            soma_itens += sub
            partes_nome = _cupom_quebrar_texto(str(prod).upper(), 18, L - 4)
            p_esq(f"{int(qtd):02d}x {partes_nome[0]:<18}{_cupom_formatar_valor(sub):>10}", negrito=True)
            for continuacao in partes_nome[1:]:
                p_esq("    " + continuacao, negrito=True)

        try:
            ajuste_val = float(ajuste or 0)
        except Exception:
            ajuste_val = 0.0

        if ajuste_val != 0:
            p_esq("-" * L)
            try:
                import config_taxa
                taxa_cfg = float(config_taxa.obter_taxa_entrega() or 0.0)
            except Exception:
                taxa_cfg = 0.0
            if ajuste_val > 0 and taxa_cfg > 0 and abs(ajuste_val - taxa_cfg) < 0.005:
                label_aj = "TAXA DE ENTREGA"
            elif ajuste_val > 0:
                label_aj = "ACRESCIMO"
            else:
                label_aj = "DESCONTO"
            p_lr("SUBTOTAL", _cupom_formatar_valor(soma_itens))
            p_lr(label_aj, _cupom_formatar_valor(abs(ajuste_val)))

        # TOTAL (valor lido de pedidos.total; nada e recalculado aqui)
        p_centro("=" * L)
        hDC.SelectObject(font_total)
        txt_total_valor = f"R$ {_cupom_formatar_valor(total)}"
        w_rotulo, _h0 = hDC.GetTextExtent("TOTAL")
        w_valor, h_total = hDC.GetTextExtent(txt_total_valor)
        x_valor = max(w_rotulo + 8, largura_texto - w_valor)
        hDC.TextOut(0, y, "TOTAL")
        hDC.TextOut(x_valor, y, txt_total_valor)
        y += max(espaco_linha, h_total) + 4
        p_centro("=" * L)
        
        p_centro("PAGUE VIA PIX")
        if pix_mp:
            p_centro(f"REF MP: {str(pix_mp.get('payment_id') or '')[-8:]}")
        y += 5 
        
        img = Image.open("temp_pix.png")
        dib = ImageWin.Dib(img)
        # QR centralizado pela largura real de 32 colunas (se falhar, x antigo = 55)
        x_qr = 55
        try:
            x_calc = (largura_texto - 180) // 2
            if largura_medida and 0 <= x_calc <= 200:
                x_qr = x_calc
        except Exception:
            x_qr = 55
        dib.draw(hDC.GetHandleOutput(), (x_qr, y, x_qr + 180, y + 180))
        y += 190

        # --- RODAPE DE EVENTOS (nunca pode impedir o restante da nota) ---
        agradecimento_ok = False
        try:
            p_centro("=" * L)

            # a) faixa preta com texto branco
            hDC.SelectObject(font_faixa)
            w_f, h_f = hDC.GetTextExtent(TXT_EVENTO_FAIXA)
            alt_faixa = h_f + 6
            try:
                hDC.FillSolidRect((0, y, largura_texto, y + alt_faixa), 0x000000)
                hDC.SetBkMode(1)
                hDC.SetTextColor(0xFFFFFF)
                hDC.TextOut(max(0, (largura_texto - w_f) // 2), y + 3, TXT_EVENTO_FAIXA)
            finally:
                restaurar_dc()
            y += alt_faixa + 6

            # b) duas linhas normais centralizadas
            p_centro_px(TXT_EVENTO_L1, font, extra=0)
            p_centro_px(TXT_EVENTO_L2, font, extra=4)

            # c) caixa com borda de 2 px e WhatsApp em negrito
            hDC.SelectObject(font_negrito)
            w_w, h_w = hDC.GetTextExtent(TXT_EVENTO_WHATS)
            pad, borda = 8, 2
            x0 = max(0, (largura_texto - w_w) // 2 - pad)
            x1 = min(largura_texto, (largura_texto + w_w) // 2 + pad)
            y1 = y + h_w + 2 * pad
            try:
                hDC.FillSolidRect((x0, y, x1, y + borda), 0x000000)
                hDC.FillSolidRect((x0, y1 - borda, x1, y1), 0x000000)
                hDC.FillSolidRect((x0, y, x0 + borda, y1), 0x000000)
                hDC.FillSolidRect((x1 - borda, y, x1, y1), 0x000000)
            finally:
                # FillSolidRect deixa a cor de fundo preta; volta ao padrao antes do texto
                restaurar_dc()
            hDC.SelectObject(font_negrito)
            hDC.TextOut(max(0, (largura_texto - w_w) // 2), y + pad, TXT_EVENTO_WHATS)
            y = y1 + 8

            # d) agradecimento (linha final)
            p_centro_px(TXT_AGRADECIMENTO, font, extra=0)
            agradecimento_ok = True
        except Exception as erro_rodape:
            print(f"Rodape de eventos simplificado: {erro_rodape}")
            restaurar_dc()
            try:
                p_centro(TXT_EVENTO_FALLBACK_1)
                p_centro(TXT_EVENTO_FALLBACK_2)
                if not agradecimento_ok:
                    p_centro(TXT_AGRADECIMENTO)
            except Exception as erro_fallback:
                print(f"Fallback do rodape falhou: {erro_fallback}")

        hDC.EndPage()
        hDC.EndDoc()
        hDC.DeleteDC()
        return True

    except Exception as e:
        messagebox.showerror("Erro de Impressão", f"Causa: {e}")
        return False


def perguntar_finalizacao_pedido(pedido_id):
    """
    Usada ao finalizar uma mesa (cobranca unica ou dividida): em vez do
    simples "Deseja imprimir o cupom?" de gerar_nota(), oferece 3 opcoes
    ao operador -- Gerar QRcode, Imprimir Cupom ou So Salvar.

    NAO altera gerar_nota() nem nenhum outro fluxo que ja chama ela
    (finalizacao de pedido comum, reimpressao, etc.) -- e uma funcao
    nova, isolada, chamada apenas pelo mesa.py.

    O botao "Gerar QRcode" fica desabilitado se o pedido nao for elegivel
    para cobranca Pix (ex.: o pedido "espelho" da divisao de conta, que
    nasce com total R$0) -- mesma regra usada em Contas a Receber e no
    QR Code da aba Pedidos, via pedido_elegivel_contas_receber().
    """
    cursor.execute(
        "SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?",
        (pedido_id,)
    )
    row = cursor.fetchone()
    elegivel_qr = bool(row) and pedido_elegivel_contas_receber(*row)

    janela = tk.Toplevel(root)
    janela.title(f"Pedido #{pedido_id}")
    janela.geometry("320x230")
    janela.resizable(False, False)
    janela.transient(root)
    janela.grab_set()

    tk.Label(
        janela,
        text="Como deseja cobrar/registrar\neste pedido?",
        font=("Arial", 11, "bold"), justify="center"
    ).pack(pady=(18, 14))

    def escolher_qr():
        janela.destroy()
        gerar_qrcode_pix_para_pedido(pedido_id)

    def escolher_imprimir():
        janela.destroy()
        imprimir_cupom_pedido(pedido_id)

    def escolher_salvar():
        janela.destroy()

    btn_qr = ttk.Button(janela, text="📲 Gerar QRcode", command=escolher_qr)
    btn_qr.pack(fill="x", padx=30, pady=4)
    if not elegivel_qr:
        btn_qr.config(state="disabled")

    ttk.Button(janela, text="🖨️ Imprimir Cupom", command=escolher_imprimir).pack(fill="x", padx=30, pady=4)
    ttk.Button(janela, text="💾 So Salvar", command=escolher_salvar).pack(fill="x", padx=30, pady=(4, 16))


# =====================================================
# 📲 CONTAS A RECEBER — QR E RESUMO DE COBRANCA PIX (tela + impressao)
# Inserir no NIVEL DE MODULO, logo ANTES de "def imprimir_comanda_cozinha(".
# (win32ui, ImageWin, qrcode, messagebox e datetime ja foram importados acima)
# =====================================================
COLUNAS_CUPOM_PIX = 32


def gerar_imagem_qr_pix(codigo, largura_max, borda=2, box_min=2):
    """
    Gera o QR do Pix a partir do texto copia-e-cola. A MESMA funcao serve a tela
    e a impressao, entao o que aparece na janela e identico ao que vai pro papel.
    O tamanho e sempre (modulos + bordas) x box_size, com box_size INTEIRO:
    a imagem e desenhada em tamanho nativo, sem esticar.
    Retorna (imagem PIL modo "1", box_size).
    """
    qr = qrcode.QRCode(
        version=None,
        error_correction=qrcode.constants.ERROR_CORRECT_M,
        box_size=1,
        border=borda,
    )
    qr.add_data(codigo)
    qr.make(fit=True)
    total_modulos = qr.modules_count + 2 * borda
    box = max(box_min, int(largura_max) // total_modulos)
    qr.box_size = box
    img = qr.make_image(fill_color="black", back_color="white").get_image().convert("1")
    return img, box


def qr_imagem_para_base64(img):
    """PNG em base64, aceito por tk.PhotoImage(data=...) — nao depende de ImageTk."""
    import io as _io
    buf = _io.BytesIO()
    img.save(buf, format="PNG")
    return base64.b64encode(buf.getvalue()).decode("ascii")


def _data_curta_cupom(valor):
    try:
        return datetime.strptime(str(valor)[:19], "%Y-%m-%d %H:%M:%S").strftime("%d/%m/%y")
    except Exception:
        return str(valor or "")[:8]


def montar_linhas_resumo_pix(id_cobranca, cliente, pedidos, valor_total, payment_id="", agora=None):
    """
    Monta o recibo como lista de (tipo, texto), tipo em {"centro", "esq", "qr"}.
    Funcao PURA (sem impressora, sem Tk): da pra testar em qualquer maquina.
    Toda linha tem no maximo COLUNAS_CUPOM_PIX (32) caracteres. Valores e TOTAL terminam na
    coluna 31, como na nota de pedido (a ultima coluna fica livre por seguranca).
    pedidos: lista de dicts {"id","cliente","data","valor","total","pago"}.
    """
    L = COLUNAS_CUPOM_PIX
    agora = agora or datetime.now()
    varios = len({str(p.get("cliente") or "").strip().upper() for p in pedidos}) > 1
    cli_cab = "VARIOS CLIENTES" if varios else str(cliente or "").upper()

    k = []
    k.append(("centro", "=" * L))
    k.append(("centro", "COBRANCA PIX"))
    k.append(("centro", "RESUMO DE PEDIDOS"))
    k.append(("esq", f"DT:{agora:%d/%m/%Y} HORA: {agora:%H:%M}"))
    if cli_cab:
        k.append(("esq", f"CLI: {cli_cab[:27]}"))
    k.append(("esq", "-" * L))
    k.append(("esq", "PEDIDO".ljust(7) + "DATA".ljust(9) + "VALOR".rjust(15)))
    k.append(("esq", "-" * L))
    for p in pedidos:
        valor = f"R$ {float(p['valor']):.2f}"
        k.append(("esq", f"{'#' + str(p['id']):<7}{_data_curta_cupom(p.get('data')):<9}{valor:>15}"))
        if varios and p.get("cliente"):
            k.append(("esq", f"  {str(p['cliente']).upper()[:29]}"))
        if float(p.get("pago") or 0) > 0.001:
            # pedido parcialmente pago: explica por que o valor cobrado e menor que o total
            k.append(("esq", f"  TOTAL {float(p['total']):.2f} PAGO {float(p['pago']):.2f}"[:L]))
    k.append(("esq", "-" * L))
    k.append(("esq", f"PEDIDOS: {len(pedidos)}"))
    k.append(("esq", f"TOTAL R$ {float(valor_total):>22.2f}"))
    k.append(("esq", "=" * L))
    k.append(("centro", "PAGUE VIA PIX"))
    k.append(("centro", "Aponte a camera do celular"))
    if payment_id:
        k.append(("centro", f"REF MP: {str(payment_id)[-8:]}"))
    k.append(("qr", ""))
    k.append(("centro", ""))
    k.append(("centro", "@cumbuca.marco"))
    k.append(("centro", "85 992425223"))
    k.append(("centro", "Obrigado e Volte Sempre"))
    return k


def imprimir_resumo_cobranca_pix(id_cobranca, cliente, pedidos, valor_total, codigo_pix, payment_id=""):
    """
    Imprime o resumo da cobranca Pix na POS-58 (mesmo padrao de imprimir_cupom_pedido,
    porem layout proprio). DEVE ser chamada na thread principal do Tk (botao/root.after),
    como as demais impressoes. Retorna True se enviou, False se falhou.
    """
    hDC = None
    doc_iniciado = False
    try:
        printer_name = "POS-58"
        hDC = win32ui.CreateDC()
        hDC.CreatePrinterDC(printer_name)

        # 8 = HORZRES: largura util real da pagina em pixels (evita "chutar" 280).
        largura_pagina = hDC.GetDeviceCaps(8) or 280
        print(f"[PIX_RECEBER] Impressora {printer_name}: largura util = {largura_pagina}px")

        img_qr, box_qr = gerar_imagem_qr_pix(codigo_pix, largura_max=min(largura_pagina - 16, 300))
        larg_qr, alt_qr = img_qr.size
        linhas = montar_linhas_resumo_pix(id_cobranca, cliente, pedidos, valor_total, payment_id)

        hDC.StartDoc(f"CobrancaPix_{id_cobranca}")
        doc_iniciado = True
        hDC.StartPage()
        desenhar_logo_titulo_cupom(hDC)

        hDC.SelectObject(win32ui.CreateFont({'name': 'Courier New', 'height': 21, 'weight': 400}))
        espaco_linha = 22
        y = 88

        for tipo, texto in linhas:
            if tipo == "qr":
                y += 6
                x = max(0, (largura_pagina - larg_qr) // 2)
                ImageWin.Dib(img_qr).draw(hDC.GetHandleOutput(), (x, y, x + larg_qr, y + alt_qr))
                y += alt_qr + 10
            elif tipo == "centro":
                hDC.TextOut(0, y, texto.center(COLUNAS_CUPOM_PIX))
                y += espaco_linha
            else:
                hDC.TextOut(0, y, texto)
                y += espaco_linha

        hDC.EndPage()
        hDC.EndDoc()
        doc_iniciado = False
        return True

    except Exception as erro:
        if doc_iniciado and hDC is not None:
            try:
                hDC.AbortDoc()
            except Exception:
                pass
        messagebox.showerror("Erro de Impressão", f"Causa: {erro}")
        return False
    finally:
        if hDC is not None:
            try:
                hDC.DeleteDC()
            except Exception:
                pass


def imprimir_comanda_cozinha(numero_mesa, cliente, garcom, itens):
    """
    Imprime a comanda de cozinha (pratos de carne/peixe lançados pelo
    garçom no celular), na mesma POS-58 do cupom do cliente. É algo
    NOVO, com layout propositalmente diferente do cupom final
    (imprimir_cupom_pedido): sem Pix, sem total, sem forma de
    pagamento — só o que a cozinha precisa saber pra produzir o
    prato: mesa, cliente, prato, quantidade e observação.

    Chamada pelo garcom_api.py (rota_comanda_cozinha) quando o garçom
    toca em "Enviar p/ cozinha" na tela de comanda do app, sempre
    agendada na thread principal (root.after) igual à impressão do
    cupom, porque win32print/win32ui só pode ser chamado por ela.

    itens: lista de dicts {"produto": str, "quantidade": int, "obs": str|None}.
    Retorna True se a impressão foi enviada, False se falhou.
    """
    try:
        printer_name = "POS-58"
        hDC = win32ui.CreateDC()
        hDC.CreatePrinterDC(printer_name)
        hDC.StartDoc(f"Cozinha_Mesa_{numero_mesa}")
        hDC.StartPage()

        fonte_titulo = win32ui.CreateFont({'name': 'Arial', 'height': 26, 'weight': 700})
        hDC.SelectObject(fonte_titulo)
        hDC.TextOut(10, 12, "COZINHA")

        font = win32ui.CreateFont({'name': 'Courier New', 'height': 22, 'weight': 400})
        hDC.SelectObject(font)
        font_negrito = win32ui.CreateFont({'name': 'Courier New', 'height': 24, 'weight': 700})

        L, espaco_linha = 32, 24
        y = 56
        data_atual = datetime.now().strftime("%d/%m/%Y")
        hora_atual = datetime.now().strftime("%H:%M")

        def p_centro(texto, negrito=False):
            nonlocal y
            hDC.SelectObject(font_negrito if negrito else font)
            hDC.TextOut(0, y, str(texto).center(L))
            y += espaco_linha

        def p_esq(texto, negrito=False):
            nonlocal y
            hDC.SelectObject(font_negrito if negrito else font)
            texto_str = str(texto)
            while len(texto_str) > L:
                quebra = texto_str[:L]
                hDC.TextOut(0, y, quebra)
                y += espaco_linha
                texto_str = texto_str[L:]
            hDC.TextOut(0, y, texto_str)
            y += espaco_linha

        p_centro("=" * L)
        p_esq(f"MESA: {str(numero_mesa).upper()}", negrito=True)
        if cliente:
            p_esq(f"CLIENTE: {str(cliente).upper()[:23]}")
        if garcom:
            p_esq(f"GARCOM: {str(garcom).upper()[:24]}")
        p_esq(f"{data_atual}  {hora_atual}")
        p_centro("-" * L)

        for item in itens:
            try:
                qtd = int(item.get("quantidade", 1))
            except (TypeError, ValueError):
                qtd = 1
            produto = str(item.get("produto", "")).upper()
            obs = (item.get("obs") or "").strip()
            p_esq(f"{qtd}x {produto}", negrito=True)
            if obs:
                p_esq(f"  OBS: {obs.upper()}")
            y += 4

        p_centro("-" * L)
        p_centro("=" * L)

        hDC.EndPage()
        hDC.EndDoc()
        hDC.DeleteDC()
        return True

    except Exception as e:
        print(f"[cozinha] Erro ao imprimir comanda de cozinha: {e}")
        return False


def calcular_crc16(payload):
    """Calcula o CRC16 CCITT (0xFFFF) necessário para o padrão Pix."""
    crc = 0xFFFF
    for char in payload:
        crc ^= (ord(char) << 8)
        for _ in range(8):
            if (crc & 0x8000):
                crc = (crc << 1) ^ 0x1021
            else:
                crc <<= 1
            crc &= 0xFFFF
    return f"{crc:04X}"

def gerar_pix_com_valor(valor_total, pedido_id):
    chave_pix = "cumbuca.marco@gmail.com"

    # ==============================
    # VALOR
    # ==============================
    valor_str = f"{float(valor_total):.2f}"
    len_valor = f"{len(valor_str):02d}"

    # ==============================
    # MERCHANT ACCOUNT (PADRÃO CORRETO)
    # ==============================
    chave_len = f"{len(chave_pix):02d}"

    merchant_account = (
        "26"
        + f"{len('0014BR.GOV.BCB.PIX01' + chave_len + chave_pix):02d}"
        + "0014BR.GOV.BCB.PIX"
        + "01"
        + chave_len
        + chave_pix
    )

    # ==============================
    # TXID (PEDIDO)
    # ==============================
    txid = f"PED{pedido_id}"
    txid_len = f"{len(txid):02d}"

    campo_txid = (
        "62"
        + f"{len('05' + txid_len + txid):02d}"
        + "05"
        + txid_len
        + txid
    )

    # ==============================
    # MONTAGEM
    # ==============================
    partes = [
        "000201",
        "010211",
        merchant_account,
        "52040000",
        "5303986",
        "54" + len_valor + valor_str,
        "5802BR",
        "5907Cumbuca",
        "6009SAO PAULO",
        campo_txid
    ]

    payload_sem_crc = "".join(partes) + "6304"

    crc_final = calcular_crc16(payload_sem_crc)

    return payload_sem_crc + crc_final


def valor_do_pix_copia_e_cola(codigo):
    """
    Le o valor (tag 54) de um Pix copia-e-cola no padrao EMV.
    Retorna float, ou None se nao der para ler (nesse caso nao se bloqueia nada).
    """
    try:
        codigo = str(codigo or "")
        i = 0
        while i + 4 <= len(codigo):
            tag = codigo[i:i + 2]
            tam = int(codigo[i + 2:i + 4])
            if tag == "54":
                return float(codigo[i + 4:i + 4 + tam])
            i += 4 + tam
    except Exception:
        pass
    return None


def obter_pix_mercado_pago_para_nota(pedido_id, valor_total, cliente=""):
    """
    Pede o Pix da nota ao servidor e CONFERE se o valor dentro do QR recebido bate com
    o total pedido. Se vier QR com valor diferente (cobranca antiga), manda cancelar e
    pede de novo uma unica vez; se ainda divergir, devolve None para quem chamou usar
    o Pix de contingencia com o valor correto, em vez de imprimir um valor errado.
    """
    valor_esperado = round(float(valor_total or 0), 2)
    for tentativa in (1, 2):
        dados = _requisitar_pix_mercado_pago_nota(pedido_id, valor_total, cliente)
        if dados is None:
            return None
        valor_qr = valor_do_pix_copia_e_cola(dados.get("qr_code"))
        if valor_qr is None or abs(valor_qr - valor_esperado) <= 0.009:
            return dados
        print(f"[MP] QR do pedido #{pedido_id} veio com R$ {valor_qr:.2f}, esperado R$ {valor_esperado:.2f} "
              f"(tentativa {tentativa}).")
        if tentativa == 2:
            break
        res = cancelar_pix_nota_mercado_pago(pedido_id, "valor_divergente_nota")
        if res not in ("cancelado", "nada"):
            break
    print(f"[MP] Nao usei o QR do Mercado Pago do pedido #{pedido_id}: valor divergente.")
    return None


def _requisitar_pix_mercado_pago_nota(pedido_id, valor_total, cliente=""):
    payload = json.dumps({
        "id_pedido": str(pedido_id),
        "valor": float(valor_total or 0),
        "cliente": str(cliente or ""),
    }).encode("utf-8")
    req = urllib.request.Request(
        "http://127.0.0.1:5000/api/mercadopago/pix",
        data=payload,
        headers={"Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=8) as resposta:
            dados = json.loads(resposta.read().decode("utf-8"))
    except Exception as erro:
        print(f"[MP] Nao consegui gerar Pix Mercado Pago para pedido #{pedido_id}: {erro}")
        return None

    if dados.get("status") != "sucesso" or not dados.get("qr_code"):
        print(f"[MP] Resposta sem QR Code para pedido #{pedido_id}: {dados}")
        return None
    return dados


def cancelar_pix_nota_mercado_pago(pedido_id, motivo="pedido_editado"):
    """
    Pede ao servidor que cancele no Mercado Pago o Pix da NOTA / "Copiar chave Pix"
    do pedido (esse Pix nao passa por contas_receber_pix_pendentes).
    Retorna "cancelado", "pago", "nada" ou None (servidor inacessivel / erro).
    """
    payload = json.dumps({"id_pedido": str(pedido_id), "motivo": motivo}).encode("utf-8")
    req = urllib.request.Request(
        "http://127.0.0.1:5000/api/mercadopago/pix/cancelar",
        data=payload,
        headers={"Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=12) as resposta:
            dados = json.loads(resposta.read().decode("utf-8"))
    except Exception as erro:
        print(f"[MP] Nao consegui cancelar o Pix da nota do pedido #{pedido_id}: {erro}")
        return None
    if dados.get("status") != "sucesso":
        print(f"[MP] Cancelamento do Pix da nota do pedido #{pedido_id} falhou: {dados}")
        return None
    return dados.get("resultado")


def reimprimir():
    # 1. Tenta obter a seleção de uma das duas tabelas (Caixa Aberto ou Histórico Anterior)
    sel = lista_caixa_atual.selection() or lista_caixa_fechado.selection()
    
    if not sel:
        messagebox.showwarning("Aviso", "Selecione um pedido na lista para imprimir!")
        return

    try:
        # 2. Pega o ID do pedido selecionado (iid da Treeview)
        pedido_id = int(sel[0])
        
        # 3. Chama a função de nota térmica que já configuramos
        # Ela vai perguntar se deseja imprimir, ler os dados do banco,
        # gerar o QR Code com o valor total e enviar para a POS-58.
        gerar_nota(pedido_id)

    except ValueError:
        messagebox.showerror("Erro", "Não foi possível identificar o ID do pedido selecionado.")
    except Exception as e:
        messagebox.showerror("Erro de Reimpressão", f"Falha ao processar reimpressão: {e}")


def copiar_chave_pix_pedido_selecionado():
    """
    Copia para a área de transferência o mesmo código Pix (copia e cola)
    que já é usado para gerar o QR Code do cupom — via
    obter_pix_mercado_pago_para_nota() / gerar_pix_com_valor(), ambas já
    existentes e usadas em imprimir_cupom_pedido(). Nenhuma delas é
    alterada aqui; esta função só reaproveita o valor já gerado por elas.

    Funciona apenas com pedidos do Caixa Aberto (lista_caixa_atual).
    Pedidos do Histórico Anterior não usam esta função pois a chave já
    pode estar expirada.
    """
    sel = lista_caixa_atual.selection()

    if not sel:
        messagebox.showwarning("Aviso", "Selecione um pedido do Caixa Aberto para copiar o código Pix.")
        return

    try:
        pedido_id = int(sel[0])

        cursor.execute("SELECT cliente, total, pagamento FROM pedidos WHERE id = ?", (pedido_id,))
        pedido = cursor.fetchone()

        if not pedido:
            messagebox.showerror("Erro", "Pedido não encontrado.")
            return

        cliente, total, pagamento = pedido
        forma = padronizar_forma_pagamento(pagamento)

        if forma.lower() not in ("pix", "pendente"):
            messagebox.showwarning(
                "Aviso",
                f"Este pedido está como \"{forma}\" e não tem chave Pix para copiar."
            )
            return

        pix_mp = obter_pix_mercado_pago_para_nota(pedido_id, float(total or 0), cliente)
        pix_codigo = (pix_mp or {}).get("qr_code") or gerar_pix_com_valor(float(total or 0), pedido_id)

        if not pix_codigo:
            messagebox.showerror("Erro", "Não foi possível gerar o código Pix deste pedido.")
            return

        root.clipboard_clear()
        root.clipboard_append(pix_codigo)
        root.update()

        messagebox.showinfo("Pix copiado", "Código Pix copiado! Cole na conversa com o cliente.")

    except Exception as e:
        messagebox.showerror("Erro", f"Falha ao copiar o código Pix:\n{e}")


def gerar_qrcode_pix_pedido_selecionado():
    """
    Gera um QR Code Pix (Mercado Pago, via servidor.py) para o pedido
    selecionado no Caixa Aberto e mostra numa janela ENXUTA: apenas o texto de
    status e o QR na tela (sem copia-e-cola, sem impressao).

    So resolve a selecao da Treeview e repassa para gerar_qrcode_pix_para_pedido(),
    que tem TODO o corpo original desta funcao (sem nenhuma alteracao de logica) --
    assim ela tambem pode ser chamada de outros lugares (ex.: Finalizar Mesa)
    passando o pedido_id diretamente, sem depender de nenhuma selecao na tela.
    """
    sel = lista_caixa_atual.selection()
    if not sel:
        messagebox.showwarning("Aviso", "Selecione um pedido do Caixa Aberto para gerar o QR Code Pix.")
        return

    try:
        pedido_id = int(sel[0])
    except (TypeError, ValueError):
        messagebox.showerror("Erro", "Nao foi possivel identificar o pedido selecionado.")
        return

    gerar_qrcode_pix_para_pedido(pedido_id)


def gerar_qrcode_pix_para_pedido(pedido_id):
    """
    Reaproveita EXATAMENTE a mesma infraestrutura ja usada em Contas a Receber,
    sem alterar nada dela:
      - registro em contas_receber_pix_pendentes (status AGUARDANDO)
      - solicitacao gravada em PASTA_PIX_RECEBER_SOLICITACOES (servidor.py responde)
      - imagem do QR feita por gerar_imagem_qr_pix() + qr_imagem_para_base64()
      - baixa automatica pela thread monitorar_confirmacoes_pix_receber()

    Quando a baixa acontecer (status vira 'PAGO'), o texto muda para
    "PAGAMENTO EFETUADO" em verde/negrito e a janela fecha sozinha em 5s.

    Corpo IDENTICO ao que existia antes dentro de gerar_qrcode_pix_pedido_selecionado,
    so que recebendo pedido_id como parametro em vez de ler da selecao da Treeview.
    """
    if not ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Aviso", "Abra o caixa antes de gerar uma cobranca Pix!")
        return

    # Valor e situacao vem do BANCO (nao do texto da tabela), com a MESMA regra
    # que a baixa automatica vai reaplicar depois.
    cursor.execute(
        "SELECT cliente, total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?",
        (pedido_id,)
    )
    pedido = cursor.fetchone()
    if not pedido:
        messagebox.showerror("Erro", "Pedido nao encontrado.")
        return

    cliente, total, valor_pago, pagamento = pedido
    if not pedido_elegivel_contas_receber(total, valor_pago, pagamento):
        messagebox.showwarning(
            "Aviso",
            f"O pedido #{pedido_id} esta como \"{padronizar_forma_pagamento(pagamento)}\" "
            f"e nao tem valor em aberto.\n\n"
            "So da para gerar QR Code Pix de pedido Pendente ou parcialmente pago,\n"
            "porque e essa a regra que a baixa automatica do Mercado Pago usa."
        )
        return

    valor_total = round(float(total or 0) - float(valor_pago or 0), 2)
    if valor_total <= 0:
        messagebox.showwarning("Aviso", "Este pedido nao tem mais valor em aberto.")
        return

    cliente = str(cliente or "").strip()

    # Protecao contra cobranca dupla: so pode haver UMA cobranca Pix valida por pedido.
    # Primeiro tira da fila as desatualizadas (valor mudou, pedido pago/cancelado, vencida).
    try:
        sincronizar_cobrancas_pix_pendentes(pedido_ids=[pedido_id], avisar=False)
        conflitos = buscar_cobrancas_pix_abertas([pedido_id])
    except Exception as erro:
        print(f"[PIX_PEDIDO] Aviso: falha ao checar cobranca duplicada: {erro}")
        conflitos = []

    # Mesmo pedido e mesmo valor, QR ainda valido: so reabre a janela com o MESMO codigo.
    reutilizar, conflitos = separar_cobranca_reutilizavel(conflitos, [pedido_id], valor_total)

    if conflitos:
        resumo_conf = "\n".join(
            f"- R$ {c['valor']:.2f}, gerado as {str(c['criado_em'])[11:16]} "
            f"(pedidos {', '.join('#' + str(p) for p in c['pedido_ids'])})"
            for c in conflitos
        )
        if not messagebox.askyesno(
            "Ja existe Pix aguardando",
            f"Ja existe cobranca Pix aguardando pagamento para o pedido #{pedido_id}:\n\n{resumo_conf}\n\n"
            f"Para evitar pagamento em duplicidade, a cobranca anterior sera CANCELADA e "
            + ("o QR ja gerado para este pedido sera reaberto." if reutilizar is not None else
               f"uma nova de R$ {valor_total:.2f} sera gerada.")
            + "\n\nContinuar?"
        ):
            return
        for c in conflitos:
            if not cancelar_cobranca_pix_local(c["id"], c["payment_id"], "substituida_por_nova_cobranca"):
                messagebox.showerror(
                    "Erro",
                    "Nao foi possivel cancelar a cobranca anterior (pasta compartilhada indisponivel?).\n"
                    "Nenhuma cobranca nova foi gerada."
                )
                return

    if reutilizar is not None:
        id_cobranca = reutilizar["id"]
        registrar_log("PEDIDO_PIX_QR_REABERTO", "FINANCEIRO", id_cobranca, {
            "pedidos": [pedido_id], "valor_total": valor_total
        })
    else:
        id_cobranca = f"CR-{uuid.uuid4().hex[:12]}"
        criado_em = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        try:
            cursor.execute("""
                INSERT INTO contas_receber_pix_pendentes
                (id_cobranca, pedido_ids, valor_total, cliente, status, criado_em)
                VALUES (?, ?, ?, ?, 'AGUARDANDO', ?)
            """, (id_cobranca, json.dumps([pedido_id]), valor_total, cliente or None, criado_em))
            conn.commit()
        except Exception as erro:
            conn.rollback()
            messagebox.showerror("Erro", f"Nao foi possivel registrar a cobranca:\n{erro}")
            return

        try:
            # Escrita atomica (.tmp + replace): o servidor.py so le JSON completo.
            salvar_json_atomico(
                os.path.join(PASTA_PIX_RECEBER_SOLICITACOES, f"{id_cobranca}.json"),
                {
                    "id_cobranca": id_cobranca,
                    "valor_total": valor_total,
                    "cliente": cliente,
                    "pedido_ids": [pedido_id],
                }
            )
        except Exception as erro:
            cursor.execute(
                "UPDATE contas_receber_pix_pendentes SET status='ERRO' WHERE id_cobranca=?",
                (id_cobranca,)
            )
            conn.commit()
            messagebox.showerror("Erro", f"Nao foi possivel enviar a solicitacao ao servidor:\n{erro}")
            return

        registrar_log("PEDIDO_PIX_QR_GERADO", "FINANCEIRO", id_cobranca, {
            "pedidos": [pedido_id], "valor_total": valor_total, "cliente": cliente
        })

    # ---------------- Janela enxuta: status + QR ----------------
    janela_qr_ped = tk.Toplevel(root)
    janela_qr_ped.title(f"QR Code Pix - Pedido #{pedido_id}")
    janela_qr_ped.geometry("360x470")
    janela_qr_ped.resizable(False, False)
    janela_qr_ped.transient(root)

    # tk.Label (nao ttk) para poder trocar cor e fonte na confirmacao.
    lbl_status_ped = tk.Label(
        janela_qr_ped,
        text="Aguardando pagamento...",
        font=("Arial", 13, "bold"),
        fg="#555555",
    )
    lbl_status_ped.pack(pady=(18, 10))

    lbl_img_ped = tk.Label(janela_qr_ped)
    lbl_img_ped.pack(pady=4)

    tk.Label(
        janela_qr_ped,
        text=f"Pedido #{pedido_id}  -  R$ {valor_total:.2f}"
             + (f"\n{cliente}" if cliente else ""),
        font=("Arial", 10), justify="center"
    ).pack(pady=(10, 12))

    estado_ped = {"inicio": time.time(), "foto": None}
    caminho_resposta_ped = os.path.join(PASTA_PIX_RECEBER_RESPOSTAS, f"{id_cobranca}.json")

    def mostrar_qr_pedido(resp):
        codigo = str(resp.get("qr_code") or "")
        qr_b64 = str(resp.get("qr_code_base64") or "")
        payment_id = str(resp.get("payment_id") or "")

        try:
            cursor.execute(
                "UPDATE contas_receber_pix_pendentes SET payment_id=? WHERE id_cobranca=?",
                (payment_id, id_cobranca)
            )
            conn.commit()
        except Exception as erro:
            print(f"[PIX_PEDIDO] Falha ao gravar payment_id de {id_cobranca}: {erro}")

        try:
            if codigo:
                cursor.execute(
                    "UPDATE contas_receber_pix_pendentes SET qr_code=? WHERE id_cobranca=?",
                    (codigo, id_cobranca)
                )
                conn.commit()
        except Exception as erro:
            print(f"[PIX_PEDIDO] Falha ao guardar o codigo do QR de {id_cobranca}: {erro}")

        try:
            os.remove(caminho_resposta_ped)
        except Exception:
            pass

        # QR na tela: gerado LOCALMENTE a partir do copia-e-cola (mesma funcao da
        # janela de Contas a Receber). Se falhar, cai no PNG do Mercado Pago.
        # ATENCAO: master=janela_qr_ped e OBRIGATORIO — este sistema tem duas
        # raizes Tk e uma PhotoImage sem master nasce na raiz errada.
        foto = None
        erros_qr = []
        if codigo:
            try:
                img_qr, _box = gerar_imagem_qr_pix(codigo, largura_max=260)
                foto = tk.PhotoImage(master=janela_qr_ped, data=qr_imagem_para_base64(img_qr))
            except Exception as erro:
                erros_qr.append(f"local: {erro}")
        if foto is None and qr_b64:
            try:
                b64 = qr_b64.split(",", 1)[1] if qr_b64.startswith("data:") and "," in qr_b64 else qr_b64
                foto = tk.PhotoImage(master=janela_qr_ped, data=b64)
                fator = max(1, -(-foto.width() // 260))   # teto da divisao: cabe em ~260px
                if fator > 1:
                    foto = foto.subsample(fator, fator)
            except Exception as erro:
                erros_qr.append(f"mercadopago: {erro}")

        if foto is not None:
            try:
                lbl_img_ped.config(image=foto)
                estado_ped["foto"] = foto          # mantem a referencia viva
            except Exception as erro:
                erros_qr.append(f"exibir: {erro}")
                foto = None

        if foto is None:
            print(f"[PIX_PEDIDO] Erro ao exibir QR de {id_cobranca}: "
                  f"{'; '.join(erros_qr) or 'resposta sem QR'}")
            lbl_img_ped.config(text="QR indisponivel - tente gerar novamente.", font=("Arial", 10))

        root.after(2000, checar_pagamento_pedido)

    def checar_resposta_pedido():
        if not janela_qr_ped.winfo_exists():
            return
        if os.path.exists(caminho_resposta_ped):
            try:
                with open(caminho_resposta_ped, "r", encoding="utf-8") as f:
                    resp = json.load(f)
            except Exception:
                resp = None   # arquivo ainda sendo escrito: tenta no proximo ciclo
            if resp is not None:
                if resp.get("erro"):
                    lbl_status_ped.config(text=f"Erro do servidor: {resp.get('erro')}")
                    if reutilizar is not None and not resp.get("pago"):
                        # O QR antigo nao existe mais no servidor: sai da fila para o proximo clique gerar outro.
                        try:
                            os.remove(caminho_resposta_ped)
                        except Exception:
                            pass
                        cancelar_cobranca_pix_local(id_cobranca, reutilizar["payment_id"], "qr_irrecuperavel")
                        lbl_status_ped.config(text="QR anterior nao encontrado. Clique em Gerar QR de novo.")
                    return
                mostrar_qr_pedido(resp)
                return
        if time.time() - estado_ped["inicio"] > 20:
            # Registro continua AGUARDANDO: o servidor ainda pode responder.
            lbl_status_ped.config(text="Nao foi possivel gerar o Pix.")
            messagebox.showwarning(
                "Pix", "Nao foi possivel gerar o Pix, tente novamente.", parent=janela_qr_ped
            )
            return
        root.after(1500, checar_resposta_pedido)

    def checar_pagamento_pedido():
        # Apenas visual: quem da a baixa e a thread de fundo que ja existe.
        if not janela_qr_ped.winfo_exists():
            return
        try:
            cursor.execute(
                "SELECT status FROM contas_receber_pix_pendentes WHERE id_cobranca=?",
                (id_cobranca,)
            )
            row = cursor.fetchone()
        except Exception:
            row = None
        if row and row[0] == "PAGO":
            lbl_status_ped.config(
                text="PAGAMENTO EFETUADO",
                fg="#27ae60",
                font=("Arial", 15, "bold"),
            )
            # Segura a janela 5 segundos para o operador ver a confirmacao.
            root.after(5000, lambda: janela_qr_ped.winfo_exists() and janela_qr_ped.destroy())
            return
        if row and row[0] in ("CANCELADO", "EXPIRADO"):
            lbl_status_ped.config(
                text="COBRANCA CANCELADA - gere um novo QR",
                fg="#c0392b",
                font=("Arial", 12, "bold"),
            )
            return
        root.after(2000, checar_pagamento_pedido)

    if reutilizar is not None and reutilizar.get("qr_code"):
        # QR ja criado e valido: mostra o MESMO codigo, sem pedir nada ao servidor.
        mostrar_qr_pedido({"qr_code": reutilizar["qr_code"], "payment_id": reutilizar["payment_id"]})
    elif reutilizar is not None:
        # Valido, mas o codigo nao estava guardado (QR criado antes): o servidor devolve o MESMO.
        lbl_status_ped.config(text="Recuperando o QR ja gerado...")
        solicitar_reenvio_qr_pix(reutilizar)
        root.after(1500, checar_resposta_pedido)
    else:
        root.after(1500, checar_resposta_pedido)


# ======================= MAQUININHA POINT - ENVIO DA COBRANCA =================
# Caminho paralelo ao QR Pix: nao usa contas_receber_pix_pendentes nem pix_receber_*.
# Tudo aqui roda na thread principal do Tk (root.after) e nao faz chamada de rede:
# a conversa com o Mercado Pago e feita pelo servidor.py, por arquivos.
POINT_TIMEOUT_RESPOSTA = 20          # segundos esperando o servidor responder
POINT_PARCELAS_MAX = 12

# status que o servidor.py escreve em point_respostas/<id>.json -> status do banco
POINT_STATUS_SERVIDOR_FINAIS = {
    "cancelado": "CANCELADO",
    "falhou": "ERRO",
    "expirado": "EXPIRADO",
    "reembolsado": "ERRO",
    "valor_divergente": "ERRO",
}
POINT_NOMES_FORMA = {
    "pix": "Pix",
    "credito": "Crédito",
    "debito": "Débito",
    "todas": "Escolher na maquininha",
}
POINT_MSG_TERMINAL_OCUPADO = (
    "A maquininha já está com outra cobrança em espera.\n\n"
    "Conclua ou cancele a cobrança que está na tela da maquininha "
    "e envie esta de novo."
)


def ler_resposta_point(id_cobranca):
    """Le point_respostas/<id>.json. Devolve dict, ou None se nao existe/ainda esta sendo escrito."""
    caminho = os.path.join(PASTA_POINT_RESPOSTAS, f"{id_cobranca}.json")
    if not os.path.exists(caminho):
        return None
    try:
        with open(caminho, "r", encoding="utf-8") as f:
            dados = json.load(f)
        return dados if isinstance(dados, dict) else None
    except Exception:
        return None


def atualizar_status_point(id_cobranca, novo_status, order_id=None):
    """Atualiza point_cobrancas. NUNCA mexe numa cobranca que ja esta PAGA."""
    try:
        cursor.execute("""
            UPDATE point_cobrancas
            SET status=?, order_id=COALESCE(NULLIF(?, ''), order_id)
            WHERE id_cobranca=? AND status<>'PAGO'
        """, (novo_status, order_id or "", id_cobranca))
        conn.commit()
    except Exception as erro:
        conn.rollback()
        print(f"[POINT] Falha ao atualizar {id_cobranca} para {novo_status}: {erro}")


def sincronizar_point_pedido(pedido_id):
    """
    Cobrancas AGUARDANDO do pedido cujo desfecho o servidor ja informou (cancelada,
    expirada, falhou...) sao encerradas no banco. Devolve as que continuam realmente
    aguardando: [(id_cobranca, valor, forma, status_resposta)].
    """
    cursor.execute("""
        SELECT id_cobranca, valor, forma FROM point_cobrancas
        WHERE pedido_id=? AND status='AGUARDANDO'
    """, (pedido_id,))
    ativas = []
    for id_cobranca, valor, forma in cursor.fetchall():
        resp = ler_resposta_point(id_cobranca) or {}
        if resp.get("erro"):
            atualizar_status_point(id_cobranca, "ERRO")
            continue
        status_resp = str(resp.get("status") or "").lower()
        if status_resp in POINT_STATUS_SERVIDOR_FINAIS:
            atualizar_status_point(id_cobranca, POINT_STATUS_SERVIDOR_FINAIS[status_resp],
                                   resp.get("order_id"))
            continue
        ativas.append((id_cobranca, valor, forma, status_resp))
    return ativas


def enviar_maquininha_pedido_selecionado():
    """Botao 'Cobrar maquininha': le o pedido selecionado no Caixa Aberto."""
    sel = lista_caixa_atual.selection()
    if not sel:
        messagebox.showwarning("Aviso", "Selecione um pedido do Caixa Aberto para cobrar na maquininha.")
        return
    try:
        pedido_id = int(sel[0])
    except (TypeError, ValueError):
        messagebox.showerror("Erro", "Não foi possível identificar o pedido selecionado.")
        return
    enviar_maquininha_para_pedido(pedido_id)


def enviar_maquininha_para_pedido(pedido_id):
    if not ciclo_caixa_aberto.get("id"):
        messagebox.showwarning("Aviso", "Abra o caixa antes de cobrar na maquininha!")
        return

    # Valor e situacao vem do BANCO, com a mesma regra que a baixa vai reaplicar.
    cursor.execute(
        "SELECT cliente, total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?",
        (pedido_id,)
    )
    pedido = cursor.fetchone()
    if not pedido:
        messagebox.showerror("Erro", "Pedido não encontrado.")
        return

    cliente, total, valor_pago, pagamento = pedido
    if not pedido_elegivel_contas_receber(total, valor_pago, pagamento):
        messagebox.showwarning(
            "Aviso",
            f"O pedido #{pedido_id} está como \"{padronizar_forma_pagamento(pagamento)}\" "
            f"e não tem valor em aberto.\n\n"
            "Só dá para cobrar na maquininha pedido Pendente ou parcialmente pago, "
            "porque é essa a regra que a baixa automática usa."
        )
        return

    valor = round(float(total or 0) - float(valor_pago or 0), 2)
    if valor <= 0:
        messagebox.showwarning("Aviso", "Este pedido não tem mais valor em aberto.")
        return
    cliente = str(cliente or "").strip()

    # 1) Ja existe cobranca na maquininha aguardando para este pedido?
    try:
        ativas = sincronizar_point_pedido(pedido_id)
    except Exception as erro:
        print(f"[POINT] Aviso: falha ao checar cobrança anterior: {erro}")
        ativas = []
    if ativas:
        id_ant, valor_ant, forma_ant, _st = ativas[0]
        if messagebox.askyesno(
            "Já existe cobrança na maquininha",
            f"O pedido #{pedido_id} já tem uma cobrança de R$ {float(valor_ant):.2f} "
            f"aguardando na maquininha.\n\n"
            "Deseja abrir a janela dela para acompanhar ou cancelar?"
        ):
            abrir_janela_espera_point(id_ant, pedido_id, float(valor_ant), forma_ant, cliente,
                                      ja_enviado=True)
        return

    # 2) Pix pendente gerado pela tela para o mesmo pedido: evita cobranca dupla.
    try:
        from datetime import timedelta
        limite = (datetime.now() - timedelta(minutes=60)).strftime("%Y-%m-%d %H:%M:%S")
        cursor.execute("""
            SELECT pedido_ids FROM contas_receber_pix_pendentes
            WHERE status='AGUARDANDO' AND COALESCE(payment_id,'') <> '' AND criado_em >= ?
        """, (limite,))
        pix_aguardando = False
        for (ids_json,) in cursor.fetchall():
            try:
                if pedido_id in {int(x) for x in json.loads(ids_json)}:
                    pix_aguardando = True
                    break
            except Exception:
                continue
    except Exception as erro:
        print(f"[POINT] Aviso: falha ao checar Pix pendente: {erro}")
        pix_aguardando = False

    if pix_aguardando and not messagebox.askyesno(
        "Já existe Pix aguardando",
        f"Já existe um QR Code Pix aguardando pagamento para o pedido #{pedido_id}.\n\n"
        "Cobrar também na maquininha pode fazer o cliente pagar duas vezes.\n"
        "Cobrar mesmo assim?"
    ):
        return

    abrir_janela_forma_point(pedido_id, valor, cliente)


def abrir_janela_forma_point(pedido_id, valor, cliente):
    """Janela de escolha da forma de pagamento da maquininha."""
    jan = tk.Toplevel(root)
    jan.title(f"Cobrar na maquininha - Pedido #{pedido_id}")
    jan.geometry("360x560")
    jan.resizable(False, False)
    jan.transient(root)

    tk.Label(jan, text=f"Pedido #{pedido_id}", font=("Arial", 12, "bold")).pack(pady=(16, 0))
    tk.Label(jan, text=f"R$ {valor:.2f}", font=("Arial", 20, "bold"), fg="#27ae60").pack(pady=(0, 2))
    if cliente:
        tk.Label(jan, text=cliente, font=("Arial", 10), fg="#555555").pack()
    tk.Label(jan, text="Forma de pagamento:", font=("Arial", 10)).pack(pady=(14, 6))

    var_parcelas = tk.StringVar(master=jan, value="1")

    def escolher(forma):
        parcelas = None
        if forma == "credito":
            try:
                n = int(var_parcelas.get())
            except (TypeError, ValueError):
                n = 1
            parcelas = n if 1 < n <= POINT_PARCELAS_MAX else None
        jan.destroy()
        registrar_envio_point(pedido_id, valor, cliente, forma, parcelas)

    estilo = dict(width=26)
    ttk.Button(jan, text="📲  Pix", command=lambda: escolher("pix"), **estilo).pack(pady=3)
    ttk.Button(jan, text="💳  Débito", command=lambda: escolher("debito"), **estilo).pack(pady=3)
    ttk.Button(jan, text="💳  Crédito", command=lambda: escolher("credito"), **estilo).pack(pady=3)

    frame_parc = tk.Frame(jan)
    frame_parc.pack(pady=(0, 4))
    tk.Label(frame_parc, text="Parcelas (crédito):", font=("Arial", 9), fg="#555555").pack(side="left")
    ttk.Combobox(
        frame_parc, textvariable=var_parcelas, state="readonly", width=4,
        values=[str(i) for i in range(1, POINT_PARCELAS_MAX + 1)]
    ).pack(side="left", padx=6)

    ttk.Button(jan, text="Escolher na maquininha (todas)", command=lambda: escolher("todas"),
               **estilo).pack(pady=3)
    ttk.Button(jan, text="Voltar", command=jan.destroy, width=26).pack(pady=(10, 0))


def registrar_envio_point(pedido_id, valor, cliente, forma, parcelas):
    """Grava point_cobrancas (AGUARDANDO) + solicitacao para o servidor.py e abre a janela de espera."""
    id_cobranca = f"PT{uuid.uuid4().hex[:12]}"
    criado_em = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    try:
        cursor.execute("""
            INSERT INTO point_cobrancas (id_cobranca, pedido_id, valor, forma, status, criado_em)
            VALUES (?, ?, ?, ?, 'AGUARDANDO', ?)
        """, (id_cobranca, pedido_id, valor, forma, criado_em))
        conn.commit()
    except Exception as erro:
        conn.rollback()
        messagebox.showerror("Erro", f"Não foi possível registrar a cobrança:\n{erro}")
        return

    solicitacao = {
        "acao": "enviar",
        "id_cobranca": id_cobranca,
        "pedido_id": pedido_id,
        "valor": valor,
        "forma": forma,
        "cliente": cliente,
    }
    if parcelas:
        solicitacao["parcelas"] = parcelas

    try:
        salvar_json_atomico(
            os.path.join(PASTA_POINT_SOLICITACOES, f"{id_cobranca}_enviar.json"), solicitacao
        )
    except Exception as erro:
        atualizar_status_point(id_cobranca, "ERRO")
        messagebox.showerror("Erro", f"Não foi possível enviar a solicitação ao servidor:\n{erro}")
        return

    registrar_log("POINT_ENVIADO", "FINANCEIRO", id_cobranca, {
        "pedido_id": pedido_id, "valor": valor, "forma": forma, "parcelas": parcelas
    })
    abrir_janela_espera_point(id_cobranca, pedido_id, valor, forma, cliente)


def abrir_janela_espera_point(id_cobranca, pedido_id, valor, forma, cliente, ja_enviado=False):
    """Janela de acompanhamento (mesmo estilo da janela do QR)."""
    jan = tk.Toplevel(root)
    jan.title(f"Maquininha - Pedido #{pedido_id}")
    jan.geometry("400x470")
    jan.resizable(False, False)
    jan.transient(root)

    lbl_status = tk.Label(jan, text="Enviando...", font=("Arial", 13, "bold"),
                          fg="#555555", wraplength=360, justify="center")
    lbl_status.pack(pady=(20, 8))

    tk.Label(
        jan,
        text=f"R$ {float(valor):.2f}",
        font=("Arial", 22, "bold"), fg="#27ae60"
    ).pack(pady=(4, 0))
    tk.Label(
        jan,
        text=f"Pedido #{pedido_id}" + (f"  -  {cliente}" if cliente else "")
             + f"\nForma: {POINT_NOMES_FORMA.get(str(forma or 'todas'), forma)}",
        font=("Arial", 10), justify="center"
    ).pack(pady=(6, 14))

    estado = {"inicio": time.time(), "respondeu": ja_enviado, "fim": False,
              "cancelando": False, "timeout_avisado": False}

    btn_cancelar = ttk.Button(jan, text="Cancelar cobrança", state="disabled")
    btn_cancelar.pack(pady=4)
    btn_descartar = ttk.Button(jan, text="Descartar envio (servidor não respondeu)")
    # btn_descartar so aparece se o servidor nao responder

    def encerrar(texto, cor="#c0392b", fechar_em=None):
        estado["fim"] = True
        lbl_status.config(text=texto, fg=cor)
        btn_cancelar.configure(state="disabled")
        btn_descartar.pack_forget()
        if fechar_em:
            root.after(fechar_em, lambda: jan.winfo_exists() and jan.destroy())
        else:
            ttk.Button(jan, text="Fechar", command=jan.destroy).pack(pady=6)

    def cancelar():
        if estado["fim"] or estado["cancelando"]:
            return
        if not messagebox.askyesno("Cancelar", "Cancelar esta cobrança na maquininha?", parent=jan):
            return
        try:
            salvar_json_atomico(
                os.path.join(PASTA_POINT_SOLICITACOES,
                             f"{id_cobranca}_cancelar_{int(time.time())}.json"),
                {"acao": "cancelar", "id_cobranca": id_cobranca}
            )
        except Exception as erro:
            messagebox.showerror("Erro", f"Não foi possível enviar o cancelamento:\n{erro}", parent=jan)
            return
        estado["cancelando"] = True
        btn_cancelar.configure(state="disabled")
        lbl_status.config(text="Cancelando...", fg="#e67e22")
        registrar_log("POINT_CANCELAR_SOLICITADO", "FINANCEIRO", id_cobranca, {"pedido_id": pedido_id})

    def descartar():
        # So e seguro se o servidor ainda NAO pegou a solicitacao (arquivo ainda na pasta).
        arq = os.path.join(PASTA_POINT_SOLICITACOES, f"{id_cobranca}_enviar.json")
        if not os.path.exists(arq):
            messagebox.showwarning(
                "Maquininha",
                "O servidor já recebeu esta solicitação, então ela pode estar na maquininha.\n"
                "Aguarde ou confira o servidor.", parent=jan)
            return
        try:
            os.remove(arq)
        except Exception as erro:
            messagebox.showerror("Erro", f"Não foi possível descartar:\n{erro}", parent=jan)
            return
        atualizar_status_point(id_cobranca, "CANCELADO")
        registrar_log("POINT_DESCARTADO", "FINANCEIRO", id_cobranca, {"pedido_id": pedido_id})
        encerrar("Envio descartado.", "#555555")

    btn_cancelar.config(command=cancelar)
    btn_descartar.config(command=descartar)

    def ciclo():
        if estado["fim"] or not jan.winfo_exists():
            return

        # 1) Banco: a baixa automatica marca PAGO.
        try:
            cursor.execute("SELECT status FROM point_cobrancas WHERE id_cobranca=?", (id_cobranca,))
            row = cursor.fetchone()
        except Exception:
            row = None
        status_db = row[0] if row else None

        if status_db == "PAGO":
            encerrar("PAGAMENTO EFETUADO", "#27ae60", fechar_em=5000)
            return
        if status_db in ("CANCELADO", "EXPIRADO", "ERRO"):
            encerrar({"CANCELADO": "Cobrança cancelada.",
                      "EXPIRADO": "Cobrança expirada.",
                      "ERRO": "Cobrança encerrada com erro."}[status_db])
            return

        # 2) Resposta do servidor.
        resp = ler_resposta_point(id_cobranca)
        if resp is None:
            if (not estado["respondeu"] and not estado["timeout_avisado"]
                    and time.time() - estado["inicio"] > POINT_TIMEOUT_RESPOSTA):
                estado["timeout_avisado"] = True
                lbl_status.config(text="O servidor não respondeu.\nA cobrança continua registrada.",
                                  fg="#e67e22")
                btn_descartar.pack(pady=4)
        else:
            if estado["timeout_avisado"]:
                estado["timeout_avisado"] = False
                btn_descartar.pack_forget()

            if resp.get("erro"):
                atualizar_status_point(id_cobranca, "ERRO")
                if resp.get("codigo") == "terminal_ocupado":
                    texto = str(resp.get("erro") or "").strip() or POINT_MSG_TERMINAL_OCUPADO
                else:
                    texto = f"Erro do servidor: {resp.get('erro')}"
                registrar_log("POINT_ERRO_ENVIO", "FINANCEIRO", id_cobranca,
                              {"codigo": resp.get("codigo"), "erro": resp.get("erro")})
                encerrar(texto)
                return

            st = str(resp.get("status") or "").lower()
            estado["respondeu"] = True
            if st in POINT_STATUS_SERVIDOR_FINAIS:
                novo = POINT_STATUS_SERVIDOR_FINAIS[st]
                atualizar_status_point(id_cobranca, novo, resp.get("order_id"))
                if st == "valor_divergente":
                    registrar_log("POINT_DIVERGENCIA", "FINANCEIRO", id_cobranca, resp)
                    encerrar("A maquininha recebeu um valor diferente do cobrado.\n"
                             "Nenhuma baixa foi feita. Confira no Mercado Pago.")
                else:
                    encerrar({"cancelado": "Cobrança cancelada.",
                              "falhou": "Pagamento recusado/falhou na maquininha.",
                              "expirado": "Cobrança expirada.",
                              "reembolsado": "Pagamento reembolsado."}[st])
                return
            if st == "pago":
                if ciclo_caixa_aberto.get("id"):
                    lbl_status.config(text="Pagamento recebido!\nAplicando a baixa...", fg="#27ae60")
                else:
                    lbl_status.config(text="Pagamento recebido!\nA baixa será aplicada quando o caixa abrir.",
                                      fg="#e67e22")
                btn_cancelar.configure(state="disabled")
            elif estado["cancelando"] and resp.get("aviso_cancelamento"):
                # A API nao cancela order que ja esta na maquininha: so pela tela dela.
                estado["cancelando"] = False
                estado["aviso_cancel"] = True
                lbl_status.config(
                    text="Não é possível cancelar por aqui.\nCancele pela tela da maquininha.",
                    fg="#e67e22")
                btn_cancelar.configure(state="normal")
            elif not estado["cancelando"]:
                # status "aguardando": order criada na maquininha
                if resp.get("order_id"):
                    atualizar_status_point(id_cobranca, "AGUARDANDO", resp.get("order_id"))
                if not estado.get("aviso_cancel"):
                    lbl_status.config(text="Aguardando pagamento na maquininha", fg="#555555")
                btn_cancelar.configure(state="normal")

        if not estado["respondeu"] and not estado["timeout_avisado"]:
            lbl_status.config(text="Enviando...", fg="#555555")

        root.after(1500, ciclo)

    root.after(800, ciclo)






