def ordenar_coluna(tree, col, reverse):
    l = [(tree.set(k, col), k) for k in tree.get_children('')]
    try:
        l.sort(key=lambda t: float(str(t[0]).replace(',', '.')), reverse=reverse)
    except ValueError:
        l.sort(key=lambda t: str(t[0]).lower(), reverse=reverse)
    for index, (val, k) in enumerate(l):
        tree.move(k, '', index)
    tree.heading(col, command=lambda: ordenar_coluna(tree, col, not reverse))

def criar_treeview(parent):
    cols = ("ID", "Cliente", "Pagamento", "Total", "Data", "Observação", "ENT", "PAG")
    tree = ttk.Treeview(parent, columns=cols, show="headings")

    for c in cols:
        tree.heading(c, text=c, command=lambda _c=c: ordenar_coluna(tree, _c, False))

    tree.column("ID", width=40, anchor="center")
    tree.column("Cliente", width=120, anchor="w")
    tree.column("Pagamento", width=80, anchor="center")
    tree.column("Total", width=60, anchor="e")
    tree.column("Data", width=110, anchor="center")
    tree.column("Observação", width=150, anchor="w")
    tree.column("ENT", width=40, anchor="center") 
    tree.column("PAG", width=40, anchor="center")

    # [TEMA MODERNO] Tons pastel, sem negrito em excesso
    # Pendente: amarelo suave
    tree.tag_configure('pendente',
        background='#FFF7E0', foreground='#92660A',
        font=('Segoe UI', 9))
    # Pago total: verde suave
    tree.tag_configure('pago',
        background='#EAF6EE', foreground='#1E7A44',
        font=('Segoe UI', 9))
    # Parcial: azul suave
    tree.tag_configure('parcial',
        background='#E8F1FB', foreground='#1D4ED8',
        font=('Segoe UI', 9))
    # Funcionario: lilas suave
    tree.tag_configure('funcionario',
        background='#F3ECF9', foreground='#6B21A8',
        font=('Segoe UI', 9, 'bold'))
    # Dividido: laranja suave
    tree.tag_configure('dividido',
        background='#FFEDD5', foreground='#C2410C',
        font=('Segoe UI', 9, 'bold'))
    # Cancelado/Descarte: cinza discreto italico
    tree.tag_configure('CANCELADO',
        background='#F3F4F6', foreground='#9CA3AF',
        font=('Segoe UI', 9, 'italic'))

    return tree

