def is_cancelado(pagamento, observacao):
    return (
        str(pagamento).upper() in ["DESCARTE", "CANCELADO"]
        or "CANCELADO" in str(observacao).upper()
    )

def _data_br_exibicao(valor):
    """Somente EXIBICAO: converte 'AAAA-MM-DD HH:MM:SS' (como esta no banco)
    para 'DD/MM/AAAA HH:MM'. Se nao reconhecer o formato, devolve o valor
    original sem alterar nada."""
    try:
        return datetime.strptime(str(valor).strip()[:19], "%Y-%m-%d %H:%M:%S").strftime("%d/%m/%Y %H:%M")
    except Exception:
        return valor

@somente_thread_principal
def carregar_historico():
    

    lista_caixa_atual.delete(*lista_caixa_atual.get_children())
    lista_caixa_fechado.delete(*lista_caixa_fechado.get_children())

    pesquisa = e_pesquisa.get().lower()
    # cliente ESCOLHIDO na lista: pedidos do TELEFONE dele (ignora o 9º dígito); texto livre: contém (como antes)
    _pred_cli = cdb_predicado_cliente(e_pesquisa)
    filtro_pag = cb_filtro_pag.get()
    id_caixa_aberto = ciclo_caixa_aberto.get("id")
    
    # 1. PEGA O VALOR DA CAIXINHA
    ocultar = ocultar_cancelados_var.get()

    if pesquisa:
        # Pesquisando cliente: varre TODA a base (sem limite), pra
        # sempre achar o pedido mesmo que seja antigo.
        cursor.execute(
            "SELECT id, cliente, pagamento, total, data, ciclo_caixa_id, observacao, "
            "COALESCE(valor_pago,0) "
            "FROM pedidos ORDER BY id DESC"
        )
    else:
        # Sem pesquisa: carrega so os 1000 pedidos mais recentes, pra
        # nao forcar a memoria toda vez que o sistema liga. A base
        # inteira continua intacta no banco -- so a listagem padrao
        # (sem filtro de cliente) fica mais leve.
        cursor.execute(
            "SELECT id, cliente, pagamento, total, data, ciclo_caixa_id, observacao, "
            "COALESCE(valor_pago,0) "
            "FROM pedidos ORDER BY id DESC LIMIT 1000"
        )
    
    # 2. APENAS UM LOOP PARA TUDO
    for r in cursor.fetchall():
        id_, cliente, pagamento, total, data, ciclo_id, observacao, valor_pago_row = r
        _obs_bruta = observacao            # com o [TEL_PEDIDO:...] (o filtro por telefone precisa dele)
        observacao = limpar_observacao_telefone(observacao)
        
        # Filtros de Pesquisa e Pagamento
        if pesquisa:
            if _pred_cli is not None:
                if not _pred_cli(cliente, _obs_bruta): continue
            elif pesquisa not in str(cliente).lower(): continue
        if filtro_pag != "Todos" and pagamento != filtro_pag: continue

        # --- LÓGICA DE CANCELAMENTO ---
        texto_cancelamento = f"{pagamento} {observacao}".upper()

        eh_cancelado = any(
            palavra in texto_cancelamento
            for palavra in (
                "CANCEL",
                "CANCELADO",
                "DESCARTE",
                "❌"
            )
        )

        # SE FOR PARA OCULTAR E FOR CANCELADO, PULA
        if ocultar and eh_cancelado:
            continue

        # --- LÓGICA VISUAL DE COR POR STATUS ---
        cliente_exibicao = str(cliente)
        valor_pago_db = 0.0

        if eh_cancelado:
            tag_visual = "CANCELADO"
            cliente_exibicao = f"❌ {cliente}"
        else:
            # valor_pago ja vem no SELECT principal (antes era um SELECT
            # por pedido dentro do loop -- N+1). Comparacoes com
            # tolerancia de 0.009 para nao classificar errado por
            # diferenca de centavo de ponto flutuante.
            valor_pago_db = round(float(valor_pago_row or 0), 2)
            total_pedido = round(float(total or 0), 2)

            pag_upper = str(pagamento).upper()
            formas_pagas = {"PIX", "DINHEIRO", "CARTÃO", "CARTAO"}

            if pag_upper in ("FUNCIONÁRIO", "FUNCIONARIO"):
                # Consumo de funcionario: cor propria (lilas) para nao
                # ser confundido com o pendente na conferencia.
                tag_visual = "funcionario"
            elif pag_upper == "DIVIDIDO":
                # Pedido "espelho" da divisao de conta (total R$0): cor
                # propria. As fatias (Pendente) seguem o padrao normal.
                tag_visual = "dividido"
            elif pag_upper in formas_pagas and valor_pago_db + 0.009 >= total_pedido:
                tag_visual = "pago"
            elif valor_pago_db > 0.009 and valor_pago_db + 0.009 < total_pedido:
                tag_visual = "parcial"
            else:
                tag_visual = "pendente"
        # ----------------------------------------

        pagamento_exibicao = pagamento
        if str(pagamento).strip().upper() == "PENDENTE" and "[GARCOM_DINHEIRO:" in str(observacao).upper():
            pagamento_exibicao = "Dinheiro Garcom"

        simbolo_pago = "✅" if pagamento not in ["Pendente", "Descarte"] else "☐"
        simbolo_entregue = "✅" if "ENTREGUE" in str(observacao).upper() else "☐"

        valores = (id_, cliente_exibicao, pagamento_exibicao, f"{total:.2f}", _data_br_exibicao(data), observacao or "", simbolo_entregue, simbolo_pago)

        destino = lista_caixa_atual if (id_caixa_aberto and ciclo_id == id_caixa_aberto) else lista_caixa_fechado
        
        destino.insert("", "end", iid=str(id_), values=valores, tags=_tags_linha_historico(id_, tag_visual))

def mostrar_detalhes_pedido(event):

    tree = event.widget

    item = tree.selection()

    if not item:
        return

    item_id = item[0]

    valores = tree.item(item_id, "values")

    pedido_id = valores[0]

    try:

        cursor.execute("""
            SELECT
                cliente,
                endereco,
                total,
                COALESCE(valor_pago,0),
                pagamento,
                observacao,
                data,
                COALESCE(ajuste,0)
            FROM pedidos
            WHERE id = ?
        """, (pedido_id,))

        pedido = cursor.fetchone()

        if not pedido:
            return

        (cliente, endereco, total, valor_pago, forma_pagamento,
         observacao, data_pedido, ajuste) = pedido

        observacao = observacao or ""
        telefone = extrair_telefone_observacao(observacao)
        observacao_exibicao = limpar_observacao_telefone(observacao).strip()

        entregue = "ENTREGUE" in observacao.upper()

        restante = total - valor_pago

        # =====================================
        # DETECÇÃO INTELIGENTE DE PAGAMENTO
        # (mesma regra usada na lista/aba Pedidos)
        # =====================================
        forma_pagamento = forma_pagamento or "Pendente"
        forma_upper = str(forma_pagamento).upper()

        if forma_upper in ["PIX", "DINHEIRO", "CARTÃO", "CARTAO"]:
            status = f"🟢 PAGO VIA {forma_pagamento.upper()}"
            valor_pago = total
            restante = 0
        elif valor_pago > 0 and valor_pago < total:
            status = "🟡 PAGAMENTO PARCIAL"
        else:
            status = "🔴 PENDENTE"

        cursor.execute(
            "SELECT produto, quantidade, venda FROM itens_pedido WHERE pedido_id = ?",
            (pedido_id,)
        )
        itens = cursor.fetchall()

        # =====================================
        # JANELA
        # =====================================
        janela = tk.Toplevel(root)
        janela.title(f"Pedido #{pedido_id}")
        janela.geometry("460x560")
        janela.minsize(400, 380)
        janela.configure(bg="#FFFFFF")
        janela.transient(root)

        def fechar_janela(event=None):
            if janela.winfo_exists():
                janela.destroy()

        # Fecha ao apertar ESC, ao clicar no X, ou ao clicar fora da
        # janela (perde o foco pra outra janela do sistema) -- por
        # pedido explicito, essa janela e propositalmente "sensivel",
        # entao NAO usamos grab_set() aqui (grab_set travaria o clique
        # fora dela, que e justamente o que deve fechar).
        janela.bind("<Escape>", fechar_janela)
        janela.protocol("WM_DELETE_WINDOW", fechar_janela)
        janela.bind("<FocusOut>", fechar_janela)
        janela.after(150, janela.focus_force)

        # ---------- Cabecalho ----------
        cabecalho = tk.Frame(janela, bg="#146238")
        cabecalho.pack(fill="x")
        tk.Label(
            cabecalho, text=f"Pedido #{pedido_id}", bg="#146238", fg="#FFFFFF",
            font=("Segoe UI", 13, "bold"), anchor="w"
        ).pack(fill="x", padx=15, pady=(12, 0))
        tk.Label(
            cabecalho, text=data_pedido or "", bg="#146238", fg="#DFF3E6",
            font=("Segoe UI", 9), anchor="w"
        ).pack(fill="x", padx=15, pady=(0, 12))

        # ---------- Area com scroll (pra caber tudo, mesmo com muitos itens) ----------
        area_scroll = tk.Frame(janela)
        area_scroll.pack(fill="both", expand=True)

        canvas = tk.Canvas(area_scroll, bg="#FFFFFF", highlightthickness=0)
        barra = ttk.Scrollbar(area_scroll, orient="vertical", command=canvas.yview)
        corpo = tk.Frame(canvas, bg="#FFFFFF")

        corpo.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.create_window((0, 0), window=corpo, anchor="nw")
        canvas.configure(yscrollcommand=barra.set)

        canvas.pack(side="left", fill="both", expand=True)
        barra.pack(side="right", fill="y")

        def _rolar(event):
            canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
        canvas.bind_all("<MouseWheel>", _rolar)
        janela.bind("<Destroy>", lambda e: canvas.unbind_all("<MouseWheel>"))

        def linha_rotulo(texto, negrito=True, cor="#16241C", tamanho=9, pad_topo=(12, 0)):
            tk.Label(
                corpo, text=texto, bg="#FFFFFF", fg=cor,
                font=("Segoe UI", tamanho, "bold" if negrito else "normal"),
                anchor="w", justify="left"
            ).pack(fill="x", padx=15, pady=pad_topo)

        def linha_valor(texto, cor="#16241C"):
            tk.Label(
                corpo, text=texto, bg="#FFFFFF", fg=cor,
                font=("Segoe UI", 10), anchor="w", justify="left", wraplength=410
            ).pack(fill="x", padx=15, pady=(0, 4))

        # Status de pagamento em destaque
        cor_status = "#146238" if "🟢" in status else ("#D97706" if "🟡" in status else "#C4432E")
        tk.Label(
            corpo, text=status, bg="#FFFFFF", fg=cor_status,
            font=("Segoe UI", 11, "bold"), anchor="w"
        ).pack(fill="x", padx=15, pady=(14, 6))

        # Entrega
        texto_entrega = "✅ ENTREGUE" if entregue else "⏳ PENDENTE DE ENTREGA"
        cor_entrega = "#146238" if entregue else "#D97706"
        tk.Label(
            corpo, text=texto_entrega, bg="#FFFFFF", fg=cor_entrega,
            font=("Segoe UI", 10, "bold"), anchor="w"
        ).pack(fill="x", padx=15, pady=(0, 10))

        linha_rotulo("CLIENTE:")
        linha_valor(cliente if cliente else "Não informado")

        linha_rotulo("TELEFONE:")
        linha_valor(telefone if telefone else "Não informado")

        linha_rotulo("ENDEREÇO:")
        linha_valor(endereco if endereco else "Não informado")

        linha_rotulo("OBSERVAÇÃO:")
        linha_valor(observacao_exibicao if observacao_exibicao else "Nenhuma")

        linha_rotulo("FORMA DE PAGAMENTO:")
        linha_valor(forma_pagamento)

        linha_rotulo("FINANCEIRO:")
        texto_fin = (
            f"Total:    R$ {total:.2f}\n"
            f"Ajuste:   R$ {ajuste:.2f}\n"
            f"Pago:     R$ {valor_pago:.2f}\n"
            f"Restante: R$ {restante:.2f}"
        )
        tk.Label(
            corpo, text=texto_fin, bg="#FFFFFF", fg="#16241C",
            font=("Consolas", 10), justify="left", anchor="w"
        ).pack(fill="x", padx=15, pady=(0, 4))

        qtd_itens = len(itens)
        linha_rotulo(f"ITENS DO PEDIDO ({qtd_itens}):")

        if not itens:
            linha_valor("Nenhum item registrado.")
        else:
            lista_itens_frame = tk.Frame(corpo, bg="#FFFFFF")
            lista_itens_frame.pack(fill="x", padx=15, pady=(0, 4))
            for produto, quantidade, venda in itens:
                subtotal = (quantidade or 0) * (venda or 0)
                linha_item = tk.Frame(lista_itens_frame, bg="#F4FAF6")
                linha_item.pack(fill="x", pady=2)
                tk.Label(
                    linha_item, text=f"{quantidade}x {produto}", bg="#F4FAF6", fg="#16241C",
                    font=("Segoe UI", 9, "bold"), anchor="w", justify="left", wraplength=280
                ).pack(side="left", padx=(8, 4), pady=6)
                tk.Label(
                    linha_item,
                    text=f"R$ {venda:.2f} un.  |  R$ {subtotal:.2f}",
                    bg="#F4FAF6", fg="#5C7568", font=("Segoe UI", 9), anchor="e"
                ).pack(side="right", padx=8, pady=6)

        tk.Frame(corpo, bg="#FFFFFF", height=16).pack(fill="x")

    except Exception as e:

        messagebox.showerror(
            "Erro",
            f"Erro ao abrir detalhes:\n{e}"
        )

import subprocess
import os
import time

def reiniciar_bot_inteligente():
    import os, subprocess, time, sys
    from tkinter import messagebox
    
    try:
        # 1. Mata apenas o processo do Node (Marinete)
        # O comando taskkill no node.exe é seguro e não fecha o Python
        os.system('taskkill /f /im node.exe /t >nul 2>&1') 
        time.sleep(1)

        # 2. Caminhos
        if getattr(sys, 'frozen', False):
            base = os.path.dirname(sys.executable)
        else:
            base = os.path.dirname(os.path.abspath(__file__))

        pasta_bot = os.path.join(base, "BOT-WHATSAPP")
        bat = os.path.join(pasta_bot, "LIGAR_MARINETE.BAT")

        if not os.path.exists(bat):
            messagebox.showerror("MARINETE", f"BAT NÃO ENCONTRADO:\n{bat}")
            return

        # 3. CORREÇÃO DO ERRO 87:
        # Usamos apenas o 'start' do Windows via shell. 
        # O 'start' já cuida de abrir em um novo console e desvincular do Python.
        comando = f'start "" "{bat}"'
        
        subprocess.Popen(
            comando, 
            shell=True, 
            cwd=pasta_bot
        )
        
        messagebox.showinfo(
            "🚀 CUMBUCA AI",
            "✅ Publicação concluída com sucesso!\n\n"
            "🌐 Site atualizado\n"
            "🤖 Atendimento automático ativo\n"
            "💬 Chat aguardando novos clientes\n\n"
            "Tudo pronto. Agora é hora de vender! 🔥"
        )

    except Exception as e:
        messagebox.showerror("Erro Marinete", f"Erro: {str(e)}")

def ordenar_historico(coluna):
    for lista in (lista_caixa_atual, lista_caixa_fechado):
        items = [(lista.set(k, coluna), k) for k in lista.get_children('')]
        try:
            items.sort(key=lambda t: float(t[0]))
        except:
            items.sort(key=lambda t: t[0])
        for index, (val, k) in enumerate(items):
            lista.move(k, '', index)

def reimprimir():
    sel = lista_caixa_atual.selection() or lista_caixa_fechado.selection()
    if not sel:
        messagebox.showwarning("Aviso", "Selecione um pedido")
        return
    pedido_id = int(sel[0])
    try:
        gerar_cupom_pedido(pedido_id)
    except NameError:
        gerar_nota(pedido_id)

import json
import os


def abrir_janela_alterar_pub(root, funcao_publicar):
    """
    Abre a janela para gerenciar o cardápio já publicado.
    Lê cardapio_hoje.json usando caminho dinâmico.
    """

    import os
    import sys
    import json

    # Descobre pasta correta (PY ou EXE)
    if getattr(sys, 'frozen', False):
        PASTA_BASE = os.path.dirname(sys.executable)
    else:
        PASTA_BASE = os.path.dirname(os.path.abspath(__file__))

    CAMINHO_JSON = os.path.join(
        PASTA_BASE,
        "cardapio_hoje.json"
    )

    print("\n=== DEBUG CARDÁPIO ===")
    print("PASTA:", PASTA_BASE)
    print("JSON:", CAMINHO_JSON)
    print("EXISTE:", os.path.exists(CAMINHO_JSON))

    if not os.path.exists(CAMINHO_JSON):
        messagebox.showwarning(
            "Aviso",
            f"Arquivo não encontrado:\n{CAMINHO_JSON}\n\nPublique um cardápio primeiro."
        )
        return

    try:
        with open(CAMINHO_JSON, "r", encoding="utf-8") as f:
            dados_cardapio = json.load(f)

        print("TIPO:", type(dados_cardapio))
        print("TOTAL:", len(dados_cardapio))

        if len(dados_cardapio) > 0:
            print("AMOSTRA:", dados_cardapio[0])

    except Exception as e:
        messagebox.showerror(
            "Erro",
            f"Erro ao ler JSON:\n{e}"
        )
        return

    if not isinstance(dados_cardapio, list):
        messagebox.showerror(
            "Erro",
            "Formato inválido.\nEsperado: lista de itens."
        )
        return

    if len(dados_cardapio) == 0:
        messagebox.showwarning(
            "Aviso",
            "O cardápio está vazio."
        )
        return

    janela_alt = tk.Toplevel(root)
    janela_alt.title("Alterar Publicação - Cardápio de Hoje")
    janela_alt.geometry("650x450")
    janela_alt.resizable(False, False)
    trazer_janela_para_frente(janela_alt)

    ttk.Label(
        janela_alt, 
        text="Itens Publicados no Cardápio:", 
        font=("Helvetica", 11, "bold")
    ).pack(pady=10, anchor="w", padx=15)

    frame_tabela = ttk.Frame(janela_alt)
    frame_tabela.pack(fill="both", expand=True, padx=15, pady=5)

    colunas = ("sel", "categoria", "item", "preco")
    tabela = ttk.Treeview(frame_tabela, columns=colunas, show="headings", selectmode="none")

    tabela.heading("sel", text="☐")
    tabela.heading("categoria", text="Categoria")
    tabela.heading("item", text="Nome do Prato / Item")
    tabela.heading("preco", text="Preço")

    tabela.column("sel", width=40, anchor="center", stretch=False)
    tabela.column("categoria", width=140, anchor="w")
    tabela.column("item", width=320, anchor="w")
    tabela.column("preco", width=250, anchor="e")

    scrollbar = ttk.Scrollbar(frame_tabela, orient="vertical", command=tabela.yview)
    tabela.configure(yscrollcommand=scrollbar.set)
    
    tabela.pack(side="left", fill="both", expand=True)
    scrollbar.pack(side="right", fill="y")
    ativar_lista_interativa(tabela, "item")

    mapeamento_itens = {}
    itens_marcados = set()  # iids da treeview marcados com ☑ para exclusão

    def atualizar_exibicao_tabela():
    
        for item in tabela.get_children():
            tabela.delete(item)
    
        mapeamento_itens.clear()
        itens_marcados.clear()
    
        print("\n=== PREENCHENDO TABELA ===")
    
        for item in dados_cardapio:
    
            categoria = item.get(
                "cat",
                "Sem categoria"
            )
    
            nome = item.get(
                "nome",
                "Sem nome"
            )
    
            preco_p = item.get(
                "p_p",
                0
            )
    
            preco_m = item.get(
                "p_m",
                0
            )
    
            preco_g = item.get(
                "p_g",
                0
            )
    
            try:
                preco=f"P:R$ {float(preco_p):.2f} | M:R$ {float(preco_m):.2f} | G:R$ {float(preco_g):.2f}"
            except:
                preco=str(preco_p)
    
            print(
                categoria,
                nome,
                preco
            )
    
            item_id=tabela.insert(
                "",
                "end",
                values=(
                    "☐",
                    categoria,
                    nome,
                    preco
                )
            )
    
            mapeamento_itens[item_id]=item

    def alternar_marcacao_item(event):
        """Marca/desmarca a caixinha ☐/☑ quando o usuário clica na 1ª coluna da linha."""

        linha_id = tabela.identify_row(event.y)
        coluna = tabela.identify_column(event.x)

        if not linha_id or linha_id not in mapeamento_itens:
            return

        # "#1" é sempre a primeira coluna exibida (a coluna "sel")
        if coluna != "#1":
            return

        valores = list(tabela.item(linha_id, "values"))

        if linha_id in itens_marcados:
            itens_marcados.discard(linha_id)
            valores[0] = "☐"
        else:
            itens_marcados.add(linha_id)
            valores[0] = "☑"

        tabela.item(linha_id, values=valores)

    tabela.bind("<Button-1>", alternar_marcacao_item)
    
    def remover_itens_selecionados():
        """
        Remove todos os itens marcados com ☑, salva o cardapio_hoje.json
        e dispara o atualizar_alteracao.bat (que faz commit/push no GitHub).
        """

        if not itens_marcados:
            messagebox.showinfo(
                "Nenhum item marcado",
                "Clique na caixinha ☐ ao lado de cada item que deseja excluir e tente novamente."
            )
            return

        itens_para_excluir = [
            mapeamento_itens[iid]
            for iid in itens_marcados
            if iid in mapeamento_itens
        ]

        nomes = "\n".join(f"- {item.get('nome', 'Sem nome')}" for item in itens_para_excluir)

        if not messagebox.askyesno(
            "Confirmar exclusão",
            f"Excluir os {len(itens_para_excluir)} item(ns) abaixo e publicar a "
            f"alteração no site agora?\n\n{nomes}"
        ):
            return

        for item_original in itens_para_excluir:
            if item_original in dados_cardapio:
                dados_cardapio.remove(item_original)

        try:
            with open(CAMINHO_JSON, "w", encoding="utf-8") as f:
                json.dump(dados_cardapio, f, indent=4, ensure_ascii=False)
        except Exception as e:
            messagebox.showerror(
                "Erro",
                f"Não foi possível salvar as alterações no cardapio_hoje.json:\n{e}"
            )
            return

        atualizar_exibicao_tabela()
        executar_bat_atualizacao()

    def executar_bat_atualizacao():
        """
        Chama o .bat que copia o cardapio_hoje.json atualizado para a pasta
        html, faz commit e push no GitHub. Caminho descoberto dinamicamente
        a partir de PASTA_BASE, então continua funcionando mesmo que o
        sistema mude de pasta no futuro.
        """

        pasta_html = os.path.join(PASTA_BASE, "html")
        caminho_bat = os.path.join(pasta_html, "atualizar_alteracao.bat")

        if not os.path.exists(caminho_bat):
            messagebox.showerror(
                "Erro",
                f"Arquivo não encontrado:\n{caminho_bat}"
            )
            return

        janela_progresso = tk.Toplevel(janela_alt)
        janela_progresso.title("Publicando...")
        janela_progresso.geometry("340x110")
        janela_progresso.resizable(False, False)
        # Sem grab_set(): a publicação roda em segundo plano (thread) e não
        # deve travar o resto do sistema enquanto o usuário aguarda.
        janela_progresso.transient(janela_alt)
        trazer_janela_para_frente(janela_progresso)

        ttk.Label(
            janela_progresso,
            text="Excluindo item(ns) e publicando no site...\n"
                 "Isso pode levar alguns instantes, aguarde.",
            justify="center"
        ).pack(expand=True, padx=15, pady=20)

        btn_excluir.config(state="disabled")
        btn_atualizar.config(state="disabled")
        btn_remover_pub.config(state="disabled")

        def rodar_bat():
            sucesso = False
            erro_msg = ""
            processo = None
            try:
                # O "silencioso" no final evita que o .bat fique parado
                # esperando "pressione uma tecla" (pause), já que ele
                # roda sem janela visível.
                processo = subprocess.Popen(
                    f'"{caminho_bat}" silencioso',
                    cwd=pasta_html,
                    shell=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    creationflags=(
                        subprocess.CREATE_NO_WINDOW
                        | subprocess.CREATE_NEW_PROCESS_GROUP
                    )
                )
                processo.communicate(timeout=600)
                sucesso = (processo.returncode == 0)
            except subprocess.TimeoutExpired:
                erro_msg = "O processo demorou demais e foi interrompido (timeout)."

                # Mata o cmd.exe do .bat E todos os processos filhos dele
                # (git.exe, powershell.exe, timeout.exe etc). Só matar o
                # processo principal deixaria "netos" órfãos rodando.
                try:
                    if processo is not None:
                        subprocess.run(
                            f"taskkill /F /T /PID {processo.pid}",
                            shell=True,
                            capture_output=True,
                            creationflags=subprocess.CREATE_NO_WINDOW
                        )
                except Exception:
                    pass

                # Como o .bat foi morto no meio da execução, ele não
                # chegou a apagar sozinho a pasta de trava. Removemos
                # aqui pelo lado do Python para não deixar lock preso.
                try:
                    import shutil
                    caminho_lock = os.path.join(pasta_html, ".atualizacao.lock")
                    if os.path.isdir(caminho_lock):
                        shutil.rmtree(caminho_lock, ignore_errors=True)
                except Exception:
                    pass
            except Exception as e:
                erro_msg = str(e)

            def finalizar():
                try:
                    janela_progresso.destroy()
                except Exception:
                    pass

                try:
                    btn_excluir.config(state="normal")
                    btn_atualizar.config(state="normal")
                    btn_remover_pub.config(state="normal")
                except Exception:
                    pass

                caminho_log = os.path.join(pasta_html, "log_atualizacao.txt")

                try:
                    if sucesso:
                        messagebox.showinfo(
                            "Sucesso",
                            "Item(ns) excluído(s) e o site foi atualizado com sucesso!"
                        )
                    else:
                        messagebox.showerror(
                            "Erro ao publicar",
                            "A exclusão foi salva no arquivo local, mas houve um "
                            "problema ao enviar a atualização para o GitHub.\n\n"
                            + (erro_msg + "\n\n" if erro_msg else "")
                            + f"Confira o log para mais detalhes:\n{caminho_log}"
                        )
                except Exception:
                    pass

            try:
                if janela_alt.winfo_exists():
                    janela_alt.after(0, finalizar)
                else:
                    finalizar()
            except Exception:
                pass

        threading.Thread(target=rodar_bat, daemon=True).start()

    def salvar_e_republicar():
        if messagebox.askyesno("Confirmar Atualização", "Deseja salvar as alterações e atualizar o site agora?"):
            try:
                with open(CAMINHO_JSON, "w", encoding="utf-8") as f:
                    json.dump(dados_cardapio, f, indent=4, ensure_ascii=False)
                
                janela_alt.destroy()
                
                # CHAMA DIRETAMENTE A FUNÇÃO DE ENVIO DO SEU SISTEMA CUMBUCA
                if funcao_publicar:
                    funcao_publicar()
                
            except Exception as e:
                messagebox.showerror("Erro", f"Não foi possível salvar as alterações:\n{e}")

    def remover_publicacao_site():
    
        if not messagebox.askyesno(
            "Confirmar",
            "Deseja remover o cardápio do site agora?"
        ):
            return
    
        try:
    
            # Caminho dinâmico da pasta HTML
            pasta_html = os.path.join(
                PASTA_BASE,
                "html"
            )
    
            caminho_bat = os.path.join(
                pasta_html,
                "fechar_cardapio.bat"
            )
    
            # Verifica se o BAT existe
            if not os.path.exists(caminho_bat):
    
                messagebox.showerror(
                    "Erro",
                    f"Arquivo não encontrado:\n{caminho_bat}"
                )
                return
    
            # Executa oculto (sem abrir CMD)
            subprocess.Popen(
                caminho_bat,
                cwd=pasta_html,
                shell=True,
                creationflags=subprocess.CREATE_NO_WINDOW
            )
    
            # Fecha janela imediatamente
            janela_alt.destroy()
    
            # Aviso
            messagebox.showinfo(
                "Sucesso",
                "O cardápio foi removido do site."
            )
    
        except Exception as e:
    
            messagebox.showerror(
                "Erro",
                f"Erro ao remover publicação:\n{e}"
            )
    
    frame_acoes = ttk.Frame(janela_alt)
    frame_acoes.pack(fill="x", padx=15, pady=15)
    
    btn_excluir = ttk.Button(
        frame_acoes,
        text="❌ Excluir Itens Marcados",
        command=remover_itens_selecionados
    )
    btn_excluir.pack(side="left", ipady=3)
    
    btn_remover_pub = ttk.Button(
        frame_acoes,
        text="🗑 Remover Publicação",
        command=remover_publicacao_site
    )
    btn_remover_pub.pack(side="left", padx=5, ipady=3)
    
    btn_cancelar = ttk.Button(
        frame_acoes,
        text="Cancelar",
        command=janela_alt.destroy
    )
    btn_cancelar.pack(side="right", padx=5, ipady=3)
    
    btn_atualizar = ttk.Button(
        frame_acoes,
        text="🔄 Atualizar",
        command=salvar_e_republicar
    )
    btn_atualizar.pack(side="right", padx=5, ipady=3)

    try:
        atualizar_exibicao_tabela()
    except Exception as _erro_tab:
        registrar_erro_diagnostico("abrir_janela_alterar_pub.atualizar_exibicao_tabela")
        messagebox.showerror(
            "Erro",
            f"Falha ao montar a lista do cardápio:\n{_erro_tab}",
            parent=janela_alt
        )
        janela_alt.destroy()
        return

    # Modal SOMENTE depois da tela pronta (antes, qualquer falha deixava
    # a janela em branco e travada).
    try:
        janela_alt.wait_visibility()
    except tk.TclError:
        pass
    janela_alt.grab_set()


