# 🔵 CORREÇÃO: UM ÚNICO FRAME DE BOTÕES ALINHADO À DIREITA (FIM DA DUPLICAÇÃO)
def registrar_dinheiro_recebido_garcom(pedido_id, mesa_numero, garcom, cliente, valor):
    """Marca dinheiro recebido pelo garcom sem lancar no caixa.

    Segura para qualquer thread (A2): na thread principal usa o cursor/conn
    globais; em outra thread usa conexao curta propria. INSERT OR IGNORE
    (garcom_repasses.pedido_id e UNIQUE) => chamar 2x nao duplica."""
    sql_repasse = """
        INSERT OR IGNORE INTO garcom_repasses (
            pedido_id, mesa_numero, garcom, cliente, valor, forma,
            status, data_registro, observacao
        ) VALUES (?, ?, ?, ?, ?, 'Dinheiro', 'PENDENTE', datetime('now','localtime'), ?)
    """
    params_repasse = (
        int(pedido_id), str(mesa_numero or ""), str(garcom or "Sem garcom"),
        str(cliente or "Consumidor Local"), float(valor or 0),
        "Dinheiro recebido pelo garcom; aguardando repasse ao caixa."
    )
    sql_obs = """
        UPDATE pedidos
        SET observacao = TRIM(COALESCE(observacao,'') || ' [GARCOM_DINHEIRO:' || ? || ']')
        WHERE id=? AND COALESCE(observacao,'') NOT LIKE '%[GARCOM_DINHEIRO:%'
    """
    params_obs = (str(garcom or "Sem garcom"), int(pedido_id))

    if _eh_thread_principal():
        try:
            cursor.execute(sql_repasse, params_repasse)
            cursor.execute(sql_obs, params_obs)
            conn.commit()
        except Exception:
            conn.rollback()
            registrar_erro_diagnostico("registrar_dinheiro_recebido_garcom", pedido=pedido_id)
            raise
    else:
        conn_g = abrir_conexao_curta()
        try:
            conn_g.execute(sql_repasse, params_repasse)
            conn_g.execute(sql_obs, params_obs)
            conn_g.commit()
        except Exception:
            conn_g.rollback()
            registrar_erro_diagnostico("registrar_dinheiro_recebido_garcom", pedido=pedido_id)
            raise
        finally:
            conn_g.close()
    try:
        registrar_log("DINHEIRO_GARCOM_PENDENTE", "PEDIDOS", pedido_id, {
            "mesa": mesa_numero, "garcom": garcom, "cliente": cliente, "valor": valor
        })
    except Exception:
        pass
    if 'carregar_historico' in globals():
        enfileirar_acao_ui(carregar_historico, chave="carregar_historico")
    return True


def abrir_repasses_garcons():
    from tkinter import messagebox

    janela = tk.Toplevel(root)
    janela.title("Repasses dos Garcons")
    janela.geometry("900x520")
    janela.transient(root)

    topo = ttk.Frame(janela)
    topo.pack(fill="x", padx=10, pady=8)
    lbl_total = ttk.Label(topo, text="Pendente: R$ 0.00", font=("Segoe UI", 11, "bold"))
    lbl_total.pack(side="left")

    corpo = ttk.Frame(janela)
    corpo.pack(fill="both", expand=True, padx=10, pady=(0, 10))

    cols = ("id", "pedido", "mesa", "garcom", "cliente", "valor", "data")
    tree = ttk.Treeview(corpo, columns=cols, show="headings", selectmode="extended")
    headings = {
        "id": "ID", "pedido": "Pedido", "mesa": "Mesa", "garcom": "Garcom",
        "cliente": "Cliente", "valor": "Valor", "data": "Recebido em"
    }
    widths = {"id": 50, "pedido": 70, "mesa": 70, "garcom": 150, "cliente": 210, "valor": 90, "data": 150}
    for col in cols:
        tree.heading(col, text=headings[col])
        tree.column(col, width=widths[col], anchor="e" if col == "valor" else "center")
    tree.column("cliente", anchor="w")
    tree.column("garcom", anchor="w")
    tree.pack(side="left", fill="both", expand=True)

    barra = ttk.Scrollbar(corpo, orient="vertical", command=tree.yview)
    barra.pack(side="right", fill="y")
    tree.configure(yscrollcommand=barra.set)

    def carregar():
        tree.delete(*tree.get_children())
        cursor.execute("""
            SELECT id, pedido_id, mesa_numero, garcom, cliente, valor, data_registro
            FROM garcom_repasses
            WHERE status='PENDENTE'
            ORDER BY garcom COLLATE NOCASE, data_registro, id
        """)
        total = 0.0
        por_garcom = {}
        for repasse_id, pedido_id, mesa, garcom, cliente, valor, data_registro in cursor.fetchall():
            valor = float(valor or 0)
            total += valor
            nome_garcom = garcom or "Sem garcom"
            por_garcom[nome_garcom] = por_garcom.get(nome_garcom, 0.0) + valor
            tree.insert("", "end", iid=str(repasse_id), values=(
                repasse_id, pedido_id, mesa or "", nome_garcom,
                cliente or "", f"{valor:.2f}", data_registro or ""
            ))
        resumo = " | ".join(f"{g}: R$ {v:.2f}" for g, v in por_garcom.items())
        lbl_total.config(text=f"Pendente: R$ {total:.2f}" + (f"    {resumo}" if resumo else ""))

    def validar_selecionados():
        selecionados = tree.selection()
        if not selecionados:
            messagebox.showwarning("Aviso", "Selecione ao menos um repasse.")
            return
        if not ciclo_caixa_aberto.get("id"):
            messagebox.showwarning("Caixa Fechado", "Abra o caixa antes de validar repasses.")
            return

        ids = [int(i) for i in selecionados]
        placeholders = ",".join(["?"] * len(ids))
        cursor.execute(f"""
            SELECT id, pedido_id, garcom, cliente, valor
            FROM garcom_repasses
            WHERE status='PENDENTE' AND id IN ({placeholders})
        """, ids)
        linhas = cursor.fetchall()
        if not linhas:
            messagebox.showinfo("Aviso", "Nenhum repasse pendente selecionado.")
            carregar()
            return

        total = sum(float(l[4] or 0) for l in linhas)
        if not messagebox.askyesno(
            "Confirmar repasse",
            f"Confirmar recebimento de {len(linhas)} repasse(s)?\n\nTotal: R$ {total:.2f}\n\n"
            "Isso vai quitar os pedidos em Dinheiro e lancar a entrada no caixa."
        ):
            return

        try:
            for repasse_id, pedido_id, garcom, cliente, valor in linhas:
                valor = float(valor or 0)
                cursor.execute("SELECT total, COALESCE(valor_pago,0), pagamento FROM pedidos WHERE id=?", (pedido_id,))
                pedido = cursor.fetchone()
                if not pedido:
                    continue
                total_pedido, valor_pago_atual, pagamento_atual = pedido
                novo_pago = min(float(total_pedido or 0), float(valor_pago_atual or 0) + valor)
                novo_status = "Dinheiro" if novo_pago >= float(total_pedido or 0) - 0.001 else "Pendente"
                cursor.execute(
                    "UPDATE pedidos SET valor_pago=?, pagamento=? WHERE id=?",
                    (novo_pago, novo_status, pedido_id)
                )
                conn.commit()
                registrar_lancamento_caixa(
                    "ENTRADA",
                    f"Repasse garcom {garcom or 'Sem garcom'} - Pedido #{pedido_id}",
                    valor,
                    "Dinheiro",
                    pedido_id=pedido_id
                )
                cursor.execute("""
                    UPDATE garcom_repasses
                    SET status='VALIDADO', data_validacao=datetime('now','localtime')
                    WHERE id=?
                """, (repasse_id,))
                registrar_log("REPASSE_GARCOM_VALIDADO", "PEDIDOS", pedido_id, {
                    "garcom": garcom, "cliente": cliente, "valor": valor,
                    "pagamento_anterior": pagamento_atual
                })
            conn.commit()
            carregar()
            carregar_historico()
            if 'carregar_receitas_caixa' in globals():
                carregar_receitas_caixa()
            messagebox.showinfo("Sucesso", "Repasse validado e lancado no caixa.")
        except Exception as erro:
            conn.rollback()
            messagebox.showerror("Erro", f"Falha ao validar repasse:\n{erro}")

    botoes = ttk.Frame(janela)
    botoes.pack(fill="x", padx=10, pady=(0, 10))
    ttk.Button(botoes, text="Atualizar", command=carregar).pack(side="left", padx=3)
    ttk.Button(botoes, text="Validar selecionados", command=validar_selecionados).pack(side="right", padx=3)

    carregar()


