# =====================================================
# A8 - CONFERENCIA SOMENTE LEITURA: "Conferir caixa x pedidos"
# Lista os pedidos em que valor_pago difere da soma LIQUIDA do caixa
# (ENTRADA - SAIDA/estornos ligados ao pedido). NAO corrige nada.
# =====================================================
SQL_CONFERENCIA_CAIXA_X_PEDIDOS = """
    SELECT p.id, p.cliente, p.total, p.valor_pago, p.pagamento,
           ROUND(COALESCE(SUM(CASE WHEN c.tipo='ENTRADA' THEN c.valor ELSE -c.valor END),0),2) AS soma_caixa
    FROM pedidos p LEFT JOIN caixa c ON c.pedido_id = p.id
    GROUP BY p.id HAVING ABS(COALESCE(p.valor_pago,0) - soma_caixa) > 0.009
    ORDER BY p.id DESC;
"""


def consultar_divergencias_caixa_x_pedidos():
    """Somente leitura (conexao curta propria). Retorna a lista de divergencias."""
    conn_conf = abrir_conexao_curta()
    try:
        return conn_conf.execute(SQL_CONFERENCIA_CAIXA_X_PEDIDOS).fetchall()
    finally:
        conn_conf.close()


def conferir_caixa_x_pedidos():
    from tkinter import messagebox, filedialog
    import csv

    try:
        linhas = consultar_divergencias_caixa_x_pedidos()
    except Exception as erro:
        registrar_erro_diagnostico("conferir_caixa_x_pedidos")
        messagebox.showerror("Conferência", f"Não foi possível consultar o banco ({type(erro).__name__}):\n{erro}")
        return

    janela = tk.Toplevel(root)
    janela.title("Conferir caixa x pedidos (somente leitura)")
    janela.geometry("980x520")
    janela.transient(root)

    topo = ttk.Frame(janela)
    topo.pack(fill="x", padx=10, pady=8)
    lbl_resumo = ttk.Label(topo, text="", font=("Segoe UI", 10, "bold"))
    lbl_resumo.pack(side="left")

    corpo = ttk.Frame(janela)
    corpo.pack(fill="both", expand=True, padx=10, pady=(0, 10))

    colunas = ("pedido", "cliente", "total", "valor_pago", "pagamento", "soma_caixa", "diferenca")
    titulos = {"pedido": "Pedido", "cliente": "Cliente", "total": "Total", "valor_pago": "Valor pago",
               "pagamento": "Pagamento", "soma_caixa": "Soma no caixa", "diferenca": "Diferença"}
    larguras = {"pedido": 70, "cliente": 240, "total": 90, "valor_pago": 100,
                "pagamento": 100, "soma_caixa": 110, "diferenca": 100}
    tree = ttk.Treeview(corpo, columns=colunas, show="headings")
    for col in colunas:
        tree.heading(col, text=titulos[col])
        tree.column(col, width=larguras[col], anchor="w" if col == "cliente" else "center")
    tree.pack(side="left", fill="both", expand=True)
    barra = ttk.Scrollbar(corpo, orient="vertical", command=tree.yview)
    barra.pack(side="right", fill="y")
    tree.configure(yscrollcommand=barra.set)

    estado = {"linhas": []}

    def preencher(dados):
        tree.delete(*tree.get_children())
        estado["linhas"] = []
        for pid, cliente, total, valor_pago, pagamento, soma in dados:
            vp = round(float(valor_pago or 0), 2)
            dif = round(vp - float(soma or 0), 2)
            registro = (pid, cliente or "", round(float(total or 0), 2), vp, pagamento or "",
                        round(float(soma or 0), 2), dif)
            estado["linhas"].append(registro)
            tree.insert("", "end", values=(
                pid, cliente or "", f"{registro[2]:.2f}", f"{vp:.2f}", pagamento or "",
                f"{registro[5]:.2f}", f"{dif:+.2f}"
            ))
        if dados:
            lbl_resumo.config(text=f"{len(dados)} pedido(s) com valor_pago diferente do caixa (nada foi alterado).")
        else:
            lbl_resumo.config(text="Nenhuma divergência: valor_pago bate com o caixa em todos os pedidos.")

    def atualizar():
        try:
            preencher(consultar_divergencias_caixa_x_pedidos())
        except Exception as erro:
            registrar_erro_diagnostico("conferir_caixa_x_pedidos.atualizar")
            messagebox.showerror("Conferência", f"Falha ao consultar ({type(erro).__name__}):\n{erro}", parent=janela)

    def exportar():
        if not estado["linhas"]:
            messagebox.showinfo("Conferência", "Não há divergências para exportar.", parent=janela)
            return
        caminho = filedialog.asksaveasfilename(
            parent=janela, defaultextension=".csv",
            initialfile=f"conferencia_caixa_x_pedidos_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv",
            filetypes=[("CSV", "*.csv")]
        )
        if not caminho:
            return
        try:
            with open(caminho, "w", encoding="utf-8-sig", newline="") as arq:
                escritor = csv.writer(arq, delimiter=";")
                escritor.writerow([titulos[c] for c in colunas])
                for reg in estado["linhas"]:
                    escritor.writerow([reg[0], reg[1], f"{reg[2]:.2f}", f"{reg[3]:.2f}", reg[4],
                                       f"{reg[5]:.2f}", f"{reg[6]:.2f}"])
            messagebox.showinfo("Conferência", f"Lista exportada em:\n{caminho}", parent=janela)
        except Exception as erro:
            registrar_erro_diagnostico("conferir_caixa_x_pedidos.exportar")
            messagebox.showerror("Conferência", f"Falha ao exportar ({type(erro).__name__}):\n{erro}", parent=janela)

    rodape = ttk.Frame(janela)
    rodape.pack(fill="x", padx=10, pady=(0, 10))
    ttk.Button(rodape, text="Atualizar", command=atualizar).pack(side="left", padx=2)
    ttk.Button(rodape, text="Exportar CSV", command=exportar).pack(side="left", padx=2)
    ttk.Button(rodape, text="Fechar", command=janela.destroy).pack(side="right", padx=2)

    preencher(linhas)


