def ordenar_treeview(tv, col, reverse):
    lista = [(tv.set(k, col), k) for k in tv.get_children('')]

    try:
        lista.sort(key=lambda t: float(t[0].replace("R$", "").replace(",", ".")), reverse=reverse)
    except:
        lista.sort(reverse=reverse)

    for index, (val, k) in enumerate(lista):
        tv.move(k, '', index)

    tv.heading(col, command=lambda: ordenar_treeview(tv, col, not reverse))

def buscar_por_letra(event):
    letra = event.char.lower()

    if not letra.isalpha():
        return

    itens = tree_cardapio.get_children()
    if not itens:
        return

    # pega item atual selecionado
    atual = tree_cardapio.focus()

    # descobre índice atual
    try:
        index_atual = itens.index(atual)
    except ValueError:
        index_atual = -1

    # percorre lista a partir do próximo (com loop)
    for i in range(1, len(itens) + 1):
        item = itens[(index_atual + i) % len(itens)]
        valores = tree_cardapio.item(item, "values")

        if valores:
            nome = str(valores[1]).lower()

            if nome.startswith(letra):
                tree_cardapio.selection_set(item)
                tree_cardapio.focus(item)
                tree_cardapio.see(item)
                break

