# 📦 1. BANCO DE DADOS (VERSÃO COMPLETA E SEGURA)
# =====================================================
def atualizar_banco():

    # -------------------------------
    # TABELA CARDAPIO
    # -------------------------------
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS cardapio (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nome TEXT NOT NULL,
        descricao TEXT,
        categoria TEXT,
        preco REAL DEFAULT 0,
        preco_g REAL DEFAULT 0,
        prod_estoque_p TEXT,
        prod_estoque_g TEXT
    )
    """)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS cardapio_dia (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        id_prato INTEGER,
        nome TEXT,
        descricao TEXT,
        categoria TEXT,
        preco REAL DEFAULT 0,
        preco_g REAL DEFAULT 0,
        prod_estoque_p TEXT,
        prod_estoque_g TEXT,
        data DATE DEFAULT CURRENT_DATE
    )
    """)

    # -------------------------------
    # TABELA FOGAO
    # -------------------------------
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS fogao (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nome TEXT,
        data_instalacao TEXT,
        duracao_dias INTEGER
    )
    """)

    # -------------------------------
    # VERIFICAR COLUNAS CARDAPIO
    # -------------------------------
    cursor.execute("PRAGMA table_info(cardapio)")
    colunas = [col[1] for col in cursor.fetchall()]

    novas = [
        ("prod_estoque_p", "TEXT"),
        ("prod_estoque_g", "TEXT")
    ]

    for col_nome, col_tipo in novas:
        if col_nome not in colunas:
            try:
                cursor.execute(f"ALTER TABLE cardapio ADD COLUMN {col_nome} {col_tipo}")
                cursor.execute(f"ALTER TABLE cardapio_dia ADD COLUMN {col_nome} {col_tipo}")
            except:
                pass

    # -------------------------------
    # COLUNA "SO_MESA" (so existe em cardapio_dia -- marca um prato do
    # dia que NAO deve ir para o cardapio_hoje.json / site, so pode ser
    # vendido na mesa/balcao). Nao existe equivalente na tabela
    # "cardapio" (catalogo geral), pois essa marcacao e por dia.
    # -------------------------------
    cursor.execute("PRAGMA table_info(cardapio_dia)")
    colunas_dia = [col[1] for col in cursor.fetchall()]
    if "so_mesa" not in colunas_dia:
        try:
            cursor.execute("ALTER TABLE cardapio_dia ADD COLUMN so_mesa INTEGER DEFAULT 0")
        except:
            pass

    # -------------------------------
    # VERIFICAR COLUNAS FOGAO
    # -------------------------------
    cursor.execute("PRAGMA table_info(fogao)")
    colunas_fogao = [col[1] for col in cursor.fetchall()]

    novas_fogao = [
        ("data_instalacao", "TEXT"),
        ("duracao_dias", "INTEGER")
    ]

    for col_nome, col_tipo in novas_fogao:
        if col_nome not in colunas_fogao:
            try:
                cursor.execute(f"ALTER TABLE fogao ADD COLUMN {col_nome} {col_tipo}")
            except:
                pass

    # -------------------------------
    # HISTÓRICO DE CARDÁPIOS (snapshot do cardápio INICIAL de cada caixa)
    # Tabelas separadas da cardapio_dia: apagar/editar o cardápio do dia
    # NUNCA mexe aqui. ciclo_id UNIQUE = no máximo 1 snapshot por caixa.
    # -------------------------------
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS cardapio_historico (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ciclo_id INTEGER NOT NULL UNIQUE,
        publicado_em TEXT,
        qtd_pratos INTEGER DEFAULT 0
    )
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS cardapio_historico_itens (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        historico_id INTEGER NOT NULL,
        nome TEXT,
        categoria TEXT,
        preco REAL DEFAULT 0,
        preco_g REAL DEFAULT 0,
        so_mesa INTEGER DEFAULT 0,
        FOREIGN KEY (historico_id) REFERENCES cardapio_historico(id)
    )
    """)
    # Despesas de notas de estoque marcadas para entrar no histórico do cardápio
    # (carnes / insumos). Separada do caixa de propósito: nota Pendente ainda não
    # passou pelo caixa, e a classificação do Resultado não pode mudar.
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS cardapio_historico_despesas (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ciclo_id INTEGER NOT NULL,
        tipo TEXT,
        valor REAL DEFAULT 0,
        fornecedor TEXT,
        referencia TEXT,
        id_despesa INTEGER,
        id_conta INTEGER,
        data_lancamento TEXT
    )
    """)

    # -------------------------------
    # TAMANHO M (novo): preco_m + prod_estoque_m
    # Cada tabela e verificada separadamente; so adiciona se a coluna ainda
    # nao existir (pratos antigos ficam com M vazio / preco 0, sem perder nada).
    # -------------------------------
    for _tab_m in ("cardapio", "cardapio_dia", "cardapio_historico_itens"):
        cursor.execute(f"PRAGMA table_info({_tab_m})")
        _cols_m = [col[1] for col in cursor.fetchall()]
        _novas_m = [("preco_m", "REAL DEFAULT 0")]
        if _tab_m != "cardapio_historico_itens":
            _novas_m.append(("prod_estoque_m", "TEXT"))
        for _col_m, _tipo_m in _novas_m:
            if _col_m not in _cols_m:
                try:
                    cursor.execute(f"ALTER TABLE {_tab_m} ADD COLUMN {_col_m} {_tipo_m}")
                except Exception as _e_m:
                    print(f"Aviso: nao consegui criar {_col_m} em {_tab_m}: {_e_m}")

    conn.commit()

# 🔵 PRIMEIRO garante estrutura
atualizar_banco()

