def carregar_itens_estoque():
    try:
        conn = abrir_conexao_curta()
        cur = conn.cursor()

        query = """
        SELECT codigo, produto 
        FROM estoque 
        WHERE categoria = 'PRODUTO' 
        ORDER BY produto
        """

        itens = [f"{codigo} - {produto}" for codigo, produto in cur.execute(query)]

        entry_estoque_p['values'] = itens
        entry_estoque_m['values'] = itens
        entry_estoque_g['values'] = itens

        conn.close()

    except Exception as e:
        print(f"Erro ao carregar estoque Cardápio: {e}")

def limpar_campos():
    entry_nome.delete(0, tk.END)
    entry_desc.delete(0, tk.END)
    combo_categoria.set("")
    preco_p_var.set("")
    preco_m_var.set("")
    preco_g_var.set("")
    entry_estoque_p.set("")
    entry_estoque_m.set("")
    entry_estoque_g.set("")
    carregar_itens_estoque()

def _mapa_precos_estoque_produto():
    """Monta um mapa {'codigo - produto': venda} usando exatamente a mesma
    consulta e o mesmo formato de texto usados em carregar_itens_estoque()
    para preencher os combos Estoque P / Estoque G. Usar o texto completo
    como chave (em vez de tentar separar o código do nome) evita qualquer
    erro de correspondência, garantindo que o preço puxado seja sempre o
    mesmo valor cadastrado em ESTOQUE > PRODUTOS ACABADOS (coluna 'venda')."""
    mapa = {}
    try:
        conn_tmp = abrir_conexao_curta()
        cur_tmp = conn_tmp.cursor()
        cur_tmp.execute("""
            SELECT codigo, produto, venda
            FROM estoque
            WHERE categoria = 'PRODUTO'
        """)
        for codigo, produto, venda in cur_tmp.fetchall():
            mapa[f"{codigo} - {produto}"] = venda
        conn_tmp.close()
    except Exception as e:
        print(f"Erro ao buscar preços do Estoque (Produtos Acabados): {e}")
    return mapa

def _codigo_produto_selecionado(texto_combo):
    texto_combo = (texto_combo or "").strip()
    if not texto_combo:
        return ""
    return texto_combo.split(" - ", 1)[0].strip()

def _nome_produto_selecionado(texto_combo):
    texto_combo = (texto_combo or "").strip()
    if " - " not in texto_combo:
        return texto_combo
    return texto_combo.split(" - ", 1)[1].strip()

def _preco_venda_produto_estoque(texto_combo):
    codigo = _codigo_produto_selecionado(texto_combo)
    nome = _nome_produto_selecionado(texto_combo)
    if not codigo and not nome:
        return None
    try:
        conn_tmp = abrir_conexao_curta()
        cur_tmp = conn_tmp.cursor()
        cur_tmp.execute("""
            SELECT venda
            FROM estoque
            WHERE UPPER(TRIM(codigo)) = UPPER(TRIM(?))
               OR UPPER(TRIM(produto)) = UPPER(TRIM(?))
            LIMIT 1
        """, (codigo, nome))
        row = cur_tmp.fetchone()
        conn_tmp.close()
        return row[0] if row else None
    except Exception as e:
        print(f"Erro ao buscar preco do Estoque (Produtos Acabados): {e}")
        return None

def _mostrar_preco_readonly(entry_preco, var_preco, venda):
    valor = f"{float(venda):.2f}" if venda is not None else ""
    entry_preco.config(state="normal")
    entry_preco.delete(0, tk.END)
    entry_preco.insert(0, valor)
    var_preco.set(valor)
    entry_preco.config(state="readonly")

def atualizar_preco_p_pelo_estoque(event=None):
    """Preenche o Preço P automaticamente com o valor de venda cadastrado
    no item de Estoque P selecionado. O campo permanece só leitura."""
    venda = _preco_venda_produto_estoque(entry_estoque_p.get())
    _mostrar_preco_readonly(entry_preco_p, preco_p_var, venda)

def atualizar_preco_m_pelo_estoque(event=None):
    """Preenche o Preço M automaticamente com o valor de venda cadastrado
    no item de Estoque M selecionado. O campo permanece só leitura."""
    venda = _preco_venda_produto_estoque(entry_estoque_m.get())
    _mostrar_preco_readonly(entry_preco_m, preco_m_var, venda)

def atualizar_preco_g_pelo_estoque(event=None):
    """Preenche o Preço G automaticamente com o valor de venda cadastrado
    no item de Estoque G selecionado. O campo permanece só leitura."""
    venda = _preco_venda_produto_estoque(entry_estoque_g.get())
    _mostrar_preco_readonly(entry_preco_g, preco_g_var, venda)

# --- Controle de ordenação e seleção específicos de Opções de Pratos ---
# (isolado das demais telas do sistema, para não afetar outras listas)
_cardapio_sort_estado = {"col": None, "reverse": False}

def _ordenar_treeview_cardapio(col, reverse=False):
    """Ordena a treeview de Opções de Pratos e memoriza a ordenação escolhida,
    para que ela seja mantida mesmo depois de editar um prato (a lista é
    recarregada do banco após cada edição)."""
    ordenar_treeview_generico(tree_cardapio, col, reverse)
    _cardapio_sort_estado["col"] = col
    _cardapio_sort_estado["reverse"] = reverse
    texto = tree_cardapio.heading(col, "text") or col
    tree_cardapio.heading(col, text=texto, command=lambda: _ordenar_treeview_cardapio(col, not reverse))

def _reaplicar_ordenacao_cardapio():
    col = _cardapio_sort_estado["col"]
    if col:
        ordenar_treeview_generico(tree_cardapio, col, _cardapio_sort_estado["reverse"])

def _selecionar_prato_por_id(id_prato):
    """Mantém/repõe a seleção em Opções de Pratos após recarregar a lista,
    para que o prato editado já fique pronto para ser adicionado ao NO DIA."""
    for item in tree_cardapio.get_children(""):
        valores = tree_cardapio.item(item, "values")
        if valores and str(valores[0]) == str(id_prato):
            tree_cardapio.selection_set(item)
            tree_cardapio.focus(item)
            tree_cardapio.see(item)
            return

def listar_cardapio():
    for i in tree_cardapio.get_children(): tree_cardapio.delete(i)
    cursor.execute("SELECT id, nome, categoria, preco, preco_m, preco_g FROM cardapio")
    for r in cursor.fetchall():
        # Trata valores None para não dar erro de formatação
        p_p = r[3] if r[3] is not None else 0.0
        p_m = r[4] if r[4] is not None else 0.0
        p_g = r[5] if r[5] is not None else 0.0
        tree_cardapio.insert("", "end", values=(r[0], r[1], r[2], f"{p_p:.2f}", f"{p_m:.2f}", f"{p_g:.2f}"))
    # Mantém a classificação (ordenação de coluna) que já estava sendo usada,
    # em vez de resetar a lista para a ordem padrão a cada recarregamento
    _reaplicar_ordenacao_cardapio()

def listar_cardapio_dia():
    for i in tree_dia.get_children(): tree_dia.delete(i)
    cursor.execute("SELECT id, nome, categoria, preco, preco_m, preco_g, so_mesa FROM cardapio_dia")
    for r in cursor.fetchall():
        # Trata valores None para não dar erro de formatação
        p_p = r[3] if r[3] is not None else 0.0
        p_m = r[4] if r[4] is not None else 0.0
        p_g = r[5] if r[5] is not None else 0.0
        # Só visual: destaca (tag) e rotula os pratos "só mesa"
        so_mesa_texto = "🍽 SÓ MESA" if r[6] else "🌐 Site + mesa"
        tree_dia.insert("", "end", values=(r[0], r[1], r[2], f"{p_p:.2f}", f"{p_m:.2f}", f"{p_g:.2f}", so_mesa_texto),
                        tags=("so_mesa",) if r[6] else ())
    try:
        _cd_atualizar_resumo_dia()   # contador visual no topo de NO DIA
    except Exception:
        pass

def salvar_prato():
    nome = entry_nome.get().strip()
    if not nome:
        messagebox.showwarning("Atenção", "O nome do prato é obrigatório!")
        return
    
    try:
        p_p = entry_preco_p.get().replace(',', '.') or "0"
        p_m = entry_preco_m.get().replace(',', '.') or "0"
        p_g = entry_preco_g.get().replace(',', '.') or "0"
        
        cursor.execute("""
            INSERT INTO cardapio (nome, descricao, categoria, preco, preco_m, preco_g, prod_estoque_p, prod_estoque_m, prod_estoque_g) 
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (nome, entry_desc.get(), combo_categoria.get(), float(p_p), float(p_m), float(p_g), 
              entry_estoque_p.get(), entry_estoque_m.get(), entry_estoque_g.get()))
        
        conn.commit()
        limpar_campos()
        listar_cardapio()
        messagebox.showinfo("Sucesso", "Prato cadastrado!")
    except Exception as e:
        messagebox.showerror("Erro", f"Falha ao salvar: {e}")

def adicionar_ao_dia(so_mesa=0):
    """so_mesa=0 (padrao): prato normal, vai pro cardapio do dia E,
    quando "gerar_json" for clicado, vai junto pro site/delivery.
    so_mesa=1: prato entra no cardapio do dia (aparece certinho no
    combo do modulo de Mesas) mas fica de fora do cardapio_hoje.json
    -- nunca e exportado pro site (ver filtro em gerar_json)."""
    item = tree_cardapio.selection()
    if not item: return
    id_p = tree_cardapio.item(item)["values"][0]
    
    cursor.execute("SELECT nome, descricao, categoria, preco, preco_m, preco_g, prod_estoque_p, prod_estoque_m, prod_estoque_g FROM cardapio WHERE id=?", (id_p,))
    p = cursor.fetchone()
    
    cursor.execute("""
        INSERT INTO cardapio_dia (id_prato, nome, descricao, categoria, preco, preco_m, preco_g, prod_estoque_p, prod_estoque_m, prod_estoque_g, so_mesa) 
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (id_p, p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7], p[8], so_mesa))
    
    conn.commit()
    listar_cardapio_dia()


def adicionar_ao_dia_so_mesa():
    item = tree_cardapio.selection()
    if not item:
        messagebox.showwarning("Atenção", "Selecione um prato em 'Opções de Pratos' primeiro.")
        return
    nome_prato = tree_cardapio.item(item)["values"][1]
    if not messagebox.askyesno(
        "Adicionar só para mesa",
        f"\"{nome_prato}\" vai entrar no cardápio do dia (aparece na comanda de "
        "Mesas), mas NUNCA será exportado pro cardapio_hoje.json -- ou seja, "
        "não aparece no site/delivery.\n\nConfirmar?"
    ):
        return
    adicionar_ao_dia(so_mesa=1)

def remover_do_dia():
    item = tree_dia.selection()
    if not item: return
    id_banco = tree_dia.item(item)["values"][0]
    cursor.execute("DELETE FROM cardapio_dia WHERE id = ?", (id_banco,))
    conn.commit()
    listar_cardapio_dia()

def esvaziar_dia():
    if messagebox.askyesno("Limpar", "Deseja esvaziar todo o cardápio do dia?"):
        cursor.execute("DELETE FROM cardapio_dia")
        conn.commit()
        listar_cardapio_dia()

import subprocess
import sys
import os

def _cd_gravar_snapshot_historico(ciclo_id):
    """Grava o cardápio INICIAL deste caixa no histórico (sem bebidas).
    Só grava se este caixa (ciclo_id) ainda não tiver snapshot: vale o PRIMEIRO
    cardápio publicado; republicar depois de tirar pratos não altera nada.
    Devolve True se gravou, False se não era para gravar."""
    cursor.execute("SELECT 1 FROM cardapio_historico WHERE ciclo_id = ?", (ciclo_id,))
    if cursor.fetchone():
        return False
    cursor.execute("""
        SELECT nome, categoria, preco, preco_g, COALESCE(so_mesa, 0), preco_m
        FROM cardapio_dia ORDER BY id
    """)
    itens = [r for r in cursor.fetchall()
             if (r[1] or "").strip().lower() != "bebidas"]
    if not itens:
        return False
    try:
        cursor.execute(
            "INSERT INTO cardapio_historico (ciclo_id, publicado_em, qtd_pratos) VALUES (?, ?, ?)",
            (ciclo_id, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), len(itens)))
        hid = cursor.lastrowid
        cursor.executemany("""
            INSERT INTO cardapio_historico_itens (historico_id, nome, categoria, preco, preco_g, so_mesa, preco_m)
            VALUES (?, ?, ?, ?, ?, ?, ?)
        """, [(hid, r[0], r[1], r[2] or 0, r[3] or 0, r[4], r[5] or 0) for r in itens])
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    return True


def gerar_json():
    # ❌ REMOVIDO: diretorio_atual = os.path.dirname(os.path.abspath(__file__))
    # ✅ USAMOS: PASTA_BASE (aquela que definimos no topo do código)
    
    path = os.path.join(PASTA_BASE, "cardapio_hoje.json")

    # 🔒 Sem caixa aberto NÃO gera cardápio: o histórico guarda o cardápio de
    # cada caixa, então o caixa precisa existir antes da publicação.
    ciclo_hist = _obter_ciclo_aberto_id()
    if not ciclo_hist:
        messagebox.showwarning(
            "Caixa fechado",
            "O caixa está fechado.\n\n"
            "Abra o caixa antes de criar o cardápio: cada cardápio publicado fica "
            "registrado no histórico junto com o caixa em que foi vendido."
        )
        return
    
    try:
        cursor.execute("""
            SELECT nome, descricao, categoria, preco, preco_g, 
                   prod_estoque_p, prod_estoque_g,
                   preco_m, prod_estoque_m
            FROM cardapio_dia
            WHERE so_mesa IS NULL OR so_mesa = 0
        """)
        rows = cursor.fetchall()
        
        if not rows:
            messagebox.showwarning("Aviso", "A lista 'NO DIA' está vazia (ou só tem itens marcados como 'só mesa')!")
            return

        dados = []
        for r in rows:
            dados.append({
                "nome": r[0],
                "desc": r[1],
                "cat": r[2],
                "p_p": r[3] if r[3] is not None else 0.0,
                "p_m": r[7] if r[7] is not None else 0.0,
                "p_g": r[4] if r[4] is not None else 0.0,
                "codigo_estoque_p": r[5] if r[5] else "",
                "codigo_estoque_m": r[8] if r[8] else "",
                "codigo_estoque_g": r[6] if r[6] else ""
            })

        # 🍹 ORDENAÇÃO: bebidas sempre por último na lista/JSON.
        # sort() é estável, então a ordem original dos itens (a ordem em que
        # foram adicionados no "NO DIA") é preservada dentro de cada grupo —
        # só as bebidas são empurradas para o final, sem embaralhar o resto.
        dados.sort(key=lambda item: (item.get("cat") or "").strip().lower() == "bebidas")

        # JSON GERADO EXATAMENTE COMO ANTES
        with open(path, "w", encoding="utf-8") as f:
            json.dump(dados, f, ensure_ascii=False, indent=4)

        # 📊 Histórico: guarda o cardápio inicial deste caixa (só o primeiro publicado).
        # Falha aqui NUNCA impede o JSON (já foi gerado); só avisa.
        aviso_hist = ""
        try:
            _cd_gravar_snapshot_historico(ciclo_hist)
        except Exception as e_hist:
            print(f"Erro ao gravar histórico de cardápio: {e_hist}")
            try:
                registrar_erro_diagnostico("gerar_json.snapshot_historico", extra={"ciclo_id": ciclo_hist})
            except Exception:
                pass
            aviso_hist = "\n\n⚠ O JSON foi gerado, mas não consegui salvar este cardápio no histórico."

        # 🔵 Pergunta se deseja abrir o editor
        resposta = messagebox.askyesno(
            "Sucesso",
            f"JSON Atualizado em:\n{path}{aviso_hist}\n\nDeseja abrir o editor de cardápio?"
        )

        if resposta:
            # ✅ AGORA USA O .EXE (CORREÇÃO)
            editor = os.path.join(PASTA_BASE, "editor_cardapio.exe")

            if os.path.exists(editor):
                subprocess.Popen(editor)  # ✅ CORRETO
            else:
                messagebox.showerror("Erro", "Editor de cardápio não encontrado.")

    except Exception as e:
        messagebox.showerror("Erro", f"Falha ao gerar JSON: {e}")

def deletar_prato_geral():
    # 1. Pega o item selecionado na treeview de Opções de Pratos
    item_selecionado = tree_cardapio.selection()

    if not item_selecionado:
        messagebox.showwarning("Aviso", "Selecione um prato em Opções de Pratos para remover!")
        return

    # 2. Pega o ID e o Nome para confirmar com o usuário
    valores = tree_cardapio.item(item_selecionado, "values")
    id_prato = valores[0]
    nome_prato = valores[1]

    confirmar = messagebox.askyesno(
        "Confirmar Exclusão", 
        f"Deseja realmente excluir o prato '{nome_prato}' de Opções de Pratos?\n\nIsso não poderá ser desfeito."
    )

    if confirmar:
        try:
            # 3. Remove do banco de dados (tabela cardapio)
            cursor.execute("DELETE FROM cardapio WHERE id = ?", (id_prato,))
            conn.commit()
            
            # 4. Atualiza a lista na tela
            listar_cardapio()
            messagebox.showinfo("Sucesso", f"Prato '{nome_prato}' removido com sucesso!")
            
        except Exception as e:
            messagebox.showerror("Erro", f"Falha ao deletar: {e}")

def carregar_prato_para_edicao(event=None):
    item = tree_cardapio.selection()
    if not item:
        return

    valores = tree_cardapio.item(item, "values")
    id_prato = valores[0]

    cursor.execute("""
        SELECT nome, descricao, categoria, preco, preco_g, prod_estoque_p, prod_estoque_g, prod_estoque_m
        FROM cardapio WHERE id=?
    """, (id_prato,))
    prato = cursor.fetchone()

    # Limpa campos
    limpar_campos()

    # Preenche
    entry_nome.insert(0, prato[0])
    entry_desc.insert(0, prato[1])
    combo_categoria.set(prato[2])
    entry_estoque_p.set(prato[5] or "")
    entry_estoque_m.set(prato[7] or "")
    entry_estoque_g.set(prato[6] or "")
    # Preço P/G não vem mais do que estava salvo no prato: é buscado
    # direto do Estoque, garantindo que sempre reflita o valor atual lá
    atualizar_preco_p_pelo_estoque()
    atualizar_preco_m_pelo_estoque()
    atualizar_preco_g_pelo_estoque()

    # Guarda ID global para atualizar
    global ID_EDITANDO
    ID_EDITANDO = id_prato

def atualizar_prato():
    global ID_EDITANDO
    if not ID_EDITANDO:
        messagebox.showwarning("Editar", "Nenhum prato selecionado!")
        return

    try:
        p_p = entry_preco_p.get().replace(',', '.') or "0"
        p_m = entry_preco_m.get().replace(',', '.') or "0"
        p_g = entry_preco_g.get().replace(',', '.') or "0"

        id_editado = ID_EDITANDO

        cursor.execute("""
            UPDATE cardapio SET 
                nome=?, descricao=?, categoria=?, 
                preco=?, preco_m=?, preco_g=?, 
                prod_estoque_p=?, prod_estoque_m=?, prod_estoque_g=?
            WHERE id=?
        """, (
            entry_nome.get(),
            entry_desc.get(),
            combo_categoria.get(),
            float(p_p),
            float(p_m),
            float(p_g),
            entry_estoque_p.get(),
            entry_estoque_m.get(),
            entry_estoque_g.get(),
            ID_EDITANDO
        ))

        conn.commit()
        listar_cardapio()
        limpar_campos()
        ID_EDITANDO = None

        # O prato editado permanece selecionado em Opções de Pratos,
        # pronto para ser adicionado ao NO DIA sem precisar buscar de novo
        _selecionar_prato_por_id(id_editado)

        messagebox.showinfo("Sucesso", "Prato atualizado!")

    except Exception as e:
        messagebox.showerror("Erro", f"Falha ao atualizar: {e}")

