def _cd_criar_card(master, titulo, cor_faixa=None):
    """Cartao com barra de titulo propria (faixa colorida + titulo + area
    'extra' no canto direito). Devolve (cartao, corpo, extra)."""
    card = tk.Frame(master, bg=cor_fundo_sistema, highlightthickness=1,
                    highlightbackground=cor_borda, highlightcolor=cor_borda, bd=0)
    topo = tk.Frame(card, bg=_CD_FUNDO_TIT)
    topo.pack(fill="x")
    tk.Frame(topo, bg=cor_faixa or cor_principal, width=5).pack(side="left", fill="y")
    tk.Label(topo, text=titulo, bg=_CD_FUNDO_TIT, fg=cor_titulo,
             font=("Segoe UI", 10, "bold"), anchor="w", padx=10, pady=7).pack(side="left")
    extra = tk.Frame(topo, bg=_CD_FUNDO_TIT)
    extra.pack(side="right", padx=8, pady=3)
    corpo = ttk.Frame(card)
    corpo.pack(fill="both", expand=True, padx=8, pady=8)
    return card, corpo, extra


def _cd_criar_tree(master, colunas, altura=7):
    """Treeview com barra de rolagem. colunas = [(id, titulo, largura, ancora, estica)]"""
    quadro = ttk.Frame(master)
    quadro.pack(fill="both", expand=True)
    tv = ttk.Treeview(quadro, columns=[c[0] for c in colunas], show="headings", height=altura)
    sb = ttk.Scrollbar(quadro, orient="vertical", command=tv.yview)
    tv.configure(yscrollcommand=sb.set)
    sb.pack(side="right", fill="y")
    tv.pack(side="left", fill="both", expand=True)
    for cid, titulo, largura, ancora, estica in colunas:
        tv.heading(cid, text=titulo, anchor=ancora)
        tv.column(cid, width=largura, minwidth=40, anchor=ancora, stretch=estica)
    return tv


