def _hist_fmt_data(iso):
    try:
        d = _datetime_cd.strptime(iso, "%Y-%m-%d")
        return f"{d.strftime('%d/%m')}  {_HIST_DIAS_SEM[d.weekday()]}"
    except Exception:
        return str(iso)


def _hist_cortar(texto, largura_px):
    """Corta o texto com reticencias para caber na largura (em pixels)."""
    if _cd_fonte_txt.measure(texto) <= largura_px:
        return texto
    while texto and _cd_fonte_txt.measure(texto + "…") > largura_px:
        texto = texto[:-1]
    return texto.rstrip() + "…"


# Categorias de despesa que entram na barra vermelha do histórico
# (nomes como em CATEGORIAS_DESPESA / caixa.categoria).
_HIST_CATS_DESPESA = ("Insumos e alimentos", "Carnes e frios")


def _hist_totais_ciclo(cur_h, ciclo_id):
    """(vendas, pendente, despesas) de UM caixa, em reais. SOMENTE LEITURA.
    vendas   = soma do TOTAL dos pedidos do caixa (pagos E pendentes), sem os
               DESCARTE/CANCELADO -- o mesmo critério do "total de vendas" dos
               relatórios. É o que mede quanto o cardápio VENDEU, não o que já
               entrou no caixa. Como parte do TOTAL do pedido (que não muda quando
               ele é pago depois), um pedido pendente que for pago NUNCA conta duas vezes.
    pendente = parte das vendas ainda não recebida (pedidos Pendente, total menos o
               que já entrou no caixa por pedido_id), igual à conta do "fiado" do Resultado.
    despesas = saídas do caixa só das categorias de _HIST_CATS_DESPESA (estornos descontam)
               + notas de estoque marcadas para o cardápio (cardapio_historico_despesas)
    O pedido pertence ao caixa por ciclo_caixa_id; se esse campo estiver vazio, pelo
    horário (entre a abertura e o fechamento do caixa), como já faz o fechamento de caixa."""
    cur_h.execute("SELECT abertura, fechamento FROM ciclos_caixa WHERE id = ?", (ciclo_id,))
    row = cur_h.fetchone()
    abertura, fechamento = (row if row else (None, None))
    filtro_ped = """
        UPPER(COALESCE(p.pagamento, '')) NOT IN ('DESCARTE', 'CANCELADO')
        AND (p.ciclo_caixa_id = :c
             OR (p.ciclo_caixa_id IS NULL AND :a IS NOT NULL AND p.data >= :a
                 AND (:f IS NULL OR p.data <= :f)))
    """
    par = {"c": ciclo_id, "a": abertura, "f": fechamento}
    cur_h.execute(f"SELECT COALESCE(SUM(p.total), 0) FROM pedidos p WHERE {filtro_ped}", par)
    vendas = _centavos(cur_h.fetchone()[0])
    cur_h.execute(f"""
        SELECT COALESCE(SUM(MAX(0, p.total - COALESCE((
                   SELECT SUM(CASE c.tipo WHEN 'ENTRADA' THEN c.valor ELSE -c.valor END)
                   FROM caixa c WHERE c.pedido_id = p.id), 0))), 0)
        FROM pedidos p
        WHERE {filtro_ped} AND UPPER(COALESCE(p.pagamento, '')) IN ('PENDENTE', '')
    """, par)
    pendente = min(_centavos(cur_h.fetchone()[0]), vendas)

    cur_h.execute("""
        SELECT c.tipo, c.descricao, c.valor, c.pedido_id, c.estornado_de, c.categoria,
               o.tipo, o.descricao, o.pedido_id, o.categoria
        FROM caixa c
        LEFT JOIN caixa o ON o.id = c.estornado_de
        WHERE c.ciclo_id = ?
    """, (ciclo_id,))
    desp = 0
    cats_ok = {c.strip().lower() for c in _HIST_CATS_DESPESA}
    for (tipo, desc, valor, pedido_id, estornado_de, cat,
         o_tipo, o_desc, o_pedido, o_cat) in cur_h.fetchall():
        v = _centavos(valor)
        if estornado_de:
            if o_tipo is None:
                continue
            grupo, rotulo = _classificar_lancamento_caixa(o_tipo, o_desc, o_cat, o_pedido)
            sinal = -1
        else:
            grupo, rotulo = _classificar_lancamento_caixa(tipo, desc, cat, pedido_id)
            sinal = 1
        if grupo == "GASTO" and (rotulo or "").strip().lower() in cats_ok:
            desp += sinal * v
    # + notas de estoque marcadas como carnes/insumos (cardapio_historico_despesas)
    try:
        cur_h.execute("SELECT COALESCE(SUM(valor), 0) FROM cardapio_historico_despesas WHERE ciclo_id = ?",
                      (ciclo_id,))
        desp += _centavos(cur_h.fetchone()[0])
    except Exception:
        pass
    return round(vendas / 100.0, 2), round(pendente / 100.0, 2), round(desp / 100.0, 2)


def _hist_buscar_dados(dias):
    """Le (sem alterar nada) o cardapio inicial salvo de cada caixa
    (cardapio_historico) e o faturamento/despesas daquele caixa."""
    hoje = _date_cd.today()
    ini = hoje - _timedelta_cd(days=max(1, dias) - 1)
    conn_h = abrir_conexao_curta()
    try:
        cur_h = conn_h.cursor()
        cur_h.execute("""
            SELECT h.id, h.ciclo_id, c.abertura
            FROM cardapio_historico h
            JOIN ciclos_caixa c ON c.id = h.ciclo_id
            WHERE c.abertura IS NOT NULL AND date(c.abertura) BETWEEN ? AND ?
            ORDER BY c.abertura DESC, h.id DESC
        """, (ini.isoformat(), hoje.isoformat()))
        cabecas = cur_h.fetchall()
        linhas = []
        for hid, ciclo_id, abertura in cabecas:
            cur_h.execute("""
                SELECT nome, COALESCE(so_mesa, 0) FROM cardapio_historico_itens
                WHERE historico_id = ? AND COALESCE(so_mesa, 0) = 0
                ORDER BY id
            """, (hid,))
            pratos = [((n or "").strip(), int(sm or 0)) for n, sm in cur_h.fetchall()]
            fat, pend, desp = _hist_totais_ciclo(cur_h, ciclo_id)
            nomes = [n for n, _sm in pratos]
            qtd = len(pratos)
            rot_qtd = f"{qtd} {'prato' if qtd == 1 else 'pratos'}"
            det = f"{rot_qtd}: " + ", ".join(nomes)
            if len(det) > 230:
                det = det[:229].rstrip() + "…"
            if pend > 0:
                det += f"   ⏳ Pendente a receber: {_res_brl(pend)}"
            linhas.append({
                "data": (abertura or "")[:10],
                "hora": (abertura or "")[11:16],
                "ciclo_id": ciclo_id,
                "resumo": (f"{rot_qtd} · " + " • ".join(nomes)) if nomes else "sem pratos do site",
                "detalhe": det,
                "faturamento": float(fat or 0.0),
                "pendente": float(pend or 0.0),
                "despesas": float(desp or 0.0),
            })
    finally:
        conn_h.close()
    return linhas


def _hist_geometria(w):
    larg_val = 130
    x_card = 150
    larg_card = max(150, int(w * 0.30))
    x_bar = x_card + larg_card + 14
    x_dir = w - 12
    return {
        "x_data": 12, "x_card": x_card, "larg_card": larg_card,
        "x_bar": x_bar, "x_dir": x_dir,
        "larg_bar": max(60, x_dir - larg_val - 8 - x_bar),
    }


# Paleta das barras do historico (so layout)
_HIST_COR_REC        = "#43A047"   # verde medio: vendas ja recebidas
_HIST_COR_REC_TOP    = "#1B5E20"   # verde escuro: melhor caixa (ranking)
_HIST_COR_PEND       = "#A5D6A7"   # verde claro: vendido e ainda nao recebido
_HIST_COR_PEND_BORDA = "#66BB6A"
_HIST_COR_TRILHO     = "#E4E8EB"   # fundo cinza neutro (nao se confunde com o pendente)
_HIST_COR_TRILHO_BDA = "#CBD2D8"


def _hist_desenhar_cabecalho(w):
    cv = cv_hist_cab
    cv.delete("all")
    g = _hist_geometria(w)
    f = ("Segoe UI", 9, "bold")
    cv.create_text(g["x_data"], 12, text="CAIXA / DATA", anchor="w", font=f, fill=cor_titulo)
    cv.create_text(g["x_card"], 12, text="CARDÁPIO INICIAL", anchor="w", font=f, fill=cor_titulo)
    # legenda de cores das barras
    x = g["x_bar"]
    limite = g["x_dir"] - 110
    fl = ("Segoe UI", 8, "bold")
    for cor, borda, rot in ((_HIST_COR_REC, _HIST_COR_REC, "Recebido"),
                            (_HIST_COR_PEND, _HIST_COR_PEND_BORDA, "Pendente"),
                            (COR_DESPESA, COR_DESPESA, "Despesas"),
                            (_HIST_COR_REC_TOP, _HIST_COR_REC_TOP, "Melhor caixa")):
        lw = _cd_fonte_txt.measure(rot) + 6
        if x + 16 + lw > limite:
            break
        cv.create_rectangle(x, 7, x + 12, 17, fill=cor, outline=borda)
        cv.create_text(x + 16, 12, text=rot, anchor="w", font=fl, fill=cor_titulo)
        x += 16 + lw + 12
    cv.create_text(g["x_dir"], 12, text="VENDAS / DESP.", anchor="e", font=f, fill=cor_titulo)


def _hist_desenhar(_e=None):
    cv = cv_hist
    cv.delete("all")
    _hist_estado["rects"] = []
    _hist_estado["hover"] = None
    w = max(cv.winfo_width(), 560)
    _hist_desenhar_cabecalho(w)

    if _hist_estado["wrap"] != w:
        _hist_estado["wrap"] = w
        try:
            lbl_hist_detalhe.configure(wraplength=max(300, w - 24))
        except Exception:
            pass

    linhas = _hist_estado["linhas"]
    if not linhas:
        cv.configure(scrollregion=(0, 0, w, 10))
        h = max(cv.winfo_height(), 100)
        cv.create_text(w / 2, h / 2,
                       text=_hist_estado["msg_vazio"] or
                       "Nenhum cardápio registrado neste período.\n"
                       "O histórico começa a ser gravado quando você gera o JSON com o caixa aberto.",
                       fill="#7F8C8D", font=("Segoe UI", 10), justify="center")
        return

    cv.configure(scrollregion=(0, 0, w, len(linhas) * _HIST_ALT))
    g = _hist_geometria(w)
    # As duas barras usam a MESMA escala (maior valor entre faturamento e despesas),
    # para a comparação verde x vermelho ser honesta dentro da linha e entre linhas.
    maxv = max(max(l["faturamento"], l["despesas"]) for l in linhas)
    melhor = max(range(len(linhas)), key=lambda i: linhas[i]["faturamento"]) \
        if max(l["faturamento"] for l in linhas) > 0 else None
    hoje_iso = _date_cd.today().isoformat()

    for i, l in enumerate(linhas):
        y0 = i * _HIST_ALT
        y1 = y0 + _HIST_ALT
        ym = (y0 + y1) / 2
        fundo = "#FFFFFF" if i % 2 == 0 else cor_zebra
        r = cv.create_rectangle(0, y0, w, y1, fill=fundo, outline="")
        _hist_estado["rects"].append((r, fundo))

        cv.create_text(g["x_data"], ym - 8, text=_hist_fmt_data(l["data"]), anchor="w",
                       font=("Segoe UI", 10, "bold"), fill=cor_titulo)
        sub = f"caixa #{l['ciclo_id']} · {l['hora']}" + ("  · hoje" if l["data"] == hoje_iso else "")
        cv.create_text(g["x_data"], ym + 9, text=sub, anchor="w",
                       font=("Segoe UI", 8), fill="#7F8C8D")

        cv.create_text(g["x_card"], ym, text=_hist_cortar(l["resumo"], g["larg_card"]),
                       anchor="w", font=("Segoe UI", 9), fill=cor_texto)

        fat, desp = l["faturamento"], l["despesas"]
        yb = y0 + 8
        alt_b = 16
        xb = g["x_bar"]
        lb = g["larg_bar"]
        f_barra = ("Segoe UI", 8, "bold")
        # barra verde (vendas): recebido (verde) + pendente (verde claro com borda)
        cv.create_rectangle(xb, yb, xb + lb, yb + alt_b,
                            fill=_HIST_COR_TRILHO, outline=_HIST_COR_TRILHO_BDA)
        if fat > 0 and maxv > 0:
            comp = max(4, lb * fat / maxv)
            pend = min(l.get("pendente", 0.0), fat)
            comp_pend = comp * pend / fat if pend > 0 else 0
            comp_rec = comp - comp_pend
            cor_rec = _HIST_COR_REC_TOP if i == melhor else _HIST_COR_REC
            if comp_rec > 0:
                cv.create_rectangle(xb, yb, xb + comp_rec, yb + alt_b, fill=cor_rec, outline="")
                txt_rec = _res_brl(fat - pend)
                if comp_rec >= _cd_fonte_txt.measure(txt_rec) + 14:
                    cv.create_text(xb + 6, yb + alt_b / 2, text=txt_rec, anchor="w",
                                   font=f_barra, fill="#FFFFFF")
            if comp_pend > 0:
                # trecho claro = vendido mas ainda não recebido (pendente)
                cv.create_rectangle(xb + comp_rec, yb, xb + comp, yb + alt_b,
                                    fill=_HIST_COR_PEND, outline=_HIST_COR_PEND_BORDA)
                txt_pend = "pend. " + _res_brl(pend)
                if comp_pend >= _cd_fonte_txt.measure(txt_pend) + 14:
                    cv.create_text(xb + comp_rec + 6, yb + alt_b / 2, text=txt_pend, anchor="w",
                                   font=f_barra, fill="#1B5E20")
        # barra vermelha (despesas) + % sobre as vendas
        yb2 = yb + alt_b + 5
        cv.create_rectangle(xb, yb2, xb + lb, yb2 + alt_b,
                            fill=_HIST_COR_TRILHO, outline=_HIST_COR_TRILHO_BDA)
        if desp > 0 and maxv > 0:
            comp2 = max(4, lb * desp / maxv)
            cv.create_rectangle(xb, yb2, xb + comp2, yb2 + alt_b, fill=COR_DESPESA, outline="")
            if fat > 0:
                pct = desp / fat * 100
                for txt_d in (f"{pct:.0f}% das vendas", f"{pct:.0f}%"):
                    if comp2 >= _cd_fonte_txt.measure(txt_d) + 14:
                        cv.create_text(xb + 6, yb2 + alt_b / 2, text=txt_d, anchor="w",
                                       font=f_barra, fill="#FFFFFF")
                        break

        txt_f = _res_brl(fat)
        if i == melhor:
            txt_f = "🏆 " + txt_f
        cv.create_text(g["x_dir"], yb + alt_b / 2, text=txt_f, anchor="e",
                       font=("Segoe UI", 9, "bold"),
                       fill=(_HIST_COR_REC_TOP if fat > 0 else "#95A5A6"))
        cv.create_text(g["x_dir"], yb2 + alt_b / 2, text=_res_brl(desp), anchor="e",
                       font=("Segoe UI", 9),
                       fill=(COR_DESPESA if desp > 0 else "#95A5A6"))
    cv.create_line(0, len(linhas) * _HIST_ALT, w, len(linhas) * _HIST_ALT, fill=cor_borda)


def _hist_marcar(idx):
    rects = _hist_estado["rects"]
    ant = _hist_estado["hover"]
    if ant is not None and 0 <= ant < len(rects):
        cv_hist.itemconfigure(rects[ant][0], fill=rects[ant][1])
    _hist_estado["hover"] = idx
    if idx is not None and 0 <= idx < len(rects):
        cv_hist.itemconfigure(rects[idx][0], fill="#DDF0E3")
        l = _hist_estado["linhas"][idx]
        lbl_hist_detalhe.configure(text=f"{_hist_fmt_data(l['data'])} {l['hora']} (caixa #{l['ciclo_id']}) — {l['detalhe']}")
    else:
        lbl_hist_detalhe.configure(text=_HIST_DICA)


def _hist_ao_mover_mouse(ev):
    if not _hist_estado["linhas"]:
        return
    idx = int(cv_hist.canvasy(ev.y) // _HIST_ALT)
    if not (0 <= idx < len(_hist_estado["linhas"])):
        idx = None
    if idx != _hist_estado["hover"]:
        _hist_marcar(idx)


def _hist_ao_redimensionar(_e=None):
    if _hist_estado["after"]:
        try:
            cv_hist.after_cancel(_hist_estado["after"])
        except Exception:
            pass
    _hist_estado["after"] = cv_hist.after(80, _hist_desenhar)


def _hist_ao_entrar_mouse(_e=None):
    # Para a rodinha do mouse funcionar sem roubar o foco de um campo que esteja sendo digitado
    try:
        foco = root.focus_get()
        if isinstance(foco, (tk.Entry, ttk.Entry, ttk.Combobox)):
            return
    except Exception:
        pass
    cv_hist.focus_set()


cv_hist.bind("<Configure>", _hist_ao_redimensionar)
cv_hist.bind("<Motion>", _hist_ao_mover_mouse)
cv_hist.bind("<Leave>", lambda _e: _hist_marcar(None))
cv_hist.bind("<Enter>", _hist_ao_entrar_mouse)
cv_hist.bind("<MouseWheel>", lambda e: cv_hist.yview_scroll(-1 if e.delta > 0 else 1, "units"))


def _hist_atualizar_resumo():
    linhas = _hist_estado["linhas"]
    if not linhas:
        lbl_hist_resumo.config(text="")
        return
    melhor = max(linhas, key=lambda l: l["faturamento"])
    media = sum(l["faturamento"] for l in linhas) / len(linhas)
    tot_f = sum(l["faturamento"] for l in linhas)
    tot_d = sum(l["despesas"] for l in linhas)
    partes = []
    if melhor["faturamento"] > 0:
        partes.append(f"🏆 Melhor caixa: {_hist_fmt_data(melhor['data'])} {melhor['hora']} — "
                      f"{_res_brl(melhor['faturamento'])}")
    partes.append(f"Média por caixa: {_res_brl(media)}")
    tot_p = sum(l.get("pendente", 0.0) for l in linhas)
    if tot_p > 0:
        partes.append(f"⏳ Pendente a receber: {_res_brl(tot_p)}")
    if tot_f > 0:
        partes.append(f"Despesas (insumos/carnes): {tot_d / tot_f * 100:.0f}% do faturamento")
    partes.append(f"{len(linhas)} caixa(s) com cardápio no período")
    lbl_hist_resumo.config(text="   •   ".join(partes))


def _hist_atualizar(_e=None):
    try:
        dias = int(combo_hist_periodo.get().split()[0])
    except Exception:
        dias = 30
    try:
        _hist_estado["linhas"] = _hist_buscar_dados(dias)
        _hist_estado["msg_vazio"] = None
    except Exception as e:
        _hist_estado["linhas"] = []
        _hist_estado["msg_vazio"] = f"Não foi possível carregar o histórico: {e}"
        print(f"Erro ao montar histórico de cardápios: {e}")
    lbl_hist_detalhe.configure(text=_HIST_DICA)
    _hist_atualizar_resumo()
    _hist_desenhar()
    try:
        cv_hist.yview_moveto(0)
    except Exception:
        pass


def _hist_ao_trocar_aba(_e=None):
    """Recalcula o histórico sempre que a aba CARDÁPIO é aberta."""
    try:
        if notebook_principal.select() == str(aba_cardapio):
            _hist_atualizar()
    except Exception:
        pass

notebook_principal.bind("<<NotebookTabChanged>>", _hist_ao_trocar_aba, add="+")

