def ao_fechar_janela():
    """Impeça o fechamento se houver um ciclo de caixa ativo."""

    if ciclo_caixa_aberto.get("id"):

        messagebox.showwarning(
            "Caixa Aberto",
            "Atenção: Feche o caixa na aba 'CAIXA' antes de sair do sistema!"
        )

    else:

        # Se o caixa estiver fechado, pergunta se quer sair mesmo
        if messagebox.askyesno(
            "Sair",
            "Deseja realmente sair?"
        ):

            # Aba ENTREGAS: aciona o "Encerrar dia" (limpa arquivos e reduz o uso do Firebase).
            # Devolve False se o operador escolher voltar ao sistema.
            try:
                import entregas_tela
                if not entregas_tela.encerrar_dia_ao_fechar(root):
                    return
            except Exception as e:
                print("Erro ao encerrar o dia das entregas:", e)

            try:
            
                backup_automatico()
            
            except Exception as e:
            
                print(
                    "Erro ao criar backup:",
                    e
                )
            
            # Fecha a janela principal
            try:
                root.destroy()
            except:
                pass
            
            # Fecha a root fantasma criada pelo ttk.Style()
            try:
                if tk._default_root:
                    tk._default_root.destroy()
            except:
                pass
            
            # Libera o socket de instância única
            try:
                lock_socket.close()
            except:
                pass
            
            # Encerra completamente o processo
            os._exit(0)

