# =====================================================
# 🎨 [APARENCIA] FUNDO DOS TÍTULOS = FUNDO DO QUADRO (acompanha o tema)
# =====================================================
# Os textos (ttk.Label) usam o estilo "TLabel", cujo fundo e diferente do
# fundo que os quadros/LabelFrames recebem do tema. Resultado: cada titulo
# ficava numa "caixinha" (a sombra) que ainda cobria o contorno do quadro.
# Esta rotina deixa cada Label com o fundo REAL do quadro onde esta e fica
# vigiando: se a cor do tema mudar (CONFIG > Aparencia), refaz na hora.
# Tambem faz o mesmo com os widgets do CustomTkinter (faixas/barras de botoes,
# cantos dos botoes) e aplica o visual das ABAS em todo o sistema:
# aba selecionada = cor do tema, maior; abas atras = cor clara, menores.
def _igualar_fundo_dos_titulos(raiz, vigiar=True):
    import tkinter.ttk as _ttk_p

    _estilo = _ttk_p.Style(raiz)
    try:
        import customtkinter as _ctk_w
        _CTkBase = getattr(_ctk_w, "CTkBaseClass", None)
    except Exception:
        _CTkBase = None
    _sondas = []          # quadros que contem titulos (para detectar troca de cor)

    def _cor_valida(w, cor):
        if isinstance(cor, (tuple, list)):
            cor = cor[0] if cor else None
        if not cor or str(cor).lower() in ("transparent", ""):
            return None
        try:
            w.winfo_rgb(str(cor))
            return str(cor)
        except Exception:
            return None

    def _fundo_real(w):
        # sobe na hierarquia ate achar a cor de fundo que realmente aparece
        while w is not None:
            cor = None
            try:
                if isinstance(w, _ttk_p.Widget):
                    nome = str(w.cget("style") or w.winfo_class())
                    cor = _cor_valida(w, _estilo.lookup(nome, "background"))
                    if cor is None:
                        cor = _cor_valida(w, _estilo.lookup(w.winfo_class(), "background"))
                else:
                    for opc in ("bg", "background", "fg_color"):
                        try:
                            cor = _cor_valida(w, w.cget(opc))
                        except Exception:
                            cor = None
                        if cor:
                            break
            except Exception:
                cor = None
            if cor:
                return cor
            w = getattr(w, "master", None)
        return None

    def _fundo_atras_ctk(w):
        # cor que aparece ATRAS de um widget CustomTkinter (para os cantos/faixas)
        pai = getattr(w, "master", None)
        while pai is not None:
            if _CTkBase is not None and isinstance(pai, _CTkBase):
                cor = None
                try:
                    cor = _cor_valida(pai, pai.cget("fg_color"))
                except Exception:
                    cor = None
                if cor is None:
                    try:
                        cor = _cor_valida(pai, pai.cget("bg_color"))
                    except Exception:
                        cor = None
                if cor:
                    return cor
                pai = getattr(pai, "master", None)
                continue
            return _fundo_real(pai)
        return None

    def _acertar_ctk(filho):
        if _CTkBase is None or not isinstance(filho, _CTkBase):
            return
        cor = _fundo_atras_ctk(filho)
        if not cor:
            return
        try:
            atual = _cor_valida(filho, filho.cget("bg_color"))
        except Exception:
            atual = None
        if atual != cor:
            filho.configure(bg_color=cor)

    def _aplicar_abas():
        # Abas de TODOS os notebooks do sistema (estilo global "TNotebook.Tab").
        try:
            g = globals()
            # [ABAS] cor da pagina = fundo do TEMA (nao do estilo TFrame, que pode voltar ao cinza na abertura)
            _tema_ab = g.get("_TEMA_ATUAL")
            pagina = (
                _cor_valida(raiz, _tema_ab.get("fundo") if isinstance(_tema_ab, dict) else None)
                or _cor_valida(raiz, _estilo.lookup("Fundo.TFrame", "background"))
                or _cor_valida(raiz, _estilo.lookup("TFrame", "background"))
                or "#F4F6F8"
            )
            clara = _cor_valida(raiz, g.get("cor_frame")) or "#FFFFFF"
            verde = _cor_valida(raiz, g.get("cor_principal")) or "#1B8F4D"
            borda = _cor_valida(raiz, g.get("cor_borda")) or "#C8D0D8"
            escuro = _cor_valida(raiz, g.get("cor_titulo")) or "#111827"
            fonte = ("Segoe UI", 10, "bold")
            _estilo.configure("TNotebook", background=pagina)
            _estilo.configure(
                "TNotebook.Tab", background=clara, foreground="#5B6670", font=fonte,
                padding=(14, 5), borderwidth=1, bordercolor=borda,
                lightcolor=clara, darkcolor=clara,
            )
            _estilo.map(
                "TNotebook.Tab",
                background=[("selected", pagina), ("active", pagina)],
                foreground=[("selected", verde), ("active", escuro)],
                lightcolor=[("selected", verde), ("active", pagina)],
                darkcolor=[("selected", pagina), ("active", pagina)],
                bordercolor=[("selected", borda)],
                padding=[("selected", (18, 10)), ("!selected", (14, 5))],
                expand=[("selected", (0, 3, 0, 0)), ("!selected", (0, 0, 0, 0))],
            )
        except Exception:
            pass

    def _percorrer(w):
        for filho in w.winfo_children():
            try:
                # o contorno do LabelFrame (clam) tem 2px, mas o layout so
                # reserva 1px: 1px de padding interno impede que o conteudo
                # "coma" a borda.
                if isinstance(filho, _ttk_p.Labelframe) and not str(filho.cget("padding")).strip():
                    filho.configure(padding=1)
            except Exception:
                pass
            try:
                _acertar_ctk(filho)
            except Exception:
                pass
            try:
                if isinstance(filho, _ttk_p.Label):
                    pai = filho.master
                    cor = _fundo_real(pai)
                    if cor:
                        filho.configure(background=cor)
                        if pai not in _sondas and len(_sondas) < 25:
                            _sondas.append(pai)
            except Exception:
                pass
            _percorrer(filho)

    def _assinatura():
        partes = []
        for nome in ("TFrame", "TLabelframe", "TLabelframe.Label", "TLabel",
                     "TNotebook", "TNotebook.Tab"):
            try:
                partes.append(_estilo.lookup(nome, "background"))
            except Exception:
                partes.append(None)
        try:
            partes.append(str(_estilo.lookup("TNotebook.Tab", "padding")))
        except Exception:
            partes.append(None)
        # [ABAS] se algo refizer so as cores do mapa das abas (aba ativa), tambem refaz
        try:
            partes.append(str(_estilo.map("TNotebook.Tab", "background")))
        except Exception:
            partes.append(None)
        for pai in list(_sondas):
            try:
                partes.append(_fundo_real(pai))
            except Exception:
                partes.append(None)
        return tuple(partes)

    estado = {"sig": None, "agendado": False}

    def _passar():
        estado["agendado"] = False
        try:
            _aplicar_abas()
            _percorrer(raiz)
            estado["sig"] = _assinatura()
        except Exception:
            pass

    def _checar():
        try:
            if _assinatura() != estado["sig"]:
                _passar()
        except Exception:
            pass
        try:
            raiz.after(300, _checar)
        except Exception:
            pass

    def _ao_trocar_aba(_e=None):
        if not estado["agendado"]:
            estado["agendado"] = True
            try:
                raiz.after(40, _passar)
            except Exception:
                estado["agendado"] = False

    _passar()
    if vigiar:
        # [ABAS] reaplica logo apos abrir (garante a cor da aba ativa com o tema salvo)
        for _ms in (150, 600, 1500):
            try:
                raiz.after(_ms, _passar)
            except Exception:
                pass
        try:
            raiz.bind_all("<<NotebookTabChanged>>", _ao_trocar_aba, add="+")
        except Exception:
            pass
        try:
            raiz.after(300, _checar)
        except Exception:
            pass
    return _passar


# [APARENCIA] titulos, faixas e abas acompanham o tema (e o contorno dos quadros nao e mais cortado)
