# =====================================================
# 📐 [TELA] AJUSTE AUTOMATICO AO TAMANHO DO MONITOR
# =====================================================
# Listas (Treeview) com altura fixa empurravam os botoes de baixo para fora
# da tela (Estoque, Caixa...). Aqui a altura de cada lista e ajustada
# sozinha: diminui se o conteudo da aba nao cabe (monitor menor) e aumenta
# se sobra espaco (monitor maior). Roda ao abrir, ao trocar de aba/sub-aba
# e quando a janela muda de tamanho. So mexe no "height" das listas.
def _ajustar_tela_ao_monitor(raiz, notebook, min_linhas=3, max_linhas=45):
    import tkinter as _tk_f
    import tkinter.ttk as _ttk_f

    _estilo = _ttk_f.Style(raiz)
    _estado = {"ocupado": False, "agendado": None}

    def _eh_janela(w):
        return w.winfo_class() in ("Toplevel", "CTkToplevel")

    def _listas_fora(w, saida):
        # listas da aba que NAO estao dentro de um sub-notebook
        for filho in w.winfo_children():
            if _eh_janela(filho) or isinstance(filho, _ttk_f.Notebook):
                continue
            if isinstance(filho, _ttk_f.Treeview):
                saida.append(filho)
            _listas_fora(filho, saida)
        return saida

    def _notebooks_diretos(w, saida):
        for filho in w.winfo_children():
            if _eh_janela(filho):
                continue
            if isinstance(filho, _ttk_f.Notebook):
                saida.append(filho)
                continue
            _notebooks_diretos(filho, saida)
        return saida

    def _altura_linha(tv):
        for nome in (str(tv.cget("style") or ""), "Treeview"):
            if not nome:
                continue
            try:
                v = _estilo.lookup(nome, "rowheight")
                if v:
                    return max(14, int(float(v)))
            except Exception:
                pass
        return 20

    def _alt(tv):
        try:
            return int(tv.cget("height"))
        except Exception:
            return 10

    def _ajustar_aba(aba, nivel=0):
        if nivel > 3:
            return
        raiz.update_idletasks()
        if not aba.winfo_ismapped() or aba.winfo_height() < 60:
            return
        nbs = _notebooks_diretos(aba, [])
        listas = _listas_fora(aba, [])

        def folga():
            raiz.update_idletasks()
            return aba.winfo_height() - aba.winfo_reqheight()

        # sub-notebooks: pede o minimo para medir o resto do conteudo
        for nb in nbs:
            try:
                nb.configure(height=1)
            except Exception:
                pass

        # 1) nao cabe: diminui a(s) maior(es) lista(s) desta aba
        for _ in range(60):
            f = folga()
            if f >= 0:
                break
            cand = [t for t in listas if _alt(t) > min_linhas]
            if not cand:
                break
            maior = max(cand, key=_alt)
            passo = max(1, int((-f) // _altura_linha(maior)))
            maior.configure(height=max(min_linhas, _alt(maior) - passo))

        # 2) sobra espaco (e nao ha sub-notebook para ocupa-lo): aumenta listas
        if not nbs:
            for _ in range(60):
                f = folga()
                cand = [t for t in listas if _alt(t) < max_linhas]
                if not cand or f < _altura_linha(cand[0]) * 1.2:
                    break
                menor = min(cand, key=_alt)
                h0 = _alt(menor)
                passo = max(1, int(f // _altura_linha(menor)))
                menor.configure(height=min(max_linhas, h0 + passo))
                if folga() < 0:
                    while folga() < 0 and _alt(menor) > h0:
                        menor.configure(height=_alt(menor) - 1)
                    break

        # 3) sub-notebook: ocupa TODO o espaco que sobrou (sem empurrar nada);
        #    se a sub-aba atual for mais alta que isso, mantem o tamanho dela.
        for nb in nbs:
            try:
                f = folga()
                sel = nb.select()
                sub = raiz.nametowidget(sel) if sel else None
                req_sel = sub.winfo_reqheight() if sub is not None else 0
                nb.configure(height=max(1 + f, req_sel, 80))
                raiz.update_idletasks()
                if sub is not None:
                    _ajustar_aba(sub, nivel + 1)
            except Exception:
                pass

    def _executar():
        _estado["agendado"] = None
        if _estado["ocupado"]:
            return
        _estado["ocupado"] = True
        try:
            sel = notebook.select()
            if sel:
                _ajustar_aba(raiz.nametowidget(sel))
        except Exception:
            pass
        finally:
            _estado["ocupado"] = False

    def _agendar(_e=None, atraso=150):
        if _e is not None and getattr(_e, "widget", None) is not raiz:
            return
        if _estado["agendado"] is not None:
            try:
                raiz.after_cancel(_estado["agendado"])
            except Exception:
                pass
        try:
            _estado["agendado"] = raiz.after(atraso, _executar)
        except Exception:
            _estado["agendado"] = None

    try:
        raiz.bind("<Configure>", _agendar, add="+")
    except Exception:
        pass
    try:
        raiz.bind_all("<<NotebookTabChanged>>", lambda e: _agendar(None, 120), add="+")
    except Exception:
        pass
    _agendar(None, 700)
    return _executar

# [TELA] listas se ajustam ao tamanho do monitor (botoes de baixo sempre visiveis)
try:
    _ajustar_tela_ao_monitor(root, notebook_principal)
except Exception as _e_tela:
    print("[TELA] ajuste ao monitor nao ativado:", _e_tela)


